def mxpc_logo_image_data() -> io.BytesIO:
    """Devuelve una copia en memoria del logo para XlsxWriter/PyInstaller."""
    return io.BytesIO(base64.b64decode(MXPC_LOGO_B64))


def mxpc_logo_image_data_excel_large() -> io.BytesIO:
    """Logo normalizado a 96 DPI para que Excel no lo reduzca por el DPI original.

    El PNG embebido original tiene metadatos cercanos a 300 DPI. XlsxWriter/Excel
    respetan ese tamaño físico y por eso el logo se veía pequeño incluso al aumentar
    x_scale/y_scale. Esta variante conserva los píxeles y regraba el PNG a 96 DPI.
    """
    try:
        from PIL import Image
        raw = io.BytesIO(base64.b64decode(MXPC_LOGO_B64))
        img = Image.open(raw).convert("RGBA")
        out = io.BytesIO()
        img.save(out, format="PNG", dpi=(96, 96))
        out.seek(0)
        return out
    except Exception:
        return mxpc_logo_image_data()


def money(value) -> float:
    if value is None:
        return 0.0
    try:
        if pd.isna(value):
            return 0.0
    except Exception:
        pass
    if isinstance(value, (int, float)):
        return float(value)
    text = str(value).strip().replace("$", "").replace(" ", "")
    if not text:
        return 0.0
    if "," in text and "." in text:
        if text.rfind(",") > text.rfind("."):
            text = text.replace(".", "").replace(",", ".")
        else:
            text = text.replace(",", "")
    elif "," in text:
        parts = text.split(",")
        text = text.replace(",", "") if len(parts[-1]) == 3 else text.replace(",", ".")
    try:
        return float(text)
    except Exception:
        return 0.0


def today_text() -> str:
    return datetime.now().strftime("%Y-%m-%d")


def excel_date_text(value) -> str:
    if value is None or pd.isna(value):
        return today_text()
    if isinstance(value, datetime):
        return value.strftime("%Y-%m-%d")
    if isinstance(value, (int, float)) and value > 20000:
        return (datetime(1899, 12, 30) + timedelta(days=float(value))).strftime("%Y-%m-%d")
    parsed = pd.to_datetime(value, errors="coerce")
    if pd.isna(parsed):
        return str(value).strip() or today_text()
    return parsed.strftime("%Y-%m-%d")


def make_code(value: str, prefix: str = "PRD") -> str:
    text = re.sub(r"[^A-Z0-9]+", "", str(value or "").upper())
    return (text or prefix)[:40]


def normalized_columns(df: pd.DataFrame) -> dict[str, str]:
    return {str(c).strip().upper(): c for c in df.columns}


def first_column(col_map: dict[str, str], *names: str):
    for name in names:
        key = name.strip().upper()
        if key in col_map:
            return col_map[key]
    return None


def default_master_sources() -> list[Path]:
    return [
        ROOT_DIR / "VENTAS 2026 CHILES MEXICOL.xlsx",
        ROOT_DIR / "VENTAS 2026.xlsx",
    ]


def read_master_sources() -> list[Path]:
    if CONFIG_PATH.exists():
        try:
            data = json.loads(CONFIG_PATH.read_text(encoding="utf-8"))
            configured = [Path(p) for p in data.get("master_sources", []) if p]
            existing = [p for p in configured if p.exists()]
            if existing:
                return existing
        except Exception:
            pass
    return default_master_sources()


def read_config() -> dict:
    if CONFIG_PATH.exists():
        try:
            data = json.loads(CONFIG_PATH.read_text(encoding="utf-8"))
            return data if isinstance(data, dict) else {}
        except Exception:
            return {}
    return {}


def write_config(data: dict):
    CONFIG_PATH.write_text(json.dumps(data, indent=2, ensure_ascii=False), encoding="utf-8")


def save_master_sources(paths: list[Path]):
    # Conserva cualquier otra preferencia de la aplicación y cambia solo la fuente activa.
    data = read_config()
    data["master_sources"] = [str(p) for p in paths]
    data["master_source_updated_at"] = datetime.now().isoformat(timespec="seconds")
    # Si no existe una carpeta vigilada, usar la carpeta de la fuente seleccionada.
    if paths and not data.get("source_watch_folder"):
        data["source_watch_folder"] = str(Path(paths[0]).resolve().parent)
    write_config(data)


def read_source_watch_folder() -> Path | None:
    data = read_config()
    raw = str(data.get("source_watch_folder", "") or "").strip()
    if raw:
        p = Path(raw)
        if p.exists() and p.is_dir():
            return p
    sources = [x for x in read_master_sources() if x.exists()]
    return sources[0].parent if sources else None


def save_source_watch_folder(folder: Path):
    data = read_config()
    data["source_watch_folder"] = str(Path(folder).resolve())
    data["source_watch_folder_updated_at"] = datetime.now().isoformat(timespec="seconds")
    write_config(data)


def _source_base_stem(path: Path) -> str:
    stem = path.stem
    # Evita nombres acumulativos al importar copias diarias o archivos de recuperación.
    stem = re.sub(r"_RECUPERACION_\d{6}$", "", stem, flags=re.I)
    stem = re.sub(r"_\d{4}-\d{2}-\d{2}$", "", stem)
    stem = re.sub(r"_ACTUALIZADA_\d{8}_?\d{0,6}$", "", stem, flags=re.I)
    return stem


def _version_date_from_name(path: Path):
    m = re.search(r"(20\d{2})[-_](\d{2})[-_](\d{2})", path.stem)
    if not m:
        m = re.search(r"(20\d{2})(\d{2})(\d{2})", path.stem)
    if m:
        try:
            return datetime(int(m.group(1)), int(m.group(2)), int(m.group(3)))
        except Exception:
            pass
    return None


def find_latest_source_version(folder: Path, active_source: Path | None = None) -> Path | None:
    folder = Path(folder)
    if not folder.exists():
        return None
    extensions = {".xlsx", ".xlsm", ".xls", ".xlsb"}
    files = [p for p in folder.iterdir() if p.is_file() and p.suffix.lower() in extensions and not p.name.startswith("~$")]
    # También revisar la subcarpeta de copias diarias.
    daily = folder / "copias_diarias"
    if daily.exists():
        files.extend([p for p in daily.iterdir() if p.is_file() and p.suffix.lower() in extensions and not p.name.startswith("~$")])
    if not files:
        return None
    if active_source is not None:
        base = _source_base_stem(active_source).lower()
        related = [p for p in files if _source_base_stem(p).lower().startswith(base) or base.startswith(_source_base_stem(p).lower())]
        if related:
            files = related
    def key(p: Path):
        d = _version_date_from_name(p)
        return (d.timestamp() if d else 0.0, p.stat().st_mtime)
    return max(files, key=key)



# ==================== V10.1.8 BACKUP SQLITE TEMPRANO ====================
def _v995_backup_database_file(db_path: Path) -> Path | None:
    """Crea una copia SQLite automática al abrir la aplicación."""
    db_path = Path(db_path)
    if not db_path.exists():
        return None

    backup_dir = db_path.parent / "respaldos_db"
    backup_dir.mkdir(parents=True, exist_ok=True)

    stamp = datetime.now().strftime("%Y%m%d_%H%M%S")
    target = backup_dir / f"{db_path.stem}_{stamp}.db"
    counter = 1
    while target.exists():
        target = backup_dir / f"{db_path.stem}_{stamp}_{counter:02d}.db"
        counter += 1

    shutil.copy2(db_path, target)

    try:
        backups = sorted(
            [p for p in backup_dir.glob(f"{db_path.stem}_*.db") if p.is_file()],
            key=lambda p: p.stat().st_mtime,
            reverse=True,
        )
        for old in backups[60:]:
            try:
                old.unlink()
            except Exception:
                pass
    except Exception:
        pass

    return target
# ==================== FIN BACKUP SQLITE TEMPRANO ====================

class SalesStore:
    def __init__(self, path: Path = DB_PATH):
        self.path = path
        if path.exists():
            try:
                _v995_backup_database_file(path)
            except Exception:
                # El respaldo nunca debe impedir que la aplicación abra.
                pass
        self.conn = sqlite3.connect(path)
        self.conn.row_factory = sqlite3.Row
        self.init_schema()

    def init_schema(self):
        cur = self.conn.cursor()
        cur.executescript(
            """
            CREATE TABLE IF NOT EXISTS ventas (
                cuenta_cobro TEXT PRIMARY KEY,
                fecha TEXT NOT NULL,
                cliente TEXT NOT NULL,
                estado_venta TEXT NOT NULL DEFAULT 'EMITIDA',
                fecha_vencimiento TEXT,
                asesor TEXT,
                cta_bancaria TEXT,
                direccion TEXT,
                ciudad_entrega TEXT,
                barrio_entrega TEXT,
                local_edificio TEXT,
                datos_entrega TEXT,
                telefono_cliente TEXT,
                estado_pago TEXT NOT NULL DEFAULT 'Pendiente',
                domicilio_empresa REAL NOT NULL DEFAULT 0,
                domicilio_cliente REAL NOT NULL DEFAULT 0,
                forma_pago TEXT,
                observacion_logistica TEXT
            );

            CREATE TABLE IF NOT EXISTS ventas_detalle (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                cuenta_cobro TEXT NOT NULL,
                item INTEGER NOT NULL,
                producto TEXT NOT NULL,
                cantidad_kls REAL NOT NULL DEFAULT 0,
                valor_x_kl REAL NOT NULL DEFAULT 0,
                valor_total REAL NOT NULL DEFAULT 0,
                comision_unitaria REAL NOT NULL DEFAULT 0,
                comision REAL NOT NULL DEFAULT 0,
                iva_19 REAL NOT NULL DEFAULT 0,
                retenciones REAL NOT NULL DEFAULT 0,
                chile_fresco REAL NOT NULL DEFAULT 0,
                domicilio REAL NOT NULL DEFAULT 0,
                FOREIGN KEY(cuenta_cobro) REFERENCES ventas(cuenta_cobro)
            );

            CREATE TABLE IF NOT EXISTS abonos (
                id_abono TEXT PRIMARY KEY,
                fecha_abono TEXT NOT NULL,
                cliente TEXT NOT NULL,
                medio_pago TEXT NOT NULL,
                cta_bancaria_destino TEXT,
                referencia_pago TEXT,
                valor_abono REAL NOT NULL DEFAULT 0,
                soporte TEXT,
                observacion_control TEXT
            );

            CREATE TABLE IF NOT EXISTS aplicacion_abonos (
                id_aplicacion INTEGER PRIMARY KEY AUTOINCREMENT,
                id_abono TEXT NOT NULL,
                cuenta_cobro TEXT NOT NULL,
                fecha_aplicacion TEXT NOT NULL,
                orden_aplicacion INTEGER NOT NULL DEFAULT 1,
                valor_aplicado REAL NOT NULL DEFAULT 0,
                observacion_aplicacion TEXT,
                FOREIGN KEY(id_abono) REFERENCES abonos(id_abono),
                FOREIGN KEY(cuenta_cobro) REFERENCES ventas(cuenta_cobro)
            );

            CREATE TABLE IF NOT EXISTS clientes (
                nombre TEXT PRIMARY KEY,
                ciudad TEXT,
                direccion TEXT,
                telefono TEXT,
                email TEXT,
                notas TEXT
            );

            CREATE TABLE IF NOT EXISTS productos (
                codigo TEXT PRIMARY KEY,
                nombre TEXT NOT NULL UNIQUE,
                unidad TEXT NOT NULL DEFAULT 'KLS',
                precio_venta REAL NOT NULL DEFAULT 0,
                comision_unitaria_sugerida REAL NOT NULL DEFAULT 0,
                costo REAL NOT NULL DEFAULT 0,
                stock_actual REAL NOT NULL DEFAULT 0,
                stock_minimo REAL NOT NULL DEFAULT 0,
                activo TEXT NOT NULL DEFAULT 'SI'
            );

            CREATE TABLE IF NOT EXISTS cotizaciones (
                numero_cotizacion TEXT PRIMARY KEY,
                fecha TEXT NOT NULL,
                valida_hasta TEXT,
                cliente TEXT NOT NULL,
                asesor TEXT,
                direccion TEXT,
                ciudad TEXT,
                telefono TEXT,
                estado TEXT NOT NULL DEFAULT 'BORRADOR',
                forma_pago TEXT,
                domicilio REAL NOT NULL DEFAULT 0,
                observaciones TEXT,
                cuenta_cobro_convertida TEXT,
                fecha_conversion TEXT
            );

            CREATE TABLE IF NOT EXISTS cotizaciones_detalle (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                numero_cotizacion TEXT NOT NULL,
                item INTEGER NOT NULL,
                producto TEXT NOT NULL,
                cantidad REAL NOT NULL DEFAULT 0,
                precio_unitario REAL NOT NULL DEFAULT 0,
                descuento REAL NOT NULL DEFAULT 0,
                subtotal REAL NOT NULL DEFAULT 0,
                iva REAL NOT NULL DEFAULT 0,
                total REAL NOT NULL DEFAULT 0,
                FOREIGN KEY(numero_cotizacion) REFERENCES cotizaciones(numero_cotizacion)
            );

            CREATE TABLE IF NOT EXISTS historial_cambios (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                fecha_hora TEXT NOT NULL,
                tipo_documento TEXT NOT NULL,
                documento TEXT NOT NULL,
                accion TEXT NOT NULL,
                campo TEXT NOT NULL,
                valor_anterior TEXT,
                valor_nuevo TEXT
            );

            CREATE TABLE IF NOT EXISTS fuentes_datos (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                ruta TEXT NOT NULL,
                nombre_archivo TEXT NOT NULL,
                tipo TEXT NOT NULL DEFAULT 'EXCEL',
                fecha_importacion TEXT NOT NULL,
                activa INTEGER NOT NULL DEFAULT 1,
                clientes_importados INTEGER NOT NULL DEFAULT 0,
                productos_importados INTEGER NOT NULL DEFAULT 0,
                ventas_importadas INTEGER NOT NULL DEFAULT 0,
                observacion TEXT
            );
            """
        )
        self.ensure_column("cotizaciones", "domicilio_empresa", "REAL NOT NULL DEFAULT 0")
        self.ensure_column("cotizaciones", "domicilio_cliente", "REAL NOT NULL DEFAULT 0")
        self.ensure_column("cotizaciones", "barrio", "TEXT")
        self.ensure_column("cotizaciones", "local_edificio", "TEXT")
        self.ensure_column("cotizaciones", "datos_entrega", "TEXT")
        # Migración compatible: las cotizaciones antiguas usaban un único campo domicilio.
        self.conn.execute(
            "UPDATE cotizaciones SET domicilio_cliente = COALESCE(domicilio, 0) "
            "WHERE COALESCE(domicilio_cliente, 0) = 0 AND COALESCE(domicilio, 0) <> 0"
        )
        self.ensure_column("ventas", "direccion", "TEXT")
        self.ensure_column("ventas", "ciudad_entrega", "TEXT")
        self.ensure_column("ventas", "barrio_entrega", "TEXT")
        self.ensure_column("ventas", "local_edificio", "TEXT")
        self.ensure_column("ventas", "datos_entrega", "TEXT")
        self.ensure_column("ventas", "telefono_cliente", "TEXT")
        self.ensure_column("ventas", "estado_pago", "TEXT NOT NULL DEFAULT 'Pendiente'")
        self.ensure_column("ventas", "domicilio_empresa", "REAL NOT NULL DEFAULT 0")
        self.ensure_column("ventas", "domicilio_cliente", "REAL NOT NULL DEFAULT 0")
        self.ensure_column("ventas", "forma_pago", "TEXT")
        self.ensure_column("ventas", "recibido_por", "TEXT")
        self.ensure_column("ventas", "factura_electronica", "TEXT")
        self.ensure_column("ventas", "fecha_factura_electronica", "TEXT")
        self.ensure_column("ventas", "cotizacion_origen", "TEXT")
        self.ensure_column("ventas", "fuente_origen", "TEXT")
        self.ensure_column("ventas", "ultima_modificacion", "TEXT")
        self.ensure_column("ventas", "modificado_manualmente", "INTEGER NOT NULL DEFAULT 0")
        self.ensure_column("clientes", "direccion", "TEXT")
        self.ensure_column("clientes", "fuente_origen", "TEXT")
        self.ensure_column("clientes", "ultima_modificacion", "TEXT")
        self.ensure_column("clientes", "modificado_manualmente", "INTEGER NOT NULL DEFAULT 0")
        self.ensure_column("productos", "comision_unitaria_sugerida", "REAL NOT NULL DEFAULT 0")
        self.ensure_column("ventas_detalle", "comision_unitaria", "REAL NOT NULL DEFAULT 0")
        self.ensure_column("productos", "fuente_origen", "TEXT")
        self.ensure_column("productos", "ultima_modificacion", "TEXT")
        self.ensure_column("productos", "modificado_manualmente", "INTEGER NOT NULL DEFAULT 0")
        self.conn.commit()
        self.seed_master_data()
        self.normalize_product_codes()

    def ensure_column(self, table: str, column: str, definition: str):
        columns = {
            row["name"]
            for row in self.conn.execute(f"PRAGMA table_info({table})").fetchall()
        }
        if column not in columns:
            self.conn.execute(f"ALTER TABLE {table} ADD COLUMN {column} {definition}")

    def seed_master_data(self):
        clientes, productos = load_master_records()
        self.import_master_records(clientes, productos)

    def import_master_records(self, clientes: list[dict], productos: list[dict], source_path: str = ""):
        stamp = datetime.now().isoformat(timespec="seconds")
        source_label = str(source_path or "").strip()
        for cliente in clientes:
            self.conn.execute(
                """
                INSERT INTO clientes (nombre, ciudad, direccion, telefono, email, notas, fuente_origen, ultima_modificacion, modificado_manualmente)
                VALUES (?, ?, ?, ?, ?, ?, ?, ?, 0)
                ON CONFLICT(nombre) DO UPDATE SET
                    ciudad=excluded.ciudad, direccion=excluded.direccion, telefono=excluded.telefono,
                    email=excluded.email, notas=excluded.notas,
                    fuente_origen=CASE WHEN excluded.fuente_origen <> '' THEN excluded.fuente_origen ELSE clientes.fuente_origen END,
                    ultima_modificacion=excluded.ultima_modificacion, modificado_manualmente=0
                """,
                (
                    cliente.get("nombre", ""), cliente.get("ciudad", ""), cliente.get("direccion", ""),
                    cliente.get("telefono", ""), cliente.get("email", ""), cliente.get("notas", ""),
                    source_label or cliente.get("fuente_origen", ""), stamp,
                ),
            )
        for producto in productos:
            self.conn.execute(
                """
                INSERT INTO productos (
                    codigo, nombre, unidad, precio_venta, comision_unitaria_sugerida, costo, stock_actual, stock_minimo, activo,
                    fuente_origen, ultima_modificacion, modificado_manualmente
                ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 0)
                ON CONFLICT(codigo) DO UPDATE SET
                    nombre=excluded.nombre, unidad=excluded.unidad, precio_venta=excluded.precio_venta,
                    comision_unitaria_sugerida=CASE WHEN productos.modificado_manualmente=1 THEN productos.comision_unitaria_sugerida ELSE excluded.comision_unitaria_sugerida END,
                    costo=excluded.costo, stock_actual=excluded.stock_actual, stock_minimo=excluded.stock_minimo,
                    activo=excluded.activo,
                    fuente_origen=CASE WHEN excluded.fuente_origen <> '' THEN excluded.fuente_origen ELSE productos.fuente_origen END,
                    ultima_modificacion=excluded.ultima_modificacion, modificado_manualmente=0
                """,
                (
                    producto.get("codigo", ""), producto.get("nombre", ""), producto.get("unidad", "KLS"),
                    float(producto.get("precio_venta", 0) or 0), float(producto.get("comision_unitaria_sugerida", 0) or 0),
                    float(producto.get("costo", 0) or 0), float(producto.get("stock_actual", 0) or 0), float(producto.get("stock_minimo", 0) or 0),
                    producto.get("activo", "SI"), source_label or producto.get("fuente_origen", ""), stamp,
                ),
            )
        self.conn.commit()

    def register_source_import(self, path: Path, clientes: int, productos: int, ventas: int, observacion: str = ""):
        self.conn.execute("UPDATE fuentes_datos SET activa = 0")
        self.conn.execute(
            """INSERT INTO fuentes_datos (ruta, nombre_archivo, fecha_importacion, activa, clientes_importados, productos_importados, ventas_importadas, observacion)
               VALUES (?, ?, ?, 1, ?, ?, ?, ?)""",
            (str(path), path.name, datetime.now().isoformat(timespec="seconds"), int(clientes), int(productos), int(ventas), observacion),
        )
        self.conn.commit()

    def source_history(self) -> pd.DataFrame:
        return self.table("SELECT * FROM fuentes_datos ORDER BY id DESC")

    def import_sales_history(self, sales: list[dict]) -> dict[str, int]:
        invoices = 0
        details = 0
        payments = 0
        for sale_pack in sales:
            sale = sale_pack["sale"]
            detail_rows = sale_pack.get("details", [])
            payment_rows = sale_pack.get("payments", [])
            if not sale.get("cuenta_cobro") or not sale.get("cliente") or not detail_rows:
                continue
            self.ensure_cliente(sale["cliente"])
            self.upsert_sale(sale)
            self.replace_sale_details(sale["cuenta_cobro"], detail_rows)
            self.replace_sale_payments(sale, payment_rows)
            invoices += 1
            details += len(detail_rows)
            payments += len(payment_rows)
        return {"facturas": invoices, "detalles": details, "abonos": payments}

    def normalize_product_codes(self):
        rows = self.conn.execute("SELECT codigo, nombre FROM productos ORDER BY nombre").fetchall()
        used = {row["codigo"] for row in rows}
        for row in rows:
            current = str(row["codigo"] or "")
            normalized = make_code(row["nombre"])
            if current == normalized and current.isalnum():
                continue
            candidate = normalized
            counter = 2
            while candidate in used and candidate != current:
                suffix = str(counter)
                candidate = f"{normalized[:40 - len(suffix)]}{suffix}"
                counter += 1
            self.conn.execute("UPDATE productos SET codigo = ? WHERE codigo = ?", (candidate, current))
            used.discard(current)
            used.add(candidate)
        self.conn.commit()

    def upsert_cliente(self, data: dict):
        stamp = datetime.now().isoformat(timespec="seconds")
        self.conn.execute(
            """
            INSERT INTO clientes (nombre, ciudad, direccion, telefono, email, notas, fuente_origen, ultima_modificacion, modificado_manualmente)
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, 1)
            ON CONFLICT(nombre) DO UPDATE SET
                ciudad=excluded.ciudad, direccion=excluded.direccion, telefono=excluded.telefono,
                email=excluded.email, notas=excluded.notas,
                ultima_modificacion=excluded.ultima_modificacion, modificado_manualmente=1
            """,
            (data["nombre"], data.get("ciudad", ""), data.get("direccion", ""), data.get("telefono", ""),
             data.get("email", ""), data.get("notas", ""), data.get("fuente_origen", "Creado en la app"), stamp),
        )
        self.conn.commit()

    def ensure_cliente(self, nombre: str):
        nombre = str(nombre or "").strip()
        if not nombre:
            return
        self.conn.execute(
            "INSERT OR IGNORE INTO clientes (nombre, ciudad, direccion, telefono, email, notas, fuente_origen, ultima_modificacion, modificado_manualmente) VALUES (?, '', '', '', '', 'Creado desde formulario', 'Creado en la app', ?, 1)",
            (nombre, datetime.now().isoformat(timespec="seconds")),
        )
        self.conn.commit()

    def rename_client(self, old_name: str, new_name: str):
        old_name = str(old_name or "").strip()
        new_name = str(new_name or "").strip()
        if not old_name or not new_name or old_name == new_name:
            return
        exists = self.conn.execute("SELECT 1 FROM clientes WHERE nombre = ?", (new_name,)).fetchone()
        if exists:
            raise ValueError(f"Ya existe un cliente llamado '{new_name}'.")
        self.conn.execute("UPDATE clientes SET nombre=?, ultima_modificacion=?, modificado_manualmente=1 WHERE nombre=?",
                          (new_name, datetime.now().isoformat(timespec="seconds"), old_name))
        self.conn.execute("UPDATE ventas SET cliente=?, ultima_modificacion=?, modificado_manualmente=1 WHERE cliente=?",
                          (new_name, datetime.now().isoformat(timespec="seconds"), old_name))
        self.conn.execute("UPDATE abonos SET cliente=? WHERE cliente=?", (new_name, old_name))
        self.conn.execute("UPDATE cotizaciones SET cliente=? WHERE cliente=?", (new_name, old_name))
        self.conn.commit()

    def upsert_producto(self, data: dict):
        codigo = data.get("codigo", "").strip() or make_code(data["nombre"])
        self.conn.execute(
            """
            INSERT INTO productos (
                codigo, nombre, unidad, precio_venta, comision_unitaria_sugerida, costo, stock_actual, stock_minimo, activo,
                fuente_origen, ultima_modificacion, modificado_manualmente
            )
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 1)
            ON CONFLICT(codigo) DO UPDATE SET
                nombre=excluded.nombre, unidad=excluded.unidad, precio_venta=excluded.precio_venta,
                comision_unitaria_sugerida=excluded.comision_unitaria_sugerida,
                costo=excluded.costo, stock_actual=excluded.stock_actual, stock_minimo=excluded.stock_minimo,
                activo=excluded.activo, ultima_modificacion=excluded.ultima_modificacion, modificado_manualmente=1
            """,
            (
                codigo,
                data["nombre"],
                data.get("unidad", "KLS"),
                float(data.get("precio_venta", 0) or 0),
                float(data.get("comision_unitaria_sugerida", 0) or 0),
                float(data.get("costo", 0) or 0),
                float(data.get("stock_actual", 0) or 0),
                float(data.get("stock_minimo", 0) or 0),
                data.get("activo", "SI"),
                data.get("fuente_origen", "Creado en la app"),
                datetime.now().isoformat(timespec="seconds"),
            ),
        )
        self.conn.commit()

    def clientes(self) -> pd.DataFrame:
        return self.table("SELECT * FROM clientes ORDER BY nombre")

    def productos(self) -> pd.DataFrame:
        return self.table("SELECT * FROM productos ORDER BY nombre")

    def upsert_sale(self, data: dict):
        self.conn.execute(
            """
            INSERT INTO ventas (
                cuenta_cobro, fecha, cliente, estado_venta, fecha_vencimiento,
                asesor, cta_bancaria, direccion, ciudad_entrega, barrio_entrega,
                local_edificio, datos_entrega, telefono_cliente, estado_pago,
                domicilio_empresa, domicilio_cliente, forma_pago, recibido_por, observacion_logistica,
                factura_electronica, fecha_factura_electronica, cotizacion_origen,
                fuente_origen, ultima_modificacion, modificado_manualmente
            )
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            ON CONFLICT(cuenta_cobro) DO UPDATE SET
                fecha=excluded.fecha, cliente=excluded.cliente, estado_venta=excluded.estado_venta,
                fecha_vencimiento=excluded.fecha_vencimiento, asesor=excluded.asesor,
                cta_bancaria=excluded.cta_bancaria, direccion=excluded.direccion,
                ciudad_entrega=excluded.ciudad_entrega, barrio_entrega=excluded.barrio_entrega,
                local_edificio=excluded.local_edificio, datos_entrega=excluded.datos_entrega,
                telefono_cliente=excluded.telefono_cliente, estado_pago=excluded.estado_pago,
                domicilio_empresa=excluded.domicilio_empresa, domicilio_cliente=excluded.domicilio_cliente,
                forma_pago=excluded.forma_pago, recibido_por=excluded.recibido_por, observacion_logistica=excluded.observacion_logistica,
                factura_electronica=excluded.factura_electronica,
                fecha_factura_electronica=excluded.fecha_factura_electronica,
                cotizacion_origen=excluded.cotizacion_origen,
                fuente_origen=CASE WHEN excluded.fuente_origen <> '' THEN excluded.fuente_origen ELSE ventas.fuente_origen END,
                ultima_modificacion=excluded.ultima_modificacion,
                modificado_manualmente=excluded.modificado_manualmente
            """,
            (
                data["cuenta_cobro"], data["fecha"], data["cliente"], data["estado_venta"],
                data.get("fecha_vencimiento", ""), data.get("asesor", ""), data.get("cta_bancaria", ""),
                data.get("direccion", ""), data.get("ciudad_entrega", ""), data.get("barrio_entrega", ""),
                data.get("local_edificio", ""), data.get("datos_entrega", ""), data.get("telefono_cliente", ""),
                data.get("estado_pago", "Pendiente"), data.get("domicilio_empresa", 0),
                data.get("domicilio_cliente", 0), data.get("forma_pago", ""), data.get("recibido_por", ""),
                data.get("observacion_logistica", ""), data.get("factura_electronica", ""),
                data.get("fecha_factura_electronica", ""), data.get("cotizacion_origen", ""),
                data.get("fuente_origen", "Creado en la app"), datetime.now().isoformat(timespec="seconds"),
                int(data.get("modificado_manualmente", 1)),
            ),
        )
        self.conn.commit()

    def add_detail(self, data: dict):
        current = self.conn.execute(
            "SELECT COALESCE(MAX(item), 0) + 1 FROM ventas_detalle WHERE cuenta_cobro = ?",
            (data["cuenta_cobro"],),
        ).fetchone()[0]
        self.conn.execute(
            """
            INSERT INTO ventas_detalle (
                cuenta_cobro, item, producto, cantidad_kls, valor_x_kl,
                valor_total, comision_unitaria, comision, iva_19, retenciones, chile_fresco, domicilio
            )
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                data["cuenta_cobro"],
                current,
                data["producto"],
                data["cantidad_kls"],
                data["valor_x_kl"],
                data["valor_total"],
                data.get("comision_unitaria", 0),
                data.get("comision", 0),
                data.get("iva_19", 0),
                data.get("retenciones", 0),
                data.get("chile_fresco", 0),
                data.get("domicilio", 0),
            ),
        )
        self.conn.commit()

    def replace_sale_detail(self, data: dict):
        self.conn.execute("DELETE FROM ventas_detalle WHERE cuenta_cobro = ?", (data["cuenta_cobro"],))
        self.conn.commit()
        self.add_detail(data)

    def replace_sale_details(self, cuenta_cobro: str, details: list[dict]):
        self.conn.execute("DELETE FROM ventas_detalle WHERE cuenta_cobro = ?", (cuenta_cobro,))
        self.conn.commit()
        for detail in details:
            payload = dict(detail)
            payload["cuenta_cobro"] = cuenta_cobro
            self.add_detail(payload)

    def replace_sale_payments(self, sale: dict, payments: list[dict]):
        cuenta_cobro = sale["cuenta_cobro"]
        old = self.conn.execute(
            "SELECT id_abono FROM aplicacion_abonos WHERE cuenta_cobro = ?",
            (cuenta_cobro,),
        ).fetchall()
        old_ids = [row["id_abono"] for row in old]
        self.conn.execute("DELETE FROM aplicacion_abonos WHERE cuenta_cobro = ?", (cuenta_cobro,))
        for id_abono in old_ids:
            still_used = self.conn.execute(
                "SELECT 1 FROM aplicacion_abonos WHERE id_abono = ? LIMIT 1",
                (id_abono,),
            ).fetchone()
            if not still_used:
                self.conn.execute("DELETE FROM abonos WHERE id_abono = ?", (id_abono,))
        self.conn.commit()

        safe_invoice = make_code(cuenta_cobro, "VENTA")
        for idx, payment in enumerate(payments, start=1):
            id_abono = f"PAY-{safe_invoice}-{idx:02d}"
            valor = float(payment.get("valor_abono", 0) or 0)
            if valor <= 0:
                continue
            self.upsert_abono(
                {
                    "id_abono": id_abono,
                    "fecha_abono": payment.get("fecha_abono") or sale["fecha"],
                    "cliente": sale["cliente"],
                    "medio_pago": payment.get("medio_pago", ""),
                    "cta_bancaria_destino": payment.get("cta_bancaria_destino", ""),
                    "referencia_pago": payment.get("referencia_pago", ""),
                    "valor_abono": valor,
                    "soporte": payment.get("referencia_pago", ""),
                    "observacion_control": "Registrado desde venta",
                }
            )
            self.add_application(
                {
                    "id_abono": id_abono,
                    "cuenta_cobro": cuenta_cobro,
                    "fecha_aplicacion": payment.get("fecha_abono") or sale["fecha"],
                    "valor_aplicado": valor,
                    "observacion_aplicacion": "Aplicacion automatica desde forma de pago",
                }
            )

    def next_abono_id(self) -> str:
        row = self.conn.execute("SELECT COUNT(*) + 1 FROM abonos").fetchone()
        return f"ABN-{int(row[0]):05d}"

    def upsert_abono(self, data: dict):
        self.conn.execute(
            """
            INSERT INTO abonos (
                id_abono, fecha_abono, cliente, medio_pago, cta_bancaria_destino,
                referencia_pago, valor_abono, soporte, observacion_control
            )
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
            ON CONFLICT(id_abono) DO UPDATE SET
                fecha_abono=excluded.fecha_abono,
                cliente=excluded.cliente,
                medio_pago=excluded.medio_pago,
                cta_bancaria_destino=excluded.cta_bancaria_destino,
                referencia_pago=excluded.referencia_pago,
                valor_abono=excluded.valor_abono,
                soporte=excluded.soporte,
                observacion_control=excluded.observacion_control
            """,
            (
                data["id_abono"],
                data["fecha_abono"],
                data["cliente"],
                data["medio_pago"],
                data.get("cta_bancaria_destino", ""),
                data.get("referencia_pago", ""),
                data["valor_abono"],
                data.get("soporte", ""),
                data.get("observacion_control", ""),
            ),
        )
        self.conn.commit()

    def add_application(self, data: dict):
        current = self.conn.execute(
            "SELECT COALESCE(MAX(orden_aplicacion), 0) + 1 FROM aplicacion_abonos WHERE id_abono = ?",
            (data["id_abono"],),
        ).fetchone()[0]
        self.conn.execute(
            """
            INSERT INTO aplicacion_abonos (
                id_abono, cuenta_cobro, fecha_aplicacion, orden_aplicacion,
                valor_aplicado, observacion_aplicacion
            )
            VALUES (?, ?, ?, ?, ?, ?)
            """,
            (
                data["id_abono"],
                data["cuenta_cobro"],
                data["fecha_aplicacion"],
                current,
                data["valor_aplicado"],
                data.get("observacion_aplicacion", ""),
            ),
        )
        self.conn.commit()

    def table(self, query: str, params=()) -> pd.DataFrame:
        return pd.read_sql_query(query, self.conn, params=params)

    def sales_summary(self) -> pd.DataFrame:
        return self.table(
            """
            SELECT
                v.cuenta_cobro,
                v.fecha,
                v.cliente,
                v.estado_venta,
                v.fuente_origen,
                COALESCE(SUM(d.valor_total + d.iva_19 + d.retenciones + d.chile_fresco), 0)
                    + COALESCE(v.domicilio_cliente, 0) AS total_factura,
                COALESCE((
                    SELECT SUM(a.valor_aplicado)
                    FROM aplicacion_abonos a
                    WHERE a.cuenta_cobro = v.cuenta_cobro
                ), 0) AS total_abonos
            FROM ventas v
            LEFT JOIN ventas_detalle d ON d.cuenta_cobro = v.cuenta_cobro
            GROUP BY v.cuenta_cobro, v.fecha, v.cliente, v.estado_venta, v.fuente_origen, v.domicilio_empresa, v.domicilio_cliente
            ORDER BY v.fecha DESC, v.cuenta_cobro DESC
            """
        )

    def export_invoice_print(self, cuenta_cobro: str, output_path: Path | None = None) -> Path:
        """Genera una cuenta de cobro MXPC con logo embebido y formato comercial."""
        sale_df = self.table("SELECT * FROM ventas WHERE cuenta_cobro = ?", (cuenta_cobro,))
        if sale_df.empty:
            raise ValueError(f"No existe la cuenta de cobro {cuenta_cobro}.")

        details = self.table(
            "SELECT * FROM ventas_detalle WHERE cuenta_cobro = ? ORDER BY item",
            (cuenta_cobro,),
        )
        applications = self.table(
            """
            SELECT a.fecha_aplicacion, b.medio_pago, b.cta_bancaria_destino,
                   b.referencia_pago, a.valor_aplicado
            FROM aplicacion_abonos a
            LEFT JOIN abonos b ON b.id_abono = a.id_abono
            WHERE a.cuenta_cobro = ?
            ORDER BY a.fecha_aplicacion, a.orden_aplicacion
            """,
            (cuenta_cobro,),
        )
        sale = sale_df.iloc[0]

        if output_path is None:
            PRINT_DIR.mkdir(parents=True, exist_ok=True)
            safe_invoice = make_code(cuenta_cobro, "FACTURA")
            output_path = PRINT_DIR / f"Cuenta_cobro_{safe_invoice}.xlsx"
        else:
            output_path.parent.mkdir(parents=True, exist_ok=True)

        product_total = float(details["valor_total"].fillna(0).sum()) if not details.empty else 0.0
        total_iva = float(details["iva_19"].fillna(0).sum()) if not details.empty else 0.0
        total_ret = money(sale.get("retencion_venta", 0))
        total_comision = float(details["comision"].fillna(0).sum()) if not details.empty else 0.0
        domicilio_cliente = money(sale.get("domicilio_cliente", 0))
        subtotal_facturable = product_total + domicilio_cliente
        total_factura = subtotal_facturable + total_iva
        total_pagado = (float(applications["valor_aplicado"].fillna(0).sum()) if not applications.empty else 0.0) + total_ret
        saldo = total_factura - total_pagado

        product_units = {}
        try:
            prod_df = self.productos()
            if not prod_df.empty:
                product_units = {
                    str(r["nombre"]).strip(): str(r.get("unidad", "") or "").strip()
                    for _, r in prod_df.iterrows()
                }
        except Exception:
            product_units = {}

        with pd.ExcelWriter(output_path, engine="xlsxwriter", date_format="yyyy-mm-dd") as writer:
            wb = writer.book
            ws = wb.add_worksheet("Cuenta de cobro")
            writer.sheets["Cuenta de cobro"] = ws

            # Identidad visual inspirada en la plantilla histórica de MXPC.
            green = "#155A3A"
            green_dark = "#103F2B"
            yellow = "#EFC96B"
            cream = "#F8F2E5"
            light_green = "#E7F1EC"
            border_color = "#4B4B4B"
            white = "#FFFFFF"

            base_border = {"border": 1, "border_color": border_color}
            fmt_logo_box = wb.add_format({**base_border, "bg_color": white})
            fmt_doc_label = wb.add_format({**base_border, "bold": True, "font_size": 10, "bg_color": green, "font_color": white, "align": "center", "valign": "vcenter"})
            fmt_doc_value = wb.add_format({**base_border, "bold": True, "font_size": 12, "bg_color": cream, "align": "center", "valign": "vcenter"})
            fmt_section = wb.add_format({**base_border, "bold": True, "font_size": 10, "bg_color": green, "font_color": white, "align": "center", "valign": "vcenter"})
            fmt_block = wb.add_format({**base_border, "font_size": 9, "text_wrap": True, "valign": "vcenter"})
            fmt_provider_bold = wb.add_format({**base_border, "bold": True, "font_size": 9, "text_wrap": True, "valign": "vcenter"})
            fmt_head = wb.add_format({**base_border, "bold": True, "font_size": 9, "bg_color": yellow, "align": "center", "valign": "vcenter", "text_wrap": True})
            fmt_cell = wb.add_format({**base_border, "font_size": 9, "valign": "vcenter", "text_wrap": True})
            fmt_qty = wb.add_format({**base_border, "font_size": 9, "num_format": "#,##0.##", "align": "center", "valign": "vcenter"})
            fmt_money = wb.add_format({**base_border, "font_size": 9, "num_format": "$#,##0;[Red]-$#,##0", "align": "right", "valign": "vcenter"})
            fmt_total_label = wb.add_format({**base_border, "bold": True, "font_size": 9, "bg_color": cream, "align": "right", "valign": "vcenter"})
            fmt_total_money = wb.add_format({**base_border, "bold": True, "font_size": 10, "bg_color": cream, "num_format": "$#,##0;[Red]-$#,##0", "align": "right", "valign": "vcenter"})
            fmt_grand_label = wb.add_format({**base_border, "bold": True, "font_size": 10, "bg_color": green, "font_color": white, "align": "right", "valign": "vcenter"})
            fmt_grand_money = wb.add_format({**base_border, "bold": True, "font_size": 11, "bg_color": green, "font_color": white, "num_format": "$#,##0;[Red]-$#,##0", "align": "right", "valign": "vcenter"})
            fmt_pay_title = wb.add_format({**base_border, "bold": True, "font_size": 9, "bg_color": light_green, "align": "left", "valign": "vcenter"})
            fmt_pay_text = wb.add_format({**base_border, "font_size": 9, "text_wrap": True, "valign": "top"})
            fmt_received_label = wb.add_format({**base_border, "bold": True, "font_size": 9, "bg_color": cream, "valign": "vcenter"})
            fmt_received_value = wb.add_format({**base_border, "font_size": 9, "valign": "vcenter"})
            fmt_obs_label = wb.add_format({**base_border, "bold": True, "font_size": 9, "bg_color": cream, "valign": "top"})
            fmt_obs = wb.add_format({**base_border, "font_size": 9, "text_wrap": True, "valign": "top"})
            fmt_thanks = wb.add_format({"italic": True, "font_size": 9, "font_color": green_dark, "align": "center", "valign": "vcenter"})
            fmt_small = wb.add_format({"font_size": 8, "font_color": "#555555", "text_wrap": True})

            # Tamaño de impresión y columnas.
            # Cabecera más amplia para que el logo MXPC tenga presencia similar
            # al formato histórico de cuenta de cobro.
            ws.set_column("A:A", 13)
            ws.set_column("B:B", 18)
            ws.set_column("C:C", 25)
            ws.set_column("D:D", 13)
            ws.set_column("E:E", 16)
            ws.set_column("F:F", 17)
            ws.set_landscape()
            ws.set_paper(9)  # A4
            ws.fit_to_pages(1, 1)
            ws.set_margins(0.28, 0.28, 0.35, 0.35)
            ws.hide_gridlines(2)
            ws.center_horizontally()

            # Cabecera: logo embebido + identificación del documento.
            ws.set_row(0, 36)
            ws.set_row(1, 36)
            ws.set_row(2, 34)
            ws.set_row(3, 34)
            ws.merge_range("A1:C4", "", fmt_logo_box)
            logo_stream = mxpc_logo_image_data_excel_large()
            try:
                ws.insert_image(
                    "A1",
                    "mxpc_logo.png",
                    {
                        "image_data": logo_stream,
                        # Logo grande, centrado y contenido dentro de A1:C4.
                        # El bloque izquierdo se amplía para reproducir la proporción
                        # del formato histórico mostrado por el usuario.
                        # Se reduce ligeramente respecto a V9.8.3 y se centra mejor
                        # dentro del bloque A1:C4, sin invadir la columna D.
                        "x_scale": 1.08,
                        "y_scale": 1.08,
                        "x_offset": 58,
                        "y_offset": 70,
                        "object_position": 1,
                    },
                )
            except Exception:
                # El documento sigue siendo válido aunque un motor de Excel externo falle al leer imágenes.
                pass

            ws.merge_range("D1:E2", "CUENTA DE COBRO No.", fmt_doc_label)
            ws.merge_range("F1:F2", str(cuenta_cobro), fmt_doc_value)
            ws.merge_range("D3:E4", "FECHA", fmt_doc_label)
            ws.merge_range("F3:F4", str(sale.get("fecha", "") or ""), fmt_doc_value)

            # Datos del cliente y proveedor, completamente enmarcados.
            ws.merge_range("A6:C6", "CLIENTE", fmt_section)
            ws.merge_range("D6:F6", "PROVEEDOR", fmt_section)

            client_rows = [
                ("Nombre", str(sale.get("cliente", "") or "")),
                ("Dirección", str(sale.get("direccion", "") or "")),
                ("Barrio", str(sale.get("barrio_entrega", "") or "")),
                ("Local / Edificio", str(sale.get("local_edificio", "") or "")),
                ("Teléfono", str(sale.get("telefono_cliente", "") or "")),
                ("Ciudad", str(sale.get("ciudad_entrega", "") or "")),
            ]
            provider_rows = [
                "MEXICO EN LA PIEL DE COLOMBIA S.A.S",
                "NIT: 901,399,198-0",
                "CRA 21 # 16-20 LOCAL 1",
                "BOGOTA",
                "3123138543 - 3224274547",
                "mexicoenlapieldecolombia@gmail.com",
            ]
            row0 = 6  # zero-based row 7
            for i, (label, value) in enumerate(client_rows):
                r = row0 + i
                ws.write(r, 0, label, fmt_provider_bold)
                ws.merge_range(r, 1, r, 2, value, fmt_block)
                ws.merge_range(r, 3, r, 5, provider_rows[i], fmt_provider_bold if i == 0 else fmt_block)
                ws.set_row(r, 21 if i != 5 else 24)

            # Tabla de productos.
            row = 13
            ws.set_row(row, 28)
            headers = ["CANTIDAD", "UNIDAD", "PRODUCTO", "", "PRECIO VENTA", "TOTAL"]
            for col, label_text in enumerate(headers):
                ws.write(row, col, label_text, fmt_head)
            row += 1

            for _, item in details.iterrows():
                qty = money(item.get("cantidad_kls", 0))
                product = str(item.get("producto", "") or "")
                unit = product_units.get(product, "")
                line_total = (
                    money(item.get("valor_total", 0))
                    + money(item.get("iva_19", 0))
                    + money(item.get("chile_fresco", 0))
                )
                ws.write_number(row, 0, qty, fmt_qty)
                ws.write(row, 1, unit, fmt_cell)
                ws.merge_range(row, 2, row, 3, product, fmt_cell)
                ws.write_number(row, 4, money(item.get("valor_x_kl", 0)), fmt_money)
                ws.write_number(row, 5, line_total, fmt_money)
                ws.set_row(row, 22)
                row += 1

            if domicilio_cliente:
                ws.write_number(row, 0, 1, fmt_qty)
                ws.write(row, 1, "", fmt_cell)
                ws.merge_range(row, 2, row, 3, _v1000_shipping_label(sale.get("ciudad_entrega","")), fmt_cell)
                ws.write_number(row, 4, domicilio_cliente, fmt_money)
                ws.write_number(row, 5, domicilio_cliente, fmt_money)
                ws.set_row(row, 22)
                row += 1

            # Mantiene una altura visual mínima de la tabla.
            minimum_product_rows = 5
            used_rows = len(details) + (1 if domicilio_cliente else 0)
            for _ in range(max(0, minimum_product_rows - used_rows)):
                ws.write(row, 0, "", fmt_cell)
                ws.write(row, 1, "", fmt_cell)
                ws.merge_range(row, 2, row, 3, "", fmt_cell)
                ws.write(row, 4, "", fmt_cell)
                ws.write(row, 5, "", fmt_cell)
                ws.set_row(row, 20)
                row += 1

            # Pago y totales como un bloque único con bordes.
            pay_start = row + 1
            ws.merge_range(pay_start, 0, pay_start, 3, "FORMAS DE PAGO", fmt_pay_title)
            ws.merge_range(pay_start + 1, 0, pay_start + 1, 3, "BANCOLOMBIA CUENTA DE AHORROS No. 22900001312", fmt_pay_text)
            ws.merge_range(pay_start + 2, 0, pay_start + 2, 3, "A NOMBRE DE MEXICO EN LA PIEL DE COLOMBIA", fmt_pay_text)

            payment_row = pay_start + 3
            if not applications.empty or total_ret > 0:
                payment_summary = []
                for _, pay in applications.iterrows():
                    medio = str(pay.get("medio_pago", "") or "").strip()
                    valor = money(pay.get("valor_aplicado", 0))
                    ref = str(pay.get("referencia_pago", "") or "").strip()
                    piece = f"{medio}: ${valor:,.0f}"
                    if ref:
                        piece += f" - Ref. {ref}"
                    payment_summary.append(piece)
                if total_ret > 0:
                    payment_summary.append(f"Retención: ${total_ret:,.0f}")
                ws.merge_range(payment_row, 0, payment_row + 1, 3, "PAGOS / RETENCIONES:\n" + " | ".join(payment_summary), fmt_pay_text)
                payment_end = payment_row + 1
            else:
                ws.merge_range(payment_row, 0, payment_row + 1, 3, "", fmt_pay_text)
                payment_end = payment_row + 1

            ws.write(pay_start, 4, "SUBTOTAL", fmt_total_label)
            ws.write_number(pay_start, 5, subtotal_facturable, fmt_total_money)
            ws.write(pay_start + 1, 4, "IVA 19 %", fmt_total_label)
            ws.write_number(pay_start + 1, 5, total_iva, fmt_total_money)
            ws.write(pay_start + 2, 4, "TOTAL A PAGAR", fmt_grand_label)
            ws.write_number(pay_start + 2, 5, total_factura, fmt_grand_money)
            ws.write(pay_start + 3, 4, "PAGADO", fmt_total_label)
            ws.write_number(pay_start + 3, 5, total_pagado, fmt_total_money)
            ws.write(pay_start + 4, 4, "SALDO", fmt_total_label)
            ws.write_number(pay_start + 4, 5, saldo, fmt_total_money)

            # Completa visualmente el borde izquierdo hasta la misma altura que los totales.
            for r in range(payment_end + 1, pay_start + 5):
                ws.merge_range(r, 0, r, 3, "", fmt_pay_text)

            row = pay_start + 6
            ws.merge_range(row, 0, row, 5, "Gracias por su confianza", fmt_thanks)
            ws.set_row(row, 22)
            row += 2

            # Recibido por: bloque completo enmarcado.
            ws.merge_range(row, 0, row, 1, "RECIBIDO POR", fmt_received_label)
            ws.merge_range(row, 2, row, 5, str(sale.get("recibido_por", "") or ""), fmt_received_value)
            ws.set_row(row, 28)
            row += 2

            # Observaciones y datos adicionales de entrega.
            obs_parts = [
                str(sale.get("observacion_logistica", "") or "").strip(),
                str(sale.get("datos_entrega", "") or "").strip(),
            ]
            observations = "\n".join(x for x in obs_parts if x)
            ws.merge_range(row, 0, row + 2, 1, "OBSERVACIONES", fmt_obs_label)
            ws.merge_range(row, 2, row + 2, 5, observations, fmt_obs)
            ws.set_row(row, 24)
            ws.set_row(row + 1, 24)
            ws.set_row(row + 2, 24)
            row += 3

            # Impresión y repetición de cabecera en páginas largas.
            ws.print_area(0, 0, row, 5)
            ws.repeat_rows(0, 5)
            ws.set_footer("&C&P de &N")

        return output_path

    def export_excel(self, output_path: Path, append_existing: bool = False):
        cab = self.sales_summary()
        ventas = self.table("SELECT * FROM ventas ORDER BY fecha, cuenta_cobro")
        detalles = self.table("SELECT * FROM ventas_detalle ORDER BY cuenta_cobro, item")
        abonos = self.table("SELECT * FROM abonos ORDER BY fecha_abono, id_abono")
        aplicaciones = self.table("SELECT * FROM aplicacion_abonos ORDER BY id_abono, orden_aplicacion")
        clientes = self.clientes()
        productos = self.productos()

        cabecera = ventas.merge(
            cab[["cuenta_cobro", "total_factura", "total_abonos"]],
            on="cuenta_cobro",
            how="left",
        )
        cabecera["saldo_pendiente"] = (cabecera["total_factura"].fillna(0) - cabecera["total_abonos"].fillna(0)).clip(lower=0)
        cabecera["estado_cartera"] = cabecera.apply(
            lambda r: "ANULADA"
            if str(r["estado_venta"]).upper() == "ANULADA"
            else "PAGADA"
            if abs(float(r["saldo_pendiente"] or 0)) <= 1 and float(r["total_factura"] or 0) > 0
            else "PARCIAL"
            if float(r["total_abonos"] or 0) > 0
            else "EMITIDA",
            axis=1,
        )

        # Trazabilidad de abonos por factura dentro del registro de ventas.
        # Una factura puede recibir varios abonos en fechas diferentes.
        if not aplicaciones.empty:
            apps_trace = aplicaciones.merge(
                abonos[["id_abono", "fecha_abono", "medio_pago", "referencia_pago"]],
                on="id_abono", how="left"
            )
            apps_trace["fecha_abono"] = apps_trace["fecha_abono"].fillna(apps_trace.get("fecha_aplicacion", ""))
            apps_trace = apps_trace.sort_values(["cuenta_cobro", "fecha_abono", "orden_aplicacion", "id_abono"])
            trace_rows = []
            for cuenta, grp in apps_trace.groupby("cuenta_cobro", dropna=False):
                last = grp.iloc[-1]
                hist = []
                for _, ap in grp.iterrows():
                    fecha = str(ap.get("fecha_abono", ap.get("fecha_aplicacion", "")) or "")
                    valor = float(ap.get("valor_aplicado", 0) or 0)
                    aid = str(ap.get("id_abono", "") or "")
                    medio = str(ap.get("medio_pago", "") or "")
                    ref = str(ap.get("referencia_pago", "") or "")
                    extra = " / ".join(x for x in [aid, medio, ref] if x)
                    hist.append(f"{fecha}: ${valor:,.0f}" + (f" ({extra})" if extra else ""))
                trace_rows.append({
                    "cuenta_cobro": str(cuenta),
                    "fecha_ultimo_abono": str(last.get("fecha_abono", last.get("fecha_aplicacion", "")) or ""),
                    "valor_ultimo_abono": float(last.get("valor_aplicado", 0) or 0),
                    "historial_abonos": " | ".join(hist),
                })
            trace_df = pd.DataFrame(trace_rows)
            cabecera = cabecera.merge(trace_df, on="cuenta_cobro", how="left")
        else:
            cabecera["fecha_ultimo_abono"] = ""
            cabecera["valor_ultimo_abono"] = 0.0
            cabecera["historial_abonos"] = ""
        cabecera["fecha_ultimo_abono"] = cabecera["fecha_ultimo_abono"].fillna("")
        cabecera["valor_ultimo_abono"] = pd.to_numeric(cabecera["valor_ultimo_abono"], errors="coerce").fillna(0)
        cabecera["historial_abonos"] = cabecera["historial_abonos"].fillna("")

        detalle_export = detalles.copy()
        if not detalle_export.empty:
            detalle_export["total_linea"] = (
                detalle_export["valor_total"].fillna(0)
                + detalle_export["comision"].fillna(0)
                + detalle_export["iva_19"].fillna(0)
                + detalle_export["retenciones"].fillna(0)
            )
            # CHILE_FRESCO es un campo legado que ya no forma parte del modelo exportado.
            detalle_export = detalle_export.drop(columns=["chile_fresco"], errors="ignore")

        # Consolidado por factura: la comisión total pertenece a cabecera, no a cada línea.
        if not detalles.empty:
            comision_factura = (
                detalles.groupby("cuenta_cobro", as_index=False)["comision"]
                .sum()
                .rename(columns={"comision": "total_comision"})
            )
            cabecera = cabecera.merge(comision_factura, on="cuenta_cobro", how="left")
            cabecera["total_comision"] = cabecera["total_comision"].fillna(0)
        else:
            cabecera["total_comision"] = 0.0

        abonos_export = abonos.copy()
        if not abonos_export.empty:
            aplicado = aplicaciones.groupby("id_abono", as_index=False)["valor_aplicado"].sum()
            aplicado = aplicado.rename(columns={"valor_aplicado": "total_aplicado"})
            abonos_export = abonos_export.merge(aplicado, on="id_abono", how="left")

            # Trazabilidad legible: a qué facturas se aplicó cada abono y cuánto a cada una.
            if not aplicaciones.empty:
                facturas_rows = []
                for aid, grp in aplicaciones.sort_values(["id_abono", "orden_aplicacion"]).groupby("id_abono"):
                    partes = []
                    for _, ap in grp.iterrows():
                        cuenta = str(ap.get("cuenta_cobro", "") or "").strip()
                        valor = float(ap.get("valor_aplicado", 0) or 0)
                        if cuenta:
                            partes.append(f"{cuenta} (${valor:,.0f})")
                    facturas_rows.append({"id_abono": aid, "facturas_aplicadas": " | ".join(partes)})
                abonos_export = abonos_export.merge(pd.DataFrame(facturas_rows), on="id_abono", how="left")
            else:
                abonos_export["facturas_aplicadas"] = ""
            abonos_export["facturas_aplicadas"] = abonos_export["facturas_aplicadas"].fillna("")
            abonos_export["total_aplicado"] = abonos_export["total_aplicado"].fillna(0)
            abonos_export["saldo_abono"] = (abonos_export["valor_abono"].fillna(0) - abonos_export["total_aplicado"]).clip(lower=0)
            abonos_export["estado_abono"] = abonos_export.apply(
                lambda r: "APLICADO"
                if abs(float(r["saldo_abono"] or 0)) <= 1
                else "PARCIAL"
                if float(r["total_aplicado"] or 0) > 0
                else "PENDIENTE",
                axis=1,
            )

        # Hoja VENTAS compatible con la estructura historica de "VENTAS 2026 CHILES MEXICOL".
        # Una fila por producto; los primeros 18 campos conservan nombre y orden del archivo antiguo.
        legacy_rows = []
        first_line = set()
        for _, row in detalle_export.iterrows():
            invoice = row["cuenta_cobro"]
            sale = ventas[ventas["cuenta_cobro"].astype(str) == str(invoice)].head(1)
            if sale.empty:
                continue
            sale = sale.iloc[0]
            is_first = str(invoice) not in {str(x) for x in first_line}

            inv_apps = aplicaciones[aplicaciones["cuenta_cobro"].astype(str) == str(invoice)].copy()
            payment = float(inv_apps["valor_aplicado"].sum()) if not inv_apps.empty else 0.0
            cab_match = cabecera[cabecera["cuenta_cobro"].astype(str) == str(invoice)]
            if not cab_match.empty:
                cab_info = cab_match.iloc[0]
                fecha_ultimo_abono = cab_info.get("fecha_ultimo_abono", "")
                valor_ultimo_abono = float(cab_info.get("valor_ultimo_abono", 0) or 0)
                saldo_pendiente = float(cab_info.get("saldo_pendiente", 0) or 0)
                historial_abonos = cab_info.get("historial_abonos", "")
            else:
                fecha_ultimo_abono = ""
                valor_ultimo_abono = 0.0
                saldo_pendiente = 0.0
                historial_abonos = ""

            # Campos de detalle: siempre una fila por producto, nunca totalizar la factura en una sola fila.
            valor_total = float(row.get("valor_total", 0) or 0)
            comision = float(row.get("comision", 0) or 0)
            iva = float(row.get("iva_19", 0) or 0)
            retenciones = float(row.get("retenciones", 0) or 0)
            # Campo legado chile_fresco se conserva en SQLite por compatibilidad,
            # pero ya no se exporta ni se usa como columna comercial.
            total_linea = valor_total + iva + retenciones

            # El domicilio cobrado al cliente se registra una sola vez por factura, como en el archivo historico.
            domicilio_cliente = money(sale.get("domicilio_cliente", 0))
            domicilio_empresa = money(sale.get("domicilio_empresa", 0))
            domicilio_historico = domicilio_cliente if is_first and domicilio_cliente else ""

            ciudad = str(sale.get("ciudad_entrega", "") or "").strip()
            observacion = str(sale.get("observacion_logistica", "") or "").strip()
            # En el historico OBSERVACIONES se uso frecuentemente para ciudad/destino.
            observaciones_historicas = " - ".join(x for x in [ciudad, observacion] if x)

            legacy_rows.append(
                {
                    # ---- Orden exacto del archivo historico (A:R) ----
                    "FECHA": sale.get("fecha", ""),
                    "CLIENTE": sale.get("cliente", ""),
                    "PRODUCTO ": row.get("producto", ""),
                    "CUENTA DE COBRO": invoice,
                    "CANT. KLS": row.get("cantidad_kls", 0),
                    "VALOR X KL": row.get("valor_x_kl", 0),
                    "VALOR TOTAL": valor_total,
                    "COMISION": comision,
                    "IVA 19%": iva if iva else "",
                    "RETENCIONES": retenciones if retenciones else "",
                    "DOMICILIO": domicilio_historico,
                    "OBSERVACIONES": observaciones_historicas if is_first else "",
                    "ASESOR": sale.get("asesor", ""),
                    "CTA BANCARIA ": sale.get("cta_bancaria", "") if is_first else "",
                    "FORMA DE PAGO ": sale.get("forma_pago", ""),
                    # ---- Campos nuevos, despues de las 18 columnas historicas ----
                    "COMISION UNITARIA": row.get("comision_unitaria", 0),
                    "UNIDAD": row.get("unidad", "KLS") or "KLS",
                    "COSTO UNITARIO": row.get("costo_unitario", 0),
                    "PRECIO VENTA": row.get("valor_x_kl", 0),
                    "DIRECCION": sale.get("direccion", ""),
                    "CIUDAD": ciudad,
                    "BARRIO": sale.get("barrio_entrega", ""),
                    "LOCAL/EDIFICIO": sale.get("local_edificio", ""),
                    "DATOS ENTREGA": sale.get("datos_entrega", ""),
                    "TELEFONO CLIENTE": sale.get("telefono_cliente", ""),
                    "ESTADO PAGO": sale.get("estado_pago", ""),
                    "DOMICILIO EMPRESA": domicilio_empresa if is_first and domicilio_empresa else "",
                    "TOTAL LINEA": total_linea + (domicilio_cliente if is_first else 0),
                    "ESTADO": sale.get("estado_venta", ""),
                    "FECHA ULTIMO ABONO": fecha_ultimo_abono if is_first else "",
                    "ULTIMO ABONO": valor_ultimo_abono if is_first and valor_ultimo_abono else "",
                    "TOTAL ABONADO": payment if is_first and payment else "",
                    "SALDO PENDIENTE": saldo_pendiente if is_first else "",
                    "HISTORIAL ABONOS": historial_abonos if is_first else "",
                }
            )
            first_line.add(str(invoice))

        legacy_columns = [
            # Hoja operativa limpia: una fila por producto y sin columnas duplicadas.
            "FECHA", "CLIENTE", "PRODUCTO ", "CUENTA DE COBRO", "CANT. KLS",
            "VALOR X KL", "VALOR TOTAL", "UNIDAD", "COSTO UNITARIO", "PRECIO VENTA",
            "COMISION UNITARIA", "COMISION", "IVA 19%", "RETENCIONES", "DOMICILIO", "DIRECCION", "CIUDAD",
            "BARRIO", "LOCAL/EDIFICIO", "DATOS ENTREGA", "TELEFONO CLIENTE",
            "OBSERVACIONES", "ASESOR", "CTA BANCARIA ", "FORMA DE PAGO ",
            "ESTADO PAGO", "DOMICILIO EMPRESA", "TOTAL LINEA", "ESTADO",
            "FECHA ULTIMO ABONO", "ULTIMO ABONO", "TOTAL ABONADO",
            "SALDO PENDIENTE", "HISTORIAL ABONOS",
        ]
        legacy = pd.DataFrame(legacy_rows, columns=legacy_columns)

        # VENTAS va primero: es la hoja operativa compatible con el archivo historico.
        # Las demas hojas conservan la estructura tecnica para auditoria y trazabilidad.
        export_frames = {
            "VENTAS": legacy,
            "Ventas_detalle": detalle_export.rename(columns=str.upper),
            "Ventas_cabecera": cabecera.rename(columns=str.upper),
            "Registro_abonos": abonos_export.rename(columns=str.upper),
            "Aplicacion_abonos": aplicaciones.rename(columns=str.upper),
            "Clientes": clientes.rename(columns=str.upper),
            "Productos": productos.rename(columns=str.upper),
        }
        if append_existing and output_path.exists():
            with pd.ExcelFile(output_path) as workbook_existing:
                for sheet_name, frame in list(export_frames.items()):
                    if sheet_name not in workbook_existing.sheet_names:
                        continue
                    previous = pd.read_excel(workbook_existing, sheet_name=sheet_name)
                    previous_cols = [str(c).strip().upper() for c in previous.columns]
                    current_cols = [str(c).strip().upper() for c in frame.columns]
                    if previous_cols != current_cols:
                        raise ValueError(
                            f"No se puede anexar la hoja {sheet_name}: las columnas no tienen el mismo formato."
                        )
                    previous.columns = frame.columns
                    export_frames[sheet_name] = pd.concat([previous, frame], ignore_index=True)
        with pd.ExcelWriter(output_path, engine="xlsxwriter", date_format="yyyy-mm-dd", datetime_format="yyyy-mm-dd") as writer:
            for sheet_name, frame in export_frames.items():
                frame.to_excel(writer, sheet_name=sheet_name, index=False)

            workbook = writer.book
            money_fmt = workbook.add_format({"num_format": "$#,##0;[Red]-$#,##0"})
            date_fmt = workbook.add_format({"num_format": "yyyy-mm-dd"})
            header_fmt = workbook.add_format({"bold": True, "bg_color": "#1F4E79", "font_color": "#FFFFFF", "border": 1})
            for sheet_name, frame in export_frames.items():
                ws = writer.sheets[sheet_name]
                ws.freeze_panes(1, 0)
                ws.autofilter(0, 0, max(len(frame), 1), max(len(frame.columns) - 1, 0))
                for col_idx, col in enumerate(frame.columns):
                    upper = str(col).upper()
                    fmt = date_fmt if "FECHA" in upper else money_fmt if any(x in upper for x in ["VALOR", "PAGO", "SALDO", "TOTAL", "COMISION", "IVA", "RETENCION"]) else None
                    ws.set_column(col_idx, col_idx, 16, fmt)
                    ws.write(0, col_idx, str(col).upper(), header_fmt)


def load_master_records(source_files: list[Path] | None = None) -> tuple[list[dict], list[dict]]:
    clientes: dict[str, dict] = {}
    productos: dict[str, dict] = {}
    if source_files is None:
        source_files = read_master_sources()
    for path in source_files:
        if not path.exists():
            continue
        try:
            workbook = pd.ExcelFile(path)
        except Exception:
            continue

        sheet_lookup = {str(s).strip().upper(): s for s in workbook.sheet_names}
        client_sheet = first_column(sheet_lookup, "CLIENTES", "MAESTRO_CLIENTES", "CLIENTES_MAESTRO")
        product_sheet = first_column(sheet_lookup, "PRODUCTOS", "MAESTRO_PRODUCTOS", "PRODUCTOS_MAESTRO", "INVENTARIO")

        if client_sheet:
            try:
                df_clients = pd.read_excel(workbook, sheet_name=client_sheet, nrows=10000)
                col_map = normalized_columns(df_clients)
                name_col = first_column(col_map, "NOMBRE", "CLIENTE")
                city_col = first_column(col_map, "CIUDAD", "MUNICIPIO")
                address_col = first_column(col_map, "DIRECCION", "DIRECCIÓN", "DIRECCION CLIENTE")
                phone_col = first_column(col_map, "TELEFONO", "TELÉFONO", "CELULAR")
                email_col = first_column(col_map, "EMAIL", "CORREO")
                notes_col = first_column(col_map, "NOTAS", "OBSERVACIONES")
                if name_col:
                    for _, row in df_clients.iterrows():
                        name = str(row.get(name_col, "") or "").strip()
                        if not name:
                            continue
                        clientes.setdefault(
                            name,
                            {
                                "nombre": name,
                                "ciudad": str(row.get(city_col, "") or "").strip() if city_col else "",
                                "direccion": str(row.get(address_col, "") or "").strip() if address_col else "",
                                "telefono": str(row.get(phone_col, "") or "").strip() if phone_col else "",
                                "email": str(row.get(email_col, "") or "").strip() if email_col else "",
                                "notas": str(row.get(notes_col, "") or "").strip() if notes_col else f"Importado desde {path.name}",
                                "fuente_origen": str(path),
                            },
                        )
            except Exception:
                pass

        if product_sheet:
            try:
                df_products = pd.read_excel(workbook, sheet_name=product_sheet, nrows=10000)
                col_map = normalized_columns(df_products)
                code_col = first_column(col_map, "CODIGO", "CÓDIGO", "CODIGO PRODUCTO", "SKU")
                name_col = first_column(col_map, "NOMBRE", "PRODUCTO")
                unit_col = first_column(col_map, "UNIDAD")
                price_col = first_column(col_map, "PRECIO_VENTA", "PRECIO VENTA", "VALOR X KL", "VALOR_X_KL")
                commission_col = first_column(col_map, "COMISION UNITARIA", "COMISIÓN UNITARIA", "COMISION SUGERIDA", "COMISIÓN SUGERIDA", "COMISION")
                cost_col = first_column(col_map, "COSTO")
                stock_col = first_column(col_map, "STOCK_ACTUAL", "STOCK ACTUAL", "INVENTARIO")
                min_col = first_column(col_map, "STOCK_MINIMO", "STOCK MINIMO", "MINIMO", "MÍNIMO")
                active_col = first_column(col_map, "ACTIVO")
                if name_col:
                    for _, row in df_products.iterrows():
                        name = str(row.get(name_col, "") or "").strip()
                        if not name:
                            continue
                        code = str(row.get(code_col, "") or "").strip() if code_col else ""
                        productos.setdefault(
                            name,
                            {
                                "codigo": make_code(code or name),
                                "nombre": name,
                                "unidad": str(row.get(unit_col, "KLS") or "KLS").strip() if unit_col else "KLS",
                                "precio_venta": money(row.get(price_col, 0)) if price_col else 0.0,
                                "comision_unitaria_sugerida": money(row.get(commission_col, 0)) if commission_col else 0.0,
                                "costo": money(row.get(cost_col, 0)) if cost_col else 0.0,
                                "stock_actual": money(row.get(stock_col, 0)) if stock_col else 0.0,
                                "stock_minimo": money(row.get(min_col, 0)) if min_col else 0.0,
                                "activo": str(row.get(active_col, "SI") or "SI").strip() if active_col else "SI",
                                "fuente_origen": str(path),
                            },
                        )
            except Exception:
                pass

        if client_sheet or product_sheet:
            workbook.close()
            continue

        try:
            df = pd.read_excel(workbook, sheet_name=workbook.sheet_names[0], nrows=10000)
        except Exception:
            workbook.close()
            continue
        workbook.close()

        col_map = normalized_columns(df)
        client_col = first_column(col_map, "CLIENTE")
        city_col = first_column(col_map, "OBSERVACIONES", "CIUDAD")
        product_col = first_column(col_map, "PRODUCTO")
        price_col = first_column(col_map, "VALOR X KL", "PRECIO VENTA", "PRECIO_VENTA")
        qty_col = first_column(col_map, "CANT. KLS", "CANTIDAD", "KLS")
        commission_col = first_column(col_map, "COMISION", "COMISIÓN", "COMISION TOTAL")

        if client_col:
            for _, row in df.iterrows():
                name = str(row.get(client_col, "") or "").strip()
                if not name:
                    continue
                city = str(row.get(city_col, "") or "").strip() if city_col else ""
                clientes.setdefault(
                    name,
                    {
                        "nombre": name,
                        "ciudad": city,
                        "direccion": "",
                        "telefono": "",
                        "email": "",
                        "notas": f"Importado desde {path.name}",
                        "fuente_origen": str(path),
                    },
                )

        if product_col:
            product_groups = df.dropna(subset=[product_col]).copy()
            for product_name, group in product_groups.groupby(product_col, dropna=False):
                name = str(product_name or "").strip()
                if not name:
                    continue
                price = 0.0
                if price_col:
                    prices = group[price_col].dropna().apply(money)
                    prices = prices[prices > 0]
                    if not prices.empty:
                        price = float(prices.median())
                commission_unit = 0.0
                if commission_col and qty_col:
                    units = []
                    for _, hist_row in group.iterrows():
                        qty = money(hist_row.get(qty_col, 0))
                        commission_total = money(hist_row.get(commission_col, 0))
                        if qty > 0 and commission_total > 0:
                            units.append(round(commission_total / qty, 2))
                    if units:
                        unit_series = pd.Series(units)
                        # Moda histórica: conserva la regla más utilizada por producto.
                        commission_unit = float(unit_series.value_counts().index[0])
                code = make_code(name)
                productos.setdefault(
                    name,
                    {
                        "codigo": code,
                        "nombre": name,
                        "unidad": "KLS",
                        "precio_venta": price,
                        "comision_unitaria_sugerida": commission_unit,
                        "costo": 0.0,
                        "stock_actual": 0.0,
                        "stock_minimo": 0.0,
                        "activo": "SI",
                        "fuente_origen": str(path),
                    },
                )

    return list(clientes.values()), list(productos.values())


def load_sales_history(source_file: Path) -> list[dict]:
    try:
        workbook = pd.ExcelFile(source_file)
    except Exception:
        return []
    sheet_lookup = {str(s).strip().upper(): s for s in workbook.sheet_names}
    sheet_name = first_column(sheet_lookup, "VENTAS")
    if not sheet_name:
        workbook.close()
        return []
    try:
        df = pd.read_excel(workbook, sheet_name=sheet_name)
    except Exception:
        workbook.close()
        return []
    workbook.close()
    if df.empty:
        return []

    col_map = normalized_columns(df)
    date_col = first_column(col_map, "FECHA")
    client_col = first_column(col_map, "CLIENTE")
    product_col = first_column(col_map, "PRODUCTO")
    invoice_col = first_column(col_map, "CUENTA DE COBRO/FACTURA", "CUENTA DE COBRO", "FACTURA")
    qty_col = first_column(col_map, "CANT. KLS", "CANTIDAD", "KLS")
    unit_col = first_column(col_map, "VALOR X KL", "VR. UNITARIO", "PRECIO VENTA")
    total_col = first_column(col_map, "VALOR TOTAL", "TOTAL")
    com_col = first_column(col_map, "COMISION", "COMISIÃ“N")
    iva_col = first_column(col_map, "IVA 19%", "IVA", "IVA_19")
    ret_col = first_column(col_map, "RETENCIONES", "RETENCION", "RETENCIÃ“N")
    chile_col = first_column(col_map, "CHILE FRESCO")
    dom_col = first_column(col_map, "DOMICILIO", "VALOR DOMICILIO")
    city_col = first_column(col_map, "OBSERVACIONES", "CIUDAD")
    asesor_col = first_column(col_map, "ASESOR")
    bank_col = first_column(col_map, "CTA BANCARIA", "CUENTA BANCARIA")
    pay_col = first_column(col_map, "PAGO")
    pay_note_col = first_column(col_map, "FORMA DE PAGO")
    address_col = first_column(col_map, "DIRECCION", "DIRECCIÃ“N", "DIRECCION CLIENTE")

    required = [date_col, client_col, product_col, invoice_col]
    if any(col is None for col in required):
        return []

    working = df.copy()
    working[invoice_col] = working[invoice_col].ffill()
    working[date_col] = working[date_col].ffill()
    working[client_col] = working[client_col].ffill()
    if asesor_col:
        working[asesor_col] = working[asesor_col].ffill()
    if bank_col:
        working[bank_col] = working[bank_col].ffill()

    sales = []
    for invoice, group in working.dropna(subset=[invoice_col]).groupby(invoice_col, dropna=False):
        invoice_id = str(invoice).strip()
        if not invoice_id:
            continue
        detail_rows = []
        domicilio_total = 0.0
        for _, row in group.iterrows():
            product = str(row.get(product_col, "") or "").strip()
            if not product:
                continue
            valor_total = money(row.get(total_col, 0)) if total_col else 0.0
            cantidad = money(row.get(qty_col, 0)) if qty_col else 0.0
            valor_kl = money(row.get(unit_col, 0)) if unit_col else 0.0
            if valor_total <= 0 and cantidad > 0 and valor_kl > 0:
                valor_total = cantidad * valor_kl
            if valor_total <= 0 and cantidad <= 0:
                continue
            detail_rows.append(
                {
                    "producto": product,
                    "cantidad_kls": cantidad,
                    "valor_x_kl": valor_kl,
                    "valor_total": valor_total,
                    "comision_unitaria": (money(row.get(com_col, 0)) / cantidad) if com_col and cantidad > 0 else 0.0,
                    "comision": money(row.get(com_col, 0)) if com_col else 0.0,
                    "iva_19": money(row.get(iva_col, 0)) if iva_col else 0.0,
                    "retenciones": money(row.get(ret_col, 0)) if ret_col else 0.0,
                    "chile_fresco": money(row.get(chile_col, 0)) if chile_col else 0.0,
                    "domicilio": 0.0,
                }
            )
            domicilio_total += money(row.get(dom_col, 0)) if dom_col else 0.0
        if not detail_rows:
            continue

        first = group.iloc[0]
        total_invoice = domicilio_total + sum(
            d["valor_total"] + d["iva_19"] + d["retenciones"] + d["chile_fresco"]
            for d in detail_rows
        )
        raw_payments = [money(value) for value in group[pay_col].dropna().tolist()] if pay_col else []
        raw_payments = [value for value in raw_payments if value > 0]
        unique_payments = list(dict.fromkeys(round(value, 2) for value in raw_payments))
        sum_unique = sum(unique_payments)
        paid = 0.0
        if raw_payments:
            paid = sum_unique if sum_unique <= total_invoice + 1 else min(max(unique_payments), total_invoice)
        estado_cartera = "PAGADA" if paid >= total_invoice - 1 and total_invoice > 0 else "PARCIAL" if paid > 0 else "EMITIDA"
        payment_note = str(first.get(pay_note_col, "") or "").strip() if pay_note_col else ""
        payments = []
        if paid > 0:
            payments.append(
                {
                    "fecha_abono": excel_date_text(first.get(date_col)),
                    "medio_pago": payment_note[:80] or "Historico",
                    "cta_bancaria_destino": str(first.get(bank_col, "") or "").strip() if bank_col else "",
                    "referencia_pago": f"Historico {invoice_id}",
                    "valor_abono": paid,
                }
            )
        sales.append(
            {
                "sale": {
                    "fecha": excel_date_text(first.get(date_col)),
                    "cliente": str(first.get(client_col, "") or "").strip(),
                    "cuenta_cobro": invoice_id,
                    "estado_venta": estado_cartera,
                    "asesor": str(first.get(asesor_col, "") or "").strip() if asesor_col else "",
                    "cta_bancaria": str(first.get(bank_col, "") or "").strip() if bank_col else "",
                    "direccion": str(first.get(address_col, "") or "").strip() if address_col else "",
                    "domicilio_empresa": 0.0,
                    "domicilio_cliente": domicilio_total,
                    "forma_pago": "Historico pendiente" if paid <= 0 else payment_note or "Historico",
                    "observacion_logistica": str(first.get(city_col, "") or "").strip() if city_col else "",
                    "fuente_origen": str(source_file),
                    "modificado_manualmente": 0,
                },
                "details": detail_rows,
                "payments": payments,
            }
        )
    return sales


def load_catalogs() -> dict[str, list[str]]:
    catalogs = {
        "productos": [],
        "asesores": ["REDES", "HEIDY", "LARY", "LUISA", "RECUPERADO"],
        "cuentas": ["EMPRESA", "CAJA-EMPRESA", "GUERITA", "NEQUI", "DAVIPLATA", "BOLD", "CARTERA"],
        "medios": ["Transferencia", "Efectivo", "Nequi", "Daviplata", "Bold", "Caja", "Mixto"],
        "estados": ["EMITIDA", "PARCIAL", "PAGADA", "ANULADA"],
    }
    for source_file in read_master_sources():
        if not source_file.exists():
            continue
        try:
            df = pd.read_excel(source_file, sheet_name=0, nrows=5000)
            col_map = {str(c).strip().upper(): c for c in df.columns}
            product_col = col_map.get("PRODUCTO")
            if product_col:
                catalogs["productos"] = sorted(
                    set(catalogs["productos"])
                    | {str(x).strip() for x in df[product_col].dropna() if str(x).strip()}
                )
            asesor_col = col_map.get("ASESOR")
            if asesor_col:
                catalogs["asesores"] = sorted(
                    set(catalogs["asesores"])
                    | {str(x).strip() for x in df[asesor_col].dropna() if str(x).strip()}
                )
            cta_col = col_map.get("CTA BANCARIA")
            if cta_col:
                catalogs["cuentas"] = sorted(
                    set(catalogs["cuentas"])
                    | {str(x).strip() for x in df[cta_col].dropna() if str(x).strip()}
                )
        except Exception:
            pass
    clientes, productos = load_master_records()
    catalogs["clientes"] = sorted({c["nombre"] for c in clientes if c.get("nombre")})
    if not catalogs["productos"]:
        catalogs["productos"] = sorted({p["nombre"] for p in productos if p.get("nombre")})
    catalogs["productos_busqueda"] = sorted(
        {
            f"{p.get('codigo', make_code(p.get('nombre', '')))} - {p['nombre']}"
            for p in productos
            if p.get("nombre")
        }
    )
    return catalogs



# Métodos comerciales adicionales: cotizaciones y control documental.
def _store_next_quote_number(self) -> str:
    rows = self.table("SELECT numero_cotizacion FROM cotizaciones")
    highest = 0
    if not rows.empty:
        for value in rows["numero_cotizacion"].astype(str):
            match = re.search(r"(\d+)$", value)
            if match:
                highest = max(highest, int(match.group(1)))
    return f"COT-{highest + 1:06d}"


def _store_quote_summary(self) -> pd.DataFrame:
    return self.table(
        """
        SELECT c.numero_cotizacion, c.fecha, c.valida_hasta, c.cliente, c.estado,
               c.cuenta_cobro_convertida,
               COALESCE(SUM(d.total), 0) + COALESCE(c.domicilio_cliente, COALESCE(c.domicilio, 0)) AS total
        FROM cotizaciones c
        LEFT JOIN cotizaciones_detalle d ON d.numero_cotizacion = c.numero_cotizacion
        GROUP BY c.numero_cotizacion, c.fecha, c.valida_hasta, c.cliente, c.estado,
                 c.cuenta_cobro_convertida, c.domicilio, c.domicilio_cliente
        ORDER BY c.fecha DESC, c.numero_cotizacion DESC
        """
    )


def _store_save_quote(self, data: dict, details: list[dict]):
    self.ensure_cliente(data["cliente"])
    self.conn.execute(
        """
        INSERT INTO cotizaciones (
            numero_cotizacion, fecha, valida_hasta, cliente, asesor, direccion,
            ciudad, telefono, barrio, local_edificio, datos_entrega, estado, forma_pago, domicilio, domicilio_empresa, domicilio_cliente, observaciones,
            cuenta_cobro_convertida, fecha_conversion
        ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        ON CONFLICT(numero_cotizacion) DO UPDATE SET
            fecha=excluded.fecha, valida_hasta=excluded.valida_hasta,
            cliente=excluded.cliente, asesor=excluded.asesor,
            direccion=excluded.direccion, ciudad=excluded.ciudad,
            telefono=excluded.telefono, barrio=excluded.barrio,
            local_edificio=excluded.local_edificio, datos_entrega=excluded.datos_entrega, estado=excluded.estado,
            forma_pago=excluded.forma_pago, domicilio=excluded.domicilio,
            domicilio_empresa=excluded.domicilio_empresa, domicilio_cliente=excluded.domicilio_cliente,
            observaciones=excluded.observaciones
        """,
        (
            data["numero_cotizacion"], data["fecha"], data.get("valida_hasta", ""),
            data["cliente"], data.get("asesor", ""), data.get("direccion", ""),
            data.get("ciudad", ""), data.get("telefono", ""), data.get("barrio", ""), data.get("local_edificio", ""), data.get("datos_entrega", ""), data.get("estado", "BORRADOR"),
            data.get("forma_pago", ""), float(data.get("domicilio_cliente", data.get("domicilio", 0)) or 0),
            float(data.get("domicilio_empresa", 0) or 0), float(data.get("domicilio_cliente", data.get("domicilio", 0)) or 0),
            data.get("observaciones", ""), data.get("cuenta_cobro_convertida", ""),
            data.get("fecha_conversion", ""),
        ),
    )
    self.conn.execute("DELETE FROM cotizaciones_detalle WHERE numero_cotizacion = ?", (data["numero_cotizacion"],))
    for idx, d in enumerate(details, 1):
        self.conn.execute(
            """
            INSERT INTO cotizaciones_detalle (
                numero_cotizacion, item, producto, cantidad, precio_unitario,
                descuento, subtotal, iva, total
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (data["numero_cotizacion"], idx, d["producto"], float(d["cantidad"]),
             float(d["precio_unitario"]), float(d.get("descuento", 0)),
             float(d["subtotal"]), float(d.get("iva", 0)), float(d["total"])),
        )
    self.conn.commit()


def _store_get_quote(self, number: str):
    head = self.table("SELECT * FROM cotizaciones WHERE numero_cotizacion = ?", (number,))
    detail = self.table("SELECT * FROM cotizaciones_detalle WHERE numero_cotizacion = ? ORDER BY item", (number,))
    return head, detail


def _store_mark_quote_converted(self, number: str, cuenta_cobro: str):
    self.conn.execute(
        "UPDATE cotizaciones SET estado='CONVERTIDA', cuenta_cobro_convertida=?, fecha_conversion=? WHERE numero_cotizacion=?",
        (cuenta_cobro, today_text(), number),
    )
    self.conn.commit()


def _store_last_numeric_account(self):
    """Devuelve la cuenta NUMÉRICA registrada más recientemente.

    No usa MAX(cuenta_cobro), porque cuentas históricas como 2541 pueden ser
    mayores que el consecutivo operativo actual (por ejemplo 0015).

    Orden de recencia:
      1. fecha de la venta
      2. ultima_modificacion
      3. rowid como desempate de inserción
    """
    rows = self.table(
        """
        SELECT rowid AS _rowid, cuenta_cobro, fecha,
               COALESCE(ultima_modificacion,'') AS ultima_modificacion
          FROM ventas
        """
    )
    if rows.empty:
        return None

    candidates = []
    for _, r in rows.iterrows():
        raw = str(r.get("cuenta_cobro", "") or "").strip()
        m = re.fullmatch(r"\d+", raw)
        if not m:
            continue

        try:
            number = int(raw)
        except Exception:
            continue

        # Las fechas ISO YYYY-MM-DD ordenan correctamente como texto.
        fecha = str(r.get("fecha", "") or "").strip()
        mod = str(r.get("ultima_modificacion", "") or "").strip()

        # Si ultima_modificacion está vacía, la fecha sigue siendo el criterio principal.
        # rowid resuelve ventas del mismo día sin timestamp.
        try:
            rowid = int(r.get("_rowid", 0) or 0)
        except Exception:
            rowid = 0

        candidates.append((fecha, mod, rowid, number))

    if not candidates:
        return None

    # Más reciente por fecha/modificación/inserción.
    candidates.sort(key=lambda x: (x[0], x[1], x[2]), reverse=True)
    return candidates[0][3]


def _store_export_quote(self, number: str, output_path: Path | None = None) -> Path:
    head, details = self.get_quote(number)
    if head.empty:
        raise ValueError(f"No existe la cotización {number}.")
    q = head.iloc[0]
    if output_path is None:
        PRINT_DIR.mkdir(parents=True, exist_ok=True)
        output_path = PRINT_DIR / f"Cotizacion_{make_code(number, 'COT')}.xlsx"
    else:
        output_path = Path(output_path)
        output_path.parent.mkdir(parents=True, exist_ok=True)

    with pd.ExcelWriter(output_path, engine="xlsxwriter") as writer:
        wb = writer.book
        ws = wb.add_worksheet("Cotización")
        writer.sheets["Cotización"] = ws

        dark = "#174A3B"; gold = "#E8B95F"; cream = "#F4E6D0"; terr = "#B65C3A"
        border = {"border": 1, "border_color": "#777777"}
        f_section = wb.add_format({**border, "bold": True, "font_color": "#FFFFFF", "bg_color": dark, "align": "center", "valign": "vcenter"})
        f_label = wb.add_format({**border, "bold": True, "font_color": dark, "bg_color": cream, "valign": "vcenter"})
        f_text = wb.add_format({**border, "text_wrap": True, "valign": "vcenter"})
        f_header = wb.add_format({**border, "bold": True, "bg_color": gold, "font_color": dark, "align": "center", "valign": "vcenter"})
        f_money = wb.add_format({**border, "num_format": "$#,##0;[Red]-$#,##0", "align": "right", "valign": "vcenter"})
        f_qty = wb.add_format({**border, "num_format": "#,##0.00", "align": "center", "valign": "vcenter"})
        f_blank = wb.add_format({**border, "align": "right", "valign": "vcenter"})
        f_total_l = wb.add_format({**border, "bold": True, "bg_color": cream, "font_color": dark, "align": "right", "valign": "vcenter"})
