        # Columnas opcionales: solo se muestran si existe al menos un valor distinto de cero.
        show_discount = (not details.empty) and details["descuento"].fillna(0).abs().gt(0.0001).any()
        show_iva = (not details.empty) and details["iva"].fillna(0).abs().gt(0.0001).any()
        table_cols = [("cantidad", "Cant."), ("producto", "Producto"), ("precio_unitario", "Precio")]
