def _store_delete_quote(self, number: str):
    self.conn.execute("DELETE FROM cotizaciones_detalle WHERE numero_cotizacion = ?", (number,))
    self.conn.execute("DELETE FROM cotizaciones WHERE numero_cotizacion = ?", (number,))
    self.conn.commit()


def _store_delete_all_quotes(self):
    self.conn.execute("DELETE FROM cotizaciones_detalle")
    self.conn.execute("DELETE FROM cotizaciones")
    self.conn.commit()



def _audit_clean(value):
    if value is None:
        return ""
    if isinstance(value, float) and pd.isna(value):
        return ""
    if isinstance(value, (pd.Timestamp, datetime)):
        return str(value)
    if isinstance(value, (dict, list, tuple)):
        return json.dumps(value, ensure_ascii=False, sort_keys=True, default=str)
    return str(value)


def _store_register_change(self, tipo_documento: str, documento: str, accion: str, campo: str, valor_anterior="", valor_nuevo=""):
    self.conn.execute(
        """INSERT INTO historial_cambios
           (fecha_hora, tipo_documento, documento, accion, campo, valor_anterior, valor_nuevo)
           VALUES (?, ?, ?, ?, ?, ?, ?)""",
        (
            datetime.now().isoformat(timespec="seconds"),
            str(tipo_documento), str(documento), str(accion), str(campo),
            _audit_clean(valor_anterior), _audit_clean(valor_nuevo),
        ),
    )
    self.conn.commit()


def _store_log_snapshot_changes(self, tipo_documento: str, documento: str, before: dict | None, after: dict | None, accion: str | None = None):
    before = before or {}
    after = after or {}
    if accion is None:
        accion = "CREAR" if not before else "EDITAR"
    keys = sorted(set(before) | set(after))
    changed = 0
    for key in keys:
        old = _audit_clean(before.get(key, ""))
        new = _audit_clean(after.get(key, ""))
        if old != new:
            self.register_change(tipo_documento, documento, accion, key, old, new)
            changed += 1
    if not changed and accion in ("CREAR", "BORRAR", "CONVERTIR"):
        self.register_change(tipo_documento, documento, accion, "documento", "", _audit_clean(after or before))


def _store_quote_snapshot(self, number: str) -> dict:
    head, det = self.get_quote(number)
    if head.empty:
        return {}
    snap = {str(k): ("" if pd.isna(v) else v) for k, v in head.iloc[0].to_dict().items()}
    records = []
    for _, row in det.iterrows():
        records.append({str(k): ("" if pd.isna(v) else v) for k, v in row.to_dict().items() if k != "id"})
    snap["productos"] = records
    return snap


def _store_sale_snapshot(self, account: str) -> dict:
    head = self.table("SELECT * FROM ventas WHERE cuenta_cobro = ?", (account,))
    if head.empty:
        return {}
    snap = {str(k): ("" if pd.isna(v) else v) for k, v in head.iloc[0].to_dict().items()}
    det = self.table("SELECT * FROM ventas_detalle WHERE cuenta_cobro = ? ORDER BY item", (account,))
    snap["productos"] = [
        {str(k): ("" if pd.isna(v) else v) for k, v in row.to_dict().items() if k != "id"}
        for _, row in det.iterrows()
    ]
    pays = self.table(
        """SELECT a.fecha_aplicacion, b.medio_pago, b.cta_bancaria_destino,
                  b.referencia_pago, a.valor_aplicado
           FROM aplicacion_abonos a
           LEFT JOIN abonos b ON b.id_abono=a.id_abono
           WHERE a.cuenta_cobro=? ORDER BY a.orden_aplicacion""", (account,)
    )
    snap["pagos"] = [
        {str(k): ("" if pd.isna(v) else v) for k, v in row.to_dict().items()}
        for _, row in pays.iterrows()
    ]
    return snap


def _store_audit_recent(self, limit: int = 100):
    return self.table(
        """SELECT fecha_hora, tipo_documento, documento, accion, campo, valor_anterior, valor_nuevo
           FROM historial_cambios ORDER BY id DESC LIMIT ?""", (int(limit),)
    )


