        self.entry(head,"cot_asesor","Asesor",4,0,width=22,values=self.catalogs["asesores"])
        self.entry(head,"cot_estado","Estado",5,0,width=22,values=["BORRADOR","ENVIADA","APROBADA","RECHAZADA","VENCIDA","CANCELADA","CONVERTIDA"],required=True); self.vars["cot_estado"].set("BORRADOR")
        self.entry(head,"cot_direccion","Dirección",6,0,width=22,required=True)
        self.entry(head,"cot_ciudad","Ciudad",7,0,width=22,required=True)
        self.entry(head,"cot_telefono","Teléfono",8,0,width=22,required=True)
        self.entry(head,"cot_barrio","Barrio",9,0,width=22)
        self.entry(head,"cot_local_edificio","Local / Edificio",10,0,width=22)
        self.entry(head,"cot_datos_entrega","Datos adicionales entrega",11,0,width=22)
        self.entry(head,"cot_forma_pago","Forma de pago",12,0,width=22,values=["Por definir"]+self.catalogs["medios"]); self.vars["cot_forma_pago"].set("Por definir")
        domicilio_empresa_entry=self.entry(head,"cot_domicilio_empresa","Domicilio empresa",13,0,width=22); domicilio_empresa_entry.insert(0,"0")
        domicilio_cliente_entry=self.entry(head,"cot_domicilio_cliente","Domicilio cliente",14,0,width=22); domicilio_cliente_entry.insert(0,"0")
        domicilio_cliente_entry.bind("<KeyRelease>",self.refresh_quote_totals,add="+")
        domicilio_cliente_entry.bind("<FocusOut>",self.refresh_quote_totals,add="+")
        self.entry(head,"cot_obs","Observaciones",15,0,width=22)

        prod=ttk.LabelFrame(editor,text="Agregar producto",padding=8)
        prod.pack(fill="x",pady=(0,8))
