            ttk.Label(summary,text=label,font=font).grid(row=r,column=0,sticky="e",padx=(8,12),pady=2)
            ttk.Label(summary,textvariable=self.quote_total_vars[key],font=font).grid(row=r,column=1,sticky="e",padx=(0,8),pady=2)
