            canvas.configure(yscrollcommand=vs.set,xscrollcommand=hs.set); canvas.grid(row=0,column=0,sticky="nsew"); vs.grid(row=0,column=1,sticky="ns"); hs.grid(row=1,column=0,sticky="ew"); host.rowconfigure(0,weight=1); host.columnconfigure(0,weight=1)
            photo=ImageTk.PhotoImage(img); canvas.create_image(10,10,image=photo,anchor="nw"); canvas.image=photo; canvas.configure(scrollregion=(0,0,img.width+20,img.height+20))
