    def _layout_sales_panels(self):
        if not hasattr(self,"sales_capture"): return
        w=self.sales_canvas.winfo_width() if hasattr(self,"sales_canvas") else self.winfo_width()
        self.sales_capture.grid_forget(); self.sales_review.grid_forget()
        if w >= 1050:
            self.sales_form_host.columnconfigure(0,weight=5); self.sales_form_host.columnconfigure(1,weight=6)
            self.sales_capture.grid(row=0,column=0,sticky="nsew",padx=(0,8)); self.sales_review.grid(row=0,column=1,sticky="nsew")
        else:
            self.sales_form_host.columnconfigure(0,weight=1); self.sales_capture.grid(row=0,column=0,sticky="ew"); self.sales_review.grid(row=1,column=0,sticky="nsew",pady=(8,0))
