# ====================== V9.2 AUTOGUARDADO DIARIO ======================
# Mantiene una copia Excel consolidada por día. La primera modificación del día
# crea el archivo; las siguientes modificaciones actualizan el mismo archivo.

def _daily_snapshot_target() -> Path:
    sources = read_master_sources()
    source = sources[0] if sources else None
    stem = source.stem if source else "fuente_maestra"
    # Preferimos guardar junto a la fuente para conservar la relación visual
    # con el archivo original. Si no es posible, usamos la carpeta de la app.
    candidates = []
    if source is not None:
        candidates.append(source.parent / "copias_diarias")
    candidates.append(APP_DIR / "copias_diarias")
    folder = None
    for candidate in candidates:
        try:
            candidate.mkdir(parents=True, exist_ok=True)
            probe = candidate / ".mxpc_write_test"
            probe.write_text("ok", encoding="utf-8")
            probe.unlink(missing_ok=True)
            folder = candidate
            break
        except Exception:
            continue
    if folder is None:
        folder = APP_DIR
    return folder / f"{stem}_{datetime.now().strftime('%Y-%m-%d')}.xlsx"


def _store_export_daily_snapshot(self, output_path: Path | None = None) -> Path:
    """Exporta una fotografía consolidada de toda la operación del día.

    No modifica la fuente original. El archivo diario se reemplaza atómicamente
    después de cada cambio confirmado en ventas, cotizaciones, abonos o maestros.
    """
    target = Path(output_path or _daily_snapshot_target())
    target.parent.mkdir(parents=True, exist_ok=True)
    stamp = datetime.now().strftime('%Y%m%d_%H%M%S_%f')
    tmp = target.with_name(f".{target.stem}_{stamp}.tmp.xlsx")

    # 1) Reutiliza la exportación consolidada ya existente de la aplicación.
    self.export_excel(tmp, append_existing=False)

    # 2) Añade las entidades que no forman parte de la exportación histórica.
    extra_frames = {
        "Cotizaciones": self.table("SELECT * FROM cotizaciones ORDER BY fecha, numero_cotizacion"),
        "Cotizaciones_detalle": self.table("SELECT * FROM cotizaciones_detalle ORDER BY numero_cotizacion, item"),
        "Historial_cambios": self.table("SELECT * FROM historial_cambios ORDER BY id"),
        "Fuentes_datos": self.table("SELECT * FROM fuentes_datos ORDER BY id"),
    }
    try:
        cartera = self.outstanding_invoices("", "Cliente").copy()
    except Exception:
        cartera = pd.DataFrame()
    extra_frames["Cartera_pendiente"] = cartera

    meta = pd.DataFrame([{
        "archivo_fuente": str(read_master_sources()[0]) if read_master_sources() else "",
        "archivo_copia_diaria": str(target),
        "fecha_actualizacion": datetime.now().isoformat(timespec="seconds"),
        "base_sqlite": str(self.path),
        "nota": "Copia diaria automática. La fuente original no se sobrescribe.",
    }])
    extra_frames["Control_autoguardado"] = meta

    with pd.ExcelWriter(tmp, engine="openpyxl", mode="a", if_sheet_exists="replace") as writer:
        for sheet_name, frame in extra_frames.items():
            frame.to_excel(writer, sheet_name=sheet_name[:31], index=False)

    # Reemplazo atómico: si el Excel está abierto en Windows, guardamos una
    # copia de recuperación para no perder la modificación registrada en SQLite.
    try:
        tmp.replace(target)
        saved = target
    except PermissionError:
        recovery = target.with_name(f"{target.stem}_RECUPERACION_{datetime.now().strftime('%H%M%S')}{target.suffix}")
        tmp.replace(recovery)
        saved = recovery
    except Exception:
        try:
            tmp.unlink(missing_ok=True)
        except Exception:
            pass
        raise

    cfg = read_config()
    cfg["daily_snapshot_path"] = str(target)
    cfg["daily_snapshot_last_saved"] = str(saved)
    cfg["daily_snapshot_updated_at"] = datetime.now().isoformat(timespec="seconds")
    write_config(cfg)
    return saved


SalesStore.export_daily_snapshot = _store_export_daily_snapshot



# ============================================================================
# V9.5 - Tres maestros oficiales + confirmación de cambios de cliente
# ============================================================================

def _v95_clean_cell(value):
    if value is None or (isinstance(value, float) and pd.isna(value)):
        return ""
    text = str(value).strip()
    if text.lower() == "nan":
        return ""
    if text.endswith('.0'):
        try:
            return str(int(float(text)))
        except Exception:
            pass
    return text


def _v95_find_sheet(workbook, *names):
    lookup = {str(s).strip().upper(): s for s in workbook.sheet_names}
    for name in names:
        hit = lookup.get(str(name).strip().upper())
        if hit:
            return hit
    return None


def load_master_records(source_files: list[Path] | None = None) -> tuple[list[dict], list[dict]]:
    """Carga exclusivamente los maestros oficiales de clientes y productos.

    Si existen Clientes_Maestro y Productos_Maestro, esas hojas tienen prioridad
    total y no se reconstruyen catálogos leyendo las ventas.
    """
    clientes: dict[str, dict] = {}
    productos: dict[str, dict] = {}
    if source_files is None:
        source_files = read_master_sources()
    for path in source_files:
        if not Path(path).exists():
            continue
        try:
            workbook = pd.ExcelFile(path)
        except Exception:
            continue
        client_sheet = _v95_find_sheet(workbook, "Clientes_Maestro", "MAESTRO_CLIENTES", "CLIENTES")
        product_sheet = _v95_find_sheet(workbook, "Productos_Maestro", "MAESTRO_PRODUCTOS", "PRODUCTOS")

        if client_sheet:
            try:
                df = pd.read_excel(workbook, sheet_name=client_sheet, nrows=20000)
                cmap = normalized_columns(df)
                def c(*opts): return first_column(cmap, *opts)
                cols = {
                    "id": c("CLIENTE_ID", "ID_CLIENTE", "ID"),
                    "nombre": c("NOMBRE", "CLIENTE"),
                    "nit": c("NIT_DOCUMENTO", "NIT", "DOCUMENTO", "CEDULA", "CÉDULA"),
                    "telefono": c("TELEFONO", "TELÉFONO", "CELULAR"),
                    "email": c("EMAIL", "CORREO"),
                    "direccion": c("DIRECCION", "DIRECCIÓN"),
                    "ciudad": c("CIUDAD", "MUNICIPIO"),
                    "barrio": c("BARRIO"),
                    "local": c("LOCAL_EDIFICIO", "LOCAL / EDIFICIO", "LOCAL", "EDIFICIO"),
                    "datos": c("DATOS_ENTREGA", "DATOS ENTREGA", "DATOS_ADICIONALES"),
                    "activo": c("ACTIVO"),
                    "notas": c("NOTAS", "OBSERVACIONES", "ESTADO_REVISION"),
                }
                if cols["nombre"]:
                    for _, row in df.iterrows():
                        name = _v95_clean_cell(row.get(cols["nombre"]))
                        if not name:
                            continue
                        clientes[name] = {
                            "cliente_id": _v95_clean_cell(row.get(cols["id"])) if cols["id"] else "",
                            "nombre": name,
                            "nit_documento": _v95_clean_cell(row.get(cols["nit"])) if cols["nit"] else "",
                            "telefono": _v95_clean_cell(row.get(cols["telefono"])) if cols["telefono"] else "",
                            "email": _v95_clean_cell(row.get(cols["email"])) if cols["email"] else "",
                            "direccion": _v95_clean_cell(row.get(cols["direccion"])) if cols["direccion"] else "",
                            "ciudad": _v95_clean_cell(row.get(cols["ciudad"])) if cols["ciudad"] else "",
                            "barrio": _v95_clean_cell(row.get(cols["barrio"])) if cols["barrio"] else "",
                            "local_edificio": _v95_clean_cell(row.get(cols["local"])) if cols["local"] else "",
                            "datos_entrega": _v95_clean_cell(row.get(cols["datos"])) if cols["datos"] else "",
                            "activo": (_v95_clean_cell(row.get(cols["activo"])) if cols["activo"] else "SI") or "SI",
                            "notas": _v95_clean_cell(row.get(cols["notas"])) if cols["notas"] else "",
                            "fuente_origen": str(path),
                        }
            except Exception:
                pass

        if product_sheet:
            try:
                df = pd.read_excel(workbook, sheet_name=product_sheet, nrows=20000)
                cmap = normalized_columns(df)
                def c(*opts): return first_column(cmap, *opts)
                cols = {
                    "codigo": c("CODIGO_PRODUCTO", "CODIGO PRODUCTO", "CODIGO", "CÓDIGO", "SKU"),
                    "nombre": c("PRODUCTO", "NOMBRE"),
                    "unidad": c("UNIDAD"),
                    "referencia": c("PRECIO_REFERENCIA", "PRECIO REFERENCIA", "PRECIO_VENTA", "PRECIO VENTA"),
                    "ultimo": c("ULTIMO_PRECIO", "ÚLTIMO_PRECIO", "ULTIMO PRECIO", "ÚLTIMO PRECIO"),
                    "comision": c("COMISION_UNITARIA_SUGERIDA", "COMISION UNITARIA SUGERIDA", "COMISIÓN UNITARIA SUGERIDA", "COMISION UNITARIA", "COMISIÓN UNITARIA"),
                    "activo": c("ACTIVO"),
                }
                if cols["nombre"]:
                    for _, row in df.iterrows():
                        name = _v95_clean_cell(row.get(cols["nombre"]))
                        if not name:
                            continue
                        code = _v95_clean_cell(row.get(cols["codigo"])) if cols["codigo"] else ""
                        referencia = money(row.get(cols["referencia"], 0)) if cols["referencia"] else 0.0
                        ultimo = money(row.get(cols["ultimo"], 0)) if cols["ultimo"] else 0.0
                        venta = ultimo if ultimo > 0 else referencia
                        productos[name] = {
                            "codigo": code or make_code(name),
                            "nombre": name,
                            "unidad": (_v95_clean_cell(row.get(cols["unidad"])) if cols["unidad"] else "KLS") or "KLS",
                            "precio_referencia": referencia,
                            "ultimo_precio": ultimo,
                            "precio_venta": venta,
                            "comision_unitaria_sugerida": money(row.get(cols["comision"], 0)) if cols["comision"] else 0.0,
                            "costo": 0.0,
                            "stock_actual": 0.0,
                            "stock_minimo": 0.0,
                            "activo": (_v95_clean_cell(row.get(cols["activo"])) if cols["activo"] else "SI") or "SI",
                            "fuente_origen": str(path),
                        }
            except Exception:
                pass
        workbook.close()
    return list(clientes.values()), list(productos.values())


def load_master_advisors(source_files: list[Path] | None = None) -> list[dict]:
    asesores: dict[str, dict] = {}
    if source_files is None:
        source_files = read_master_sources()
    for path in source_files:
        if not Path(path).exists():
            continue
        try:
            workbook = pd.ExcelFile(path)
        except Exception:
            continue
        sheet = _v95_find_sheet(workbook, "Asesores_Maestro", "MAESTRO_ASESORES", "ASESORES")
        if not sheet:
            workbook.close(); continue
        try:
            df = pd.read_excel(workbook, sheet_name=sheet, nrows=5000)
            cmap = normalized_columns(df)
            def c(*opts): return first_column(cmap, *opts)
            id_col = c("ASESOR_ID", "ID_ASESOR", "ID")
            name_col = c("NOMBRE_ASESOR", "NOMBRE ASESOR", "ASESOR", "NOMBRE")
            type_col = c("TIPO")
            phone_col = c("TELEFONO", "TELÉFONO", "CELULAR")
            email_col = c("EMAIL", "CORREO")
            active_col = c("ACTIVO")
            notes_col = c("OBSERVACIONES", "NOTAS")
            if name_col:
                for _, row in df.iterrows():
                    name = _v95_clean_cell(row.get(name_col))
                    if not name:
                        continue
                    asesores[name] = {
                        "asesor_id": _v95_clean_cell(row.get(id_col)) if id_col else "",
                        "nombre": name,
                        "tipo": _v95_clean_cell(row.get(type_col)) if type_col else "PERSONA",
                        "telefono": _v95_clean_cell(row.get(phone_col)) if phone_col else "",
                        "email": _v95_clean_cell(row.get(email_col)) if email_col else "",
                        "activo": (_v95_clean_cell(row.get(active_col)) if active_col else "SI") or "SI",
                        "observaciones": _v95_clean_cell(row.get(notes_col)) if notes_col else "",
                        "fuente_origen": str(path),
                    }
        except Exception:
            pass
        workbook.close()
    return list(asesores.values())


def _v95_import_master_records(self, clientes: list[dict], productos: list[dict], source_path: str = ""):
    stamp = datetime.now().isoformat(timespec="seconds")
    source_label = str(source_path or "").strip()
    for cliente in clientes:
        self.conn.execute(
            """
            INSERT INTO clientes (
                nombre, ciudad, direccion, telefono, email, notas, fuente_origen, ultima_modificacion,
                modificado_manualmente, cliente_id, nit_documento, barrio, local_edificio, datos_entrega, activo
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, 0, ?, ?, ?, ?, ?, ?)
            ON CONFLICT(nombre) DO UPDATE SET
                ciudad=excluded.ciudad, direccion=excluded.direccion, telefono=excluded.telefono,
                email=excluded.email, notas=excluded.notas, cliente_id=excluded.cliente_id,
                nit_documento=excluded.nit_documento, barrio=excluded.barrio,
                local_edificio=excluded.local_edificio, datos_entrega=excluded.datos_entrega,
                activo=excluded.activo,
                fuente_origen=CASE WHEN excluded.fuente_origen <> '' THEN excluded.fuente_origen ELSE clientes.fuente_origen END,
                ultima_modificacion=excluded.ultima_modificacion, modificado_manualmente=0
            """,
            (
                cliente.get("nombre", ""), cliente.get("ciudad", ""), cliente.get("direccion", ""),
                cliente.get("telefono", ""), cliente.get("email", ""), cliente.get("notas", ""),
                source_label or cliente.get("fuente_origen", ""), stamp,
                cliente.get("cliente_id", ""), cliente.get("nit_documento", ""), cliente.get("barrio", ""),
                cliente.get("local_edificio", ""), cliente.get("datos_entrega", ""), cliente.get("activo", "SI"),
            ),
        )
    for producto in productos:
        code = _v95_clean_cell(producto.get("codigo", ""))
        name = str(producto.get("nombre", "") or "").strip()
        if not name:
            continue
        existing = self.conn.execute("SELECT codigo FROM productos WHERE nombre = ?", (name,)).fetchone()
        if existing and code and str(existing["codigo"]) != code:
            collision = self.conn.execute("SELECT 1 FROM productos WHERE codigo = ? AND nombre <> ?", (code, name)).fetchone()
            if not collision:
                self.conn.execute("UPDATE productos SET codigo = ? WHERE nombre = ?", (code, name))
        self.conn.execute(
            """
            INSERT INTO productos (
                codigo, nombre, unidad, precio_venta, comision_unitaria_sugerida, costo, stock_actual,
                stock_minimo, activo, fuente_origen, ultima_modificacion, modificado_manualmente,
                precio_referencia, ultimo_precio
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 0, ?, ?)
            ON CONFLICT(codigo) DO UPDATE SET
                nombre=excluded.nombre, unidad=excluded.unidad, precio_venta=excluded.precio_venta,
                comision_unitaria_sugerida=CASE WHEN productos.modificado_manualmente=1 THEN productos.comision_unitaria_sugerida ELSE excluded.comision_unitaria_sugerida END,
                costo=excluded.costo, stock_actual=excluded.stock_actual, stock_minimo=excluded.stock_minimo,
                activo=excluded.activo, precio_referencia=excluded.precio_referencia,
                ultimo_precio=excluded.ultimo_precio,
                fuente_origen=CASE WHEN excluded.fuente_origen <> '' THEN excluded.fuente_origen ELSE productos.fuente_origen END,
                ultima_modificacion=excluded.ultima_modificacion, modificado_manualmente=0
            """,
            (
                code or make_code(name), name, producto.get("unidad", "KLS"),
                float(producto.get("precio_venta", 0) or 0), float(producto.get("comision_unitaria_sugerida", 0) or 0),
                float(producto.get("costo", 0) or 0), float(producto.get("stock_actual", 0) or 0),
                float(producto.get("stock_minimo", 0) or 0), producto.get("activo", "SI"),
                source_label or producto.get("fuente_origen", ""), stamp,
                float(producto.get("precio_referencia", 0) or 0), float(producto.get("ultimo_precio", 0) or 0),
            ),
        )
    self.conn.commit()


def _v95_import_master_advisors(self, asesores: list[dict], source_path: str = ""):
    stamp = datetime.now().isoformat(timespec="seconds")
    source_label = str(source_path or "").strip()
    for asesor in asesores:
        name = str(asesor.get("nombre", "") or "").strip()
        if not name:
            continue
        self.conn.execute(
            """
            INSERT INTO asesores (asesor_id, nombre, tipo, telefono, email, activo, observaciones, fuente_origen, ultima_modificacion, modificado_manualmente)
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, 0)
            ON CONFLICT(nombre) DO UPDATE SET
                asesor_id=excluded.asesor_id, tipo=excluded.tipo, telefono=excluded.telefono,
                email=excluded.email, activo=excluded.activo, observaciones=excluded.observaciones,
                fuente_origen=CASE WHEN excluded.fuente_origen <> '' THEN excluded.fuente_origen ELSE asesores.fuente_origen END,
                ultima_modificacion=excluded.ultima_modificacion, modificado_manualmente=0
            """,
            (
                asesor.get("asesor_id", ""), name, asesor.get("tipo", "PERSONA"),
                asesor.get("telefono", ""), asesor.get("email", ""), asesor.get("activo", "SI"),
                asesor.get("observaciones", ""), source_label or asesor.get("fuente_origen", ""), stamp,
            ),
        )
    self.conn.commit()


def _v95_seed_master_data(self):
    # Migración de esquema antes de importar las hojas maestras.
    self.ensure_column("clientes", "cliente_id", "TEXT")
    self.ensure_column("clientes", "nit_documento", "TEXT")
    self.ensure_column("clientes", "barrio", "TEXT")
    self.ensure_column("clientes", "local_edificio", "TEXT")
    self.ensure_column("clientes", "datos_entrega", "TEXT")
    self.ensure_column("clientes", "activo", "TEXT NOT NULL DEFAULT 'SI'")
    self.ensure_column("productos", "precio_referencia", "REAL NOT NULL DEFAULT 0")
    self.ensure_column("productos", "ultimo_precio", "REAL NOT NULL DEFAULT 0")
    self.conn.execute(
        """
        CREATE TABLE IF NOT EXISTS asesores (
            nombre TEXT PRIMARY KEY,
            asesor_id TEXT,
            tipo TEXT,
            telefono TEXT,
            email TEXT,
            activo TEXT NOT NULL DEFAULT 'SI',
            observaciones TEXT,
            fuente_origen TEXT,
            ultima_modificacion TEXT,
            modificado_manualmente INTEGER NOT NULL DEFAULT 0
        )
        """
    )
    self.conn.commit()
    clientes, productos = load_master_records()
    asesores = load_master_advisors()
    # IMPORTANTE V9.6.1: usar los métodos actualmente enlazados en SalesStore.
    # De este modo, al arrancar se utiliza el importador robusto V9.6 y no la
    # implementación antigua V9.5 que podía chocar con UNIQUE(productos.nombre).
    self.import_master_records(clientes, productos)
    self.import_master_advisors(asesores)


def _v95_normalize_product_codes(self):
    """Garantiza código numérico sin destruir los códigos definidos por el maestro."""
    rows = self.conn.execute("SELECT codigo, nombre FROM productos ORDER BY nombre").fetchall()
    numeric = []
    for row in rows:
        try:
            numeric.append(int(str(row["codigo"]).strip()))
        except Exception:
            pass
    next_code = max(numeric or [1000]) + 1
    used = {str(r["codigo"]) for r in rows}
    for row in rows:
        current = str(row["codigo"] or "").strip()
        if current.isdigit():
            continue
        while str(next_code) in used:
            next_code += 1
        self.conn.execute("UPDATE productos SET codigo=? WHERE codigo=?", (str(next_code), current))
        used.add(str(next_code)); used.discard(current); next_code += 1
    self.conn.commit()


def _v95_asesores(self):
    return self.table("SELECT * FROM asesores WHERE COALESCE(activo,'SI') <> 'NO' ORDER BY nombre")


SalesStore.import_master_records = _v95_import_master_records
SalesStore.import_master_advisors = _v95_import_master_advisors
SalesStore.seed_master_data = _v95_seed_master_data
SalesStore.normalize_product_codes = _v95_normalize_product_codes
SalesStore.asesores = _v95_asesores


def load_catalogs() -> dict[str, list[str]]:
    clientes, productos = load_master_records()
    asesores = load_master_advisors()
    return {
        "clientes": sorted({c["nombre"] for c in clientes if c.get("nombre") and str(c.get("activo", "SI")).upper() != "NO"}),
        "productos": sorted({p["nombre"] for p in productos if p.get("nombre") and str(p.get("activo", "SI")).upper() != "NO"}),
        "productos_busqueda": sorted({f"{p.get('codigo','')} - {p['nombre']}" for p in productos if p.get("nombre") and str(p.get("activo", "SI")).upper() != "NO"}),
        "asesores": sorted({a["nombre"] for a in asesores if a.get("nombre") and str(a.get("activo", "SI")).upper() != "NO"}),
        "cuentas": ["EMPRESA", "CAJA-EMPRESA", "GUERITA", "NEQUI", "DAVIPLATA", "BOLD", "CARTERA"],
        "medios": ["Transferencia", "Efectivo", "Nequi", "Daviplata", "Bold", "Caja", "Mixto"],
        "estados": ["EMITIDA", "PARCIAL", "PAGADA", "ANULADA"],
    }


def _v95_reload_master_catalogs(self):
    clientes = self.store.clientes()
    productos = self.store.productos()
    asesores = self.store.asesores()
    if not clientes.empty and "activo" in clientes.columns:
        clientes = clientes[clientes["activo"].fillna("SI").astype(str).str.upper() != "NO"]
    if not productos.empty and "activo" in productos.columns:
        productos = productos[productos["activo"].fillna("SI").astype(str).str.upper() != "NO"]
    self.catalogs["clientes"] = clientes["nombre"].astype(str).tolist() if not clientes.empty else []
    self.catalogs["productos"] = productos["nombre"].astype(str).tolist() if not productos.empty else []
    self.catalogs["productos_busqueda"] = self.product_search_values()
    self.catalogs["asesores"] = asesores["nombre"].astype(str).tolist() if not asesores.empty else []
    for key, values in [
        ("venta_cliente", self.catalogs["clientes"]),
        ("abono_cliente", self.catalogs["clientes"]),
        ("det_producto", self.catalogs["productos_busqueda"]),
        ("cot_cliente", self.catalogs["clientes"]),
        ("cot_producto", self.catalogs["productos_busqueda"]),
        ("venta_asesor", self.catalogs["asesores"]),
        ("cot_asesor", self.catalogs["asesores"]),
    ]:
        widget = self.widgets.get(key)
        if isinstance(widget, ttk.Combobox):
            widget.configure(values=values)


SalesFormApp.reload_master_catalogs = _v95_reload_master_catalogs


def _v95_populate_client_fields(self, name: str, prefix: str = "venta"):
    name = str(name or "").strip()
    if not name:
        return
    row = self.store.table("SELECT * FROM clientes WHERE nombre = ?", (name,))
    if row.empty:
        return
    c = row.iloc[0]
    mapping = {
        f"{prefix}_telefono": "telefono",
        f"{prefix}_direccion": "direccion",
        f"{prefix}_ciudad": "ciudad",
        f"{prefix}_barrio": "barrio",
        f"{prefix}_local_edificio": "local_edificio",
        f"{prefix}_datos_entrega": "datos_entrega",
    }
    for key, col in mapping.items():
        if key in self.vars:
            value = "" if pd.isna(c.get(col, "")) else str(c.get(col, "") or "")
            self.vars[key].set(value)
    if prefix == "venta":
        self.set_sales_status(f"Cliente seleccionado: {name}. Datos cargados desde el maestro.", "productos")


def _v95_populate_sales_client(self, name: str):
    return _v95_populate_client_fields(self, name, "venta")

SalesFormApp.populate_client_fields = _v95_populate_sales_client


