def _v95_client_form_data(self, prefix: str) -> dict:
    def get(key):
        return self.vars.get(f"{prefix}_{key}", tk.StringVar()).get().strip()
    return {
        "nombre": get("cliente"),
        "telefono": get("telefono"),
        "direccion": get("direccion"),
        "ciudad": get("ciudad"),
        "barrio": get("barrio"),
        "local_edificio": get("local_edificio"),
        "datos_entrega": get("datos_entrega"),
        "email": "",
    }


def _v95_confirm_client_master(self, prefix: str) -> tuple[bool, bool]:
    """Retorna (es_nuevo, autorizo_guardar_o_actualizar)."""
    data = _v95_client_form_data(self, prefix)
    name = data["nombre"]
    if not name:
        return False, False
    row = self.store.table("SELECT * FROM clientes WHERE nombre = ?", (name,))
    if row.empty:
        yes = messagebox.askyesno(
            "Cliente nuevo",
            f"El cliente '{name}' no existe en el maestro.\n\n¿Desea agregarlo a Clientes_Maestro con los datos diligenciados?\n\n"
            "Si elige No, los datos se usarán únicamente en este documento.",
            parent=self,
        )
        if yes:
            self.store.upsert_cliente({**data, "notas": "Agregado con autorización del usuario", "fuente_origen": "Creado en la app"})
            # Completar campos extendidos que el upsert histórico no maneja.
            self.store.conn.execute(
                "UPDATE clientes SET barrio=?, local_edificio=?, datos_entrega=?, activo='SI' WHERE nombre=?",
                (data["barrio"], data["local_edificio"], data["datos_entrega"], name),
            )
            self.store.conn.commit()
            self.reload_master_catalogs()
        return True, yes

    old = row.iloc[0]
    labels = {
        "telefono": "Teléfono", "direccion": "Dirección", "ciudad": "Ciudad",
        "barrio": "Barrio", "local_edificio": "Local / Edificio", "datos_entrega": "Datos de entrega",
    }
    changes = []
    for field, label in labels.items():
        oldv = "" if pd.isna(old.get(field, "")) else str(old.get(field, "") or "").strip()
        newv = str(data.get(field, "") or "").strip()
        if newv != oldv:
            changes.append((field, label, oldv, newv))
    if not changes:
        return False, False

    lines = []
    for _, label, oldv, newv in changes:
        lines.append(f"{label}:\n  Maestro: {oldv or '(vacío)'}\n  Nuevo:   {newv or '(vacío)'}")
    yes = messagebox.askyesno(
        "Actualizar datos del cliente",
        f"Se detectaron datos diferentes para '{name}':\n\n" + "\n\n".join(lines) +
        "\n\n¿Desea actualizar el maestro de clientes?\n\nSi elige No, el maestro conservará sus datos actuales.",
        parent=self,
    )
    if yes:
        update = {
            "nombre": name,
            "ciudad": data["ciudad"], "direccion": data["direccion"], "telefono": data["telefono"],
            "email": "" if pd.isna(old.get("email", "")) else str(old.get("email", "") or ""),
            "notas": "Actualizado con autorización del usuario", "fuente_origen": "Actualizado en la app",
        }
        self.store.upsert_cliente(update)
        self.store.conn.execute(
            "UPDATE clientes SET barrio=?, local_edificio=?, datos_entrega=? WHERE nombre=?",
            (data["barrio"], data["local_edificio"], data["datos_entrega"], name),
        )
        self.store.conn.commit()
        self.reload_master_catalogs()
    return False, yes


_v95_original_save_sale = SalesFormApp.save_sale
def _v95_save_sale(self):
    # Preguntar antes de que el flujo histórico cree automáticamente un cliente nuevo.
    cliente = self.vars.get("venta_cliente", tk.StringVar()).get().strip()
    row = self.store.table("SELECT 1 FROM clientes WHERE nombre=?", (cliente,)) if cliente else pd.DataFrame()
    is_new = bool(cliente) and row.empty
    _, authorized = _v95_confirm_client_master(self, "venta")
    if is_new and not authorized:
        original_upsert = self.store.upsert_cliente
        try:
            self.store.upsert_cliente = lambda data: None
            return _v95_original_save_sale(self)
        finally:
            self.store.upsert_cliente = original_upsert
    return _v95_original_save_sale(self)
SalesFormApp.save_sale = _v95_save_sale


_v95_original_save_quote = SalesFormApp.save_quote
def _v95_save_quote(self):
    _v95_confirm_client_master(self, "cot")
    return _v95_original_save_quote(self)
SalesFormApp.save_quote = _v95_save_quote


def _v95_import_master_source(self, source_path: Path):
    clientes, productos = load_master_records([source_path])
    asesores = load_master_advisors([source_path])
    if not clientes and not productos and not asesores:
        raise ValueError("No se encontraron las hojas maestras Clientes_Maestro, Productos_Maestro o Asesores_Maestro.")
    save_master_sources([source_path])
    self.store.import_master_records(clientes, productos, str(source_path))
    self.store.import_master_advisors(asesores, str(source_path))
    self.store.normalize_product_codes()
    self.store.register_source_import(
        source_path, len(clientes), len(productos), 0,
        f"Maestros oficiales importados. Asesores: {len(asesores)}. No se importaron ventas desde la fuente maestra."
    )
    self.catalogs = load_catalogs()
    self.reload_master_catalogs()
    self.refresh_all()
    self.refresh_source_panel()
    messagebox.showinfo(
        "Fuente maestra actualizada",
        f"Fuente activa:\n{source_path}\n\nClientes: {len(clientes)}\nProductos: {len(productos)}\nAsesores: {len(asesores)}\nVentas importadas: 0\n\n"
        "Las ventas nuevas se registran exclusivamente desde la aplicación.",
        parent=self,
    )
SalesFormApp.import_master_source = _v95_import_master_source


def _v95_export_daily_snapshot(self, output_path: Path | None = None) -> Path:
    target = Path(output_path or _daily_snapshot_target())
    target.parent.mkdir(parents=True, exist_ok=True)
    stamp = datetime.now().strftime('%Y%m%d_%H%M%S_%f')
    tmp = target.with_name(f".{target.stem}_{stamp}.tmp.xlsx")
    self.export_excel(tmp, append_existing=False)

    clientes = self.table("SELECT * FROM clientes ORDER BY nombre").copy()
    productos = self.table("SELECT * FROM productos ORDER BY CAST(codigo AS INTEGER), nombre").copy()
    asesores = self.table("SELECT * FROM asesores ORDER BY nombre").copy()

    # Nombres de columnas alineados con las hojas maestras oficiales.
    if not clientes.empty:
        clientes_master = pd.DataFrame({
            "CLIENTE_ID": clientes.get("cliente_id", ""),
            "NOMBRE": clientes["nombre"],
            "NIT_DOCUMENTO": clientes.get("nit_documento", ""),
            "TELEFONO": clientes.get("telefono", ""),
            "EMAIL": clientes.get("email", ""),
            "DIRECCION": clientes.get("direccion", ""),
            "CIUDAD": clientes.get("ciudad", ""),
            "BARRIO": clientes.get("barrio", ""),
            "LOCAL_EDIFICIO": clientes.get("local_edificio", ""),
            "DATOS_ENTREGA": clientes.get("datos_entrega", ""),
            "ACTIVO": clientes.get("activo", "SI"),
            "ULTIMA_ACTUALIZACION": clientes.get("ultima_modificacion", ""),
            "FUENTE_DATOS": clientes.get("fuente_origen", ""),
            "ESTADO_REVISION": "",
        })
    else:
        clientes_master = pd.DataFrame(columns=["CLIENTE_ID","NOMBRE","NIT_DOCUMENTO","TELEFONO","EMAIL","DIRECCION","CIUDAD","BARRIO","LOCAL_EDIFICIO","DATOS_ENTREGA","ACTIVO","ULTIMA_ACTUALIZACION","FUENTE_DATOS","ESTADO_REVISION"])

    if not productos.empty:
        productos_master = pd.DataFrame({
            "CODIGO_PRODUCTO": productos["codigo"],
            "PRODUCTO": productos["nombre"],
            "PRECIO_REFERENCIA": productos.get("precio_referencia", productos.get("precio_venta", 0)),
            "ULTIMO_PRECIO": productos.get("ultimo_precio", productos.get("precio_venta", 0)),
            "PRECIO_MIN_HISTORICO": 0,
            "PRECIO_MAX_HISTORICO": 0,
            "COMISION_UNITARIA_SUGERIDA": productos.get("comision_unitaria_sugerida", 0),
            "FECHA_ULTIMO_PRECIO": productos.get("ultima_modificacion", ""),
            "ACTIVO": productos.get("activo", "SI"),
            "VARIANTES_DETECTADAS": "",
            "ESTADO_REVISION": "",
        })
    else:
        productos_master = pd.DataFrame(columns=["CODIGO_PRODUCTO","PRODUCTO","PRECIO_REFERENCIA","ULTIMO_PRECIO","PRECIO_MIN_HISTORICO","PRECIO_MAX_HISTORICO","COMISION_UNITARIA_SUGERIDA","FECHA_ULTIMO_PRECIO","ACTIVO","VARIANTES_DETECTADAS","ESTADO_REVISION"])

    if not asesores.empty:
        asesores_master = pd.DataFrame({
            "ASESOR_ID": asesores.get("asesor_id", ""),
            "NOMBRE_ASESOR": asesores["nombre"],
            "TIPO": asesores.get("tipo", ""),
            "TELEFONO": asesores.get("telefono", ""),
            "EMAIL": asesores.get("email", ""),
            "ACTIVO": asesores.get("activo", "SI"),
            "ULTIMA_ACTUALIZACION": asesores.get("ultima_modificacion", ""),
            "FUENTE_DATOS": asesores.get("fuente_origen", ""),
            "OBSERVACIONES": asesores.get("observaciones", ""),
            "REGISTROS_HISTORICOS": 0,
        })
    else:
        asesores_master = pd.DataFrame(columns=["ASESOR_ID","NOMBRE_ASESOR","TIPO","TELEFONO","EMAIL","ACTIVO","ULTIMA_ACTUALIZACION","FUENTE_DATOS","OBSERVACIONES","REGISTROS_HISTORICOS"])

    extra_frames = {
        "Clientes_Maestro": clientes_master,
        "Productos_Maestro": productos_master,
        "Asesores_Maestro": asesores_master,
        "Cotizaciones": self.table("SELECT * FROM cotizaciones ORDER BY fecha, numero_cotizacion"),
        "Cotizaciones_detalle": self.table("SELECT * FROM cotizaciones_detalle ORDER BY numero_cotizacion, item"),
        "Historial_cambios": self.table("SELECT * FROM historial_cambios ORDER BY id"),
        "Fuentes_datos": self.table("SELECT * FROM fuentes_datos ORDER BY id"),
    }
    try:
        extra_frames["Cartera_pendiente"] = self.outstanding_invoices("", "Cliente").copy()
    except Exception:
        extra_frames["Cartera_pendiente"] = pd.DataFrame()
    extra_frames["Control_autoguardado"] = pd.DataFrame([{
        "archivo_fuente": str(read_master_sources()[0]) if read_master_sources() else "",
        "archivo_copia_diaria": str(target),
        "fecha_actualizacion": datetime.now().isoformat(timespec="seconds"),
        "base_sqlite": str(self.path),
        "nota": "Copia diaria automática con los tres maestros oficiales.",
    }])
    with pd.ExcelWriter(tmp, engine="openpyxl", mode="a", if_sheet_exists="replace") as writer:
        for sheet_name, frame in extra_frames.items():
            frame.to_excel(writer, sheet_name=sheet_name[:31], index=False)
    try:
        tmp.replace(target); saved = target
    except PermissionError:
        recovery = target.with_name(f"{target.stem}_RECUPERACION_{datetime.now().strftime('%H%M%S')}{target.suffix}")
        tmp.replace(recovery); saved = recovery
    cfg = read_config()
    cfg["daily_snapshot_path"] = str(target)
    cfg["daily_snapshot_last_saved"] = str(saved)
    cfg["daily_snapshot_updated_at"] = datetime.now().isoformat(timespec="seconds")
    write_config(cfg)
    return saved

SalesStore.export_daily_snapshot = _v95_export_daily_snapshot



# ==================== V9.6 FUENTE MAESTRA ROBUSTA ====================

def _v96_validate_master_workbook(source_path: Path):
    """Valida el contrato mínimo de la fuente maestra.

    La hoja de ventas no es requisito de importación: la fuente maestra alimenta
    exclusivamente Clientes_Maestro, Productos_Maestro y Asesores_Maestro.
    """
    required = {
        "Clientes_Maestro": [
            "CLIENTE_ID", "NOMBRE", "NIT_DOCUMENTO", "TELEFONO", "EMAIL",
            "DIRECCION", "CIUDAD", "BARRIO", "LOCAL_EDIFICIO", "DATOS_ENTREGA", "ACTIVO",
        ],
        "Productos_Maestro": [
            "CODIGO_PRODUCTO", "PRODUCTO", "PRECIO_REFERENCIA", "ULTIMO_PRECIO",
            "COMISION_UNITARIA_SUGERIDA", "ACTIVO",
        ],
        "Asesores_Maestro": [
            "ASESOR_ID", "NOMBRE_ASESOR", "TIPO", "ACTIVO",
        ],
    }
    try:
        workbook = pd.ExcelFile(source_path)
    except Exception as exc:
        raise ValueError(f"No fue posible abrir la fuente maestra:\n{source_path}\n\n{exc}") from exc
    try:
        lookup = {str(s).strip().upper(): s for s in workbook.sheet_names}
        problems = []
        for sheet_name, columns in required.items():
            actual_sheet = lookup.get(sheet_name.upper())
            if not actual_sheet:
                problems.append(f"Falta la hoja '{sheet_name}'.")
                continue
            df = pd.read_excel(workbook, sheet_name=actual_sheet, nrows=3)
            actual_cols = {str(c).strip().upper() for c in df.columns}
            missing = [c for c in columns if c.upper() not in actual_cols]
            if missing:
                problems.append(f"{sheet_name}: faltan columnas {', '.join(missing)}")
        if problems:
            raise ValueError(
                "La fuente seleccionada no cumple el formato maestro requerido.\n\n"
                + "\n".join(f"• {p}" for p in problems)
                + "\n\nLa hoja de ventas puede estar vacía; no se usa para cargar los maestros."
            )
    finally:
        workbook.close()


def _v96_validate_incoming_products(productos: list[dict]):
    seen_codes = {}
    seen_names = {}
    problems = []
    for producto in productos:
        name = str(producto.get("nombre", "") or "").strip()
        code = _v95_clean_cell(producto.get("codigo", ""))
        if not name:
            continue
        nkey = name.casefold()
        ckey = str(code).strip()
        if nkey in seen_names and seen_names[nkey] != ckey:
            problems.append(f"Producto duplicado por nombre: '{name}' con códigos {seen_names[nkey]} y {ckey}.")
        else:
            seen_names[nkey] = ckey
        if ckey:
            if ckey in seen_codes and seen_codes[ckey].casefold() != nkey:
                problems.append(f"Código {ckey} asignado a dos productos: '{seen_codes[ckey]}' y '{name}'.")
            else:
                seen_codes[ckey] = name
    if problems:
        raise ValueError("Hay inconsistencias en Productos_Maestro:\n\n" + "\n".join(f"• {p}" for p in problems[:20]))


def _v96_import_master_records(self, clientes: list[dict], productos: list[dict], source_path: str = ""):
    """Importación tolerante a catálogos antiguos.

    Resuelve choques nombre/código antes de escribir, en vez de intentar crear un
    segundo producto con el mismo nombre. La fuente maestra es la autoridad para
    código, nombre, precio y comisión de los productos que contiene.
    """
    stamp = datetime.now().isoformat(timespec="seconds")
    source_label = str(source_path or "").strip()
    _v96_validate_incoming_products(productos)

    try:
        self.conn.execute("BEGIN IMMEDIATE")

        # Clientes: conservar la clave por nombre, actualizando sus datos maestros.
        for cliente in clientes:
            name = str(cliente.get("nombre", "") or "").strip()
            if not name:
                continue
            self.conn.execute(
                """
                INSERT INTO clientes (
                    nombre, ciudad, direccion, telefono, email, notas, fuente_origen, ultima_modificacion,
                    modificado_manualmente, cliente_id, nit_documento, barrio, local_edificio, datos_entrega, activo
                ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, 0, ?, ?, ?, ?, ?, ?)
                ON CONFLICT(nombre) DO UPDATE SET
                    ciudad=excluded.ciudad, direccion=excluded.direccion, telefono=excluded.telefono,
                    email=excluded.email, notas=excluded.notas, cliente_id=excluded.cliente_id,
                    nit_documento=excluded.nit_documento, barrio=excluded.barrio,
                    local_edificio=excluded.local_edificio, datos_entrega=excluded.datos_entrega,
                    activo=excluded.activo,
                    fuente_origen=CASE WHEN excluded.fuente_origen <> '' THEN excluded.fuente_origen ELSE clientes.fuente_origen END,
                    ultima_modificacion=excluded.ultima_modificacion, modificado_manualmente=0
                """,
                (
                    name, cliente.get("ciudad", ""), cliente.get("direccion", ""),
                    cliente.get("telefono", ""), cliente.get("email", ""), cliente.get("notas", ""),
                    source_label or cliente.get("fuente_origen", ""), stamp,
                    cliente.get("cliente_id", ""), cliente.get("nit_documento", ""), cliente.get("barrio", ""),
                    cliente.get("local_edificio", ""), cliente.get("datos_entrega", ""), cliente.get("activo", "SI"),
                ),
            )

        # Productos que no estén en la nueva fuente dejan de aparecer en catálogos,
        # pero no se borran para preservar cualquier referencia histórica por nombre.
        if productos:
            self.conn.execute("UPDATE productos SET activo='NO' WHERE COALESCE(activo,'SI') <> 'NO'")

        for idx, producto in enumerate(productos, start=1):
            code = _v95_clean_cell(producto.get("codigo", ""))
            name = str(producto.get("nombre", "") or "").strip()
            if not name:
                continue
            if not code:
                # El maestro actual usa códigos numéricos; si por excepción falta uno,
                # asignar el siguiente disponible sin tocar códigos ya existentes.
                numeric = []
                for r in self.conn.execute("SELECT codigo FROM productos").fetchall():
                    try:
                        numeric.append(int(str(r["codigo"]).strip()))
                    except Exception:
                        pass
                code = str(max(numeric or [1000]) + 1)

            by_name = self.conn.execute(
                "SELECT rowid, codigo, nombre FROM productos WHERE TRIM(nombre)=TRIM(?) COLLATE NOCASE LIMIT 1",
                (name,),
            ).fetchone()
            by_code = self.conn.execute(
                "SELECT rowid, codigo, nombre FROM productos WHERE codigo=? LIMIT 1",
                (code,),
            ).fetchone()

            # Si nombre y código apuntan a dos filas antiguas distintas, consolidarlas.
            if by_name and by_code and by_name["rowid"] != by_code["rowid"]:
                # No hay FK hacia productos: ventas_detalle/cotizaciones guardan el nombre.
                # Eliminar solo la fila de catálogo que ocupa el código deseado.
                self.conn.execute("DELETE FROM productos WHERE rowid=?", (by_code["rowid"],))
                by_code = None

            values = (
                name, producto.get("unidad", "KLS"),
                float(producto.get("precio_venta", 0) or 0),
                float(producto.get("comision_unitaria_sugerida", 0) or 0),
                float(producto.get("costo", 0) or 0),
                float(producto.get("stock_actual", 0) or 0),
                float(producto.get("stock_minimo", 0) or 0),
                producto.get("activo", "SI") or "SI",
                source_label or producto.get("fuente_origen", ""), stamp,
                float(producto.get("precio_referencia", 0) or 0),
                float(producto.get("ultimo_precio", 0) or 0),
            )

            if by_name:
                self.conn.execute(
                    """
                    UPDATE productos SET
                        codigo=?, nombre=?, unidad=?, precio_venta=?, comision_unitaria_sugerida=?,
                        costo=?, stock_actual=?, stock_minimo=?, activo=?, fuente_origen=?, ultima_modificacion=?,
                        modificado_manualmente=0, precio_referencia=?, ultimo_precio=?
                    WHERE rowid=?
                    """,
                    (code,) + values + (by_name["rowid"],),
                )
            elif by_code:
                self.conn.execute(
                    """
                    UPDATE productos SET
                        nombre=?, unidad=?, precio_venta=?, comision_unitaria_sugerida=?,
                        costo=?, stock_actual=?, stock_minimo=?, activo=?, fuente_origen=?, ultima_modificacion=?,
                        modificado_manualmente=0, precio_referencia=?, ultimo_precio=?
                    WHERE rowid=?
                    """,
                    values + (by_code["rowid"],),
                )
            else:
                self.conn.execute(
                    """
                    INSERT INTO productos (
                        codigo, nombre, unidad, precio_venta, comision_unitaria_sugerida, costo, stock_actual,
                        stock_minimo, activo, fuente_origen, ultima_modificacion, modificado_manualmente,
                        precio_referencia, ultimo_precio
                    ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 0, ?, ?)
                    """,
                    (code,) + values,
                )

        self.conn.commit()
    except Exception:
        self.conn.rollback()
        raise


def _v96_import_master_source(self, source_path: Path):
    _v96_validate_master_workbook(source_path)
    clientes, productos = load_master_records([source_path])
    asesores = load_master_advisors([source_path])
    if not clientes or not productos or not asesores:
        raise ValueError(
            "La fuente debe contener registros en las tres hojas maestras: "
            "Clientes_Maestro, Productos_Maestro y Asesores_Maestro."
        )
    save_master_sources([source_path])
    self.store.import_master_records(clientes, productos, str(source_path))
    self.store.import_master_advisors(asesores, str(source_path))
    # No reconstruir códigos desde nombres: conservar los códigos numéricos del maestro.
    self.store.register_source_import(
        source_path, len(clientes), len(productos), 0,
        f"Fuente maestra V9.6 importada. Asesores: {len(asesores)}. Ventas importadas: 0."
    )
    self.catalogs = load_catalogs()
    self.reload_master_catalogs()
    self.refresh_all()
    self.refresh_source_panel()
    messagebox.showinfo(
        "Fuente maestra actualizada",
        f"Fuente activa:\n{source_path}\n\n"
        f"Clientes: {len(clientes)}\nProductos: {len(productos)}\nAsesores: {len(asesores)}\nVentas importadas: 0\n\n"
        "Los tres maestros quedaron sincronizados. La hoja de ventas puede permanecer vacía; "
        "las ventas nuevas se registran desde la aplicación.",
        parent=self,
    )


SalesStore.import_master_records = _v96_import_master_records

