# ==================== FIN V9.5 TRES MAESTROS ====================

def _autosave_after_db_change(method_name: str):
    """Envuelve una acción de UI y exporta solo si SQLite realmente cambió."""
    original = getattr(SalesFormApp, method_name, None)
    if original is None:
        return
    def wrapped(self, *args, **kwargs):
        before = getattr(self.store.conn, "total_changes", 0)
        result = original(self, *args, **kwargs)
        after = getattr(self.store.conn, "total_changes", 0)
        if after > before:
            try:
                path = self.store.export_daily_snapshot()
                self.last_daily_snapshot_path = str(path)
            except Exception as exc:
                # La operación ya quedó segura en SQLite. Se informa el problema
                # del Excel sin revertir la venta/cotización/abono registrado.
                try:
                    messagebox.showwarning(
                        "Autoguardado diario",
                        "El cambio quedó guardado en la base de datos, pero no fue posible actualizar la copia Excel diaria.\n\n"
                        f"Detalle: {exc}",
                        parent=self,
                    )
                except Exception:
                    pass
        return result
    setattr(SalesFormApp, method_name, wrapped)


# Acciones operativas que deben refrescar automáticamente la copia diaria.
for _method in [
    "save_sale",
    "save_quote",
    "delete_selected_quote",
    "delete_all_quotes",
    "save_payment",
    "apply_payment",
    # También mantenemos sincronizados los cambios de maestros.
    "save_client",
    "save_product",
]:
    _autosave_after_db_change(_method)

# ==================== FIN V9.2 AUTOGUARDADO DIARIO ====================



