def _v98_on_quote_product_select(self, _event=None):
    try:
        row = self.find_product_row(self.vars["cot_producto"].get().strip())
        if row.empty:
            return
        p = row.iloc[0]
        self.vars["cot_producto"].set(f"{p['codigo']} - {p['nombre']}")
        costo = float(p.get("costo", 0) or 0)
        comision = float(p.get("comision_unitaria_sugerida", 0) or 0)
        precio = float(p.get("ultimo_precio", 0) or p.get("precio_venta", 0) or p.get("precio_referencia", 0) or 0)
        if "cot_costo" in self.vars:
            self.vars["cot_costo"].set(f"{costo:.0f}")
        if "cot_comision_unitaria" in self.vars:
            self.vars["cot_comision_unitaria"].set(f"{comision:.0f}")
        if precio > 0:
            self.vars["cot_precio"].set(f"{precio:.0f}")
    except Exception:
        pass
SalesFormApp._v98_on_quote_product_select = _v98_on_quote_product_select


def _v98_add_quote_line(self):
    try:
        p = self.find_product_row(self.require("cot_producto", "Producto"))
        if p.empty:
            raise ValueError("Seleccione un producto válido.")
        p = p.iloc[0]
        qty = money(self.vars["cot_cantidad"].get())
        sale_price = money(self.vars["cot_precio"].get()) or money(p.get("ultimo_precio", 0)) or money(p.get("precio_venta", 0))
        cost = money(self.vars.get("cot_costo", tk.StringVar(value="0")).get())
        commission_unit = money(self.vars.get("cot_comision_unitaria", tk.StringVar(value="0")).get())
        if qty <= 0 or sale_price <= 0:
            raise ValueError("Cantidad y precio de venta deben ser mayores a cero.")
        gross = qty * sale_price
        desc = min(money(self.vars["cot_descuento"].get()), gross)
        base = gross - desc
        iva = base * 0.19 if self.vars["cot_iva_auto"].get().upper() == "SI" else 0
        self.quote_lines.append({
            "producto": str(p["nombre"]), "cantidad": qty,
            "precio_unitario": sale_price, "precio_venta": sale_price,
            "costo_unitario": cost, "comision_unitaria": commission_unit,
            "descuento": desc, "subtotal": base, "iva": iva, "total": base + iva,
        })
        self.refresh_quote_lines()
        for key, value in (("cot_producto", ""), ("cot_cantidad", "1"), ("cot_precio", "0"),
                           ("cot_costo", "0"), ("cot_comision_unitaria", "0"), ("cot_descuento", "0")):
            if key in self.vars:
                self.vars[key].set(value)
    except Exception as exc:
        messagebox.showerror("Cotización", str(exc), parent=self)
SalesFormApp.add_quote_line = _v98_add_quote_line


