# Conversión de cotización: transfiere exactamente precio de venta, costo y comisión,
# sin sumar la comisión nuevamente al total.
def _v98_convert_quote_to_sale(self):
    try:
        num = self.require("cot_numero", "Número de cotización")
        existing_head, _ = self.store.get_quote(num)
        if not existing_head.empty:
            existing = existing_head.iloc[0]
            if str(existing.get("estado", "")).upper() == "CONVERTIDA" and str(existing.get("cuenta_cobro_convertida", "") or "").strip():
                raise ValueError(f"Esta cotización ya fue convertida en la cuenta {existing['cuenta_cobro_convertida']}.")
        if not self.quote_lines:
            raise ValueError("Agregue al menos un producto a la cotización antes de convertirla.")
        quote_data = {
            "numero_cotizacion": num, "fecha": self.require("cot_fecha", "Fecha"),
            "valida_hasta": self.require("cot_valida", "Válida hasta"),
            "cliente": self.require("cot_cliente", "Cliente"), "asesor": self.vars["cot_asesor"].get().strip(),
            "direccion": self.require("cot_direccion", "Dirección"), "ciudad": self.require("cot_ciudad", "Ciudad"),
            "telefono": self.require("cot_telefono", "Teléfono"), "barrio": self.vars["cot_barrio"].get().strip(),
            "local_edificio": self.vars["cot_local_edificio"].get().strip(), "datos_entrega": self.vars["cot_datos_entrega"].get().strip(),
            "estado": self.require("cot_estado", "Estado"), "forma_pago": self.vars["cot_forma_pago"].get().strip(),
            "domicilio": money(self.vars["cot_domicilio_cliente"].get()), "domicilio_empresa": money(self.vars["cot_domicilio_empresa"].get()),
            "domicilio_cliente": money(self.vars["cot_domicilio_cliente"].get()), "observaciones": self.vars["cot_obs"].get().strip(),
        }
        before = self.store.quote_snapshot(num)
        self.store.save_quote(quote_data, self.quote_lines)
        after = self.store.quote_snapshot(num)
        self.store.log_snapshot_changes("Cotización", num, before, after, "EDITAR" if before else "CREAR")
        head, det = self.store.get_quote(num)
        q = head.iloc[0]
        def qtext(field):
            value = q.get(field, "")
            return "" if pd.isna(value) else str(value).strip()
        self.clear_sales_form(); self.show_page("ventas"); self.update_idletasks()
        transfer = {
            "venta_cliente": qtext("cliente"), "venta_asesor": qtext("asesor"), "venta_direccion": qtext("direccion"),
            "venta_ciudad": qtext("ciudad"), "venta_telefono": qtext("telefono"), "venta_barrio": qtext("barrio"),
            "venta_local_edificio": qtext("local_edificio"), "venta_datos_entrega": qtext("datos_entrega"),
            "venta_obs": qtext("observaciones"), "venta_cotizacion_origen": num,
            "venta_domicilio_empresa": str(float(q.get("domicilio_empresa",0) or 0)),
            "venta_domicilio_cliente": str(float(q.get("domicilio_cliente",q.get("domicilio",0)) or 0)),
        }
        for key, value in transfer.items():
            if key in self.vars: self.vars[key].set(value)
        self.product_lines=[]
        for _, r in det.iterrows():
            prod_match = self.store.table("SELECT codigo, costo, comision_unitaria_sugerida FROM productos WHERE nombre=? LIMIT 1", (r["producto"],))
            code = str(prod_match.iloc[0]["codigo"] or "") if not prod_match.empty else ""
            cost = float(r.get("costo_unitario", 0) or 0)
            if cost <= 0 and not prod_match.empty: cost = float(prod_match.iloc[0].get("costo",0) or 0)
            commission_unit = float(r.get("comision_unitaria",0) or 0)
            if commission_unit <= 0 and not prod_match.empty: commission_unit = float(prod_match.iloc[0].get("comision_unitaria_sugerida",0) or 0)
            qty=float(r["cantidad"]); sale_price=float(r.get("precio_venta",0) or r.get("precio_unitario",0) or 0)
            subtotal=float(r["subtotal"]); iva=float(r["iva"])
            self.product_lines.append({
                "codigo":code, "producto":r["producto"], "cantidad_kls":qty,
                "valor_x_kl":sale_price, "valor_total":subtotal, "costo_unitario":cost,
                "comision_unitaria":commission_unit, "comision":qty*commission_unit,
                "iva_19":iva, "retenciones":0, "chile_fresco":0, "domicilio":0,
                "total_linea":subtotal+iva,
            })
        self.refresh_product_lines()
        self.set_sales_status(f"Cotización {num} cargada. Precio de venta, costo y comisión fueron transferidos sin duplicar valores.", "documento")
        messagebox.showinfo("Cotización convertida", f"Cotización {num} cargada en Ventas. Complete la cuenta de cobro y el pago.", parent=self)
    except Exception as exc:
        messagebox.showerror("Convertir cotización", str(exc), parent=self)
SalesFormApp.convert_quote_to_sale = _v98_convert_quote_to_sale


