# Excel diario: reforzar campos de costo/precio en VENTAS y detalle después de la exportación base.
_v98_previous_export_daily_snapshot = SalesStore.export_daily_snapshot
def _v98_export_daily_snapshot(self, output_path: Path | None = None) -> Path:
    saved = Path(_v98_previous_export_daily_snapshot(self, output_path or _daily_snapshot_target()))
    # Asegurar que el archivo guardado tenga las columnas explícitas en la hoja VENTAS.
    try:
        ventas = self.table("SELECT * FROM ventas ORDER BY fecha, cuenta_cobro")
        det = self.table("SELECT * FROM ventas_detalle ORDER BY cuenta_cobro, item")
        if not det.empty:
            # Ventas_detalle ya lleva costo_unitario por SELECT *; añadir alias claro de precio.
            det_export = det.copy()
            det_export["precio_venta"] = det_export.get("valor_x_kl", 0)
            det_export["total_linea"] = det_export.get("valor_total",0) + det_export.get("iva_19",0) + det_export.get("retenciones",0) + det_export.get("chile_fresco",0)
            # No reemplazar las otras hojas: solo refrescar detalle con campos explícitos.
            with pd.ExcelWriter(saved, engine="openpyxl", mode="a", if_sheet_exists="replace") as writer:
                det_export.rename(columns=str.upper).to_excel(writer, sheet_name="Ventas_detalle", index=False)
    except Exception:
        pass
    return saved
SalesStore.export_daily_snapshot = _v98_export_daily_snapshot


# Evitar que un diálogo nativo deje la aplicación minimizada u oculta en Windows.
_v98_original_asksaveasfilename = filedialog.asksaveasfilename
def _v98_asksaveasfilename(*args, **kwargs):
    parent = kwargs.get("parent")
    result = _v98_original_asksaveasfilename(*args, **kwargs)
    try:
        w = parent
        visited=set()
        while w is not None and id(w) not in visited:
            visited.add(id(w))
            try:
                w.deiconify(); w.lift(); w.focus_force()
                w.attributes("-topmost", True); w.after(120, lambda ww=w: ww.attributes("-topmost", False))
            except Exception:
                pass
            w = getattr(w, "master", None)
    except Exception:
        pass
    return result
filedialog.asksaveasfilename = _v98_asksaveasfilename


# Crear/actualizar una copia diaria incluso al abrir la aplicación, para que la ruta
# quede visible desde el comienzo y no dependa de que el primer cambio dispare el backup.
_v98_original_app_init = SalesFormApp.__init__
def _v98_app_init(self, *args, **kwargs):
    _v98_original_app_init(self, *args, **kwargs)
    try:
        path = self.store.export_daily_snapshot()
        self.last_daily_snapshot_path = str(path)
    except Exception as exc:
        self.last_daily_snapshot_path = ""
        # La variable `exc` deja de existir al terminar el except.
        # Capturamos el texto antes de programar el callback de Tkinter.
        _daily_error_text = str(exc)
        _daily_expected_path = str(_daily_snapshot_target())
        try:
            self.after(
                300,
                lambda err=_daily_error_text, expected=_daily_expected_path: messagebox.showwarning(
                    "Copia diaria",
                    "La aplicación abrió, pero no fue posible crear la copia diaria inicial.\n\n"
                    f"Ruta esperada: {expected}\n\nDetalle: {err}",
                    parent=self,
                ),
            )
        except Exception:
            pass
SalesFormApp.__init__ = _v98_app_init

