# ==================== V10.1.8 PRODUCTO MAESTRO / UNIDAD / COSTO ====================
# Objetivos:
# - La unidad y el costo provienen del maestro de productos cuando existan.
# - Si un producto se crea/edita en la app, su unidad/costo quedan en SQLite y en el Excel diario.
# - Cotización y venta muestran la unidad y conservan costo/comisión internos.
# - Al seleccionar otro producto, SIEMPRE se refrescan precio, costo, comisión y unidad.
# - La unidad se guarda por línea para no depender de cambios futuros del maestro.

_v985_previous_load_master_records = load_master_records
def load_master_records(source_files: list[Path] | None = None) -> tuple[list[dict], list[dict]]:
    clientes, productos = _v985_previous_load_master_records(source_files)
    product_map = {str(p.get("nombre", "") or "").strip().upper(): p for p in productos if p.get("nombre")}
    files = source_files if source_files is not None else read_master_sources()

    for source in files or []:
        path = Path(source)
        if not path.exists():
            continue
        try:
            book = pd.ExcelFile(path)
            sheet = _v95_find_sheet(book, "Productos_Maestro", "MAESTRO_PRODUCTOS", "PRODUCTOS")
            if not sheet:
                book.close()
                continue
            df = pd.read_excel(book, sheet_name=sheet, nrows=20000)
            cmap = normalized_columns(df)
            def c(*opts): return first_column(cmap, *opts)
            name_col = c("PRODUCTO", "NOMBRE")
            unit_col = c("UNIDAD", "UNIDAD_MEDIDA", "UNIDAD MEDIDA", "UOM")
            cost_col = c(
                "COSTO_UNITARIO", "COSTO UNITARIO", "COSTO",
                "COSTO_COMPRA", "COSTO COMPRA", "ULTIMO_COSTO", "ÚLTIMO COSTO"
            )
            if name_col:
                for _, row in df.iterrows():
                    name = _v95_clean_cell(row.get(name_col))
                    if not name:
                        continue
                    p = product_map.get(name.strip().upper())
                    if p is None:
                        continue
                    unit = _v95_clean_cell(row.get(unit_col)) if unit_col else ""
                    if unit:
                        p["unidad"] = unit.upper()
                    elif not str(p.get("unidad", "") or "").strip():
                        p["unidad"] = "KLS"
                    if cost_col:
                        p["costo"] = money(row.get(cost_col, 0))
            book.close()
        except Exception:
            try:
                book.close()
            except Exception:
                pass

    for p in productos:
        if not str(p.get("unidad", "") or "").strip():
            p["unidad"] = "KLS"
        p["unidad"] = str(p["unidad"]).strip().upper()
        p["costo"] = float(p.get("costo", 0) or 0)
    return clientes, productos


# Esquema: conservar la unidad usada realmente en cada línea.
_v985_previous_init_schema = SalesStore.init_schema
def _v985_init_schema(self):
    _v985_previous_init_schema(self)
    self.ensure_column("ventas_detalle", "unidad", "TEXT NOT NULL DEFAULT 'KLS'")
    self.ensure_column("cotizaciones_detalle", "unidad", "TEXT NOT NULL DEFAULT 'KLS'")
    try:
        self.conn.execute("""
            UPDATE ventas_detalle
               SET unidad = COALESCE(
                   NULLIF((SELECT p.unidad FROM productos p WHERE p.nombre=ventas_detalle.producto LIMIT 1),''),
                   'KLS'
               )
             WHERE unidad IS NULL OR TRIM(unidad)=''
        """)
        self.conn.execute("""
            UPDATE cotizaciones_detalle
               SET unidad = COALESCE(
                   NULLIF((SELECT p.unidad FROM productos p WHERE p.nombre=cotizaciones_detalle.producto LIMIT 1),''),
                   'KLS'
               )
             WHERE unidad IS NULL OR TRIM(unidad)=''
        """)
        self.conn.commit()
    except Exception:
        pass
SalesStore.init_schema = _v985_init_schema


def _v985_add_detail(self, data: dict):
    current = self.conn.execute(
        "SELECT COALESCE(MAX(item), 0) + 1 FROM ventas_detalle WHERE cuenta_cobro = ?",
        (data["cuenta_cobro"],),
    ).fetchone()[0]
    self.conn.execute(
        """
        INSERT INTO ventas_detalle (
            cuenta_cobro, item, producto, unidad, cantidad_kls, valor_x_kl,
            valor_total, costo_unitario, comision_unitaria, comision, iva_19,
            retenciones, chile_fresco, domicilio
        ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        """,
        (
            data["cuenta_cobro"], current, data["producto"],
            str(data.get("unidad", "KLS") or "KLS").strip().upper(),
            data["cantidad_kls"], data["valor_x_kl"], data["valor_total"],
            data.get("costo_unitario", 0), data.get("comision_unitaria", 0),
            data.get("comision", 0), data.get("iva_19", 0),
            data.get("retenciones", 0), data.get("chile_fresco", 0),
            data.get("domicilio", 0),
        ),
    )
    self.conn.commit()
SalesStore.add_detail = _v985_add_detail


def _v985_save_quote(self, data: dict, details: list[dict]):
    self.ensure_cliente(data["cliente"])
    self.conn.execute(
        """
        INSERT INTO cotizaciones (
            numero_cotizacion, fecha, valida_hasta, cliente, asesor, direccion,
            ciudad, telefono, barrio, local_edificio, datos_entrega, estado,
            forma_pago, domicilio, domicilio_empresa, domicilio_cliente, observaciones,
            cuenta_cobro_convertida, fecha_conversion
        ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        ON CONFLICT(numero_cotizacion) DO UPDATE SET
            fecha=excluded.fecha, valida_hasta=excluded.valida_hasta,
            cliente=excluded.cliente, asesor=excluded.asesor,
            direccion=excluded.direccion, ciudad=excluded.ciudad,
            telefono=excluded.telefono, barrio=excluded.barrio,
            local_edificio=excluded.local_edificio, datos_entrega=excluded.datos_entrega,
            estado=excluded.estado, forma_pago=excluded.forma_pago,
            domicilio=excluded.domicilio, domicilio_empresa=excluded.domicilio_empresa,
            domicilio_cliente=excluded.domicilio_cliente, observaciones=excluded.observaciones
        """,
        (
            data["numero_cotizacion"], data["fecha"], data.get("valida_hasta", ""),
            data["cliente"], data.get("asesor", ""), data.get("direccion", ""),
            data.get("ciudad", ""), data.get("telefono", ""), data.get("barrio", ""),
            data.get("local_edificio", ""), data.get("datos_entrega", ""),
            data.get("estado", "BORRADOR"), data.get("forma_pago", ""),
            float(data.get("domicilio_cliente", data.get("domicilio", 0)) or 0),
            float(data.get("domicilio_empresa", 0) or 0),
            float(data.get("domicilio_cliente", data.get("domicilio", 0)) or 0),
            data.get("observaciones", ""), data.get("cuenta_cobro_convertida", ""),
            data.get("fecha_conversion", ""),
        ),
    )
    self.conn.execute("DELETE FROM cotizaciones_detalle WHERE numero_cotizacion=?", (data["numero_cotizacion"],))
    for idx, d in enumerate(details, 1):
        pv = float(d.get("precio_venta", d.get("precio_unitario", 0)) or 0)
        self.conn.execute(
            """
            INSERT INTO cotizaciones_detalle (
                numero_cotizacion, item, producto, unidad, cantidad, precio_unitario,
                costo_unitario, comision_unitaria, precio_venta,
                descuento, subtotal, iva, total
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                data["numero_cotizacion"], idx, d["producto"],
                str(d.get("unidad", "KLS") or "KLS").strip().upper(),
                float(d["cantidad"]), pv,
                float(d.get("costo_unitario", 0) or 0),
                float(d.get("comision_unitaria", 0) or 0), pv,
                float(d.get("descuento", 0) or 0), float(d["subtotal"]),
                float(d.get("iva", 0) or 0), float(d["total"]),
            ),
        )
    self.conn.commit()
SalesStore.save_quote = _v985_save_quote


