# Copia diaria: el maestro de productos conserva unidad y costo, y el detalle conserva la unidad por línea.
_v985_previous_export_daily_snapshot = SalesStore.export_daily_snapshot
def _v985_export_daily_snapshot(self, output_path: Path | None = None) -> Path:
    saved=Path(_v985_previous_export_daily_snapshot(self, output_path or _daily_snapshot_target()))
    try:
        productos=self.productos().copy()
        if not productos.empty:
            pm=pd.DataFrame({
                "CODIGO_PRODUCTO":productos["codigo"],
                "PRODUCTO":productos["nombre"],
                "UNIDAD":productos.get("unidad","KLS"),
                "COSTO_UNITARIO":productos.get("costo",0),
                "PRECIO_REFERENCIA":productos.get("precio_referencia",productos.get("precio_venta",0)),
                "ULTIMO_PRECIO":productos.get("ultimo_precio",productos.get("precio_venta",0)),
                "COMISION_UNITARIA_SUGERIDA":productos.get("comision_unitaria_sugerida",0),
                "ACTIVO":productos.get("activo","SI"),
                "ULTIMA_ACTUALIZACION":productos.get("ultima_modificacion",""),
                "FUENTE_DATOS":productos.get("fuente_origen",""),
            })
        else:
            pm=pd.DataFrame(columns=[
                "CODIGO_PRODUCTO","PRODUCTO","UNIDAD","COSTO_UNITARIO",
                "PRECIO_REFERENCIA","ULTIMO_PRECIO","COMISION_UNITARIA_SUGERIDA",
                "ACTIVO","ULTIMA_ACTUALIZACION","FUENTE_DATOS"
            ])
        with pd.ExcelWriter(saved,engine="openpyxl",mode="a",if_sheet_exists="replace") as writer:
            pm.to_excel(writer,sheet_name="Productos_Maestro",index=False)
    except Exception:
        pass
    return saved
SalesStore.export_daily_snapshot = _v985_export_daily_snapshot

# ==================== FIN V10.1.8 ====================



# ==================== V10.1.8 MAESTRO PRODUCTOS + EXPORTACIÓN ====================
# Reglas:
# 1. Nunca cambiar silenciosamente precio/costo/comisión/unidad del producto maestro.
# 2. Si una venta/cotización usa valores distintos al maestro, preguntar si se actualiza.
# 3. Toda actualización aceptada registra fecha, auditoría y refresca la copia Excel diaria.
# 4. Exportaciones separan COSTO de PRECIO DE VENTA y muestran código/unidad.

def _v986_num(value) -> float:
    try:
        return float(value or 0)
    except Exception:
        return money(value)


def _v986_norm(value) -> str:
    return str(value or "").strip()


def _v986_product_snapshot(row) -> dict:
    if row is None:
        return {}
    try:
        return {
            "codigo": _v986_norm(row.get("codigo", "")),
            "nombre": _v986_norm(row.get("nombre", "")),
            "unidad": (_v986_norm(row.get("unidad", "KLS")) or "KLS").upper(),
            "precio_venta": _v986_num(row.get("precio_venta", 0)),
            "ultimo_precio": _v986_num(row.get("ultimo_precio", row.get("precio_venta", 0))),
            "precio_referencia": _v986_num(row.get("precio_referencia", 0)),
            "comision_unitaria_sugerida": _v986_num(row.get("comision_unitaria_sugerida", 0)),
            "costo": _v986_num(row.get("costo", 0)),
            "stock_actual": _v986_num(row.get("stock_actual", 0)),
            "stock_minimo": _v986_num(row.get("stock_minimo", 0)),
            "activo": (_v986_norm(row.get("activo", "SI")) or "SI").upper(),
        }
    except Exception:
        return {}


def _v986_product_changes(before: dict, after: dict, fields: list[str] | None = None) -> list[tuple[str, object, object]]:
    labels = {
        "codigo": "Código",
        "nombre": "Nombre",
        "unidad": "Unidad",
        "precio_venta": "Precio de venta",
        "costo": "Costo por unidad",
        "comision_unitaria_sugerida": "Comisión por unidad",
        "stock_actual": "Stock actual",
        "stock_minimo": "Stock mínimo",
        "activo": "Activo",
    }
    fields = fields or list(labels)
    changes = []
    numeric = {"precio_venta", "costo", "comision_unitaria_sugerida", "stock_actual", "stock_minimo"}
    for key in fields:
        old = before.get(key, "")
        new = after.get(key, "")
        different = abs(_v986_num(old) - _v986_num(new)) > 0.000001 if key in numeric else _v986_norm(old).upper() != _v986_norm(new).upper()
        if different:
            changes.append((labels.get(key, key), old, new))
    return changes


def _v986_format_changes(changes: list[tuple[str, object, object]]) -> str:
    lines = []
    for label, old, new in changes:
        if label in {"Precio de venta", "Costo por unidad", "Comisión por unidad", "Stock actual", "Stock mínimo"}:
            try:
                old_txt = f"${_v986_num(old):,.0f}"
                new_txt = f"${_v986_num(new):,.0f}"
            except Exception:
                old_txt, new_txt = str(old), str(new)
        else:
            old_txt = str(old or "(vacío)")
            new_txt = str(new or "(vacío)")
        lines.append(f"• {label}: {old_txt}  →  {new_txt}")
    return "\n".join(lines)


def _v986_write_product_master(self, before: dict, after: dict, source_note: str = "Actualizado en la app"):
    """Persistencia autorizada del producto maestro, incluida la fecha del último cambio."""
    stamp = datetime.now().isoformat(timespec="seconds")
    old_code = _v986_norm(before.get("codigo", ""))
    new_code = _v986_norm(after.get("codigo", "")) or old_code or make_code(after["nombre"])

    # Si se cambia el código, preservar la misma fila siempre que el código nuevo esté libre.
    if before and old_code and old_code != new_code:
        conflict = self.conn.execute("SELECT 1 FROM productos WHERE codigo=? AND codigo<>?", (new_code, old_code)).fetchone()
        if conflict:
            raise ValueError(f"El código {new_code} ya está asignado a otro producto.")
        self.conn.execute("UPDATE productos SET codigo=? WHERE codigo=?", (new_code, old_code))

    # Mantener precio de referencia histórico. Para un producto nuevo, inicializarlo con el precio actual.
    ref_price = _v986_num(before.get("precio_referencia", 0))
    if not before and ref_price <= 0:
        ref_price = _v986_num(after.get("precio_venta", 0))

    self.conn.execute(
        """
        INSERT INTO productos (
            codigo, nombre, unidad, precio_venta, comision_unitaria_sugerida, costo,
            stock_actual, stock_minimo, activo, fuente_origen, ultima_modificacion,
            modificado_manualmente, precio_referencia, ultimo_precio
        ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 1, ?, ?)
        ON CONFLICT(codigo) DO UPDATE SET
            nombre=excluded.nombre,
            unidad=excluded.unidad,
            precio_venta=excluded.precio_venta,
            comision_unitaria_sugerida=excluded.comision_unitaria_sugerida,
            costo=excluded.costo,
            stock_actual=excluded.stock_actual,
            stock_minimo=excluded.stock_minimo,
            activo=excluded.activo,
            fuente_origen=excluded.fuente_origen,
            ultima_modificacion=excluded.ultima_modificacion,
            modificado_manualmente=1,
            precio_referencia=CASE
                WHEN COALESCE(productos.precio_referencia,0)<>0 THEN productos.precio_referencia
                ELSE excluded.precio_referencia END,
            ultimo_precio=excluded.ultimo_precio
        """,
        (
            new_code,
            _v986_norm(after.get("nombre", "")),
            (_v986_norm(after.get("unidad", "KLS")) or "KLS").upper(),
            _v986_num(after.get("precio_venta", 0)),
            _v986_num(after.get("comision_unitaria_sugerida", 0)),
            _v986_num(after.get("costo", 0)),
            _v986_num(after.get("stock_actual", 0)),
            _v986_num(after.get("stock_minimo", 0)),
            (_v986_norm(after.get("activo", "SI")) or "SI").upper(),
            source_note,
            stamp,
            ref_price,
            _v986_num(after.get("precio_venta", 0)),
        ),
    )
    self.conn.commit()

    # Auditoría campo a campo.
    action = "CREAR" if not before else "EDITAR"
    for label, old, new in _v986_product_changes(before, after):
        self.register_change("PRODUCTO", new_code, action, label, old, new)
    if not before:
        self.register_change("PRODUCTO", new_code, "CREAR", "producto", "", after.get("nombre", ""))

    return new_code, stamp


SalesStore.save_product_master_confirmed = _v986_write_product_master


def _v986_find_existing_product(self, code: str, name: str):
    code = _v986_norm(code)
    name = _v986_norm(name)
    if code:
        df = self.store.table("SELECT * FROM productos WHERE codigo=? LIMIT 1", (code,))
        if not df.empty:
            return df.iloc[0]
    if name:
        df = self.store.table("SELECT * FROM productos WHERE TRIM(nombre)=TRIM(?) COLLATE NOCASE LIMIT 1", (name,))
        if not df.empty:
            return df.iloc[0]
    return None


def _v986_refresh_after_product_master_change(self, message: str):
    self.reload_master_catalogs()
    self.refresh_all()
    try:
        saved = self.store.export_daily_snapshot()
        self.last_daily_snapshot_path = str(saved)
        message = f"{message}\n\nCopia diaria actualizada:\n{saved}"
    except Exception as exc:
        message = f"{message}\n\nEl cambio quedó guardado en SQLite, pero la copia diaria no pudo actualizarse:\n{exc}"
    messagebox.showinfo("Producto maestro", message, parent=self)


def _v986_save_product(self):
    """Edición del maestro desde Clientes / Productos con confirmación obligatoria."""
    try:
        proposed = {
            "codigo": self.vars["prod_codigo"].get().strip(),
            "nombre": self.require("prod_nombre", "Nombre del producto"),
            "unidad": (self.vars["prod_unidad"].get().strip() or "KLS").upper(),
            "precio_venta": money(self.vars["prod_precio"].get()),
            "comision_unitaria_sugerida": money(self.vars["prod_comision_unitaria"].get()),
            "costo": money(self.vars["prod_costo"].get()),
            "stock_actual": money(self.vars["prod_stock"].get()),
            "stock_minimo": money(self.vars["prod_minimo"].get()),
            "activo": (self.vars["prod_activo"].get().strip() or "SI").upper(),
        }
        existing_row = _v986_find_existing_product(self, proposed["codigo"], proposed["nombre"])
        before = _v986_product_snapshot(existing_row)

        if before:
            changes = _v986_product_changes(before, proposed)
            if not changes:
                messagebox.showinfo("Producto", "No se detectaron cambios en el producto.", parent=self)
                return
            ok = messagebox.askyesno(
                "Actualizar producto maestro",
                "Se detectaron cambios en el producto maestro:\n\n"
                + _v986_format_changes(changes)
                + "\n\n¿Desea actualizar el maestro con estos datos?",
                parent=self,
            )
            if not ok:
                return
            code, stamp = self.store.save_product_master_confirmed(before, proposed, "Actualizado en Productos / Inventario")
            _v986_refresh_after_product_master_change(
                self,
                f"Producto {code} actualizado.\nFecha del último cambio: {stamp}",
            )
        else:
            ok = messagebox.askyesno(
                "Agregar producto al maestro",
                f'El producto "{proposed["nombre"]}" no existe en el maestro.\n\n'
                "¿Desea agregarlo con los datos diligenciados?",
                parent=self,
            )
            if not ok:
                return
            code, stamp = self.store.save_product_master_confirmed({}, proposed, "Creado en Productos / Inventario")
            _v986_refresh_after_product_master_change(
                self,
                f"Producto {code} agregado.\nFecha de creación: {stamp}",
            )
    except Exception as exc:
        messagebox.showerror("Error", str(exc), parent=self)


SalesFormApp.save_product = _v986_save_product


def _v986_offer_master_update_from_line(self, product_row, proposed: dict, context: str) -> bool:
    """Compara la línea de venta/cotización con el maestro y ofrece actualizarlo."""
    if product_row is None:
        return False
    before = _v986_product_snapshot(product_row)
    after = dict(before)
    after.update({
        "unidad": (_v986_norm(proposed.get("unidad", before.get("unidad", "KLS"))) or "KLS").upper(),
        "precio_venta": _v986_num(proposed.get("precio_venta", before.get("precio_venta", 0))),
        "costo": _v986_num(proposed.get("costo", before.get("costo", 0))),
        "comision_unitaria_sugerida": _v986_num(
            proposed.get("comision_unitaria_sugerida", before.get("comision_unitaria_sugerida", 0))
        ),
    })
    changes = _v986_product_changes(
        before, after, ["unidad", "precio_venta", "costo", "comision_unitaria_sugerida"]
    )
    if not changes:
        return False

    ok = messagebox.askyesno(
        "Datos diferentes al producto maestro",
        f"En {context} se están usando datos diferentes para {before.get('nombre','el producto')}:\n\n"
        + _v986_format_changes(changes)
        + "\n\n¿Desea actualizar también el maestro de productos?\n\n"
          "Si elige No, estos valores se usarán únicamente en esta operación.",
        parent=self,
    )
    if not ok:
        return False

    self.store.save_product_master_confirmed(before, after, f"Actualizado desde {context}")
    self.reload_master_catalogs()
    try:
        self.last_daily_snapshot_path = str(self.store.export_daily_snapshot())
    except Exception:
        pass
    return True


SalesFormApp.offer_product_master_update_from_line = _v986_offer_master_update_from_line


