# Esquema histórico: guardar código de producto por línea además de nombre/unidad.
_v986_previous_init_schema = SalesStore.init_schema
def _v986_init_schema(self):
    _v986_previous_init_schema(self)
    self.ensure_column("ventas_detalle", "codigo_producto", "TEXT")
    self.ensure_column("cotizaciones_detalle", "codigo_producto", "TEXT")
    try:
        self.conn.execute("""
            UPDATE ventas_detalle
               SET codigo_producto=(SELECT p.codigo FROM productos p WHERE p.nombre=ventas_detalle.producto LIMIT 1)
             WHERE COALESCE(codigo_producto,'')=''
        """)
        self.conn.execute("""
            UPDATE cotizaciones_detalle
               SET codigo_producto=(SELECT p.codigo FROM productos p WHERE p.nombre=cotizaciones_detalle.producto LIMIT 1)
             WHERE COALESCE(codigo_producto,'')=''
        """)
        self.conn.commit()
    except Exception:
        pass
SalesStore.init_schema = _v986_init_schema


def _v986_add_detail(self, data: dict):
    current = self.conn.execute(
        "SELECT COALESCE(MAX(item), 0) + 1 FROM ventas_detalle WHERE cuenta_cobro = ?",
        (data["cuenta_cobro"],),
    ).fetchone()[0]
    code = _v986_norm(data.get("codigo", data.get("codigo_producto", "")))
    if not code:
        row = self.conn.execute("SELECT codigo FROM productos WHERE nombre=? LIMIT 1", (data["producto"],)).fetchone()
        code = str(row["codigo"]) if row else ""
    self.conn.execute(
        """
        INSERT INTO ventas_detalle (
            cuenta_cobro, item, codigo_producto, producto, unidad, cantidad_kls, valor_x_kl,
            valor_total, costo_unitario, comision_unitaria, comision, iva_19,
            retenciones, chile_fresco, domicilio
        ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        """,
        (
            data["cuenta_cobro"], current, code, data["producto"],
            str(data.get("unidad", "KLS") or "KLS").strip().upper(),
            data["cantidad_kls"], data["valor_x_kl"], data["valor_total"],
            data.get("costo_unitario", 0), data.get("comision_unitaria", 0),
            data.get("comision", 0), data.get("iva_19", 0),
            data.get("retenciones", 0), data.get("chile_fresco", 0),
            data.get("domicilio", 0),
        ),
    )
    self.conn.commit()
SalesStore.add_detail = _v986_add_detail


