# ==================== V10.1.8 GUÍA DE ENVÍO PDF 10x15 ====================
# Sustituye la guía Excel por una etiqueta PDF sencilla de 10 x 15 cm.
# No incluye contenido del envío.

def _v994_wrap_canvas_text(canvas_obj, text_value, x, y, max_width, font_name="Helvetica", font_size=10, leading=12, max_lines=4):
    from reportlab.pdfbase.pdfmetrics import stringWidth

    text_value = str(text_value or "").strip()
    if not text_value:
        return y

    words = text_value.split()
    lines = []
    current = ""

    for word in words:
        test = word if not current else f"{current} {word}"
        if stringWidth(test, font_name, font_size) <= max_width:
            current = test
        else:
            if current:
                lines.append(current)
            current = word

    if current:
        lines.append(current)

    if len(lines) > max_lines:
        lines = lines[:max_lines]
        last = lines[-1]
        while stringWidth(last + "...", font_name, font_size) > max_width and len(last) > 1:
            last = last[:-1]
        lines[-1] = last.rstrip() + "..."

    canvas_obj.setFont(font_name, font_size)
    for line in lines:
        canvas_obj.drawString(x, y, line)
        y -= leading
    return y


def _v994_export_shipping_guide_pdf(self, cuenta_cobro: str, output_path: Path | None = None) -> Path:
    try:
        from reportlab.pdfgen import canvas
        from reportlab.lib.units import cm
        from reportlab.lib.colors import HexColor, black, white
    except Exception as exc:
        raise RuntimeError(
            "La guía PDF requiere reportlab. Instale con: pip install reportlab"
        ) from exc

    sale_df = self.table(
        "SELECT * FROM ventas WHERE cuenta_cobro=?",
        (cuenta_cobro,),
    )
    if sale_df.empty:
        raise ValueError(f"No existe la cuenta de cobro {cuenta_cobro}.")

    sale = sale_df.iloc[0]

    # Reusar la obtención robusta de datos del destinatario.
    try:
        recipient = _v992_client_shipping_data(self, sale)
    except Exception:
        client_name = str(sale.get("cliente", "") or "").strip()
        recipient = {
            "nombre": client_name,
            "telefono": str(sale.get("telefono_cliente", "") or "").strip(),
            "direccion": str(sale.get("direccion", "") or "").strip(),
            "ciudad": str(sale.get("ciudad_entrega", "") or "").strip(),
            "barrio": str(sale.get("barrio_entrega", "") or "").strip(),
            "local_edificio": str(sale.get("local_edificio", "") or "").strip(),
            "datos_entrega": str(sale.get("datos_entrega", "") or "").strip(),
        }

    order_num = str(cuenta_cobro or "").strip().lstrip("0") or "0"
    now_guide = datetime.now()
    shipping_id = f"{order_num}-{now_guide.strftime('%d%m%y%H%M')}"

    if output_path is None:
        PRINT_DIR.mkdir(parents=True, exist_ok=True)
        output_path = PRINT_DIR / f"Guia_envio_{make_code(cuenta_cobro, 'ENVIO')}.pdf"
    else:
        output_path = Path(output_path)
        if output_path.suffix.lower() != ".pdf":
            output_path = output_path.with_suffix(".pdf")
        output_path.parent.mkdir(parents=True, exist_ok=True)

    page_w = 10 * cm
    page_h = 15 * cm

    c = canvas.Canvas(str(output_path), pagesize=(page_w, page_h))
    c.setTitle(f"Guía de envío {shipping_id}")

    green = HexColor("#155A3A")
    light = HexColor("#E7F1EC")
    margin = 0.45 * cm
    inner_w = page_w - 2 * margin
    y = page_h - margin

    # Encabezado.
    header_h = 1.25 * cm
    c.setFillColor(green)
    c.rect(margin, y - header_h, inner_w, header_h, fill=1, stroke=0)
    c.setFillColor(white)
    c.setFont("Helvetica-Bold", 15)
    c.drawCentredString(page_w / 2, y - 0.78 * cm, "GUÍA DE ENVÍO")
    y -= header_h + 0.18 * cm

    c.setFillColor(black)
    c.setFont("Helvetica-Bold", 10)
    c.drawString(margin, y, f"ID: {shipping_id}")
    c.setFont("Helvetica", 8.5)
    fecha_txt = now_guide.strftime("%d/%m/%Y %H:%M")
    c.drawRightString(page_w - margin, y, fecha_txt)
    y -= 0.5 * cm

    # Bloque remitente.
    section_h = 0.58 * cm
    c.setFillColor(light)
    c.rect(margin, y - section_h + 0.12 * cm, inner_w, section_h, fill=1, stroke=0)
    c.setFillColor(green)
    c.setFont("Helvetica-Bold", 10)
    c.drawString(margin + 0.15 * cm, y - 0.24 * cm, "REMITENTE")
    y -= section_h + 0.08 * cm

    c.setFillColor(black)
    c.setFont("Helvetica-Bold", 10.5)
    c.drawString(margin, y, "Heidy Galeano")
    y -= 0.42 * cm
    c.setFont("Helvetica", 9)
    c.drawString(margin, y, "C.C 901,399,198")
    y -= 0.38 * cm
    c.drawString(margin, y, "CRA 21 # 16-20 LOCAL 1")
    y -= 0.38 * cm
    c.drawString(margin, y, "Bogotá")
    y -= 0.38 * cm
    c.drawString(margin, y, "Tel. 3123138543")
    y -= 0.58 * cm

    # Bloque destinatario.
    c.setFillColor(light)
    c.rect(margin, y - section_h + 0.12 * cm, inner_w, section_h, fill=1, stroke=0)
    c.setFillColor(green)
    c.setFont("Helvetica-Bold", 10)
    c.drawString(margin + 0.15 * cm, y - 0.24 * cm, "DESTINATARIO")
    y -= section_h + 0.12 * cm

    c.setFillColor(black)
    c.setFont("Helvetica-Bold", 13)
    y = _v994_wrap_canvas_text(
        c,
        recipient.get("nombre") or "SIN NOMBRE",
        margin,
        y,
        inner_w,
        font_name="Helvetica-Bold",
        font_size=13,
        leading=15,
        max_lines=2,
    )
    y -= 0.1 * cm

    fields = [
        ("ID", shipping_id),
        ("Teléfono", recipient.get("telefono") or "NO SUMINISTRADO"),
        ("Dirección", recipient.get("direccion") or "NO SUMINISTRADA"),
        ("Barrio", recipient.get("barrio") or ""),
        ("Local / Edificio", recipient.get("local_edificio") or ""),
        ("Ciudad", recipient.get("ciudad") or "NO SUMINISTRADA"),
        ("Indicaciones", recipient.get("datos_entrega") or ""),
    ]

    label_w = 2.35 * cm
    value_x = margin + label_w
    value_w = inner_w - label_w

    for label, value in fields:
        if not str(value or "").strip() and label not in {"ID", "Teléfono", "Dirección", "Ciudad"}:
            continue

        c.setFont("Helvetica-Bold", 8.5)
        c.drawString(margin, y, f"{label}:")
        y = _v994_wrap_canvas_text(
            c,
            value,
            value_x,
            y,
            value_w,
            font_name="Helvetica",
            font_size=9.2,
            leading=11,
            max_lines=3 if label in {"Dirección", "Indicaciones"} else 2,
        )
        y -= 0.11 * cm

    # Marco exterior.
    c.setStrokeColor(green)
    c.setLineWidth(1.4)
    c.rect(
        margin - 0.12 * cm,
        margin - 0.12 * cm,
        inner_w + 0.24 * cm,
        page_h - 2 * margin + 0.24 * cm,
        fill=0,
        stroke=1,
    )

    c.showPage()
    c.save()
    return Path(output_path)


SalesStore.export_shipping_guide = _v994_export_shipping_guide_pdf


# Reemplazar únicamente el diálogo post-venta para guardar la guía como PDF.
def _v994_show_invoice_generation_dialog(self, cuenta_cobro: str, total_factura: float, total_pagos: float):
    win = tk.Toplevel(self)
    win.title(f"Venta guardada - Cuenta {cuenta_cobro}")
    win.transient(self)
    win.grab_set()
    win.resizable(False, False)

    body = ttk.Frame(win, padding=18)
    body.pack(fill="both", expand=True)

    ttk.Label(body, text="Venta guardada correctamente", style="Title.TLabel").pack(anchor="w")
    ttk.Label(body, text=f"Cuenta de cobro: {cuenta_cobro}").pack(anchor="w", pady=(10, 0))
    ttk.Label(body, text=f"Total: ${total_factura:,.0f}").pack(anchor="w")
    ttk.Label(body, text=f"Pagado: ${total_pagos:,.0f}").pack(anchor="w")

    status = tk.StringVar(
        value="Puede generar la cuenta de cobro y la etiqueta PDF de envío."
    )
    ttk.Label(body, textvariable=status, wraplength=560).pack(anchor="w", pady=(10, 10))

    buttons = ttk.Frame(body)
    buttons.pack(fill="x")

    def restore():
        try:
            win.deiconify()
            win.lift()
            win.focus_force()
        except Exception:
            pass

    def generate_invoice():
        try:
            safe_invoice = make_code(cuenta_cobro, "FACTURA")
            cfg = read_config()
            initial_dir = cfg.get("invoice_output_dir", "") or str(PRINT_DIR)
            try:
                Path(initial_dir).mkdir(parents=True, exist_ok=True)
            except Exception:
                initial_dir = str(APP_DIR)

            selected = filedialog.asksaveasfilename(
                parent=win,
                title="Guardar cuenta de cobro",
                initialdir=initial_dir,
                initialfile=f"Cuenta_cobro_{safe_invoice}.xlsx",
                defaultextension=".xlsx",
                filetypes=[("Excel", "*.xlsx")],
            )
            restore()
            if not selected:
                return

            path = self.store.export_invoice_print(cuenta_cobro, Path(selected))
            cfg["invoice_output_dir"] = str(Path(path).parent)
            write_config(cfg)
            status.set(f"Cuenta de cobro generada: {path}")
            messagebox.showinfo(
                "Cuenta de cobro",
                f"Documento generado correctamente:\n{path}",
                parent=win,
            )
            win.after(100, restore)
        except Exception as exc:
            messagebox.showerror("Cuenta de cobro", str(exc), parent=win)
            win.after(100, restore)

    def generate_shipping():
        try:
            safe_invoice = make_code(cuenta_cobro, "ENVIO")
            cfg = read_config()
            initial_dir = (
                cfg.get("shipping_guide_output_dir", "")
                or cfg.get("invoice_output_dir", "")
                or str(PRINT_DIR)
            )
            try:
                Path(initial_dir).mkdir(parents=True, exist_ok=True)
            except Exception:
                initial_dir = str(APP_DIR)

            selected = filedialog.asksaveasfilename(
                parent=win,
                title="Guardar etiqueta de envío",
                initialdir=initial_dir,
                initialfile=f"Guia_envio_{safe_invoice}.pdf",
                defaultextension=".pdf",
                filetypes=[("PDF", "*.pdf")],
            )
            restore()
            if not selected:
                return

            path = self.store.export_shipping_guide(cuenta_cobro, Path(selected))
            cfg["shipping_guide_output_dir"] = str(Path(path).parent)
            write_config(cfg)
            status.set(f"Etiqueta PDF generada: {path}")
            messagebox.showinfo(
                "Guía de envío",
                f"Etiqueta generada correctamente:\n{path}",
                parent=win,
            )
            win.after(100, restore)
        except Exception as exc:
            messagebox.showerror("Guía de envío", str(exc), parent=win)
            win.after(100, restore)

    ttk.Button(
        buttons,
        text="Generar cuenta de cobro",
        style="Primary.TButton",
        command=generate_invoice,
    ).pack(side="left", padx=(0, 6))

    ttk.Button(
        buttons,
        text="Generar guía de envío",
        command=generate_shipping,
    ).pack(side="left", padx=(0, 6))

    ttk.Button(buttons, text="Cerrar", command=win.destroy).pack(side="right")

    win.update_idletasks()
    x = self.winfo_rootx() + max(0, (self.winfo_width() - win.winfo_width()) // 2)
    y = self.winfo_rooty() + max(0, (self.winfo_height() - win.winfo_height()) // 2)
    win.geometry(f"+{x}+{y}")
    self.wait_window(win)


SalesFormApp.show_invoice_generation_dialog = _v994_show_invoice_generation_dialog

