def _v996_save_sale(self):
    if "venta_factura" in self.vars:
        raw = self.vars["venta_factura"].get()
        normalized = _v996_account_key(raw)
        if normalized:
            self.vars["venta_factura"].set(normalized)
    editing = getattr(self, "editing_sale_account", None)
    if editing:
        self.editing_sale_account = _v996_account_key(editing)
    return _v996_previous_save_sale(self)

