# ---- Unidad de producto editable y resistente a reimportación ----
_v996_previous_import_master_records = SalesStore.import_master_records
def _v996_import_master_records(self, clientes, productos, source_path=""):
    # Resguardar cambios manuales antes de reimportar el Excel maestro.
    manual = self.table(
        """
        SELECT codigo, nombre, unidad, precio_venta, comision_unitaria_sugerida,
               costo, stock_actual, stock_minimo, activo, fuente_origen,
               ultima_modificacion, precio_referencia, ultimo_precio
          FROM productos
         WHERE COALESCE(modificado_manualmente,0)=1
        """
    )
    result = _v996_previous_import_master_records(
        self, clientes, productos, source_path
    )

    # La edición autorizada desde la app tiene prioridad frente a una fuente antigua.
    for _, r in manual.iterrows():
        code = str(r.get("codigo", "") or "").strip()
        name = str(r.get("nombre", "") or "").strip()
        target = None
        if code:
            target = self.conn.execute(
                "SELECT rowid FROM productos WHERE codigo=? LIMIT 1",
                (code,),
            ).fetchone()
        if target is None and name:
            target = self.conn.execute(
                "SELECT rowid FROM productos "
                "WHERE TRIM(nombre)=TRIM(?) COLLATE NOCASE LIMIT 1",
                (name,),
            ).fetchone()
        if target is None:
            continue

        self.conn.execute(
            """
            UPDATE productos
               SET unidad=?,
                   precio_venta=?,
                   comision_unitaria_sugerida=?,
                   costo=?,
                   stock_actual=?,
                   stock_minimo=?,
                   activo=?,
                   fuente_origen=?,
                   ultima_modificacion=?,
                   modificado_manualmente=1,
                   precio_referencia=?,
                   ultimo_precio=?
             WHERE rowid=?
            """,
            (
                (str(r.get("unidad", "KLS") or "KLS").strip().upper()),
                float(r.get("precio_venta", 0) or 0),
                float(r.get("comision_unitaria_sugerida", 0) or 0),
                float(r.get("costo", 0) or 0),
                float(r.get("stock_actual", 0) or 0),
                float(r.get("stock_minimo", 0) or 0),
                str(r.get("activo", "SI") or "SI"),
                str(r.get("fuente_origen", "") or ""),
                str(r.get("ultima_modificacion", "") or ""),
                float(r.get("precio_referencia", 0) or 0),
                float(r.get("ultimo_precio", r.get("precio_venta", 0)) or 0),
                target["rowid"],
            ),
        )
    self.conn.commit()
    return result

SalesStore.import_master_records = _v996_import_master_records


# ---- Buscadores y orden descendente en maestros ----
def _v996_numeric_sort(value):
    s = str(value or "").strip()
    try:
        return (1, int(float(s)))
    except Exception:
        return (0, s.upper())


def _v996_refresh_master_tables(self):
    # CLIENTES: CLIENTE_ID descendente y filtro por ID/nombre/ciudad/teléfono.
    if hasattr(self, "clients_tree"):
        q = self.vars.get(
            "master_client_search", tk.StringVar(value="")
        ).get().strip().lower()
        clients = self.store.table(
            "SELECT * FROM clientes WHERE COALESCE(activo,'SI') <> 'NO'"
        )
        rows = []
        for _, r in clients.iterrows():
            searchable = " | ".join(
                str(r.get(k, "") or "")
                for k in ("cliente_id", "nombre", "ciudad", "telefono")
            ).lower()
            if q and q not in searchable:
                continue
            rows.append(r)
        rows.sort(
            key=lambda r: _v996_numeric_sort(r.get("cliente_id", "")),
            reverse=True,
        )
        self.fill_tree(
            self.clients_tree,
            [
                (
                    r.get("cliente_id", ""),
                    r.get("nombre", ""),
                    r.get("ciudad", ""),
                    r.get("direccion", ""),
                    r.get("telefono", ""),
                    r.get("email", ""),
                    r.get("fuente_origen", ""),
                    "Sí" if int(r.get("modificado_manualmente", 0) or 0) else "No",
                )
                for r in rows
            ],
        )

    # PRODUCTOS: código descendente y filtro por código/nombre/unidad.
    if hasattr(self, "products_tree"):
        q = self.vars.get(
            "master_product_search", tk.StringVar(value="")
        ).get().strip().lower()
        products = self.store.table(
            "SELECT * FROM productos WHERE COALESCE(activo,'SI') <> 'NO'"
        )
        rows = []
        for _, r in products.iterrows():
            searchable = " | ".join(
                str(r.get(k, "") or "")
                for k in ("codigo", "nombre", "unidad")
            ).lower()
            if q and q not in searchable:
                continue
            rows.append(r)
        rows.sort(
            key=lambda r: _v996_numeric_sort(r.get("codigo", "")),
            reverse=True,
        )
        self.fill_tree(
            self.products_tree,
            [
                (
                    r.get("codigo", ""),
                    r.get("nombre", ""),
                    r.get("unidad", ""),
                    f"{float(r.get('precio_venta',0) or 0):,.0f}",
                    f"{float(r.get('comision_unitaria_sugerida',0) or 0):,.0f}",
                    f"{float(r.get('stock_actual',0) or 0):,.2f}",
                    f"{float(r.get('stock_minimo',0) or 0):,.2f}",
                    r.get("activo", "SI"),
                )
                for r in rows
            ],
        )


_v996_previous_build_masters_tab = SalesFormApp.build_masters_tab
def _v996_build_masters_tab(self):
    _v996_previous_build_masters_tab(self)

    # Unidad: permitir las variantes comerciales solicitadas y escritura manual.
    unit_widget = self.widgets.get("prod_unidad")
    if isinstance(unit_widget, ttk.Combobox):
        unit_widget.configure(
            values=["KG", "KLS", "GR", "PAQUETE", "UNIDAD", "CAJA"],
            state="normal",
        )

    # Clientes: añadir CLIENTE_ID como primera columna.
    if hasattr(self, "clients_tree"):
        columns = (
            "cliente_id", "nombre", "ciudad", "direccion",
            "telefono", "email", "origen", "modificado"
        )
        self.clients_tree.configure(columns=columns)
        titles = {
            "cliente_id": "ID",
            "nombre": "Cliente",
            "ciudad": "Ciudad",
            "direccion": "Dirección",
            "telefono": "Teléfono",
            "email": "Email",
            "origen": "Fuente origen",
            "modificado": "Edición manual",
        }
        for col in columns:
            self.clients_tree.heading(col, text=titles[col])
            self.clients_tree.column(
                col,
                width=95 if col == "cliente_id"
                else 210 if col in {"nombre", "direccion", "origen"}
                else 120,
                anchor="w",
            )

        frame = self.clients_tree.master
        self.clients_tree.grid_configure(row=1, column=0, sticky="nsew")
        for child in frame.winfo_children():
            if isinstance(child, ttk.Scrollbar):
                orient = str(child.cget("orient"))
                if orient == "vertical":
                    child.grid_configure(row=1, column=1, sticky="ns")
                else:
                    child.grid_configure(row=2, column=0, sticky="ew")

        search = ttk.Frame(frame)
        search.grid(row=0, column=0, columnspan=2, sticky="ew", pady=(0, 6))
        ttk.Label(search, text="Buscar cliente:").pack(side="left")
        self.vars["master_client_search"] = tk.StringVar()
        ent = ttk.Entry(
            search,
            textvariable=self.vars["master_client_search"],
        )
        ent.pack(side="left", fill="x", expand=True, padx=(6, 0))
        ent.bind(
            "<KeyRelease>",
            lambda _e: _v996_refresh_master_tables(self),
            add="+",
        )
        frame.rowconfigure(1, weight=1)

    if hasattr(self, "products_tree"):
        frame = self.products_tree.master
        self.products_tree.grid_configure(row=1, column=0, sticky="nsew")
        for child in frame.winfo_children():
            if isinstance(child, ttk.Scrollbar):
                orient = str(child.cget("orient"))
                if orient == "vertical":
                    child.grid_configure(row=1, column=1, sticky="ns")
                else:
                    child.grid_configure(row=2, column=0, sticky="ew")

        search = ttk.Frame(frame)
        search.grid(row=0, column=0, columnspan=2, sticky="ew", pady=(0, 6))
        ttk.Label(search, text="Buscar producto:").pack(side="left")
        self.vars["master_product_search"] = tk.StringVar()
        ent = ttk.Entry(
            search,
            textvariable=self.vars["master_product_search"],
        )
        ent.pack(side="left", fill="x", expand=True, padx=(6, 0))
        ent.bind(
            "<KeyRelease>",
            lambda _e: _v996_refresh_master_tables(self),
            add="+",
        )
        frame.rowconfigure(1, weight=1)

    _v996_refresh_master_tables(self)

