# Selección de cliente compatible con la nueva columna ID.
def _v996_on_client_select(self, _event=None):
    selected = self.clients_tree.selection()
    if not selected:
        return
    values = self.clients_tree.item(selected[0], "values")
    if not values:
        return

    client_id = str(values[0] or "").strip()
    client_name = str(values[1] or "").strip() if len(values) > 1 else ""

    if client_id:
        row = self.store.table(
            "SELECT * FROM clientes WHERE cliente_id=? LIMIT 1",
            (client_id,),
        )
    else:
        row = self.store.table(
            "SELECT * FROM clientes WHERE nombre=? LIMIT 1",
            (client_name,),
        )
    if row.empty:
        return
    row = row.iloc[0]
    self.editing_client_name = str(row.get("nombre", "") or "")

    for key, col in {
        "cli_nombre": "nombre",
        "cli_ciudad": "ciudad",
        "cli_direccion": "direccion",
        "cli_telefono": "telefono",
        "cli_email": "email",
        "cli_notas": "notas",
    }.items():
        self.vars[key].set("" if pd.isna(row[col]) else str(row[col]))

SalesFormApp.on_client_select = _v996_on_client_select


