# Refuerzo de guardado de unidad: normalizar y mantener el valor elegido.
_v996_previous_save_product = SalesFormApp.save_product
def _v996_save_product(self):
    unit = ""
    if "prod_unidad" in self.vars:
        unit = self.vars["prod_unidad"].get().strip().upper()
        aliases = {
            "KILO": "KG",
            "KILOS": "KG",
            "KILOGRAMO": "KG",
            "KILOGRAMOS": "KG",
            "UND": "UNIDAD",
            "UN": "UNIDAD",
            "PAQ": "PAQUETE",
        }
        unit = aliases.get(unit, unit) or "KLS"
        self.vars["prod_unidad"].set(unit)

    result = _v996_previous_save_product(self)

    # Volver a leer desde SQLite para verificar que el cambio quedó persistido.
    try:
        code = self.vars["prod_codigo"].get().strip()
        if code and unit:
            row = self.store.table(
                "SELECT unidad FROM productos WHERE codigo=? LIMIT 1",
                (code,),
            )
            if not row.empty and str(row.iloc[0]["unidad"] or "").upper() != unit:
                self.store.conn.execute(
                    """
                    UPDATE productos
                       SET unidad=?, ultima_modificacion=?,
                           modificado_manualmente=1
                     WHERE codigo=?
                    """,
                    (
                        unit,
                        datetime.now().isoformat(timespec="seconds"),
                        code,
                    ),
                )
                self.store.conn.commit()
                self.refresh_all()
    except Exception:
        pass

    return result

SalesFormApp.save_product = _v996_save_product


# ---- ID de cliente para cotizaciones ----
def _v996_ensure_client_id(store, client_name: str) -> str:
    name = str(client_name or "").strip()
    if not name:
        return ""

    store.ensure_cliente(name)
    row = store.conn.execute(
        "SELECT cliente_id FROM clientes WHERE nombre=? LIMIT 1",
        (name,),
    ).fetchone()
    existing = str(row["cliente_id"] or "").strip() if row else ""
    if existing:
        return existing

    values = store.conn.execute(
        "SELECT cliente_id FROM clientes "
        "WHERE cliente_id IS NOT NULL AND TRIM(cliente_id)<>''"
    ).fetchall()
    numeric = []
    for r in values:
        s = str(r["cliente_id"] or "").strip()
        if re.fullmatch(r"\d+", s):
            try:
                numeric.append(int(s))
            except Exception:
                pass

    new_id = str(max(numeric or [10000]) + 1)
    store.conn.execute(
        """
        UPDATE clientes
           SET cliente_id=?,
               ultima_modificacion=?,
               modificado_manualmente=1
         WHERE nombre=?
        """,
        (
            new_id,
            datetime.now().isoformat(timespec="seconds"),
            name,
        ),
    )
    store.conn.commit()
    return new_id


def _v996_fill_quote_client_id(self):
    if "cot_cliente_id" not in self.vars:
        return
    name = self.vars.get(
        "cot_cliente", tk.StringVar(value="")
    ).get().strip()
    if not name:
        self.vars["cot_cliente_id"].set("")
        return
    row = self.store.table(
        "SELECT cliente_id FROM clientes WHERE nombre=? LIMIT 1",
        (name,),
    )
    value = ""
    if not row.empty:
        value = str(row.iloc[0].get("cliente_id", "") or "").strip()
    self.vars["cot_cliente_id"].set(value)


