# Store: guardar cliente_id aunque el método histórico no lo conociera.
_v996_previous_store_save_quote = SalesStore.save_quote
def _v996_store_save_quote(self, data: dict, details: list[dict]):
    override = str(
        getattr(self, "_v996_quote_client_id_override", "") or ""
    ).strip()
    if not override:
        override = _v996_ensure_client_id(self, data.get("cliente", ""))

    result = _v996_previous_store_save_quote(self, data, details)
    self.conn.execute(
        "UPDATE cotizaciones SET cliente_id=? WHERE numero_cotizacion=?",
        (
            override,
            data.get("numero_cotizacion", ""),
        ),
    )
    self.conn.commit()
    return result

SalesStore.save_quote = _v996_store_save_quote


# UI: si ID queda vacío, usar/generar automáticamente el CLIENTE_ID.
_v996_previous_ui_save_quote = SalesFormApp.save_quote
def _v996_ui_save_quote(self):
    client_name = self.vars.get(
        "cot_cliente", tk.StringVar(value="")
    ).get().strip()
    typed = self.vars.get(
        "cot_cliente_id", tk.StringVar(value="")
    ).get().strip()
    if not typed and client_name:
        typed = _v996_ensure_client_id(self.store, client_name)
        if "cot_cliente_id" in self.vars:
            self.vars["cot_cliente_id"].set(typed)

    self.store._v996_quote_client_id_override = typed
    try:
        return _v996_previous_ui_save_quote(self)
    finally:
        try:
            delattr(self.store, "_v996_quote_client_id_override")
        except Exception:
            pass

SalesFormApp.save_quote = _v996_ui_save_quote


# Cargar ID al editar una cotización.
_v996_previous_load_quote_by_number = SalesFormApp.load_quote_by_number
def _v996_load_quote_by_number(self, num: str):
    result = _v996_previous_load_quote_by_number(self, num)
    try:
        head, _ = self.store.get_quote(num)
        if not head.empty and "cot_cliente_id" in self.vars:
            value = str(head.iloc[0].get("cliente_id", "") or "").strip()
            if not value:
                value = _v996_ensure_client_id(
                    self.store,
                    str(head.iloc[0].get("cliente", "") or ""),
                )
            self.vars["cot_cliente_id"].set(value)
    except Exception:
        pass
    return result

