REPORTS_DIR = APP_DIR / "reportes_cartera"


def _v1000_norm_city(value) -> str:
    import unicodedata
    text = str(value or "").strip().upper()
    text = "".join(
        ch for ch in unicodedata.normalize("NFD", text)
        if unicodedata.category(ch) != "Mn"
    )
    text = re.sub(r"[^A-Z0-9]+", " ", text)
    return re.sub(r"\s+", " ", text).strip()


def _v1000_shipping_label(city) -> str:
    """Bogotá -> DOMICILIO; cualquier otra ciudad -> ENVÍO."""
    city_norm = _v1000_norm_city(city)
    return "DOMICILIO" if "BOGOTA" in city_norm else "ENVÍO"


def _v1000_cartera_dataframe(self) -> pd.DataFrame:
    """Cartera gerencial vigente: una fila por cuenta con saldo real > 0."""
    summary = self.sales_summary().copy()
    if summary.empty:
        return pd.DataFrame(columns=[
            "fecha_venta","dias_cartera","cliente","cuenta_cobro","ciudad","asesor",
            "total_factura","total_abonos","saldo_pendiente","estado_cartera",
            "fecha_ultimo_abono","valor_ultimo_abono","telefono_cliente"
        ])

    sales = self.table("""
        SELECT cuenta_cobro, fecha, cliente, ciudad_entrega, asesor,
               telefono_cliente, estado_venta
          FROM ventas
    """)
    df = summary.merge(
        sales[[
            "cuenta_cobro","ciudad_entrega","asesor",
            "telefono_cliente"
        ]],
        on="cuenta_cobro",
        how="left",
    )

    df["total_factura"] = pd.to_numeric(df["total_factura"], errors="coerce").fillna(0)
    df["total_abonos"] = pd.to_numeric(df["total_abonos"], errors="coerce").fillna(0)
    df["saldo_pendiente"] = (df["total_factura"] - df["total_abonos"]).clip(lower=0)

    # Último abono real aplicado a cada cuenta.
    apps = self.table("""
        SELECT id_aplicacion, cuenta_cobro, fecha_aplicacion,
               valor_aplicado, id_abono, orden_aplicacion
          FROM aplicacion_abonos
         ORDER BY cuenta_cobro, fecha_aplicacion,
                  orden_aplicacion, id_aplicacion
    """)
    if not apps.empty:
        apps = apps.copy()
        apps["_fecha"] = pd.to_datetime(apps["fecha_aplicacion"], errors="coerce")
        apps = apps.sort_values(
            ["cuenta_cobro","_fecha","orden_aplicacion","id_aplicacion","id_abono"]
        )
        last = (
            apps.groupby("cuenta_cobro", as_index=False)
            .tail(1)[["cuenta_cobro","fecha_aplicacion","valor_aplicado"]]
            .rename(columns={
                "fecha_aplicacion":"fecha_ultimo_abono",
                "valor_aplicado":"valor_ultimo_abono",
            })
        )
        df = df.merge(last, on="cuenta_cobro", how="left")
    else:
        df["fecha_ultimo_abono"] = ""
        df["valor_ultimo_abono"] = 0.0

    df["fecha_ultimo_abono"] = df["fecha_ultimo_abono"].fillna("")
    df["valor_ultimo_abono"] = pd.to_numeric(
        df["valor_ultimo_abono"], errors="coerce"
    ).fillna(0)

    # Solo deudores reales y nunca ventas anuladas.
    df = df[
        (df["saldo_pendiente"] > 1)
        & (~df["estado_venta"].astype(str).str.upper().eq("ANULADA"))
    ].copy()

    today = pd.Timestamp(datetime.now().date())
    sale_dates = pd.to_datetime(df["fecha"], errors="coerce")
    df["dias_cartera"] = (today - sale_dates.dt.normalize()).dt.days.fillna(0).clip(lower=0).astype(int)
    df["estado_cartera"] = df.apply(
        lambda r: "PARCIAL" if float(r.get("total_abonos",0) or 0) > 0 else "PENDIENTE",
        axis=1,
    )

    df = df.rename(columns={
        "fecha":"fecha_venta",
        "ciudad_entrega":"ciudad",
    })
    # Referencia gerencial explícita: cuenta + fecha de la deuda.
    def _v1013_account_date(row):
        fecha = pd.to_datetime(row.get("fecha_venta"), errors="coerce")
        fecha_txt = fecha.strftime("%d/%m/%Y") if pd.notna(fecha) else str(row.get("fecha_venta",""))[:10]
        return f"{row.get('cuenta_cobro','')} ({fecha_txt})"

    df["cuenta_fecha"] = df.apply(_v1013_account_date, axis=1)

    cols = [
        "fecha_venta","dias_cartera","cliente","cuenta_cobro","cuenta_fecha",
        "ciudad","asesor","total_factura","total_abonos","saldo_pendiente",
        "estado_cartera","fecha_ultimo_abono","valor_ultimo_abono","telefono_cliente",
    ]
    for col in cols:
        if col not in df.columns:
            df[col] = ""
    return df[cols].sort_values(
        ["fecha_venta","saldo_pendiente"],
        ascending=[True,False],
    ).reset_index(drop=True)


SalesStore.cartera_management = _v1000_cartera_dataframe


# Añadir/actualizar una pestaña CARTERA en cada exportación y copia diaria.
_v1000_previous_export_excel = SalesStore.export_excel
def _v1000_export_excel(self, output_path: Path, append_existing: bool = False):
    result = _v1000_previous_export_excel(self, output_path, append_existing)
    cartera = self.cartera_management()
    with pd.ExcelWriter(
        output_path,
        engine="openpyxl",
        mode="a",
        if_sheet_exists="replace",
    ) as writer:
        cartera.rename(columns=str.upper).to_excel(
            writer,
            sheet_name="Cartera",
            index=False,
        )
    try:
        _v987_style_excel_file(output_path)
    except Exception:
        pass
    return result


