def _v1010_upsert_transporter(self,data:dict):
    name = _v1010_clean(data.get("nombre"))
    if not name:
        raise ValueError("Falta el nombre de la transportadora o domiciliario.")
    tid = _v1010_clean(data.get("transportadora_id"))
    if not tid:
        row = self.conn.execute(
            "SELECT COALESCE(MAX(CAST(transportadora_id AS INTEGER)),3000)+1 "
            "FROM transportadoras WHERE transportadora_id GLOB '[0-9]*'"
        ).fetchone()
        tid = str(row[0] or 3001)
    stamp = datetime.now().isoformat(timespec="seconds")
    self.conn.execute(
        """
        INSERT INTO transportadoras (
            transportadora_id,nombre,tipo,cobertura,activo,fuente_datos,
            observaciones,ultima_modificacion,modificado_manualmente
        ) VALUES (?,?,?,?,?,?,?,?,1)
        ON CONFLICT(transportadora_id) DO UPDATE SET
            nombre=excluded.nombre,tipo=excluded.tipo,cobertura=excluded.cobertura,
            activo=excluded.activo,fuente_datos=excluded.fuente_datos,
            observaciones=excluded.observaciones,
            ultima_modificacion=excluded.ultima_modificacion,
            modificado_manualmente=1
        """,
        (
            tid,name,
            (_v1010_clean(data.get("tipo")) or "TRANSPORTADORA").upper(),
            _v1010_clean(data.get("cobertura")),
            (_v1010_clean(data.get("activo")) or "SI").upper(),
            _v1010_clean(data.get("fuente_datos")) or "Creado en la app",
            _v1010_clean(data.get("observaciones")),
            stamp,
        ),
    )
    self.conn.commit()
    return tid

SalesStore.upsert_transporter = _v1010_upsert_transporter


# Toda venta guarda el proveedor logístico y asigna asesor al cliente si aún no tiene uno.
_v1010_previous_upsert_sale = SalesStore.upsert_sale
def _v1010_upsert_sale(self,data:dict):
    result = _v1010_previous_upsert_sale(self,data)

    transport_name = _v1010_clean(
        data.get("transportadora",
                 getattr(self,"_v1010_transportadora",""))
    )
    transport_id = _v1010_clean(
        data.get("transportadora_id",
                 getattr(self,"_v1010_transportadora_id",""))
    )
    dispatch_type = _v1010_clean(
        data.get("tipo_despacho",
                 getattr(self,"_v1010_tipo_despacho",""))
    ).upper()

    if transport_name and (not transport_id or not dispatch_type):
        found = self.conn.execute(
            """
            SELECT transportadora_id,tipo FROM transportadoras
             WHERE TRIM(nombre)=TRIM(?) COLLATE NOCASE LIMIT 1
            """,
            (transport_name,),
        ).fetchone()
        if found:
            transport_id = transport_id or _v1010_clean(found["transportadora_id"])
            dispatch_type = dispatch_type or _v1010_clean(found["tipo"]).upper()
    if transport_name and not dispatch_type:
        dispatch_type = "OTRO"

    self.conn.execute(
        """
        UPDATE ventas
           SET transportadora_id=?, transportadora=?, tipo_despacho=?
         WHERE cuenta_cobro=?
        """,
        (
            transport_id,transport_name,dispatch_type,
            data.get("cuenta_cobro",""),
        ),
    )

    client = _v1010_clean(data.get("cliente"))
    advisor = _v1010_clean(data.get("asesor")).upper()
    if client and advisor:
        arow = self.conn.execute(
            "SELECT asesor_id FROM asesores WHERE UPPER(TRIM(nombre))=? LIMIT 1",
            (advisor,),
        ).fetchone()
        aid = _v1010_clean(arow["asesor_id"]) if arow else ""
        self.conn.execute(
            """
            UPDATE clientes
               SET asesor_id=CASE
                     WHEN TRIM(COALESCE(asesor_id,''))='' THEN ? ELSE asesor_id END,
                   asesor_asignado=CASE
                     WHEN TRIM(COALESCE(asesor_asignado,''))='' THEN ? ELSE asesor_asignado END
             WHERE nombre=?
            """,
            (aid,advisor,client),
        )
    self.conn.commit()
    return result

SalesStore.upsert_sale = _v1010_upsert_sale


def _v1010_resolve_transporter(self):
    if "venta_transportadora" not in self.vars:
        return
    name = self.vars["venta_transportadora"].get().strip()
    tid = ""
    tipo = ""
    if name:
        row = self.store.table(
            """
            SELECT transportadora_id,nombre,tipo
              FROM transportadoras
             WHERE TRIM(nombre)=TRIM(?) COLLATE NOCASE
             LIMIT 1
            """,
            (name,),
        )
        if not row.empty:
            r = row.iloc[0]
            tid = _v1010_clean(r.get("transportadora_id"))
            name = _v1010_clean(r.get("nombre"))
            tipo = _v1010_clean(r.get("tipo")).upper()
            self.vars["venta_transportadora"].set(name)
    self.vars["venta_transportadora_id"].set(tid)
    self.vars["venta_tipo_despacho"].set(tipo or ("OTRO" if name else ""))


