    ent.bind(
        "<KeyRelease>",
        lambda _e:_v1010_refresh_master_tables(self),
        add="+",
    )
    frame.rowconfigure(1,weight=1)
    frame.columnconfigure(0,weight=1)

    _v1010_refresh_master_tables(self)

