def _v1010_refresh_master_tables(self):
    # Clientes con asesor visible y buscable.
    if hasattr(self,"clients_tree"):
        q=self.vars.get(
            "master_client_search",tk.StringVar(value="")
        ).get().strip().lower()
        clients=self.store.table(
            "SELECT * FROM clientes WHERE COALESCE(activo,'SI') <> 'NO'"
        )
        rows=[]
        for _,r in clients.iterrows():
            searchable=" | ".join(
                str(r.get(k,"") or "")
                for k in (
                    "cliente_id","nombre","asesor_asignado","ciudad",
                    "direccion","telefono"
                )
            ).lower()
            if q and q not in searchable:
                continue
            rows.append(r)
        rows.sort(
            key=lambda r:_v996_numeric_sort(r.get("cliente_id","")),
            reverse=True,
        )
        self.fill_tree(
            self.clients_tree,
            [(
                r.get("cliente_id",""),
                r.get("nombre",""),
                r.get("asesor_asignado",""),
                r.get("ciudad",""),
                r.get("direccion",""),
                r.get("telefono",""),
                r.get("email",""),
                r.get("fuente_origen",""),
                "Sí" if int(r.get("modificado_manualmente",0) or 0) else "No",
            ) for r in rows],
        )

    # Mantener productos con la lógica vigente.
    if hasattr(self,"products_tree"):
        q=self.vars.get(
            "master_product_search",tk.StringVar(value="")
        ).get().strip().lower()
        products=self.store.table(
            "SELECT * FROM productos WHERE COALESCE(activo,'SI') <> 'NO'"
        )
        rows=[]
        for _,r in products.iterrows():
            searchable=" | ".join(
                str(r.get(k,"") or "") for k in ("codigo","nombre","unidad")
            ).lower()
            if q and q not in searchable:
                continue
            rows.append(r)
        rows.sort(
            key=lambda r:_v996_numeric_sort(r.get("codigo","")),
            reverse=True,
        )
        self.fill_tree(
            self.products_tree,
            [(
                r.get("codigo",""),r.get("nombre",""),r.get("unidad",""),
                f"{float(r.get('precio_venta',0) or 0):,.0f}",
                f"{float(r.get('comision_unitaria_sugerida',0) or 0):,.0f}",
                f"{float(r.get('stock_actual',0) or 0):,.2f}",
                f"{float(r.get('stock_minimo',0) or 0):,.2f}",
                r.get("activo","SI"),
            ) for r in rows],
        )

    if hasattr(self,"transporters_tree"):
        q=self.vars.get(
            "master_transport_search",tk.StringVar(value="")
        ).get().strip().lower()
        rows=self.store.transporters()
        if not rows.empty and q:
            mask=(
                rows["transportadora_id"].astype(str).str.lower().str.contains(q,na=False)
                | rows["nombre"].astype(str).str.lower().str.contains(q,na=False)
                | rows["tipo"].astype(str).str.lower().str.contains(q,na=False)
                | rows["cobertura"].astype(str).str.lower().str.contains(q,na=False)
            )
            rows=rows[mask]
        self.fill_tree(
            self.transporters_tree,
            [(
                r.get("transportadora_id",""),r.get("nombre",""),
                r.get("tipo",""),r.get("cobertura",""),r.get("activo","SI"),
            ) for _,r in rows.iterrows()],
        )


