# Postprocesar exportaciones/copia diaria: logística + maestros completos.
_v1010_previous_export_excel = SalesStore.export_excel
def _v1010_export_excel(self,output_path:Path,append_existing:bool=False):
    result=_v1010_previous_export_excel(self,output_path,append_existing)

    # Mapas de logística por cuenta.
    sales=self.table(
        """
        SELECT cuenta_cobro,transportadora_id,transportadora,tipo_despacho
          FROM ventas
        """
    )
    log_map={}
    for _,r in sales.iterrows():
        log_map[str(r["cuenta_cobro"])]=(
            _v1010_clean(r.get("transportadora_id")),
            _v1010_clean(r.get("transportadora")),
            _v1010_clean(r.get("tipo_despacho")),
        )

    # Maestros.
    clients=self.clientes().copy()
    clientes_master=pd.DataFrame({
        "CLIENTE_ID":clients.get("cliente_id",""),
        "NOMBRE":clients.get("nombre",""),
        "ASESOR_ID":clients.get("asesor_id",""),
        "ASESOR_ASIGNADO":clients.get("asesor_asignado",""),
        "NIT_DOCUMENTO":clients.get("nit_documento",""),
        "TELEFONO":clients.get("telefono",""),
        "EMAIL":clients.get("email",""),
        "DIRECCION":clients.get("direccion",""),
        "CIUDAD":clients.get("ciudad",""),
        "BARRIO":clients.get("barrio",""),
        "LOCAL_EDIFICIO":clients.get("local_edificio",""),
        "DATOS_ENTREGA":clients.get("datos_entrega",""),
        "ACTIVO":clients.get("activo","SI"),
        "ULTIMA_ACTUALIZACION":clients.get("ultima_modificacion",""),
        "FUENTE_DATOS":clients.get("fuente_origen",""),
        "ESTADO_REVISION":clients.get("notas",""),
    })

    advisors=self.table("SELECT * FROM asesores ORDER BY asesor_id")
    assigned=(
        clients.groupby("asesor_asignado",dropna=False).size().to_dict()
        if not clients.empty and "asesor_asignado" in clients.columns else {}
    )
    hist=self.table(
        """
        SELECT asesor,COUNT(*) registros
          FROM ventas
         WHERE TRIM(COALESCE(asesor,''))<>''
         GROUP BY asesor
        """
    )
    hist_map={
        _v1010_clean(r.get("asesor")).upper():int(r.get("registros",0) or 0)
        for _,r in hist.iterrows()
    } if not hist.empty else {}
    asesores_master=pd.DataFrame({
        "ASESOR_ID":advisors.get("asesor_id",""),
        "NOMBRE_ASESOR":advisors.get("nombre",""),
        "TIPO":advisors.get("tipo",""),
        "TELEFONO":advisors.get("telefono",""),
        "EMAIL":advisors.get("email",""),
        "ACTIVO":advisors.get("activo","SI"),
        "ULTIMA_ACTUALIZACION":advisors.get("ultima_modificacion",""),
        "FUENTE_DATOS":advisors.get("fuente_origen",""),
        "OBSERVACIONES":advisors.get("observaciones",""),
    })
    if not asesores_master.empty:
        asesores_master["CLIENTES_ASIGNADOS"]=[
            int(assigned.get(str(x or "").strip(),0))
            for x in asesores_master["NOMBRE_ASESOR"]
        ]
        asesores_master["VENTAS_HISTORICAS"]=[
            hist_map.get(str(x or "").strip().upper(),0)
            for x in asesores_master["NOMBRE_ASESOR"]
        ]

    tr=self.table("SELECT * FROM transportadoras ORDER BY transportadora_id")
    transport_master=pd.DataFrame({
        "TRANSPORTADORA_ID":tr.get("transportadora_id",""),
        "NOMBRE":tr.get("nombre",""),
        "TIPO":tr.get("tipo",""),
        "COBERTURA":tr.get("cobertura",""),
        "ACTIVO":tr.get("activo","SI"),
        "FUENTE_DATOS":tr.get("fuente_datos",""),
        "OBSERVACIONES":tr.get("observaciones",""),
    })

    # Leer las dos hojas operativas creadas por el exportador vigente y añadir columnas.
    try:
        cab=pd.read_excel(output_path,sheet_name="Ventas_cabecera",dtype={"CUENTA_COBRO":str})
        if "CUENTA_COBRO" in cab.columns:
            vals=[log_map.get(str(x).strip(),("","","")) for x in cab["CUENTA_COBRO"]]
            cab["TRANSPORTADORA_ID"]=[x[0] for x in vals]
            cab["TRANSPORTADORA"]=[x[1] for x in vals]
            cab["TIPO_DESPACHO"]=[x[2] for x in vals]
    except Exception:
        cab=pd.DataFrame()

    try:
        flat=pd.read_excel(output_path,sheet_name="VENTAS",dtype={"CUENTA DE COBRO":str})
        if "CUENTA DE COBRO" in flat.columns:
            vals=[log_map.get(str(x).strip(),("","","")) for x in flat["CUENTA DE COBRO"]]
            flat["TRANSPORTADORA_ID"]=[x[0] for x in vals]
            flat["TRANSPORTADORA"]=[x[1] for x in vals]
            flat["TIPO_DESPACHO"]=[x[2] for x in vals]
    except Exception:
        flat=pd.DataFrame()

    with pd.ExcelWriter(
        output_path,engine="openpyxl",mode="a",if_sheet_exists="replace"
    ) as writer:
        if not cab.empty:
            cab.to_excel(writer,sheet_name="Ventas_cabecera",index=False)
        if not flat.empty:
            flat.to_excel(writer,sheet_name="VENTAS",index=False)
        clientes_master.to_excel(writer,sheet_name="Clientes_Maestro",index=False)
        asesores_master.to_excel(writer,sheet_name="Asesores_Maestro",index=False)
        transport_master.to_excel(writer,sheet_name="Transportadoras_Maestro",index=False)

    try:
        _v987_style_excel_file(output_path)
    except Exception:
        pass
    return result

SalesStore.export_excel = _v1010_export_excel


