# ==================== V10.1.8 AUDITORÍA DE ABONOS + FRESCOS SIN IVA ====================

def _v1014_clean(v) -> str:
    if v is None:
        return ""
    try:
        if pd.isna(v):
            return ""
    except Exception:
        pass
    return str(v).strip()


def _v1014_yes(v) -> bool:
    return _v1014_clean(v).upper() in {"SI","SÍ","YES","1","TRUE"}


def _v1014_is_fresh_product_row(row) -> bool:
    """Regla operativa MXPC: producto marcado fresco o nombre con FRESCO/FRESCA => IVA bloqueado en 0."""
    try:
        if _v1014_yes(row.get("producto_fresco")):
            return True
    except Exception:
        pass
    name = _v1014_clean(row.get("nombre", row.get("producto",""))).upper()
    return "FRESCO" in name or "FRESCA" in name


# ---- Esquema producto: bandera explícita de fresco e IVA aplicable ----
_v1014_previous_seed_master_data = SalesStore.seed_master_data
def _v1014_seed_master_data(self):
    self.ensure_column("productos","producto_fresco","TEXT NOT NULL DEFAULT 'NO'")
    self.ensure_column("productos","iva_aplica","TEXT NOT NULL DEFAULT 'SI'")
    _v1014_previous_seed_master_data(self)

    # Solo inferencia segura por nombre explícito; no se reclasifican productos ambiguos.
    self.conn.execute(
        """
        UPDATE productos
           SET producto_fresco='SI', iva_aplica='NO'
         WHERE UPPER(nombre) LIKE '%FRESCO%'
            OR UPPER(nombre) LIKE '%FRESCA%'
        """
    )
    self.conn.execute(
        """
        UPDATE productos
           SET iva_aplica='NO'
         WHERE UPPER(COALESCE(producto_fresco,'NO')) IN ('SI','SÍ','YES','1','TRUE')
        """
    )
    self.conn.commit()

SalesStore.seed_master_data = _v1014_seed_master_data


# Persistir clasificación fiscal operativa del producto.
_v1014_previous_upsert_producto = SalesStore.upsert_producto
def _v1014_upsert_producto(self,data:dict):
    result = _v1014_previous_upsert_producto(self,data)
    codigo = _v1014_clean(data.get("codigo")) or make_code(data.get("nombre",""))
    fresco = "SI" if _v1014_yes(data.get("producto_fresco")) else "NO"
    iva_aplica = "NO" if fresco == "SI" else ("SI" if _v1014_yes(data.get("iva_aplica","SI")) else "NO")
    self.conn.execute(
        """
        UPDATE productos
           SET producto_fresco=?, iva_aplica=?
         WHERE codigo=?
        """,
        (fresco, iva_aplica, codigo),
    )
    self.conn.commit()
    return result

SalesStore.upsert_producto = _v1014_upsert_producto


# ---- Auditoría de abonos: una fila por aplicación a cuenta de cobro ----
def _v1014_payment_audit(self) -> pd.DataFrame:
    q = """
    SELECT
        a.id_aplicacion,
        a.id_abono,
        b.fecha_abono,
        b.cliente,
        b.medio_pago,
        b.cta_bancaria_destino,
        b.referencia_pago,
        b.valor_abono,
        a.orden_aplicacion,
        a.cuenta_cobro,
        v.fecha AS fecha_cuenta_cobro,
        v.fecha_vencimiento,
        v.asesor,
        v.estado_venta,
        a.fecha_aplicacion,
        a.valor_aplicado,
        a.observacion_aplicacion
    FROM aplicacion_abonos a
    JOIN abonos b ON b.id_abono=a.id_abono
    LEFT JOIN ventas v ON v.cuenta_cobro=a.cuenta_cobro
    ORDER BY b.fecha_abono, a.id_abono, a.orden_aplicacion, a.id_aplicacion
    """
    df = self.table(q)
    if df.empty:
        return pd.DataFrame(columns=[
            "id_aplicacion","id_abono","fecha_abono","cliente","medio_pago",
            "cta_bancaria_destino","referencia_pago","valor_abono",
            "orden_aplicacion","cuenta_cobro","fecha_cuenta_cobro",
            "dias_entre_cuenta_y_abono","total_factura","saldo_antes",
            "valor_aplicado","saldo_despues","fecha_aplicacion","asesor",
            "estado_venta","observacion_aplicacion"
        ])

    summary = self.sales_summary()[["cuenta_cobro","total_factura"]].copy()
    summary["cuenta_cobro"] = summary["cuenta_cobro"].astype(str)
    df["cuenta_cobro"] = df["cuenta_cobro"].astype(str)
    df = df.merge(summary,on="cuenta_cobro",how="left")
    df["total_factura"] = pd.to_numeric(df["total_factura"],errors="coerce").fillna(0)
    df["valor_aplicado"] = pd.to_numeric(df["valor_aplicado"],errors="coerce").fillna(0)
    df["valor_abono"] = pd.to_numeric(df["valor_abono"],errors="coerce").fillna(0)

    # Saldo antes/después de cada aplicación, siguiendo orden cronológico de aplicaciones.
    df = df.sort_values(["cuenta_cobro","fecha_aplicacion","id_aplicacion"]).copy()
    df["_acum_prev"] = (
        df.groupby("cuenta_cobro")["valor_aplicado"].cumsum() - df["valor_aplicado"]
    )
    df["saldo_antes"] = (df["total_factura"] - df["_acum_prev"]).clip(lower=0)
    df["saldo_despues"] = (df["saldo_antes"] - df["valor_aplicado"]).clip(lower=0)

    fc = pd.to_datetime(df["fecha_cuenta_cobro"],errors="coerce")
    fa = pd.to_datetime(df["fecha_abono"],errors="coerce")
    df["dias_entre_cuenta_y_abono"] = (fa-fc).dt.days
    df["dias_entre_cuenta_y_abono"] = df["dias_entre_cuenta_y_abono"].fillna(0).astype(int)

    cols = [
        "id_aplicacion","id_abono","fecha_abono","cliente","medio_pago",
        "cta_bancaria_destino","referencia_pago","valor_abono",
        "orden_aplicacion","cuenta_cobro","fecha_cuenta_cobro",
        "dias_entre_cuenta_y_abono","total_factura","saldo_antes",
        "valor_aplicado","saldo_despues","fecha_aplicacion","asesor",
        "estado_venta","observacion_aplicacion"
    ]
    return df[cols].sort_values(
        ["fecha_abono","id_abono","orden_aplicacion","id_aplicacion"],
        ascending=[False,False,True,True]
    ).reset_index(drop=True)

SalesStore.payment_audit = _v1014_payment_audit


def _v1014_payment_register_enriched(self) -> pd.DataFrame:
    ab = self.table("SELECT * FROM abonos ORDER BY fecha_abono DESC, id_abono DESC")
    if ab.empty:
        return ab
    audit = self.payment_audit()
    detail_map = {}
    oldest_map = {}
    count_map = {}
    if not audit.empty:
        for aid, group in audit.groupby("id_abono"):
            refs = []
            for _,r in group.sort_values(["fecha_cuenta_cobro","cuenta_cobro"]).iterrows():
                fd = pd.to_datetime(r.get("fecha_cuenta_cobro"),errors="coerce")
                fd_txt = fd.strftime("%d/%m/%Y") if pd.notna(fd) else _v1014_clean(r.get("fecha_cuenta_cobro"))
                refs.append(
                    f"{r.get('cuenta_cobro','')} ({fd_txt}) - ${float(r.get('valor_aplicado',0) or 0):,.0f}"
                )
            detail_map[aid] = " | ".join(refs)
            count_map[aid] = len(group)
            dates = pd.to_datetime(group["fecha_cuenta_cobro"],errors="coerce").dropna()
            oldest_map[aid] = dates.min().strftime("%Y-%m-%d") if not dates.empty else ""

    applied = audit.groupby("id_abono")["valor_aplicado"].sum().to_dict() if not audit.empty else {}
    ab["CUENTAS_APLICADAS_DETALLE"] = [detail_map.get(x,"") for x in ab["id_abono"]]
    ab["NUM_CUENTAS_APLICADAS"] = [count_map.get(x,0) for x in ab["id_abono"]]
    ab["FECHA_CUENTA_MAS_ANTIGUA"] = [oldest_map.get(x,"") for x in ab["id_abono"]]
    ab["TOTAL_APLICADO"] = [float(applied.get(x,0) or 0) for x in ab["id_abono"]]
    ab["SALDO_SIN_APLICAR"] = (
        pd.to_numeric(ab["valor_abono"],errors="coerce").fillna(0)
        - pd.to_numeric(ab["TOTAL_APLICADO"],errors="coerce").fillna(0)
    ).clip(lower=0)
    ab["ESTADO_ABONO"] = ab.apply(
        lambda r: "APLICADO"
        if float(r["SALDO_SIN_APLICAR"] or 0) <= 1 and float(r["valor_abono"] or 0) > 0
        else ("PARCIAL" if float(r["TOTAL_APLICADO"] or 0)>0 else "PENDIENTE"),
        axis=1
    )
    return ab

SalesStore.payment_register_enriched = _v1014_payment_register_enriched


