def _v1014_add_selected_pending_to_plan(self):
    sels=self.pending_invoices_tree.selection()
    if not sels:
        messagebox.showwarning("Abonos","Seleccione una o varias cuentas pendientes.")
        return
    existing={str(x["cuenta_cobro"]):x for x in self.payment_plan}
    plan_client=str(self.vars.get("abono_cliente",tk.StringVar()).get()).strip()
    for item in sels:
        vals=self.pending_invoices_tree.item(item,"values")
        account=str(vals[0]); fecha=str(vals[1]); client=str(vals[2]); saldo=money(vals[6])
        if plan_client and client != plan_client:
            messagebox.showerror(
                "Abonos",
                f"La cuenta {account} pertenece a {client}. "
                "Un mismo abono solo puede aplicarse a cuentas del mismo cliente."
            )
            return
        plan_client=client
        if account not in existing:
            self.payment_plan.append({
                "cuenta_cobro":account,
                "fecha_cuenta":fecha,
                "cliente":client,
                "saldo":saldo,
                "valor_aplicado":0.0
            })
    self.vars["abono_cliente"].set(plan_client)
    self.refresh_payment_plan()

