# Guardado de producto con regla: fresco => IVA_APLICA=NO.
def _v1014_save_product(self):
    try:
        fresco=self.vars.get("prod_fresco",tk.StringVar(value="NO")).get().strip().upper() or "NO"
        iva_aplica=self.vars.get("prod_iva_aplica",tk.StringVar(value="SI")).get().strip().upper() or "SI"
        if fresco=="SI":
            iva_aplica="NO"
            self.vars["prod_iva_aplica"].set("NO")
        self.store.upsert_producto({
            "codigo":self.vars["prod_codigo"].get().strip(),
            "nombre":self.require("prod_nombre","Nombre del producto"),
            "unidad":self.vars["prod_unidad"].get().strip() or "KLS",
            "precio_venta":money(self.vars["prod_precio"].get()),
            "comision_unitaria_sugerida":money(self.vars["prod_comision_unitaria"].get()),
            "costo":money(self.vars["prod_costo"].get()),
            "stock_actual":money(self.vars["prod_stock"].get()),
            "stock_minimo":money(self.vars["prod_minimo"].get()),
            "activo":self.vars["prod_activo"].get().strip() or "SI",
            "producto_fresco":fresco,
            "iva_aplica":iva_aplica,
            "fuente_origen":"Creado/actualizado en la app",
        })
        self.reload_master_catalogs()
        self.refresh_all()
        messagebox.showinfo(
            "Producto guardado",
            "Producto actualizado. Si está marcado como fresco, el IVA queda bloqueado en NO."
        )
    except Exception as exc:
        messagebox.showerror("Error",str(exc))

