def _v1015_cancel_selected_payment(self):
    selected = self.payments_tree.selection() if hasattr(self,"payments_tree") else ()
    if not selected:
        messagebox.showwarning(
            "Anular abono",
            "Seleccione primero el abono que desea anular en la tabla de abonos registrados."
        )
        return
    values = self.payments_tree.item(selected[0],"values")
    if not values:
        return
    payment_id = str(values[0] or "").strip()

    status = self.store.payment_status(payment_id)
    if not status:
        messagebox.showerror("Anular abono",f"No se encontró el abono {payment_id}.")
        return
    if str(status.get("estado_registro_calc","ACTIVO")).upper() == "ANULADO":
        messagebox.showinfo(
            "Anular abono",
            f"El abono {payment_id} ya está anulado."
        )
        return

    detail = (
        f"Abono: {payment_id}\n"
        f"Fecha: {status.get('fecha_abono','')}\n"
        f"Cliente: {status.get('cliente','')}\n"
        f"Valor: ${float(status.get('valor_abono',0) or 0):,.0f}\n"
        f"Aplicado a: {status.get('cuentas_actuales','Sin aplicaciones')}\n\n"
        "La anulación reabrirá el saldo de las cuentas afectadas y conservará "
        "el registro original para auditoría.\n\n¿Desea continuar?"
    )
    if not messagebox.askyesno("Confirmar anulación de abono",detail):
        return

    reason = simpledialog.askstring(
        "Motivo de anulación",
        "Indique el motivo de la anulación (obligatorio):",
        parent=self
    )
    if reason is None:
        return
    reason = reason.strip()
    if not reason:
        messagebox.showerror(
            "Anular abono",
            "Debe escribir un motivo para poder anular el abono."
        )
        return
    if not messagebox.askyesno(
        "Confirmación final",
        f"Se anulará definitivamente el abono {payment_id}.\n\n"
        f"Motivo: {reason}\n\n"
        "El ID quedará bloqueado y no podrá reutilizarse. ¿Confirmar?"
    ):
        return

    try:
        result = self.store.cancel_payment(payment_id,reason)
        excel_path = self.store.export_payment_control()
        daily_path = self.store.export_daily_snapshot()
        self.last_daily_snapshot_path = str(daily_path)
        self.refresh_all()
        self.search_pending_invoices()
        messagebox.showinfo(
            "Abono anulado",
            f"Abono {payment_id} anulado correctamente.\n\n"
            f"Cuentas reabiertas: {', '.join(result['cuentas']) if result['cuentas'] else 'Ninguna'}\n"
            f"Motivo: {reason}\n\n"
            f"Control de abonos:\n{excel_path}\n\n"
            f"Copia diaria actualizada:\n{daily_path}"
        )
    except Exception as exc:
        messagebox.showerror("Error al anular abono",str(exc))

SalesFormApp.cancel_selected_payment = _v1015_cancel_selected_payment


# Antes de registrar, detectar duplicado exacto / probable.
_v1015_previous_register_planned_payment = SalesFormApp.register_planned_payment
def _v1015_register_planned_payment(self):
    try:
        if not self.payment_plan:
            raise ValueError("Agregue al menos una factura pendiente al abono.")
        preview = {
            "id_abono":self.require("abono_id","ID abono"),
            "fecha_abono":self.require("abono_fecha","Fecha"),
            "cliente":self.vars["abono_cliente"].get().strip(),
            "referencia_pago":self.vars["abono_ref"].get().strip(),
            "valor_abono":money(self.vars["abono_valor"].get()),
        }
        dup = self.store.possible_duplicate_payment(preview)
        if dup:
            if dup.get("bloquear"):
                messagebox.showerror(
                    "Abono duplicado / ya registrado",
                    dup.get("detalle","El abono ya existe.") +
                    "\n\nNo se registró ningún cambio. "
                    "Si el registro anterior es incorrecto, anúlelo antes de crear el pago correcto."
                )
                return
            if not messagebox.askyesno(
                "Posible abono duplicado",
                dup.get("detalle","Se encontró un pago similar.") +
                "\n\nLa fecha, cliente y valor coinciden con otro abono activo. "
                "Esto puede ser legítimo, pero requiere confirmación.\n\n"
                "¿Está seguro de que se trata de un pago diferente?"
            ):
                return
        return _v1015_previous_register_planned_payment(self)
    except Exception as exc:
        messagebox.showerror("Error al registrar abono",str(exc))

SalesFormApp.register_planned_payment = _v1015_register_planned_payment

