# ==================== V10.1.8 TRAZABILIDAD DE ABONOS EN VENTAS ====================

def _v1016_payment_trace_by_account(self) -> pd.DataFrame:
    """Resumen auditable de pagos por cuenta de cobro."""
    apps = self.table(
        """
        SELECT
            a.id_aplicacion,
            a.id_abono,
            a.cuenta_cobro,
            a.fecha_aplicacion,
            a.orden_aplicacion,
            a.valor_aplicado,
            b.fecha_abono,
            b.medio_pago,
            b.referencia_pago,
            COALESCE(b.estado_registro,'ACTIVO') estado_registro
        FROM aplicacion_abonos a
        JOIN abonos b ON b.id_abono=a.id_abono
        WHERE COALESCE(b.estado_registro,'ACTIVO') <> 'ANULADO'
        ORDER BY a.cuenta_cobro,b.fecha_abono,a.orden_aplicacion,a.id_aplicacion
        """
    )
    if apps.empty:
        return pd.DataFrame(columns=[
            "cuenta_cobro","id_ultimo_abono","fecha_ultimo_abono",
            "medio_ultimo_abono","referencia_ultimo_abono",
            "valor_ultimo_abono","total_abonado","historial_abonos"
        ])

    rows=[]
    for account, grp in apps.groupby("cuenta_cobro",dropna=False):
        grp=grp.sort_values(
            ["fecha_abono","fecha_aplicacion","orden_aplicacion","id_aplicacion"]
        )
        last=grp.iloc[-1]
        hist=[]
        for _,r in grp.iterrows():
            fecha=str(r.get("fecha_abono") or r.get("fecha_aplicacion") or "")
            aid=str(r.get("id_abono") or "")
            medio=str(r.get("medio_pago") or "")
            ref=str(r.get("referencia_pago") or "")
            valor=float(r.get("valor_aplicado",0) or 0)
            bits=[aid,fecha,medio]
            if ref:
                bits.append(f"Ref: {ref}")
            hist.append(
                " / ".join(bits) + f" / ${valor:,.0f}"
            )
        rows.append({
            "cuenta_cobro":str(account),
            "id_ultimo_abono":str(last.get("id_abono") or ""),
            "fecha_ultimo_abono":str(last.get("fecha_abono") or last.get("fecha_aplicacion") or ""),
            "medio_ultimo_abono":str(last.get("medio_pago") or ""),
            "referencia_ultimo_abono":str(last.get("referencia_pago") or ""),
            "valor_ultimo_abono":float(last.get("valor_aplicado",0) or 0),
            "total_abonado":float(pd.to_numeric(grp["valor_aplicado"],errors="coerce").fillna(0).sum()),
            "historial_abonos":" | ".join(hist),
        })
    return pd.DataFrame(rows)

SalesStore.payment_trace_by_account = _v1016_payment_trace_by_account


def _v1016_apply_payment_trace_to_export(self, output_path:Path):
    """Añade trazabilidad explícita y enlaces internos al Registro_abonos."""
    from openpyxl import load_workbook
    from openpyxl.styles import Font

    target=Path(output_path)
    if not target.exists():
        return target

    trace=self.payment_trace_by_account()
    trace_map={}
    if not trace.empty:
        for _,r in trace.iterrows():
            trace_map[str(r["cuenta_cobro"]).strip()]=r.to_dict()

    # Totales/saldos actuales por factura.
    summary=self.sales_summary().copy()
    sum_map={}
    if not summary.empty:
        for _,r in summary.iterrows():
            sum_map[str(r["cuenta_cobro"]).strip()]={
                "total_factura":float(r.get("total_factura",0) or 0),
                "total_abonos":float(r.get("total_abonos",0) or 0),
                "saldo_pendiente":max(
                    float(r.get("total_factura",0) or 0)
                    - float(r.get("total_abonos",0) or 0),0
                ),
            }

    wb=load_workbook(target)

    # Localizar cada abono dentro de Registro_abonos para crear hipervínculos.
    payment_row={}
    if "Registro_abonos" in wb.sheetnames:
        ws_reg=wb["Registro_abonos"]
        headers={
            str(c.value).strip().upper():c.column
            for c in ws_reg[1] if c.value is not None
        }
        id_col=headers.get("ID_ABONO")
        if id_col:
            for row in range(2,ws_reg.max_row+1):
                val=ws_reg.cell(row,id_col).value
                if val not in (None,""):
                    payment_row[str(val).strip()]=row

    link_font=Font(color="0563C1",underline="single")

    specs={
        "VENTAS":{
            "account_headers":["CUENTA DE COBRO","CUENTA_COBRO"],
            "new_headers":[
                "ID_ULTIMO_ABONO","FECHA_ULTIMO_ABONO","MEDIO_ULTIMO_ABONO",
                "REFERENCIA_ULTIMO_ABONO","VALOR_ULTIMO_ABONO","TOTAL_ABONADO",
                "SALDO_PENDIENTE","HISTORIAL_ABONOS","ENLACE_ABONO"
            ],
        },
        "Ventas_detalle":{
            "account_headers":["CUENTA_COBRO","CUENTA DE COBRO"],
            "new_headers":[
                "ID_ULTIMO_ABONO","FECHA_ULTIMO_ABONO","MEDIO_ULTIMO_ABONO",
                "REFERENCIA_ULTIMO_ABONO","TOTAL_ABONADO","SALDO_PENDIENTE",
                "HISTORIAL_ABONOS","ENLACE_ABONO"
            ],
        },
        "Ventas_cabecera":{
            "account_headers":["CUENTA_COBRO","CUENTA DE COBRO"],
            "new_headers":[
                "ID_ULTIMO_ABONO","FECHA_ULTIMO_ABONO","MEDIO_ULTIMO_ABONO",
                "REFERENCIA_ULTIMO_ABONO","VALOR_ULTIMO_ABONO",
                "HISTORIAL_ABONOS","ENLACE_ABONO"
            ],
        },
    }

    for sheet_name,spec in specs.items():
        if sheet_name not in wb.sheetnames:
            continue
        ws=wb[sheet_name]
        headers={
            str(c.value).strip().upper():c.column
            for c in ws[1] if c.value is not None
        }
        account_col=None
        for candidate in spec["account_headers"]:
            if candidate in headers:
                account_col=headers[candidate]
                break
        if not account_col:
            continue

        # Crear columnas que falten.
        for h in spec["new_headers"]:
            if h not in headers:
                col=ws.max_column+1
                ws.cell(1,col).value=h
                headers[h]=col

        for row in range(2,ws.max_row+1):
            account=str(ws.cell(row,account_col).value or "").strip()
            if not account:
                continue
            tr=trace_map.get(account,{})
            sm=sum_map.get(account,{})
            values={
                "ID_ULTIMO_ABONO":tr.get("id_ultimo_abono",""),
                "FECHA_ULTIMO_ABONO":tr.get("fecha_ultimo_abono",""),
                "MEDIO_ULTIMO_ABONO":tr.get("medio_ultimo_abono",""),
                "REFERENCIA_ULTIMO_ABONO":tr.get("referencia_ultimo_abono",""),
                "VALOR_ULTIMO_ABONO":tr.get("valor_ultimo_abono",0) if tr else "",
                "TOTAL_ABONADO":sm.get("total_abonos",0),
                "SALDO_PENDIENTE":sm.get("saldo_pendiente",0),
                "HISTORIAL_ABONOS":tr.get("historial_abonos",""),
            }
            for key,val in values.items():
                if key in headers:
                    ws.cell(row,headers[key]).value=val

            # Enlace interno al abono más reciente.
            link_col=headers.get("ENLACE_ABONO")
            aid=str(tr.get("id_ultimo_abono","") or "")
            if link_col:
                cell=ws.cell(row,link_col)
                if aid and aid in payment_row:
                    cell.value=f"Ver {aid}"
                    cell.hyperlink=f"#'Registro_abonos'!A{payment_row[aid]}"
                    cell.font=link_font
                else:
                    cell.value=""

        ws.freeze_panes="A2"
        ws.auto_filter.ref=ws.dimensions

        # Anchos razonables.
        for header,width in {
            "ID_ULTIMO_ABONO":18,
            "FECHA_ULTIMO_ABONO":16,
            "MEDIO_ULTIMO_ABONO":18,
            "REFERENCIA_ULTIMO_ABONO":22,
            "VALOR_ULTIMO_ABONO":18,
            "TOTAL_ABONADO":18,
            "SALDO_PENDIENTE":18,
            "HISTORIAL_ABONOS":55,
            "ENLACE_ABONO":18,
        }.items():
            col=headers.get(header)
            if col:
                ws.column_dimensions[ws.cell(1,col).column_letter].width=width

    wb.save(target)
    return target


