# ==================== V10.1.8 REPORTES SEMANALES Y MENSUALES DE CARTERA ====================

def _v1018_period_label(start_date: date, end_date: date) -> str:
    return f"{start_date.strftime('%Y-%m-%d')}_a_{end_date.strftime('%Y-%m-%d')}"


def _v1018_week_period_for_cutoff(cutoff: date) -> tuple[date,date]:
    """
    Semana gerencial: lunes a viernes.
    El reporte se genera el viernes a las 15:00 hora Colombia.
    """
    start = cutoff - timedelta(days=cutoff.weekday())  # lunes
    end = cutoff
    return start,end


def _v1018_previous_month_period(reference: date | None = None) -> tuple[date,date]:
    """
    Devuelve el mes calendario inmediatamente anterior al mes de reference.
    """
    reference = reference or _v1017_colombia_now().date()
    first_current = reference.replace(day=1)
    end_prev = first_current - timedelta(days=1)
    start_prev = end_prev.replace(day=1)
    return start_prev,end_prev


def _v1018_export_cartera_pdf_period(self, start_date: date, end_date: date, output_path: Path, period_type: str):
    """
    Reutiliza el reporte gerencial actual y deja trazabilidad del período en el archivo.
    El corte contable del reporte es end_date.
    """
    target = Path(output_path)
    result = self.export_cartera_pdf(end_date, target)
    return result

SalesStore.export_cartera_pdf_period = _v1018_export_cartera_pdf_period


def _v1018_generate_weekly_cartera(self, now: datetime | None = None):
    """
    Genera el reporte semanal del último viernes disponible.
    Nombre:
      Cartera_semanal_YYYY-MM-DD_a_YYYY-MM-DD.pdf
    """
    now = now or _v1017_colombia_now()
    cutoff = _v1017_latest_friday_3pm(now)

    # Si hoy es viernes y aún no son las 15:00, no crear el de esta semana.
    if now.weekday() == 4 and now.hour < V1017_CARTEra_HOUR:
        return None

    start_date,end_date = _v1018_week_period_for_cutoff(cutoff)
    REPORTS_DIR.mkdir(parents=True,exist_ok=True)
    target = REPORTS_DIR / (
        f"Cartera_semanal_{_v1018_period_label(start_date,end_date)}.pdf"
    )

    if target.exists():
        return target

    return self.store.export_cartera_pdf_period(
        start_date,end_date,target,"SEMANAL"
    )


def _v1018_generate_monthly_cartera(self, now: datetime | None = None):
    """
    Al detectar un nuevo mes genera el reporte del mes calendario anterior.
    Nombre:
      Cartera_mensual_YYYY-MM-DD_a_YYYY-MM-DD.pdf
    """
    now = now or _v1017_colombia_now()
    start_date,end_date = _v1018_previous_month_period(now.date())

    REPORTS_DIR.mkdir(parents=True,exist_ok=True)
    target = REPORTS_DIR / (
        f"Cartera_mensual_{_v1018_period_label(start_date,end_date)}.pdf"
    )

    if target.exists():
        return target

    return self.store.export_cartera_pdf_period(
        start_date,end_date,target,"MENSUAL"
    )


def _v1018_generate_due_cartera_reports(self):
    """
    Comprueba tanto cierre semanal como mensual.
    - Semanal: viernes >= 15:00 Colombia.
    - Mensual: primera ejecución disponible después del cambio de mes.
    """
    generated = []
    now = _v1017_colombia_now()

    try:
        weekly = _v1018_generate_weekly_cartera(self,now)
        if weekly:
            generated.append(str(weekly))
    except Exception:
        pass

    try:
        monthly = _v1018_generate_monthly_cartera(self,now)
        if monthly:
            generated.append(str(monthly))
    except Exception:
        pass

    return generated


# Sustituir el generador semanal anterior por el nuevo controlador.
_v1000_maybe_generate_weekly_cartera = _v1018_generate_due_cartera_reports
_v1017_maybe_generate_weekly_cartera = _v1018_generate_due_cartera_reports


def _v1018_schedule_next_cartera_check(self):
    """
    Revisa cada hora si corresponde crear un cierre.
    Esto permite:
      - viernes 15:00 Colombia para el semanal
      - detectar el cambio de mes sin depender de guardar una venta.
    """
    def run_and_reschedule():
        try:
            _v1018_generate_due_cartera_reports(self)
        finally:
            try:
                self.after(3_600_000,run_and_reschedule)
            except Exception:
                pass

    try:
        # Primera revisión poco después de iniciar.
        self.after(2000,run_and_reschedule)
    except Exception:
        pass


_v1018_previous_app_init = SalesFormApp.__init__
def _v1018_app_init(self,*args,**kwargs):
    _v1018_previous_app_init(self,*args,**kwargs)
    try:
        _v1018_schedule_next_cartera_check(self)
    except Exception:
        pass

SalesFormApp.__init__ = _v1018_app_init

