# ==================== V10.2.6 CORTES FÍSICOS POR PRODUCTO ====================

def _v1026_normalize_count_datetime(value) -> str:
    """
    Para un conteo físico necesitamos fecha Y hora.
    Si el usuario escribe solo la fecha de hoy, se usa la hora Colombia actual.
    Para una fecha histórica sin hora se conserva el final del día para evitar
    descontar otra vez ventas de ese mismo día cuya hora histórica no conocemos.
    """
    raw = _v1020_text(value)
    now = _v1017_colombia_now().replace(tzinfo=None)

    if not raw:
        return now.isoformat(timespec="seconds")

    # Pandas/Timestamp o datetime.
    try:
        if hasattr(value, "to_pydatetime"):
            dt = value.to_pydatetime()
            if getattr(dt, "tzinfo", None):
                dt = dt.astimezone(V1017_COLOMBIA_TZ).replace(tzinfo=None)
            return dt.isoformat(timespec="seconds")
    except Exception:
        pass

    # Fecha simple YYYY-MM-DD.
    if re.fullmatch(r"\d{4}-\d{2}-\d{2}", raw):
        try:
            d = datetime.strptime(raw, "%Y-%m-%d").date()
            if d == now.date():
                return now.isoformat(timespec="seconds")
            return datetime.combine(d, datetime.max.time()).isoformat(timespec="seconds")
        except Exception:
            return raw

    # Aceptar YYYY-MM-DD HH:MM[:SS].
    try:
        parsed = pd.to_datetime(raw, errors="raise")
        if hasattr(parsed, "to_pydatetime"):
            parsed = parsed.to_pydatetime()
        if getattr(parsed, "tzinfo", None):
            parsed = parsed.astimezone(V1017_COLOMBIA_TZ).replace(tzinfo=None)
        return parsed.isoformat(timespec="seconds")
    except Exception:
        return raw


def _v1026_create_inventory_cut_tables(self):
    self.conn.executescript(
        """
        CREATE TABLE IF NOT EXISTS inventario_cortes (
            id_corte INTEGER PRIMARY KEY AUTOINCREMENT,
            codigo_producto TEXT NOT NULL,
            fecha_hora_corte TEXT NOT NULL,
            cantidad_contada REAL NOT NULL,
            id_movimiento TEXT NOT NULL,
            responsable TEXT,
            observacion TEXT,
            fecha_registro TEXT NOT NULL
        );

        CREATE INDEX IF NOT EXISTS idx_inventario_cortes_producto_fecha
            ON inventario_cortes(codigo_producto, fecha_hora_corte);

        CREATE TABLE IF NOT EXISTS inventario_corte_ventas (
            id_corte INTEGER NOT NULL,
            venta_item_key TEXT NOT NULL,
            cuenta_cobro TEXT NOT NULL,
            item INTEGER,
            cantidad_en_corte REAL NOT NULL DEFAULT 0,
            PRIMARY KEY (id_corte, venta_item_key)
        );
        """
    )
    self.conn.commit()


def _v1026_snapshot_sales_at_cut(self, id_corte:int, codigo_producto:str):
    """
    Guarda qué ventas ya existían cuando se hizo el conteo físico.
    Así esas ventas se consideran incluidas en el stock contado y no se
    descuentan por segunda vez.
    """
    sales = self.table(
        """
        SELECT
            d.cuenta_cobro,
            d.item,
            d.codigo_producto,
            COALESCE(d.cantidad_kls,0) cantidad,
            COALESCE(v.estado_venta,'') estado_venta
        FROM ventas_detalle d
        JOIN ventas v ON v.cuenta_cobro=d.cuenta_cobro
        WHERE d.codigo_producto=?
        """,
        (codigo_producto,),
    )

    cur = self.conn.cursor()
    for _, r in sales.iterrows():
        if _v1017_norm_sale_status(r.get("estado_venta")) == "ANULADA":
            continue
        account = _v1020_text(r.get("cuenta_cobro"))
        item = int(_v1020_num(r.get("item"),0))
        key = f"{account}|{item}"
        qty = abs(_v1020_num(r.get("cantidad"),0))
        cur.execute(
            """
            INSERT OR REPLACE INTO inventario_corte_ventas
            (id_corte,venta_item_key,cuenta_cobro,item,cantidad_en_corte)
            VALUES (?,?,?,?,?)
            """,
            (id_corte,key,account,item,qty),
        )
    self.conn.commit()


def _v1026_latest_inventory_cut(self, codigo_producto:str):
    df = self.table(
        """
        SELECT *
        FROM inventario_cortes
        WHERE codigo_producto=?
        ORDER BY fecha_hora_corte DESC, id_corte DESC
        LIMIT 1
        """,
        (codigo_producto,),
    )
    return None if df.empty else df.iloc[0].to_dict()


def _v1026_cut_baseline_qty(self, id_corte:int, cuenta_cobro:str, item:int) -> float:
    key = f"{cuenta_cobro}|{int(item)}"
    df = self.table(
        """
        SELECT cantidad_en_corte
        FROM inventario_corte_ventas
        WHERE id_corte=? AND venta_item_key=?
        LIMIT 1
        """,
        (int(id_corte),key),
    )
    if df.empty:
        return 0.0
    return abs(_v1020_num(df.iloc[0].get("cantidad_en_corte"),0))


SalesStore.create_inventory_cut_tables = _v1026_create_inventory_cut_tables
SalesStore.snapshot_sales_at_cut = _v1026_snapshot_sales_at_cut
SalesStore.latest_inventory_cut = _v1026_latest_inventory_cut
SalesStore.cut_baseline_qty = _v1026_cut_baseline_qty


