def _v1030_active_master_path() -> Path | None:
    sources = [Path(p) for p in read_master_sources() if Path(p).exists()]
    return sources[0] if sources else None


def _v1030_backup_master_file(path: Path) -> Path | None:
    """
    Crea respaldo del Excel maestro antes de escribirlo.
    """
    path = Path(path)
    if not path.exists():
        return None
    backup_dir = path.parent / "respaldos_maestro"
    backup_dir.mkdir(parents=True, exist_ok=True)
    stamp = datetime.now().strftime("%Y%m%d_%H%M%S")
    target = backup_dir / f"{path.stem}_{stamp}{path.suffix}"
    counter = 1
    while target.exists():
        target = backup_dir / f"{path.stem}_{stamp}_{counter:02d}{path.suffix}"
        counter += 1
    shutil.copy2(path, target)
    return target


def _v1030_write_dataframe_to_sheet(ws, df: pd.DataFrame):
    """
    Reemplaza únicamente el contenido tabular de una hoja,
    preservando el resto del libro.
    """
    from openpyxl.styles import PatternFill, Font, Alignment, Border, Side

    # Limpiar filas existentes.
    if ws.max_row > 0:
        ws.delete_rows(1, ws.max_row)

    headers = list(df.columns)
    for c, value in enumerate(headers, start=1):
        ws.cell(row=1, column=c, value=value)

    for r_idx, row in enumerate(df.itertuples(index=False, name=None), start=2):
        for c_idx, value in enumerate(row, start=1):
            if pd.isna(value):
                value = None
            ws.cell(row=r_idx, column=c_idx, value=value)

    green = "155E42"
    white = "FFFFFF"
    thin = Side(style="thin", color="D5DDD9")
    for cell in ws[1]:
        cell.fill = PatternFill("solid", fgColor=green)
        cell.font = Font(bold=True, color=white)
        cell.alignment = Alignment(horizontal="center", vertical="center", wrap_text=True)

    ws.freeze_panes = "A2"
    ws.auto_filter.ref = ws.dimensions

    for row in ws.iter_rows():
        for cell in row:
            cell.border = Border(left=thin, right=thin, top=thin, bottom=thin)
            cell.alignment = Alignment(vertical="top", wrap_text=True)

    for col_cells in ws.columns:
        letter = col_cells[0].column_letter
        max_len = 10
        for cell in col_cells[:2500]:
            try:
                max_len = max(max_len, len(str(cell.value or "")))
            except Exception:
                pass
        ws.column_dimensions[letter].width = min(max_len + 2, 45)


def _v1030_master_frames(self):
    """
    Construye los maestros desde SQLite, que es la fuente operativa.
    """
    clients = self.clientes().copy()
    products = self.productos().copy()

    def series(df, col, default=""):
        if col in df.columns:
            return df[col]
        return pd.Series([default] * len(df), index=df.index)

    clientes_master = pd.DataFrame({
        "CLIENTE_ID": series(clients, "cliente_id"),
        "NOMBRE": series(clients, "nombre"),
        "ASESOR_ID": series(clients, "asesor_id"),
        "ASESOR_ASIGNADO": series(clients, "asesor_asignado"),
        "NIT_DOCUMENTO": series(clients, "nit_documento"),
        "TELEFONO": series(clients, "telefono"),
        "EMAIL": series(clients, "email"),
        "DIRECCION": series(clients, "direccion"),
        "CIUDAD": series(clients, "ciudad"),
        "BARRIO": series(clients, "barrio"),
        "LOCAL_EDIFICIO": series(clients, "local_edificio"),
        "DATOS_ENTREGA": series(clients, "datos_entrega"),
        "ACTIVO": series(clients, "activo", "SI"),
        "ULTIMA_ACTUALIZACION": series(clients, "ultima_modificacion"),
        "FUENTE_DATOS": series(clients, "fuente_origen"),
        "ESTADO_REVISION": series(clients, "notas"),
    })

    productos_master = pd.DataFrame({
        "CODIGO_PRODUCTO": series(products, "codigo"),
        "PRODUCTO": series(products, "nombre"),
        "UNIDAD": series(products, "unidad"),
        "COSTO_UNITARIO": series(products, "costo", 0),
        "PRECIO_REFERENCIA": series(products, "precio_referencia", 0),
        "ULTIMO_PRECIO": series(products, "ultimo_precio", 0),
        "COMISION_UNITARIA_SUGERIDA": series(products, "comision_unitaria_sugerida", 0),
        "ACTIVO": series(products, "activo", "SI"),
        "ULTIMA_ACTUALIZACION": series(products, "ultima_modificacion"),
        "FUENTE_DATOS": series(products, "fuente_origen"),
        "PRODUCTO_FRESCO": series(products, "producto_fresco", "NO"),
        "IVA_APLICA": series(products, "iva_aplica", "SI"),
        "STOCK_ACTUAL": series(products, "stock_actual", 0),
        "CATEGORIA_INVENTARIO": series(products, "categoria_inventario"),
        "FECHA_INVENTARIO": series(products, "fecha_inventario"),
        "OBSERVACION_INVENTARIO": series(products, "observacion_inventario"),
    })

    return clientes_master, productos_master


def _v1030_write_master_workbook(self, reason="Actualización desde la app") -> dict:
    """
    Guarda en el archivo Excel maestro activo los cambios de clientes y productos.
    Antes de escribir, crea un respaldo físico del maestro.
    """
    if getattr(self, "_suspend_master_writeback", False):
        return {"guardado": False, "motivo": "SUSPENDIDO"}

    path = _v1030_active_master_path()
    if not path:
        return {"guardado": False, "motivo": "SIN_MAESTRO_ACTIVO"}

    if path.suffix.lower() not in {".xlsx", ".xlsm"}:
        return {"guardado": False, "motivo": f"FORMATO_NO_EDITABLE:{path.suffix}"}

    try:
        from openpyxl import load_workbook

        backup = _v1030_backup_master_file(path)

        keep_vba = path.suffix.lower() == ".xlsm"
        book = load_workbook(path, keep_vba=keep_vba)

        clientes_master, productos_master = self._v1030_master_frames()

        if "Clientes_Maestro" in book.sheetnames:
            ws_clients = book["Clientes_Maestro"]
        else:
            ws_clients = book.create_sheet("Clientes_Maestro")

        if "Productos_Maestro" in book.sheetnames:
            ws_products = book["Productos_Maestro"]
        else:
            ws_products = book.create_sheet("Productos_Maestro")

        _v1030_write_dataframe_to_sheet(ws_clients, clientes_master)
        _v1030_write_dataframe_to_sheet(ws_products, productos_master)

        # Hoja de trazabilidad del guardado.
        if "Control_App" in book.sheetnames:
            ws_control = book["Control_App"]
        else:
            ws_control = book.create_sheet("Control_App")
            ws_control.append(["FECHA_HORA", "ACCION", "DETALLE"])

        ws_control.append([
            datetime.now().isoformat(timespec="seconds"),
            "SINCRONIZACION_MAESTRO",
            reason,
        ])

        # Guardado atómico: primero temporal y luego reemplazo.
        temp = path.with_name(path.stem + ".__tmp__" + path.suffix)
        book.save(temp)
        book.close()

        # Reemplazar el original solo después de que el temporal se guardó bien.
        os.replace(temp, path)

        return {
            "guardado": True,
            "archivo": str(path),
            "respaldo": str(backup) if backup else "",
            "clientes": int(len(clientes_master)),
            "productos": int(len(productos_master)),
        }

    except PermissionError:
        return {
            "guardado": False,
            "motivo": "ARCHIVO_ABIERTO_O_SIN_PERMISO",
            "archivo": str(path),
        }
    except Exception as exc:
        try:
            temp = path.with_name(path.stem + ".__tmp__" + path.suffix)
            if temp.exists():
                temp.unlink()
        except Exception:
            pass
        return {
            "guardado": False,
            "motivo": f"ERROR:{exc}",
            "archivo": str(path),
        }


SalesStore._v1030_master_frames = _v1030_master_frames
