_v1030_previous_import_inventory_excel = SalesStore.import_inventory_excel
def _v1030_import_inventory_excel(self, path: Path, confirm_changes_callback=None):
    old_suspend = getattr(self, "_suspend_master_writeback", False)
    self._suspend_master_writeback = True
    try:
        result = _v1030_previous_import_inventory_excel(self, path, confirm_changes_callback)
    finally:
        self._suspend_master_writeback = old_suspend

    wb_result = self.write_master_workbook(
        f"Carga de inventario desde {Path(path).name}"
    )
    result["maestro_excel_guardado"] = bool(wb_result.get("guardado"))
    result["maestro_excel_archivo"] = wb_result.get("archivo", "")
    result["maestro_excel_motivo"] = wb_result.get("motivo", "")
    return result

