# ==================== V10.3.1 MAESTRO VIVO: VENTAS + CLIENTES + PRODUCTOS + INVENTARIO ====================

V1031_MASTER_SYNC_SHEETS = [
    "VENTAS",
    "Ventas_detalle",
    "Ventas_cabecera",
    "Registro_abonos",
    "Aplicacion_abonos",
    "Auditoria_abonos",
    "Cartera",
    "Cartera_pendiente",
    "Clientes",
    "Productos",
    "Inventario_movimientos",
    "Inventario_cambios",
]

def _v1031_replace_sheet_from_workbook(target_book, source_book, sheet_name):
    """
    Reemplaza una hoja del maestro con la versión más reciente del export operativo.
    Conserva las demás hojas del libro maestro.
    """
    if sheet_name not in source_book.sheetnames:
        return False

    src = source_book[sheet_name]

    if sheet_name in target_book.sheetnames:
        old = target_book[sheet_name]
        idx = target_book.sheetnames.index(sheet_name)
        target_book.remove(old)
        dst = target_book.create_sheet(sheet_name, idx)
    else:
        dst = target_book.create_sheet(sheet_name)

    for row in src.iter_rows():
        for cell in row:
            nc = dst[cell.coordinate]
            nc.value = cell.value
            if cell.has_style:
                from copy import copy
                nc._style = copy(cell._style)
                nc.font = copy(cell.font)
                nc.fill = copy(cell.fill)
                nc.border = copy(cell.border)
                nc.alignment = copy(cell.alignment)
                nc.number_format = cell.number_format
                nc.protection = copy(cell.protection)
            if cell.hyperlink:
                nc._hyperlink = copy(cell.hyperlink)
            if cell.comment:
                nc.comment = copy(cell.comment)

    # Dimensiones de columnas/filas.
    from copy import copy
    for key, dim in src.column_dimensions.items():
        dst.column_dimensions[key] = copy(dim)
    for key, dim in src.row_dimensions.items():
        dst.row_dimensions[key] = copy(dim)

    # Freeze panes, filtros, merges.
    dst.freeze_panes = src.freeze_panes
    try:
        dst.auto_filter.ref = src.auto_filter.ref
    except Exception:
        pass
    for merged in src.merged_cells.ranges:
        dst.merge_cells(str(merged))

    return True


def _v1031_write_full_master_workbook(self, reason="Actualización integral desde la app") -> dict:
    """
    V10.3.1:
    El maestro se convierte en una copia viva de la operación:
      - ventas,
      - detalle/cabecera,
      - pagos/abonos,
      - cartera,
      - clientes,
      - productos,
      - inventario,
      - Clientes_Maestro / Productos_Maestro.

    La copia diaria sigue existiendo como respaldo histórico independiente.
    """
    if getattr(self, "_suspend_master_writeback", False):
        return {"guardado": False, "motivo": "SUSPENDIDO"}

    master_path = _v1030_active_master_path()
    if not master_path:
        return {"guardado": False, "motivo": "SIN_MAESTRO_ACTIVO"}

    try:
        from openpyxl import load_workbook

        # 1) Crear respaldo del maestro actual.
        backup = _v1030_backup_master_file(master_path)

        # 2) Crear export operativo temporal con la información más reciente de SQLite.
        temp_export = master_path.with_name(
            f".__mxpc_operativo_{datetime.now().strftime('%Y%m%d_%H%M%S')}.xlsx"
        )
        self.export_excel(temp_export)

        # 3) Abrir maestro y export temporal.
        master_book = load_workbook(
            master_path,
            keep_vba=master_path.suffix.lower() == ".xlsm"
        )
        export_book = load_workbook(temp_export, data_only=False)

        copied = []
        for sheet_name in V1031_MASTER_SYNC_SHEETS:
            if _v1031_replace_sheet_from_workbook(master_book, export_book, sheet_name):
                copied.append(sheet_name)

        # 4) Reconstruir maestros de clientes y productos desde SQLite.
        clientes_master, productos_master = self._v1030_master_frames()

        if "Clientes_Maestro" in master_book.sheetnames:
            ws_clients = master_book["Clientes_Maestro"]
        else:
            ws_clients = master_book.create_sheet("Clientes_Maestro")

        if "Productos_Maestro" in master_book.sheetnames:
            ws_products = master_book["Productos_Maestro"]
        else:
            ws_products = master_book.create_sheet("Productos_Maestro")

        _v1030_write_dataframe_to_sheet(ws_clients, clientes_master)
        _v1030_write_dataframe_to_sheet(ws_products, productos_master)

        # 5) Añadir resumen de inventario actual desde SQLite.
        try:
            inv = self.table(
                """
                SELECT
                    codigo codigo_producto,
                    nombre producto,
                    unidad,
                    COALESCE(stock_actual,0) stock_actual,
                    COALESCE(stock_minimo,0) stock_minimo,
                    CASE
                        WHEN COALESCE(stock_actual,0) <= COALESCE(stock_minimo,0)
                        THEN 'EN/BAJO MINIMO'
                        ELSE 'OK'
                    END estado_stock,
                    activo,
                    ultima_modificacion
                FROM productos
                ORDER BY nombre
                """
            )
            if "Inventario_Resumen" in master_book.sheetnames:
                ws_inv = master_book["Inventario_Resumen"]
            else:
                ws_inv = master_book.create_sheet("Inventario_Resumen")
            _v1030_write_dataframe_to_sheet(ws_inv, inv.rename(columns=str.upper))
        except Exception:
            pass

        # 6) Hoja de control y trazabilidad.
        if "Control_App" in master_book.sheetnames:
            ws_control = master_book["Control_App"]
        else:
            ws_control = master_book.create_sheet("Control_App")
            ws_control.append(["FECHA_HORA", "ACCION", "DETALLE"])

        ws_control.append([
            datetime.now().isoformat(timespec="seconds"),
            "SINCRONIZACION_MAESTRO_COMPLETA",
            f"{reason}. Hojas operativas sincronizadas: {', '.join(copied)}",
        ])

        # 7) Guardado atómico.
        tmp_master = master_path.with_name(master_path.stem + ".__tmp__" + master_path.suffix)
        master_book.save(tmp_master)
        master_book.close()
        export_book.close()

        os.replace(tmp_master, master_path)

        try:
            temp_export.unlink()
        except Exception:
            pass

        return {
            "guardado": True,
            "archivo": str(master_path),
            "respaldo": str(backup) if backup else "",
            "hojas_sincronizadas": copied,
            "clientes": int(len(clientes_master)),
            "productos": int(len(productos_master)),
        }

    except PermissionError:
        return {
            "guardado": False,
            "motivo": "ARCHIVO_MAESTRO_ABIERTO_O_SIN_PERMISO",
            "archivo": str(master_path),
        }
    except Exception as exc:
        try:
            if 'temp_export' in locals() and temp_export.exists():
                temp_export.unlink()
        except Exception:
            pass
        try:
            if 'tmp_master' in locals() and tmp_master.exists():
                tmp_master.unlink()
        except Exception:
            pass
        return {
            "guardado": False,
            "motivo": f"ERROR:{exc}",
            "archivo": str(master_path),
        }


# Sustituir el write-back parcial de V10.3.0 por sincronización integral.
SalesStore.write_master_workbook = _v1031_write_full_master_workbook


