# Validación comercial actualizada:
# - permite precio 0 únicamente cuando fue autorizado por reposición/obsequio.
# - retención se reconoce como parte de la cancelación de la cuenta.
def _v1032_validate_sale_before_save(self):
    self.require("venta_fecha", "Fecha")
    self.require("venta_factura", "Cuenta de cobro")
    self.require("venta_estado", "Estado de la venta")
    self.require("venta_asesor", "Asesor")

    cliente = self.require("venta_cliente", "Cliente").strip()
    client_df = self.store.table("SELECT * FROM clientes WHERE nombre = ?", (cliente,))
    cliente_nuevo = client_df.empty
    client = None if cliente_nuevo else client_df.iloc[0]

    ciudad = self.require("venta_ciudad", "Ciudad de entrega")
    direccion = self.require("venta_direccion", "Dirección de entrega")
    telefono = self.vars.get("venta_telefono", tk.StringVar()).get().strip()
    if not telefono and client is not None:
        telefono = str(client.get("telefono", "") or "").strip()
        if telefono and "venta_telefono" in self.vars:
            self.vars["venta_telefono"].set(telefono)
    if not telefono:
        raise ValueError("Falta el teléfono del cliente.")

    if not self.product_lines:
        raise ValueError("Agregue al menos un producto antes de guardar la venta.")

    productos_maestro = self.store.productos()
    codigos_validos = set(productos_maestro["codigo"].astype(str)) if not productos_maestro.empty else set()
    nombres_validos = set(productos_maestro["nombre"].astype(str)) if not productos_maestro.empty else set()

    for i,line in enumerate(self.product_lines,start=1):
        code = str(line.get("codigo","")).strip()
        if not code or code not in codigos_validos:
            if str(line.get("producto","")) not in nombres_validos:
                raise ValueError(f"Producto {i}: el producto no existe en el maestro.")
        if money(line.get("cantidad_kls",0)) <= 0:
            raise ValueError(f"Producto {i}: la cantidad debe ser mayor a cero.")

        zero_ok = bool(line.get("precio_cero_autorizado",False))
        price = money(line.get("valor_x_kl",0))
        subtotal = money(line.get("valor_total",0))
        if price <= 0 and not zero_ok:
            raise ValueError(f"Producto {i}: el precio unitario debe ser mayor a cero.")
        if subtotal <= 0 and not zero_ok:
            raise ValueError(f"Producto {i}: el subtotal debe ser mayor a cero.")

    total_factura = self.invoice_total()
    # Se permite total 0 si todas las líneas gratuitas fueron autorizadas.
    if total_factura <= 0:
        all_free = bool(self.product_lines) and all(
            bool(x.get("precio_cero_autorizado",False)) for x in self.product_lines
        )
        if not all_free:
            raise ValueError("El total de la venta debe ser mayor a cero.")

    cash_payments = sum(money(line.get("valor_abono",0)) for line in self.payment_lines)
    retention = money(self.vars.get("venta_retencion",tk.StringVar(value="0")).get())
    if retention < 0:
        raise ValueError("La retención no puede ser negativa.")
    if retention > total_factura + 1:
        raise ValueError("La retención no puede superar el total de la factura.")

    total_reconocido = cash_payments + retention
    estado_pago = self.require("venta_estado_pago","Estado de pago")

    if total_reconocido > total_factura + 1:
        raise ValueError(
            f"Pagos + retención ({total_reconocido:,.0f}) superan "
            f"el total de la venta ({total_factura:,.0f})."
        )

    if estado_pago == "Pendiente":
        if total_reconocido > 1:
            raise ValueError(
                "El estado es Pendiente, pero existen pagos o retención."
            )
    elif estado_pago == "Parcial":
        if total_reconocido <= 0 or total_reconocido >= total_factura - 1:
            raise ValueError(
                "Para estado Parcial, pagos + retención deben ser mayores a cero "
                "y menores al total."
            )
    elif estado_pago == "Pagado":
        if abs(total_factura-total_reconocido) > 1:
            raise ValueError(
                f"Estado Pagado: efectivo ({cash_payments:,.0f}) + "
                f"retención ({retention:,.0f}) deben coincidir con "
                f"el total ({total_factura:,.0f})."
            )
    elif estado_pago == "Mixto":
        components = len(self.payment_lines) + (1 if retention > 0 else 0)
        if components < 2:
            raise ValueError(
                "Para estado Mixto registre al menos dos componentes de pago "
                "(incluida la retención si aplica)."
            )
        if abs(total_factura-total_reconocido) > 1:
            raise ValueError(
                "Para estado Mixto la suma de pagos + retención debe coincidir con el total."
            )
    else:
        raise ValueError("Seleccione un estado de pago válido.")

    for i,pay in enumerate(self.payment_lines,start=1):
        if not str(pay.get("medio_pago","")).strip():
            raise ValueError(f"Pago {i}: falta el medio de pago.")
        if money(pay.get("valor_abono",0)) <= 0:
            raise ValueError(f"Pago {i}: el valor debe ser mayor a cero.")

    return {
        "cliente":cliente,
        "ciudad":ciudad,
        "direccion":direccion,
        "telefono":telefono,
        "cliente_nuevo":cliente_nuevo,
        "barrio":self.vars.get("venta_barrio",tk.StringVar()).get().strip(),
        "local_edificio":self.vars.get("venta_local_edificio",tk.StringVar()).get().strip(),
        "datos_entrega":self.vars.get("venta_datos_entrega",tk.StringVar()).get().strip(),
        "estado_pago":estado_pago,
    }, total_factura, total_reconocido

