def _v1032_export_shipping_guide(self, cuenta_cobro:str, output_path:Path|None=None)->Path:
    try:
        from reportlab.pdfgen import canvas
        from reportlab.lib.units import cm
        from reportlab.lib.colors import HexColor, black, white
    except Exception as exc:
        raise RuntimeError("La guía PDF requiere reportlab.") from exc

    sale_df=self.table("SELECT * FROM ventas WHERE cuenta_cobro=?",(cuenta_cobro,))
    if sale_df.empty:
        raise ValueError(f"No existe la cuenta de cobro {cuenta_cobro}.")
    sale=sale_df.iloc[0]

    try:
        recipient=_v992_client_shipping_data(self,sale)
    except Exception:
        recipient={
            "nombre":str(sale.get("cliente","") or "").strip(),
            "telefono":str(sale.get("telefono_cliente","") or "").strip(),
            "direccion":str(sale.get("direccion","") or "").strip(),
            "ciudad":str(sale.get("ciudad_entrega","") or "").strip(),
            "barrio":str(sale.get("barrio_entrega","") or "").strip(),
            "local_edificio":str(sale.get("local_edificio","") or "").strip(),
            "datos_entrega":str(sale.get("datos_entrega","") or "").strip(),
        }

    transportadora=str(sale.get("transportadora","") or "").strip()
    tipo_despacho=str(sale.get("tipo_despacho","") or "").strip()

    order_num=str(cuenta_cobro or "").strip().lstrip("0") or "0"
    now_guide=datetime.now()
    shipping_id=f"{order_num}-{now_guide.strftime('%d%m%y%H%M')}"

    if output_path is None:
        PRINT_DIR.mkdir(parents=True,exist_ok=True)
        output_path=PRINT_DIR/f"Guia_envio_{make_code(cuenta_cobro,'ENVIO')}.pdf"
    else:
        output_path=Path(output_path)
        if output_path.suffix.lower()!=".pdf":
            output_path=output_path.with_suffix(".pdf")
        output_path.parent.mkdir(parents=True,exist_ok=True)

    page_w,page_h=10*cm,15*cm
    c=canvas.Canvas(str(output_path),pagesize=(page_w,page_h))
    c.setTitle(f"Guía de envío {shipping_id}")

    green=HexColor("#155A3A"); light=HexColor("#E7F1EC")
    margin=.45*cm; inner_w=page_w-2*margin; y=page_h-margin

    header_h=1.25*cm
    c.setFillColor(green); c.rect(margin,y-header_h,inner_w,header_h,fill=1,stroke=0)
    c.setFillColor(white); c.setFont("Helvetica-Bold",15)
    c.drawCentredString(page_w/2,y-.78*cm,"GUÍA DE ENVÍO")
    y-=header_h+.18*cm

    c.setFillColor(black); c.setFont("Helvetica-Bold",10)
    c.drawString(margin,y,f"ID: {shipping_id}")
    c.setFont("Helvetica",8.5)
    c.drawRightString(page_w-margin,y,now_guide.strftime("%d/%m/%Y %H:%M"))
    y-=.48*cm

    # Transportadora destacada.
    c.setFillColor(light); c.rect(margin,y-.62*cm,inner_w,.62*cm,fill=1,stroke=0)
    c.setFillColor(green); c.setFont("Helvetica-Bold",9.5)
    logistic = transportadora or "NO ASIGNADA"
    if tipo_despacho:
        logistic += f" · {tipo_despacho.title()}"
    c.drawString(margin+.15*cm,y-.39*cm,f"TRANSPORTADORA: {logistic}")
    y-=.78*cm

    section_h=.58*cm
    c.setFillColor(light); c.rect(margin,y-section_h+.12*cm,inner_w,section_h,fill=1,stroke=0)
    c.setFillColor(green); c.setFont("Helvetica-Bold",10)
    c.drawString(margin+.15*cm,y-.24*cm,"REMITENTE")
    y-=section_h+.08*cm

    c.setFillColor(black); c.setFont("Helvetica-Bold",10.5)
    c.drawString(margin,y,"Heidy Galeano"); y-=.39*cm
    c.setFont("Helvetica",9)
    c.drawString(margin,y,"C.C 901,399,198"); y-=.36*cm
    c.drawString(margin,y,"CRA 21 # 16-20 LOCAL 1"); y-=.36*cm
    c.drawString(margin,y,"Bogotá"); y-=.36*cm
    c.drawString(margin,y,"Tel. 3123138543"); y-=.52*cm

    c.setFillColor(light); c.rect(margin,y-section_h+.12*cm,inner_w,section_h,fill=1,stroke=0)
    c.setFillColor(green); c.setFont("Helvetica-Bold",10)
    c.drawString(margin+.15*cm,y-.24*cm,"DESTINATARIO")
    y-=section_h+.12*cm

    c.setFillColor(black); c.setFont("Helvetica-Bold",13)
    y=_v994_wrap_canvas_text(
        c,recipient.get("nombre") or "SIN NOMBRE",
        margin,y,inner_w,
        font_name="Helvetica-Bold",font_size=13,leading=15,max_lines=2
    )
    y-=.08*cm

    fields=[
        ("Teléfono",recipient.get("telefono") or "NO SUMINISTRADO"),
        ("Dirección",recipient.get("direccion") or "NO SUMINISTRADA"),
        ("Barrio",recipient.get("barrio") or ""),
        ("Local / Edificio",recipient.get("local_edificio") or ""),
        ("Ciudad",recipient.get("ciudad") or "NO SUMINISTRADA"),
        ("Indicaciones",recipient.get("datos_entrega") or ""),
    ]
    label_w=2.35*cm; value_x=margin+label_w; value_w=inner_w-label_w
    for label,value in fields:
        if not str(value or "").strip() and label not in {"Teléfono","Dirección","Ciudad"}:
            continue
        c.setFont("Helvetica-Bold",8.5); c.drawString(margin,y,f"{label}:")
        y=_v994_wrap_canvas_text(
            c,value,value_x,y,value_w,
            font_name="Helvetica",font_size=9.2,leading=11,
            max_lines=3 if label in {"Dirección","Indicaciones"} else 2
        )
        y-=.09*cm

    c.setStrokeColor(green); c.setLineWidth(1.4)
    c.rect(
        margin-.12*cm,margin-.12*cm,
        inner_w+.24*cm,page_h-2*margin+.24*cm,
        fill=0,stroke=1
    )
    c.showPage(); c.save()
    return Path(output_path)

SalesStore.export_shipping_guide = _v1032_export_shipping_guide


