_v1033_previous_add_quote_line = SalesFormApp.add_quote_line
def _v1033_add_quote_line(self):
    q = self.vars.get("cot_producto", tk.StringVar()).get().strip()
    row = self.find_product_row(q) if q else pd.DataFrame()

    if not row.empty:
        p = row.iloc[0]
        selected = self.vars.get(
            "cot_unidad",
            tk.StringVar(value=str(p.get("unidad","KLS") or "KLS"))
        ).get()
        selected = self._v1033_confirm_unit_change(
            p, selected, "cotización"
        )
