def _v1034_create_audit_tables(self):
    self.conn.executescript(
        """
        CREATE TABLE IF NOT EXISTS historial_facturas (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            fecha_hora TEXT NOT NULL,
            cuenta_cobro TEXT NOT NULL,
            accion TEXT NOT NULL,
            seccion TEXT NOT NULL,
            campo TEXT NOT NULL,
            valor_anterior TEXT,
            valor_nuevo TEXT,
            origen TEXT,
            usuario TEXT
        );

        CREATE INDEX IF NOT EXISTS idx_historial_facturas_cuenta_fecha
            ON historial_facturas(cuenta_cobro, fecha_hora);

        CREATE TABLE IF NOT EXISTS auditoria_coherencia_ventas (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            fecha_hora TEXT NOT NULL,
            cuenta_cobro TEXT NOT NULL,
            total_factura REAL NOT NULL DEFAULT 0,
            total_reconocido REAL NOT NULL DEFAULT 0,
            estado_pago_anterior TEXT,
            estado_venta_anterior TEXT,
            estado_pago_esperado TEXT,
            estado_venta_esperado TEXT,
            accion TEXT NOT NULL,
            detalle TEXT
        );

        CREATE INDEX IF NOT EXISTS idx_auditoria_coherencia_cuenta_fecha
            ON auditoria_coherencia_ventas(cuenta_cobro, fecha_hora);
        """
    )
    self.conn.commit()

