SalesStore.audit_coherence_row = _v1034_audit_coherence_row


def _v1034_sync_account_status(self, cuenta_cobro: str) -> dict:
    check = self.payment_integrity_for_account(cuenta_cobro)
    if not check:
        return {}

    account = check["cuenta_cobro"]
    old_sale = check["estado_venta_actual"]
    old_payment = check["estado_pago_actual"]
    new_sale = check["estado_venta_esperado"]
    new_payment = check["estado_pago_esperado"]

    if not check["coherente"]:
        detail = (
            f"Coherencia automática: total factura ${check['total_factura']:,.0f}; "
            f"pagos/retenciones reconocidos ${check['total_reconocido']:,.0f}. "
            f"{old_sale}/{old_payment} -> {new_sale}/{new_payment}."
        )
        self.audit_coherence_row(check, "CORREGIDA", detail)

        self.conn.execute(
            """
            UPDATE ventas
            SET estado_venta=?, estado_pago=?, ultima_modificacion=?
            WHERE cuenta_cobro=?
            """,
            (
                new_sale,
                new_payment,
                datetime.now().isoformat(timespec="seconds"),
                account,
            ),
        )
        self.conn.commit()

        if old_sale != new_sale:
            self.register_change(
                "Venta", account, "AUTO_COHERENCIA",
                "estado_venta", old_sale, new_sale
            )
        if _v1017_norm_payment_status(old_payment) != _v1017_norm_payment_status(new_payment):
            self.register_change(
                "Venta", account, "AUTO_COHERENCIA",
                "estado_pago", old_payment, new_payment
            )

    return {
        "estado_venta": new_sale,
        "estado_pago": new_payment,
        "total_factura": check["total_factura"],
        "total_abonos": check["total_reconocido"],
        "saldo": max(
            float(check["total_factura"] or 0)
            - float(check["total_reconocido"] or 0),
            0,
        ),
        "corregido": not check["coherente"],
    }

SalesStore.sync_account_status = _v1034_sync_account_status


def _v1034_verify_and_repair_all_sales(self) -> list[dict]:
    accounts = self.table(
        "SELECT cuenta_cobro FROM ventas ORDER BY fecha, cuenta_cobro"
    )
    repaired = []
    for _, row in accounts.iterrows():
        account = str(row.get("cuenta_cobro","") or "").strip()
        if not account:
            continue
        check = self.payment_integrity_for_account(account)
        if not check or check["coherente"]:
            continue
        before = dict(check)
        result = self.sync_account_status(account)
        repaired.append({**before, **result})
    return repaired

SalesStore.verify_and_repair_all_sales = _v1034_verify_and_repair_all_sales


