# Avisar al usuario si al abrir se encontraron/corrigieron incoherencias antiguas.
_v1034_previous_app_init = SalesFormApp.__init__
def _v1034_app_init(self, *args, **kwargs):
    _v1034_previous_app_init(self, *args, **kwargs)
    repairs = getattr(self.store, "_v1034_startup_repairs", []) or []
    if repairs:
        lines = []
        for r in repairs[:12]:
            lines.append(
                f"{r.get('cuenta_cobro')}: "
                f"{r.get('estado_venta_actual')}/{r.get('estado_pago_actual')} "
                f"→ {r.get('estado_venta_esperado')}/{r.get('estado_pago_esperado')}"
            )
        extra = (
            f"\n... y {len(repairs)-12} adicionales."
            if len(repairs) > 12 else ""
        )
        try:
            messagebox.showwarning(
                "Coherencia de pagos corregida",
                "Se detectaron facturas con estados que no coincidían con los "
                "pagos realmente registrados.\n\n"
                + "\n".join(lines)
                + extra
                + "\n\nLos cambios quedaron registrados en el historial interno.",
                parent=self,
            )
        except Exception:
            pass

SalesFormApp.__init__ = _v1034_app_init


# En una venta nueva/edición, NO permitir guardar estados incompatibles.
_v1034_previous_save_sale = SalesFormApp.save_sale
def _v1034_save_sale(self):
    try:
        # Llevar al arreglo cualquier línea pendiente que el usuario haya escrito.
        if not self.product_lines and self.vars.get("det_producto",tk.StringVar()).get().strip():
            self.add_product_line()
        if (
            not self.payment_lines
            and money(self.vars.get("sale_pay_valor",tk.StringVar(value="0")).get()) > 0
        ):
            self.add_payment_line()

        selected_sale = _v1017_norm_sale_status(
            self.vars.get("venta_estado",tk.StringVar(value="EMITIDA")).get()
        )
        selected_payment = _v1017_norm_payment_status(
            self.vars.get("venta_estado_pago",tk.StringVar(value="Pendiente")).get()
        )

        total = float(self.invoice_total() or 0)
        cash = sum(
            float(x.get("valor_abono",0) or 0)
            for x in getattr(self,"payment_lines",[])
        )
        retention = money(
            self.vars.get("venta_retencion",tk.StringVar(value="0")).get()
        )
        recognized = cash + retention
        components = len(getattr(self,"payment_lines",[])) + (
            1 if retention > 0.0001 else 0
        )

        if selected_sale == "ANULADA":
            if recognized > 0.0001:
                messagebox.showerror(
                    "Estados incompatibles",
                    "Una factura ANULADA no puede guardarse con pagos o retenciones activas.\n\n"
                    "Retire/anule los pagos antes de continuar.",
                    parent=self,
                )
                return
            expected_sale = "ANULADA"
            expected_payment = "Anulada"
        else:
            expected_payment = _v1017_payment_status_from_amounts(
                total, recognized, components
            )
            expected_sale = _v1017_expected_sale_status(expected_payment)

        mismatch = (
            selected_sale != expected_sale
            or _v1017_norm_payment_status(selected_payment)
               != _v1017_norm_payment_status(expected_payment)
        )

        if mismatch:
            ok = messagebox.askyesno(
                "Estados de factura y pago no son coherentes",
                f"Total factura: ${total:,.0f}\n"
                f"Pagos + retención reconocidos: ${recognized:,.0f}\n\n"
                f"Seleccionado:\n"
                f"  Factura: {selected_sale}\n"
                f"  Pago: {selected_payment}\n\n"
                f"Coherencia requerida:\n"
                f"  Factura: {expected_sale}\n"
                f"  Pago: {expected_payment}\n\n"
                "La venta NO puede guardarse con la combinación actual.\n\n"
                "¿Desea corregir automáticamente los estados y continuar?",
                parent=self,
            )
            if not ok:
                return
            self.vars["venta_estado"].set(expected_sale)
            self.vars["venta_estado_pago"].set(expected_payment)

        return _v1034_previous_save_sale(self)

    except Exception as exc:
        messagebox.showerror("Validación de venta", str(exc), parent=self)
        return

SalesFormApp.save_sale = _v1034_save_sale


# Historial y auditoría deben viajar tanto en la copia diaria como en el maestro.
_v1034_previous_export_excel = SalesStore.export_excel
def _v1034_export_excel(self, output_path:Path, append_existing:bool=False):
    result = _v1034_previous_export_excel(self, output_path, append_existing)

    try:
        from openpyxl import load_workbook
        from openpyxl.styles import PatternFill, Font, Alignment

        book = load_workbook(output_path)

        datasets = {
            "Historial_facturas": self.table(
                "SELECT * FROM historial_facturas ORDER BY id"
            ),
            "Auditoria_coherencia": self.table(
                "SELECT * FROM auditoria_coherencia_ventas ORDER BY id"
            ),
        }

        for sheet_name, df in datasets.items():
            if sheet_name in book.sheetnames:
                del book[sheet_name]
            ws = book.create_sheet(sheet_name)

            headers = list(df.columns)
            for col, header in enumerate(headers, start=1):
                cell = ws.cell(1,col,header)
                cell.fill = PatternFill("solid", fgColor="155E42")
                cell.font = Font(bold=True,color="FFFFFF")
                cell.alignment = Alignment(
                    horizontal="center", vertical="center", wrap_text=True
                )

            for row_idx, values in enumerate(
                df.itertuples(index=False,name=None), start=2
            ):
                for col_idx, value in enumerate(values,start=1):
                    if pd.isna(value):
                        value = None
                    ws.cell(row_idx,col_idx,value)

            ws.freeze_panes = "A2"
            if headers:
                ws.auto_filter.ref = ws.dimensions
            for col in ws.columns:
                letter = col[0].column_letter
                max_len = max(
                    [len(str(c.value or "")) for c in col[:500]] + [10]
                )
                ws.column_dimensions[letter].width = min(max_len+2,45)

        book.save(output_path)
        book.close()
    except Exception:
        pass

    return result

SalesStore.export_excel = _v1034_export_excel


