# En desarrollo usa la carpeta del .py; empaquetada con PyInstaller usa la carpeta del .exe.
# Así la base, configuración y documentos permanecen externos y persistentes.
APP_DIR = (
    Path(sys.executable).resolve().parent
    if getattr(sys, "frozen", False)
    else Path(__file__).resolve().parent
)
ROOT_DIR = APP_DIR.parent
DB_PATH = APP_DIR / "ventas_formulario.db"
CONFIG_PATH = APP_DIR / "ventas_formulario_config.json"
PRINT_DIR = APP_DIR / "facturas_generadas"


# Recursos iniciales incluidos dentro del .exe con PyInstaller.
SEED_DB_NAME = "ventas_formulario_PRUEBAS_LIMPIO.db"
SEED_MASTER_NAME = "BASE_MAESTRA_MXPC_2026_INICIO_PRUEBAS.xlsx"
PORTABLE_DATA_DIR = APP_DIR / "datos"
PORTABLE_MASTER_PATH = PORTABLE_DATA_DIR / SEED_MASTER_NAME

def _bundle_resource_path(name: str) -> Path:
    """Devuelve la ruta de un recurso tanto en desarrollo como dentro de PyInstaller."""
    if getattr(sys, "frozen", False) and hasattr(sys, "_MEIPASS"):
        return Path(sys._MEIPASS) / name
    return Path(__file__).resolve().parent / name

def initialize_portable_installation():
    """Primer arranque portable.

    Si el equipo no tiene archivos de trabajo, extrae desde el propio ejecutable
    la base SQLite inicial y la fuente maestra. Nunca reemplaza una base existente.
    """
    APP_DIR.mkdir(parents=True, exist_ok=True)
    PORTABLE_DATA_DIR.mkdir(parents=True, exist_ok=True)
    PRINT_DIR.mkdir(parents=True, exist_ok=True)
    (APP_DIR / "copias_diarias").mkdir(parents=True, exist_ok=True)
    (APP_DIR / "respaldos_db").mkdir(parents=True, exist_ok=True)

    seed_db = _bundle_resource_path(SEED_DB_NAME)
    seed_master = _bundle_resource_path(SEED_MASTER_NAME)

    if not DB_PATH.exists():
        if not seed_db.exists():
            raise FileNotFoundError(f"No se encontró la base inicial incluida: {seed_db}")
        shutil.copy2(seed_db, DB_PATH)

    if not PORTABLE_MASTER_PATH.exists():
        if not seed_master.exists():
            raise FileNotFoundError(f"No se encontró la fuente maestra incluida: {seed_master}")
        shutil.copy2(seed_master, PORTABLE_MASTER_PATH)

    # Configuración inicial: solo se crea/ajusta si no hay una fuente válida.
    cfg = {}
    if CONFIG_PATH.exists():
        try:
            loaded = json.loads(CONFIG_PATH.read_text(encoding="utf-8"))
            if isinstance(loaded, dict):
                cfg = loaded
        except Exception:
            cfg = {}

    current_sources = [Path(p) for p in cfg.get("master_sources", []) if p]
    if not any(p.exists() for p in current_sources):
        cfg["master_sources"] = [str(PORTABLE_MASTER_PATH)]
        cfg["source_watch_folder"] = str(PORTABLE_DATA_DIR)
        cfg["master_source_updated_at"] = datetime.now().isoformat(timespec="seconds")
