    def show_page(self, name: str):
        page = self.pages.get(name)
        if page:
            page.tkraise()

    def add_tree_scrollbars(self, parent, tree: ttk.Treeview):
        tree.grid(row=0, column=0, sticky="nsew")
        ybar = ttk.Scrollbar(parent, orient="vertical", command=tree.yview)
        xbar = ttk.Scrollbar(parent, orient="horizontal", command=tree.xview)
        ybar.grid(row=0, column=1, sticky="ns")
        xbar.grid(row=1, column=0, sticky="ew")
        tree.configure(yscrollcommand=ybar.set, xscrollcommand=xbar.set)
        parent.rowconfigure(0, weight=1)
        parent.columnconfigure(0, weight=1)
        return tree

    def make_scrollable_page(self, parent, *, bg="#F5F7F6"):
        """Crea un área verticalmente desplazable cuyo contenido siempre usa el ancho visible.

        La página general no tiene scroll horizontal: las tablas administran su propio
        desplazamiento horizontal. Esto evita que botones o campos desaparezcan fuera
        del viewport cuando cambia la resolución o el escalado de Windows.
        """
        host = ttk.Frame(parent)
        host.pack(fill="both", expand=True)
        canvas = tk.Canvas(host, highlightthickness=0, bg=bg)
        ybar = ttk.Scrollbar(host, orient="vertical", command=canvas.yview)
        canvas.configure(yscrollcommand=ybar.set)
        canvas.grid(row=0, column=0, sticky="nsew")
        ybar.grid(row=0, column=1, sticky="ns")
        host.rowconfigure(0, weight=1)
        host.columnconfigure(0, weight=1)

        inner = ttk.Frame(canvas)
        window_id = canvas.create_window((0, 0), window=inner, anchor="nw")

        def sync_scrollregion(_event=None):
            canvas.configure(scrollregion=canvas.bbox("all"))

        def sync_width(event):
            # La página ocupa exactamente el ancho visible. El scroll horizontal
            # queda reservado para Treeview u otros controles que realmente lo necesiten.
            canvas.itemconfigure(window_id, width=max(1, event.width))
            sync_scrollregion()

        inner.bind("<Configure>", sync_scrollregion, add="+")
        canvas.bind("<Configure>", sync_width, add="+")

        def wheel(event):
            if parent.winfo_ismapped():
                delta = -1 if event.delta > 0 else 1
                canvas.yview_scroll(delta * 3, "units")

        # El handler solo actúa cuando esta página está visible.
        self.bind_all("<MouseWheel>", wheel, add="+")
        return inner, canvas

    def active_source_text(self) -> str:
        sources = read_master_sources()
        existing = [str(p) for p in sources if p.exists()]
        return existing[0] if existing else "Sin Excel fuente activo"

    def refresh_source_panel(self):
        if "active_source" in self.vars:
            self.vars["active_source"].set(self.active_source_text())
        if hasattr(self, "sidebar_source_var"):
            active=self.active_source_text()
            self.sidebar_source_var.set(Path(active).name if active != "Sin Excel fuente activo" else "Sin fuente Excel")
        if hasattr(self, "sources_tree"):
            hist = self.store.source_history()
            self.fill_tree(self.sources_tree, [
                (r["fecha_importacion"], r["nombre_archivo"], "Sí" if int(r["activa"] or 0) else "No",
                 r["clientes_importados"], r["productos_importados"], r["ventas_importadas"], r["ruta"])
                for _, r in hist.iterrows()
            ])

    def reimport_active_source(self):
        sources = [p for p in read_master_sources() if p.exists()]
        if not sources:
            self.select_master_source()
            return
        self.import_master_source(sources[0])

    def import_master_source(self, source_path: Path):
        clientes, productos = load_master_records([source_path])
        sales_history = load_sales_history(source_path)
        if not clientes and not productos and not sales_history:
            raise ValueError("No se encontraron clientes, productos ni ventas reconocibles en el Excel seleccionado.")
        save_master_sources([source_path])
        self.store.import_master_records(clientes, productos, str(source_path))
        history_summary = self.store.import_sales_history(sales_history) if sales_history else {"facturas": 0, "detalles": 0, "abonos": 0}
        self.store.register_source_import(source_path, len(clientes), len(productos), history_summary["facturas"], "Importación desde interfaz")
        self.store.normalize_product_codes()
        self.catalogs = load_catalogs()
        self.reload_master_catalogs()
        self.refresh_all()
        self.refresh_source_panel()
        messagebox.showinfo(
            "Fuente actualizada",
            f"Fuente activa:\n{source_path}\n\nClientes: {len(clientes)}\nProductos: {len(productos)}\nVentas: {history_summary['facturas']}\n\nLa ruta y la fecha de importación quedaron registradas en la bitácora."
        )

    def update_sales_steps(self, active: str):
        return

    def set_sales_status(self, message: str, active_step: str | None = None):
        if "venta_observacion_estado" in self.vars:
            self.vars["venta_observacion_estado"].set(message)
        if active_step:
            self.update_sales_steps(active_step)
        if hasattr(self, "sales_status_label"):
            self.sales_status_label.configure(bg="#FFE0B5")
            self.after(240, lambda: self.sales_status_label.configure(bg="#FFF7E8"))

    def entry(self, parent, key, label, row, col, width=18, values=None, required=False):
        display_label = f"{label} *" if required else label
        ttk.Label(parent, text=display_label).grid(row=row, column=col, sticky="w", padx=4, pady=3)
        var = tk.StringVar()
        self.vars[key] = var
        if values is None:
            widget = ttk.Entry(parent, textvariable=var, width=width)
        else:
            widget = ttk.Combobox(parent, textvariable=var, width=width, values=values)
        widget.grid(row=row, column=col + 1, sticky="ew", padx=4, pady=3)
        self.widgets[key] = widget
        return widget

    def attach_autocomplete(self, widget, catalog_key: str):
        def filter_values(_event=None):
            typed = widget.get().strip().lower()
            values = self.catalogs.get(catalog_key, [])
            if typed:
                values = [v for v in values if typed in str(v).lower()]
            widget.configure(values=values[:80])

        widget.bind("<KeyRelease>", filter_values, add="+")

    def attach_client_suggestions(self, widget):
        widget.bind("<KeyRelease>", self.update_client_suggestions, add="+")
        widget.bind("<<ComboboxSelected>>", lambda _e: self.populate_client_fields(widget.get()), add="+")
        widget.bind("<Return>", lambda _e: self.populate_client_fields(widget.get()), add="+")

    def update_client_suggestions(self, _event=None):
        if not hasattr(self, "client_suggestions"):
            return
        typed = self.vars["venta_cliente"].get().strip().lower()
        self.client_suggestions.delete(0, tk.END)
        if not typed:
            self.clear_client_preview()
            return
        matches = [c for c in self.catalogs.get("clientes", []) if typed in c.lower()][:8]
        for match in matches:
            self.client_suggestions.insert(tk.END, match)
        if len(matches) == 1 and matches[0].lower() == typed:
            self.populate_client_fields(matches[0])

    def select_client_suggestion(self, _event=None):
        selected = self.client_suggestions.curselection()
        if not selected:
            return
        name = self.client_suggestions.get(selected[0])
        self.vars["venta_cliente"].set(name)
        self.populate_client_fields(name)

    def clear_client_preview(self):
        for key in ["venta_ciudad", "venta_telefono"]:
            if key in self.vars:
                self.vars[key].set("")

    def populate_client_fields(self, name: str):
        name = str(name or "").strip()
        if not name:
            self.clear_client_preview()
            return
        row = self.store.table("SELECT * FROM clientes WHERE nombre = ?", (name,))
        if row.empty:
            self.clear_client_preview()
            return
        client = row.iloc[0]
        if "venta_ciudad" in self.vars:
            self.vars["venta_ciudad"].set("" if pd.isna(client.get("ciudad", "")) else str(client.get("ciudad", "")))
        if "venta_telefono" in self.vars:
            self.vars["venta_telefono"].set("" if pd.isna(client.get("telefono", "")) else str(client.get("telefono", "")))
        address = "" if pd.isna(client.get("direccion", "")) else str(client.get("direccion", ""))
        if address:
            self.vars["venta_direccion"].set(address)
        self.set_sales_status(f"Cliente seleccionado: {name}. Continue con los productos.", "productos")

    def product_search_values(self) -> list[str]:
        productos = self.store.productos()
        if productos.empty:
            return []
        values = []
        for _, row in productos.iterrows():
            codigo = str(row["codigo"] or make_code(row["nombre"]))
            values.append(f"{codigo} - {row['nombre']}")
        return sorted(values)

    def find_product_row(self, query: str) -> pd.DataFrame:
        text = str(query or "").strip()
        if not text:
            return pd.DataFrame()
        if " - " in text:
            code, name = text.split(" - ", 1)
            row = self.store.table(
                "SELECT * FROM productos WHERE codigo = ? OR nombre = ? LIMIT 1",
                (code.strip(), name.strip()),
            )
            if not row.empty:
                return row
        like = f"%{text}%"
        return self.store.table(
            """
            SELECT *
            FROM productos
            WHERE codigo LIKE ? OR nombre LIKE ?
            ORDER BY
                CASE
                    WHEN codigo = ? THEN 0
                    WHEN nombre = ? THEN 1
                    ELSE 2
                END,
                nombre
            LIMIT 1
            """,
            (like, like, text, text),
        )

    def build_dashboard_tab(self):
        top=ttk.Frame(self.dashboard_tab); top.pack(fill="x",pady=(0,10))
        ttk.Label(top,text="Resumen comercial",style="Title.TLabel").pack(anchor="w")
        ttk.Label(top,text="Indicadores de ventas, cotizaciones y cartera.",style="Hint.TLabel").pack(anchor="w")
        cards=ttk.Frame(self.dashboard_tab); cards.pack(fill="x",pady=(0,12))
        self.dashboard_vars={k:tk.StringVar(value="0") for k in ["ventas","cotizaciones","pendientes","cartera"]}
        for i,(title,key) in enumerate([("Ventas registradas","ventas"),("Cotizaciones","cotizaciones"),("Cotizaciones abiertas","pendientes"),("Cartera pendiente","cartera")]):
            f=ttk.LabelFrame(cards,text=title,padding=12); f.grid(row=0,column=i,sticky="nsew",padx=4); cards.columnconfigure(i,weight=1)
            ttk.Label(f,textvariable=self.dashboard_vars[key],font=("Segoe UI",18,"bold")).pack(anchor="w")
        recent=ttk.LabelFrame(self.dashboard_tab,text="Actividad reciente",padding=8); recent.pack(fill="both",expand=True)
        cols=("tipo","numero","fecha","cliente","estado","total")
        dash_tree_wrap=ttk.Frame(recent); dash_tree_wrap.pack(fill="both",expand=True)
        self.dashboard_tree=ttk.Treeview(dash_tree_wrap,columns=cols,show="headings")
        for c,t,w in [("tipo","Tipo",100),("numero","Documento",130),("fecha","Fecha",100),("cliente","Cliente",230),("estado","Estado",120),("total","Total",120)]: self.dashboard_tree.heading(c,text=t); self.dashboard_tree.column(c,width=w,anchor="w")
        self.add_tree_scrollbars(dash_tree_wrap,self.dashboard_tree)
        self.dashboard_tree.bind("<Double-1>", self.open_dashboard_document)

        audit=ttk.LabelFrame(self.dashboard_tab,text="Historial de cambios",padding=8)
        audit.pack(fill="both",expand=True,pady=(8,0))
        audit_cols=("fecha","tipo","documento","accion","campo","anterior","nuevo")
        audit_wrap=ttk.Frame(audit); audit_wrap.pack(fill="both",expand=True)
        self.audit_tree=ttk.Treeview(audit_wrap,columns=audit_cols,show="headings",height=7)
        for c,t,w in [("fecha","Fecha/hora",145),("tipo","Tipo",90),("documento","Documento",120),("accion","Acción",80),("campo","Campo",150),("anterior","Anterior",220),("nuevo","Nuevo",220)]:
            self.audit_tree.heading(c,text=t); self.audit_tree.column(c,width=w,anchor="w")
        self.add_tree_scrollbars(audit_wrap,self.audit_tree)
        self.audit_tree.bind("<Double-1>", self.open_audit_document)

    def open_dashboard_document(self, _event=None):
        sel=self.dashboard_tree.selection()
        if not sel:
            return
        values=self.dashboard_tree.item(sel[0],"values")
        if len(values)<2:
            return
        tipo=str(values[0]).strip().lower(); doc=str(values[1]).strip()
        if tipo.startswith("venta"):
            self.load_sale_for_edit(doc); self.show_page("ventas")
        elif tipo.startswith("cot"):
            self.load_quote_by_number(doc); self.show_page("cotizaciones")

    def open_audit_document(self, _event=None):
        sel=self.audit_tree.selection()
        if not sel:
            return
        values=self.audit_tree.item(sel[0],"values")
        if len(values)<3:
            return
        tipo=str(values[1]).strip().lower(); doc=str(values[2]).strip()
        if tipo.startswith("venta") and not self.store.table("SELECT 1 FROM ventas WHERE cuenta_cobro=?",(doc,)).empty:
            self.load_sale_for_edit(doc); self.show_page("ventas")
        elif tipo.startswith("cot") and not self.store.get_quote(doc)[0].empty:
            self.load_quote_by_number(doc); self.show_page("cotizaciones")

    def load_quote_by_number(self, num: str):
        head,det=self.store.get_quote(num)
        if head.empty:
            return
        q=head.iloc[0]
        mapping={"cot_numero":"numero_cotizacion","cot_fecha":"fecha","cot_valida":"valida_hasta","cot_cliente":"cliente","cot_asesor":"asesor","cot_estado":"estado","cot_direccion":"direccion","cot_ciudad":"ciudad","cot_telefono":"telefono","cot_barrio":"barrio","cot_local_edificio":"local_edificio","cot_datos_entrega":"datos_entrega","cot_forma_pago":"forma_pago","cot_domicilio_empresa":"domicilio_empresa","cot_domicilio_cliente":"domicilio_cliente","cot_obs":"observaciones"}
        for key,col in mapping.items():
            if key in self.vars:
                self.vars[key].set("" if col not in q.index or pd.isna(q.get(col,"")) else str(q.get(col,"")))
        self.quote_lines=[{"producto":str(r["producto"]),"cantidad":float(r["cantidad"]),"precio_unitario":float(r["precio_unitario"]),"descuento":float(r["descuento"]),"subtotal":float(r["subtotal"]),"iva":float(r["iva"]),"total":float(r["total"])} for _,r in det.iterrows()]
        self.refresh_quote_lines()

