        qclient=self.entry(head,"cot_cliente","Cliente",3,0,width=22,values=self.catalogs.get("clientes",[]),required=True); self.attach_autocomplete(qclient,"clientes")
        self.entry(head,"cot_asesor","Asesor",4,0,width=22,values=self.catalogs["asesores"])
        self.entry(head,"cot_estado","Estado",5,0,width=22,values=["BORRADOR","ENVIADA","APROBADA","RECHAZADA","VENCIDA","CANCELADA","CONVERTIDA"],required=True); self.vars["cot_estado"].set("BORRADOR")
        self.entry(head,"cot_direccion","Dirección",6,0,width=22,required=True)
        self.entry(head,"cot_ciudad","Ciudad",7,0,width=22,required=True)
        self.entry(head,"cot_telefono","Teléfono",8,0,width=22,required=True)
        self.entry(head,"cot_barrio","Barrio",9,0,width=22)
        self.entry(head,"cot_local_edificio","Local / Edificio",10,0,width=22)
        self.entry(head,"cot_datos_entrega","Datos adicionales entrega",11,0,width=22)
        self.entry(head,"cot_forma_pago","Forma de pago",12,0,width=22,values=["Por definir"]+self.catalogs["medios"]); self.vars["cot_forma_pago"].set("Por definir")
        domicilio_empresa_entry=self.entry(head,"cot_domicilio_empresa","Domicilio empresa",13,0,width=22); domicilio_empresa_entry.insert(0,"0")
        domicilio_cliente_entry=self.entry(head,"cot_domicilio_cliente","Domicilio cliente",14,0,width=22); domicilio_cliente_entry.insert(0,"0")
        domicilio_cliente_entry.bind("<KeyRelease>",self.refresh_quote_totals,add="+")
        domicilio_cliente_entry.bind("<FocusOut>",self.refresh_quote_totals,add="+")
        self.entry(head,"cot_obs","Observaciones",15,0,width=22)

        prod=ttk.LabelFrame(editor,text="Agregar producto",padding=8)
        prod.pack(fill="x",pady=(0,8))
        prod.columnconfigure(1,weight=1)
        qp=self.entry(prod,"cot_producto","Producto",0,0,width=22,values=self.catalogs.get("productos_busqueda",self.catalogs.get("productos",[]))); self.attach_autocomplete(qp,"productos_busqueda")
        self.entry(prod,"cot_cantidad","Cantidad",1,0,width=22).insert(0,"1")
        self.entry(prod,"cot_precio","Precio unitario",2,0,width=22).insert(0,"0")
        self.entry(prod,"cot_descuento","Descuento $",3,0,width=22).insert(0,"0")
        self.entry(prod,"cot_iva_auto","IVA 19%",4,0,width=22,values=["SI","NO"]); self.vars["cot_iva_auto"].set("SI")
        ttk.Button(prod,text="+ Agregar a cotización",style="Soft.TButton",command=self.add_quote_line).grid(row=5,column=0,columnspan=2,sticky="ew",pady=(7,0))

        qlines=ttk.LabelFrame(listing,text="Productos de la cotización",padding=8)
        qlines.pack(fill="both",expand=False,pady=(0,8))
        quote_lines_wrap=ttk.Frame(qlines)
        quote_lines_wrap.pack(fill="both",expand=True)
        self.quote_lines_tree=ttk.Treeview(quote_lines_wrap,columns=("producto","cantidad","precio","desc","iva","total"),show="headings",height=6)
        for c,t,w in [("producto","Producto",220),("cantidad","Cant.",70),("precio","Precio",100),("desc","Desc.",90),("iva","IVA",90),("total","Total",110)]:
            self.quote_lines_tree.heading(c,text=t); self.quote_lines_tree.column(c,width=w,anchor="w")
        self.add_tree_scrollbars(quote_lines_wrap,self.quote_lines_tree)
