        self.sales_capture=ttk.Frame(self.sales_form_host); self.sales_review=ttk.Frame(self.sales_form_host)
        doc=ttk.LabelFrame(self.sales_capture,text="1. Documento y cliente",padding=8); doc.pack(fill="x",pady=(0,8)); doc.columnconfigure(1,weight=1); doc.columnconfigure(3,weight=1)
