        self.entry(doc,"venta_estado","Estado",2,2,values=self.catalogs["estados"],required=True); self.vars["venta_estado"].set("EMITIDA")
        self.entry(doc,"venta_asesor","Asesor",3,0,values=self.catalogs["asesores"],required=True)
        self.entry(doc,"venta_telefono","Teléfono cliente",3,2,width=28,required=True)
        self.entry(doc,"venta_direccion","Dirección entrega",4,0,width=28,required=True)
        self.entry(doc,"venta_ciudad","Ciudad",4,2,width=28,required=True)
        self.entry(doc,"venta_barrio","Barrio",5,0,width=28)
        self.entry(doc,"venta_local_edificio","Local / Edificio",5,2,width=28)
        self.entry(doc,"venta_datos_entrega","Datos adicionales entrega",6,0,width=28)
        self.entry(doc,"venta_cotizacion_origen","Cotización origen",6,2,width=28).configure(state="readonly")
        self.entry(doc,"venta_recibido_por","Recibido por",7,0,width=28)
        self.entry(doc,"venta_obs","Observaciones",7,2,width=28)
        self.client_suggestions=tk.Listbox(doc,height=3); self.client_suggestions.grid(row=8,column=0,columnspan=4,sticky="ew",padx=4,pady=2); self.client_suggestions.bind("<<ListboxSelect>>",self.select_client_suggestion)
        prod=ttk.LabelFrame(self.sales_capture,text="2. Agregar producto",padding=8); prod.pack(fill="x",pady=(0,8)); prod.columnconfigure(1,weight=1); prod.columnconfigure(3,weight=1)
        pw=self.entry(prod,"det_producto","Producto",0,0,width=28,values=self.catalogs.get("productos_busqueda",self.catalogs["productos"]),required=True); pw.bind("<<ComboboxSelected>>",self.on_detail_product_select); pw.bind("<Return>",self.on_detail_product_select); self.attach_autocomplete(pw,"productos_busqueda")
