        self.entry(prod,"det_comision_unitaria","Comisión por unidad",3,0).insert(0,"0"); self.entry(prod,"det_comision","Comisión total",3,2).insert(0,"0"); self.widgets["det_comision"].configure(state="readonly")
        self.entry(prod,"det_iva","IVA",4,0).insert(0,"0"); self.entry(prod,"det_retenciones","Retenciones",4,2).insert(0,"0"); self.entry(prod,"det_auto_iva","Calcular IVA",5,0,values=["SI","NO"]); self.vars["det_auto_iva"].set("SI"); self.entry(prod,"det_total_linea","Total línea",5,2).insert(0,"0"); self.vars["det_chile"]=tk.StringVar(value="0"); self.vars["det_domicilio"]=tk.StringVar(value="0")
        for k in ["det_cantidad","det_valor_kl","det_valor_total","det_comision_unitaria","det_iva","det_retenciones"]: self.widgets[k].bind("<FocusOut>",self.recalculate_detail_total)
        self.widgets["det_auto_iva"].bind("<<ComboboxSelected>>",self.recalculate_detail_total); ttk.Button(prod,text="Agregar producto",style="Soft.TButton",command=self.add_product_line).grid(row=6,column=0,columnspan=4,sticky="ew",padx=4,pady=3)
        pay=ttk.LabelFrame(self.sales_capture,text="3. Pago y domicilio",padding=8); pay.pack(fill="x"); pay.columnconfigure(1,weight=1); pay.columnconfigure(3,weight=1)
