    def build_masters_tab(self):
        """Página responsive de clientes/productos con scroll vertical general.

        La página completa puede desplazarse verticalmente para que los formularios
        de Cliente y Producto nunca queden cortados en pantallas pequeñas. Las tablas
        conservan sus propios scrollbars horizontal y vertical.
        """
        page, canvas = self.make_scrollable_page(self.masters_tab)
        self.masters_canvas = canvas

        # Encabezado: usa grid para poder envolver los botones en pantallas estrechas.
        top = ttk.Frame(page)
        top.pack(fill="x", pady=(0, 10))
        top.columnconfigure(0, weight=1)
        ttk.Label(top, text="Datos maestros editables", style="Title.TLabel").grid(
            row=0, column=0, sticky="w", padx=(0, 8), pady=(0, 6)
        )
        actions = ttk.Frame(top)
        actions.grid(row=0, column=1, sticky="e")
        ttk.Button(actions, text="Cambiar Excel fuente", style="Accent.TButton",
                   command=self.select_master_source).pack(side="left", padx=3)
        ttk.Button(actions, text="Reimportar fuente",
                   command=self.reimport_active_source).pack(side="left", padx=3)
        ttk.Button(actions, text="Exportar fuente actualizada",
                   command=self.export_updated_master_source).pack(side="left", padx=3)
        ttk.Button(actions, text="Recargar listas",
                   command=self.reload_master_catalogs).pack(side="left", padx=3)

        source_box = ttk.LabelFrame(page, text="Fuente y trazabilidad", padding=8)
        source_box.pack(fill="x", pady=(0, 10))
        self.vars["active_source"] = tk.StringVar(value=self.active_source_text())
        ttk.Label(source_box, text="Excel activo:", style="Muted.TLabel").pack(side="left")
        ttk.Label(source_box, textvariable=self.vars["active_source"]).pack(
            side="left", padx=(6, 0), fill="x", expand=True
        )

        # Contenedor responsive. En pantallas anchas se muestran formulario y tablas
        # lado a lado; en pantallas pequeñas las tablas pasan debajo del formulario.
        body = ttk.Frame(page)
        body.pack(fill="both", expand=True)
        body.columnconfigure(0, weight=0, minsize=420)
        body.columnconfigure(1, weight=1)
        body.rowconfigure(0, weight=1)

        left = ttk.Frame(body)
        right = ttk.Frame(body)
        left.grid(row=0, column=0, sticky="nsew", padx=(0, 10))
        right.grid(row=0, column=1, sticky="nsew")

        client_box = ttk.LabelFrame(left, text="Cliente", padding=10)
        client_box.pack(fill="x")
        self.entry(client_box, "cli_nombre", "Nombre", 0, 0, width=34)
        self.entry(client_box, "cli_ciudad", "Ciudad", 1, 0, width=28)
        self.entry(client_box, "cli_direccion", "Direccion", 2, 0, width=34)
        self.entry(client_box, "cli_telefono", "Telefono", 3, 0, width=28)
        self.entry(client_box, "cli_email", "Email", 4, 0, width=28)
        self.entry(client_box, "cli_notas", "Notas", 5, 0, width=34)
        ttk.Button(client_box, text="Guardar cliente", command=self.save_client).grid(
            row=6, column=0, columnspan=2, sticky="ew", pady=(8, 0)
        )

        product_box = ttk.LabelFrame(left, text="Producto e inventario", padding=10)
        product_box.pack(fill="x", pady=(10, 0))
        self.entry(product_box, "prod_codigo", "Codigo", 0, 0)
        self.entry(product_box, "prod_nombre", "Producto", 1, 0, width=34)
        self.entry(product_box, "prod_unidad", "Unidad", 2, 0,
                   values=["KLS", "UNIDAD", "CAJA", "PAQUETE"])
        self.vars["prod_unidad"].set("KLS")
        self.entry(product_box, "prod_precio", "Precio venta", 3, 0).insert(0, "0")
        self.entry(product_box, "prod_comision_unitaria",
                   "Comisión sugerida / unidad", 4, 0).insert(0, "0")
        self.entry(product_box, "prod_costo", "Costo", 5, 0).insert(0, "0")
        self.entry(product_box, "prod_stock", "Stock actual", 6, 0).insert(0, "0")
        self.entry(product_box, "prod_minimo", "Stock minimo", 7, 0).insert(0, "0")
        self.entry(product_box, "prod_activo", "Activo", 8, 0, values=["SI", "NO"])
        self.vars["prod_activo"].set("SI")
        ttk.Button(product_box, text="Guardar producto", command=self.save_product).grid(
            row=9, column=0, columnspan=2, sticky="ew", pady=(8, 0)
        )

        master_notebook = ttk.Notebook(right)
        master_notebook.pack(fill="both", expand=True)

        clients_frame = ttk.Frame(master_notebook)
        products_frame = ttk.Frame(master_notebook)
        sources_frame = ttk.Frame(master_notebook)
        master_notebook.add(clients_frame, text="Clientes")
        master_notebook.add(products_frame, text="Productos / inventario")
        master_notebook.add(sources_frame, text="Trazabilidad de fuentes")

        self.clients_tree = ttk.Treeview(
            clients_frame,
            columns=("nombre", "ciudad", "direccion", "telefono", "email", "origen", "modificado"),
            show="headings",
            height=17,
        )
        for col, title in zip(
            ("nombre", "ciudad", "direccion", "telefono", "email", "origen", "modificado"),
            ("Cliente", "Ciudad", "Dirección", "Teléfono", "Email", "Fuente origen", "Edición manual"),
        ):
            self.clients_tree.heading(col, text=title)
            self.clients_tree.column(
                col, width=210 if col in ["nombre", "direccion", "origen"] else 120, anchor="w"
            )
        self.add_tree_scrollbars(clients_frame, self.clients_tree)
        self.clients_tree.bind("<<TreeviewSelect>>", self.on_client_select)

        self.products_tree = ttk.Treeview(
            products_frame,
            columns=("codigo", "nombre", "unidad", "precio", "comision", "stock", "minimo", "activo"),
            show="headings",
            height=17,
        )
        headings = {
            "codigo": "Codigo",
            "nombre": "Producto",
            "unidad": "Unidad",
            "precio": "Precio",
            "comision": "Comisión/u",
            "stock": "Stock",
            "minimo": "Minimo",
            "activo": "Activo",
        }
        for col in ("codigo", "nombre", "unidad", "precio", "comision", "stock", "minimo", "activo"):
            self.products_tree.heading(col, text=headings[col])
            self.products_tree.column(col, width=210 if col == "nombre" else 95, anchor="w")
        self.add_tree_scrollbars(products_frame, self.products_tree)
        self.products_tree.bind("<<TreeviewSelect>>", self.on_product_select)

        self.sources_tree = ttk.Treeview(
            sources_frame,
            columns=("fecha", "archivo", "activa", "clientes", "productos", "ventas", "ruta"),
            show="headings",
            height=17,
        )
        for col, title, width in [
            ("fecha", "Fecha importación", 155), ("archivo", "Archivo", 220), ("activa", "Activa", 65),
            ("clientes", "Clientes", 80), ("productos", "Productos", 80),
            ("ventas", "Ventas", 75), ("ruta", "Ruta completa", 420),
        ]:
            self.sources_tree.heading(col, text=title)
            self.sources_tree.column(col, width=width, anchor="w")
        self.add_tree_scrollbars(sources_frame, self.sources_tree)

        # Breakpoint responsive. El ancho del canvas refleja el viewport real.
        self._masters_compact_layout = None

        def layout_masters(event=None):
            width = event.width if event is not None and hasattr(event, "width") else canvas.winfo_width()
            compact = width < 1180
            if compact == self._masters_compact_layout:
                return
            self._masters_compact_layout = compact

            left.grid_forget()
            right.grid_forget()
            if compact:
                body.columnconfigure(0, weight=1, minsize=0)
                body.columnconfigure(1, weight=0, minsize=0)
                body.rowconfigure(0, weight=0)
                body.rowconfigure(1, weight=1)
                left.grid(row=0, column=0, sticky="ew", padx=0, pady=(0, 10))
                right.grid(row=1, column=0, sticky="nsew")
            else:
                body.columnconfigure(0, weight=0, minsize=420)
                body.columnconfigure(1, weight=1)
                body.rowconfigure(0, weight=1)
                body.rowconfigure(1, weight=0)
                left.grid(row=0, column=0, sticky="nsew", padx=(0, 10), pady=0)
                right.grid(row=0, column=1, sticky="nsew")
            page.update_idletasks()
            canvas.configure(scrollregion=canvas.bbox("all"))

        canvas.bind("<Configure>", layout_masters, add="+")
        self.after_idle(layout_masters)

    def build_summary_tab(self):
        columns = ("factura", "fecha", "cliente", "total", "abonos", "saldo", "estado")
        self.summary_tree = ttk.Treeview(self.summary_tab, columns=columns, show="headings")
        for col, title in zip(columns, ["Factura", "Fecha", "Cliente", "Total", "Abonos", "Saldo", "Estado"]):
            self.summary_tree.heading(col, text=title)
            self.summary_tree.column(col, width=135 if col != "cliente" else 260, anchor="w")
        self.add_tree_scrollbars(self.summary_tab, self.summary_tree)
        self.summary_tree.bind("<Double-1>", self.open_sale_from_summary)

    def require(self, key, label):
        value = self.vars[key].get().strip()
        if not value:
            raise ValueError(f"Falta diligenciar: {label}")
        return value

    def save_client(self):
        try:
            new_name = self.require("cli_nombre", "Nombre del cliente")
            old_name = getattr(self, "editing_client_name", None)
            if old_name and old_name != new_name:
                self.store.rename_client(old_name, new_name)
            self.store.upsert_cliente(
                {
                    "nombre": new_name,
                    "ciudad": self.vars["cli_ciudad"].get().strip(),
                    "direccion": self.vars["cli_direccion"].get().strip(),
                    "telefono": self.vars["cli_telefono"].get().strip(),
                    "email": self.vars["cli_email"].get().strip(),
                    "notas": self.vars["cli_notas"].get().strip(),
                }
            )
            self.editing_client_name = new_name
            self.reload_master_catalogs()
            self.refresh_all()
            messagebox.showinfo("Cliente guardado", "El cliente quedó actualizado y la trazabilidad fue conservada.")
        except Exception as exc:
            messagebox.showerror("Error", str(exc))

    def save_product(self):
        try:
            self.store.upsert_producto(
                {
                    "codigo": self.vars["prod_codigo"].get().strip(),
                    "nombre": self.require("prod_nombre", "Nombre del producto"),
                    "unidad": self.vars["prod_unidad"].get().strip() or "KLS",
                    "precio_venta": money(self.vars["prod_precio"].get()),
                    "comision_unitaria_sugerida": money(self.vars["prod_comision_unitaria"].get()),
                    "costo": money(self.vars["prod_costo"].get()),
                    "stock_actual": money(self.vars["prod_stock"].get()),
                    "stock_minimo": money(self.vars["prod_minimo"].get()),
                    "activo": self.vars["prod_activo"].get().strip() or "SI",
                }
            )
            self.reload_master_catalogs()
            self.refresh_all()
            messagebox.showinfo("Producto guardado", "El producto e inventario quedaron actualizados.")
        except Exception as exc:
            messagebox.showerror("Error", str(exc))

    def on_client_select(self, _event=None):
        selected = self.clients_tree.selection()
        if not selected:
            return
        values = self.clients_tree.item(selected[0], "values")
        if not values:
            return
        self.editing_client_name = str(values[0])
        row = self.store.table("SELECT * FROM clientes WHERE nombre = ?", (values[0],))
        if row.empty:
            return
        row = row.iloc[0]
        for key, col in {
            "cli_nombre": "nombre",
            "cli_ciudad": "ciudad",
            "cli_direccion": "direccion",
            "cli_telefono": "telefono",
            "cli_email": "email",
            "cli_notas": "notas",
        }.items():
            self.vars[key].set("" if pd.isna(row[col]) else str(row[col]))

    def on_product_select(self, _event=None):
        selected = self.products_tree.selection()
        if not selected:
            return
        values = self.products_tree.item(selected[0], "values")
        if not values:
            return
        row = self.store.table("SELECT * FROM productos WHERE codigo = ?", (values[0],))
        if row.empty:
            return
        row = row.iloc[0]
        for key, col in {
            "prod_codigo": "codigo",
            "prod_nombre": "nombre",
            "prod_unidad": "unidad",
            "prod_precio": "precio_venta",
            "prod_comision_unitaria": "comision_unitaria_sugerida",
            "prod_costo": "costo",
            "prod_stock": "stock_actual",
            "prod_minimo": "stock_minimo",
            "prod_activo": "activo",
        }.items():
            self.vars[key].set("" if pd.isna(row[col]) else str(row[col]))

    def on_detail_product_select(self, _event=None):
        query = self.vars["det_producto"].get().strip()
        if not query:
            return
        row = self.find_product_row(query)
        if row.empty:
            return
        product = row.iloc[0]
        self.vars["det_codigo"].set(str(product["codigo"] or ""))
        self.vars["det_producto"].set(f"{product['codigo']} - {product['nombre']}")
        price = float(product["precio_venta"] or 0)
        if price > 0 and money(self.vars["det_valor_kl"].get()) <= 0:
            self.vars["det_valor_kl"].set(f"{price:.0f}")
        commission_unit = float(product.get("comision_unitaria_sugerida", 0) or 0)
        self.vars["det_comision_unitaria"].set(f"{commission_unit:.0f}")
        self.recalculate_detail_total()

    def recalculate_detail_total(self, _event=None):
        cantidad = money(self.vars.get("det_cantidad", tk.StringVar()).get())
        valor_kl = money(self.vars.get("det_valor_kl", tk.StringVar()).get())
        valor_total = money(self.vars.get("det_valor_total", tk.StringVar()).get())
        if cantidad > 0 and valor_kl > 0:
            valor_total = cantidad * valor_kl
            self.vars["det_valor_total"].set(f"{valor_total:.0f}")
        commission_unit = money(self.vars.get("det_comision_unitaria", tk.StringVar()).get())
        commission_total = cantidad * commission_unit if cantidad > 0 and commission_unit > 0 else 0.0
        self.vars["det_comision"].set(f"{commission_total:.0f}")
        if self.vars.get("det_auto_iva", tk.StringVar(value="SI")).get().strip().upper() == "SI":
            self.vars["det_iva"].set(f"{valor_total * 0.19:.0f}")
        total_linea = (
            valor_total
            + money(self.vars.get("det_iva", tk.StringVar()).get())
            + money(self.vars.get("det_retenciones", tk.StringVar()).get())
        )
        self.vars["det_total_linea"].set(f"{total_linea:.0f}")

    def invoice_domicilio_total(self) -> float:
        # Solo el domicilio cobrado al cliente hace parte del total comercial.
        return money(self.vars.get("venta_domicilio_cliente", tk.StringVar()).get())

    def invoice_products_total(self) -> float:
        return sum(line["total_linea"] for line in self.product_lines)

    def invoice_total(self) -> float:
        return self.invoice_products_total() + self.invoice_domicilio_total()

    def refresh_invoice_totals(self, _event=None):
        if "venta_total_productos" in self.vars:
            self.vars["venta_total_productos"].set(f"{self.invoice_total():,.0f}")
        if "venta_total_pagos" in self.vars:
            self.vars["venta_total_pagos"].set(f"{sum(line['valor_abono'] for line in self.payment_lines):,.0f}")

    def add_product_line(self):
        try:
            product_row = self.find_product_row(self.require("det_producto", "Producto"))
            if product_row.empty:
                raise ValueError("Seleccione un producto valido desde la busqueda por codigo o nombre.")
            product = product_row.iloc[0]
            cantidad = money(self.vars["det_cantidad"].get())
            valor_kl = money(self.vars["det_valor_kl"].get())
            valor_total = money(self.vars["det_valor_total"].get())
            if cantidad <= 0:
                raise ValueError("La cantidad en KLS debe ser mayor a cero.")
            if valor_total <= 0 and valor_kl > 0:
                valor_total = cantidad * valor_kl
                self.vars["det_valor_total"].set(f"{valor_total:.0f}")
            if valor_total <= 0:
                raise ValueError("El valor total del producto debe ser mayor a cero.")
            if self.vars["det_auto_iva"].get().strip().upper() == "SI":
                self.vars["det_iva"].set(f"{valor_total * 0.19:.0f}")
            line = {
                "codigo": str(product["codigo"] or ""),
                "producto": str(product["nombre"]),
                "cantidad_kls": cantidad,
                "valor_x_kl": valor_kl,
                "valor_total": valor_total,
                "comision_unitaria": money(self.vars["det_comision_unitaria"].get()),
                "comision": money(self.vars["det_comision"].get()),
                "iva_19": money(self.vars["det_iva"].get()),
                "retenciones": money(self.vars["det_retenciones"].get()),
                "chile_fresco": money(self.vars["det_chile"].get()),
                "domicilio": 0,
            }
            line["total_linea"] = (
                line["valor_total"]
                + line["iva_19"]
                + line["retenciones"]
            )
            self.product_lines.append(line)
            self.refresh_product_lines()
            self.set_sales_status(f"Producto agregado: {line['producto']} por {line['total_linea']:,.0f}.", "productos")
        except Exception as exc:
            messagebox.showerror("Error", str(exc))

    def remove_product_line(self):
        selected = self.product_lines_tree.selection()
        if not selected:
            return
        index = self.product_lines_tree.index(selected[0])
        if 0 <= index < len(self.product_lines):
            removed = self.product_lines.pop(index)
            self.set_sales_status(f"Producto quitado: {removed['producto']}.", "productos")
        self.refresh_product_lines()

    def refresh_product_lines(self):
        self.fill_tree(
            self.product_lines_tree,
            [
                (
                    line["codigo"],
                    line["producto"],
                    f"{line['cantidad_kls']:,.2f}",
                    f"{line['valor_x_kl']:,.0f}",
                    f"{line['valor_total']:,.0f}",
                    f"{line.get('comision_unitaria', 0):,.0f}",
                    f"{line['comision']:,.0f}",
                    f"{line['iva_19']:,.0f}",
                    f"{line['total_linea']:,.0f}",
                )
                for line in self.product_lines
            ],
        )
        children = self.product_lines_tree.get_children()
        if children:
            self.product_lines_tree.see(children[-1])
            self.product_lines_tree.selection_set(children[-1])
        self.refresh_invoice_totals()

    def add_payment_line(self):
        try:
            medio = self.require("sale_pay_medio", "Medio de pago")
            valor = money(self.vars["sale_pay_valor"].get())
            if valor <= 0:
                raise ValueError("El valor del pago debe ser mayor a cero.")
            self.payment_lines.append(
                {
                    "medio_pago": medio,
                    "cta_bancaria_destino": self.vars["sale_pay_cta"].get().strip(),
                    "referencia_pago": self.vars["sale_pay_ref"].get().strip(),
                    "valor_abono": valor,
                    "fecha_abono": self.vars["venta_fecha"].get().strip() or today_text(),
                }
            )
            self.refresh_payment_lines()
            self.set_sales_status(f"Pago agregado: {medio} por {valor:,.0f}.", "pago")
        except Exception as exc:
            messagebox.showerror("Error", str(exc))

    def remove_payment_line(self):
        selected = self.payment_lines_tree.selection()
        if not selected:
            return
        index = self.payment_lines_tree.index(selected[0])
        if 0 <= index < len(self.payment_lines):
            removed = self.payment_lines.pop(index)
            self.set_sales_status(f"Pago quitado: {removed['medio_pago']} por {removed['valor_abono']:,.0f}.", "pago")
        self.refresh_payment_lines()

    def refresh_payment_lines(self):
        self.fill_tree(
            self.payment_lines_tree,
            [
                (
                    line["medio_pago"],
                    line["cta_bancaria_destino"],
                    line["referencia_pago"],
                    f"{line['valor_abono']:,.0f}",
                )
                for line in self.payment_lines
            ],
        )
        children = self.payment_lines_tree.get_children()
        if children:
            self.payment_lines_tree.see(children[-1])
            self.payment_lines_tree.selection_set(children[-1])
        self.refresh_invoice_totals()

