def _autosave_after_db_change(method_name: str):
    """Envuelve una acción de UI y exporta solo si SQLite realmente cambió."""
    original = getattr(SalesFormApp, method_name, None)
    if original is None:
        return
    def wrapped(self, *args, **kwargs):
        before = getattr(self.store.conn, "total_changes", 0)
        result = original(self, *args, **kwargs)
        after = getattr(self.store.conn, "total_changes", 0)
        if after > before:
            try:
                path = self.store.export_daily_snapshot()
                self.last_daily_snapshot_path = str(path)
            except Exception as exc:
                # La operación ya quedó segura en SQLite. Se informa el problema
                # del Excel sin revertir la venta/cotización/abono registrado.
                try:
                    messagebox.showwarning(
                        "Autoguardado diario",
                        "El cambio quedó guardado en la base de datos, pero no fue posible actualizar la copia Excel diaria.\n\n"
                        f"Detalle: {exc}",
                        parent=self,
                    )
                except Exception:
                    pass
        return result
    setattr(SalesFormApp, method_name, wrapped)


# Acciones operativas que deben refrescar automáticamente la copia diaria.
for _method in [
    "save_sale",
    "save_quote",
    "delete_selected_quote",
    "delete_all_quotes",
    "save_payment",
    "apply_payment",
    # También mantenemos sincronizados los cambios de maestros.
    "save_client",
    "save_product",
]:
    _autosave_after_db_change(_method)

# ==================== FIN V9.2 AUTOGUARDADO DIARIO ====================



# ==================== V9.8 OPERACION PORTABLE CORREGIDA ====================
# Unifica todas las rutas operativas alrededor del ejecutable, crea una copia diaria
# desde el arranque y separa precio de venta de costo/comisión internos.

ACCOUNTS_DIR = APP_DIR / "cuentas_cobro"
QUOTES_DIR = APP_DIR / "cotizaciones_generadas"
DAILY_DIR = APP_DIR / "copias_diarias"
BACKUP_DIR = APP_DIR / "respaldos_db"

# Extender la instalación portable con una única estructura de trabajo predecible.
_v98_original_initialize_portable_installation = initialize_portable_installation
def initialize_portable_installation():
    _v98_original_initialize_portable_installation()
    for folder in (ACCOUNTS_DIR, QUOTES_DIR, DAILY_DIR, BACKUP_DIR, PORTABLE_DATA_DIR):
        folder.mkdir(parents=True, exist_ok=True)
    cfg = read_config()
    cfg.setdefault("invoice_output_dir", str(ACCOUNTS_DIR))
    cfg.setdefault("quote_output_dir", str(QUOTES_DIR))
    cfg["daily_output_dir"] = str(DAILY_DIR.resolve())
    cfg["workspace_dir"] = str(APP_DIR.resolve())
    write_config(cfg)


# La copia diaria siempre queda junto al ejecutable, no dentro de /datos ni al lado
# de una fuente que pueda haberse escogido en otra ubicación.
def _daily_snapshot_target() -> Path:
    """Ruta fija de la copia diaria.

    Desarrollo:
        <carpeta del .py>\\copias_diarias\\ventas_formulario_YYYY-MM-DD.xlsx

    Ejecutable portable:
        <carpeta del .exe>\\copias_diarias\\ventas_formulario_YYYY-MM-DD.xlsx

    La ruta ya no depende del nombre ni de la ubicación del Excel fuente.
    """
    DAILY_DIR.mkdir(parents=True, exist_ok=True)
    return DAILY_DIR / f"ventas_formulario_{datetime.now().strftime('%Y-%m-%d')}.xlsx"


# Migraciones de detalle para registrar el valor interno sin alterar el documento al cliente.
_v98_original_init_schema = SalesStore.init_schema
def _v98_init_schema(self):
    _v98_original_init_schema(self)
    self.ensure_column("ventas_detalle", "costo_unitario", "REAL NOT NULL DEFAULT 0")
    self.ensure_column("cotizaciones_detalle", "costo_unitario", "REAL NOT NULL DEFAULT 0")
    self.ensure_column("cotizaciones_detalle", "comision_unitaria", "REAL NOT NULL DEFAULT 0")
    self.ensure_column("cotizaciones_detalle", "precio_venta", "REAL NOT NULL DEFAULT 0")
    self.conn.execute("UPDATE cotizaciones_detalle SET precio_venta=precio_unitario WHERE COALESCE(precio_venta,0)=0")
    self.conn.commit()
SalesStore.init_schema = _v98_init_schema


# Guardar costo y comisión dentro de cada línea de venta.
def _v98_add_detail(self, data: dict):
    current = self.conn.execute(
        "SELECT COALESCE(MAX(item), 0) + 1 FROM ventas_detalle WHERE cuenta_cobro = ?",
        (data["cuenta_cobro"],),
    ).fetchone()[0]
    self.conn.execute(
        """
        INSERT INTO ventas_detalle (
            cuenta_cobro, item, producto, cantidad_kls, valor_x_kl,
            valor_total, costo_unitario, comision_unitaria, comision, iva_19,
            retenciones, chile_fresco, domicilio
        ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        """,
        (
            data["cuenta_cobro"], current, data["producto"], data["cantidad_kls"],
            data["valor_x_kl"], data["valor_total"], data.get("costo_unitario", 0),
            data.get("comision_unitaria", 0), data.get("comision", 0),
            data.get("iva_19", 0), data.get("retenciones", 0),
            data.get("chile_fresco", 0), data.get("domicilio", 0),
        ),
    )
    self.conn.commit()
SalesStore.add_detail = _v98_add_detail


# Cotización: precio de venta visible al cliente; costo y comisión quedan solo internos.
def _v98_save_quote(self, data: dict, details: list[dict]):
    self.ensure_cliente(data["cliente"])
    self.conn.execute(
        """
        INSERT INTO cotizaciones (
            numero_cotizacion, fecha, valida_hasta, cliente, asesor, direccion,
            ciudad, telefono, barrio, local_edificio, datos_entrega, estado,
            forma_pago, domicilio, domicilio_empresa, domicilio_cliente, observaciones,
            cuenta_cobro_convertida, fecha_conversion
        ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        ON CONFLICT(numero_cotizacion) DO UPDATE SET
            fecha=excluded.fecha, valida_hasta=excluded.valida_hasta,
            cliente=excluded.cliente, asesor=excluded.asesor,
            direccion=excluded.direccion, ciudad=excluded.ciudad,
            telefono=excluded.telefono, barrio=excluded.barrio,
            local_edificio=excluded.local_edificio, datos_entrega=excluded.datos_entrega,
            estado=excluded.estado, forma_pago=excluded.forma_pago,
            domicilio=excluded.domicilio, domicilio_empresa=excluded.domicilio_empresa,
            domicilio_cliente=excluded.domicilio_cliente, observaciones=excluded.observaciones
        """,
        (
            data["numero_cotizacion"], data["fecha"], data.get("valida_hasta", ""),
            data["cliente"], data.get("asesor", ""), data.get("direccion", ""),
            data.get("ciudad", ""), data.get("telefono", ""), data.get("barrio", ""),
            data.get("local_edificio", ""), data.get("datos_entrega", ""),
            data.get("estado", "BORRADOR"), data.get("forma_pago", ""),
            float(data.get("domicilio_cliente", data.get("domicilio", 0)) or 0),
            float(data.get("domicilio_empresa", 0) or 0),
            float(data.get("domicilio_cliente", data.get("domicilio", 0)) or 0),
            data.get("observaciones", ""), data.get("cuenta_cobro_convertida", ""),
            data.get("fecha_conversion", ""),
        ),
    )
    self.conn.execute("DELETE FROM cotizaciones_detalle WHERE numero_cotizacion = ?", (data["numero_cotizacion"],))
    for idx, d in enumerate(details, 1):
        precio_venta = float(d.get("precio_venta", d.get("precio_unitario", 0)) or 0)
        self.conn.execute(
            """
            INSERT INTO cotizaciones_detalle (
                numero_cotizacion, item, producto, cantidad, precio_unitario,
                costo_unitario, comision_unitaria, precio_venta,
                descuento, subtotal, iva, total
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                data["numero_cotizacion"], idx, d["producto"], float(d["cantidad"]),
                precio_venta, float(d.get("costo_unitario", 0) or 0),
                float(d.get("comision_unitaria", 0) or 0), precio_venta,
                float(d.get("descuento", 0) or 0), float(d["subtotal"]),
                float(d.get("iva", 0) or 0), float(d["total"]),
            ),
        )
    self.conn.commit()
SalesStore.save_quote = _v98_save_quote


