# Conversión de cotización: transfiere exactamente precio de venta, costo y comisión,
# sin sumar la comisión nuevamente al total.
def _v98_convert_quote_to_sale(self):
    try:
        num = self.require("cot_numero", "Número de cotización")
        existing_head, _ = self.store.get_quote(num)
        if not existing_head.empty:
            existing = existing_head.iloc[0]
            if str(existing.get("estado", "")).upper() == "CONVERTIDA" and str(existing.get("cuenta_cobro_convertida", "") or "").strip():
                raise ValueError(f"Esta cotización ya fue convertida en la cuenta {existing['cuenta_cobro_convertida']}.")
        if not self.quote_lines:
            raise ValueError("Agregue al menos un producto a la cotización antes de convertirla.")
        quote_data = {
            "numero_cotizacion": num, "fecha": self.require("cot_fecha", "Fecha"),
            "valida_hasta": self.require("cot_valida", "Válida hasta"),
            "cliente": self.require("cot_cliente", "Cliente"), "asesor": self.vars["cot_asesor"].get().strip(),
            "direccion": self.require("cot_direccion", "Dirección"), "ciudad": self.require("cot_ciudad", "Ciudad"),
            "telefono": self.require("cot_telefono", "Teléfono"), "barrio": self.vars["cot_barrio"].get().strip(),
            "local_edificio": self.vars["cot_local_edificio"].get().strip(), "datos_entrega": self.vars["cot_datos_entrega"].get().strip(),
            "estado": self.require("cot_estado", "Estado"), "forma_pago": self.vars["cot_forma_pago"].get().strip(),
            "domicilio": money(self.vars["cot_domicilio_cliente"].get()), "domicilio_empresa": money(self.vars["cot_domicilio_empresa"].get()),
            "domicilio_cliente": money(self.vars["cot_domicilio_cliente"].get()), "observaciones": self.vars["cot_obs"].get().strip(),
        }
        before = self.store.quote_snapshot(num)
        self.store.save_quote(quote_data, self.quote_lines)
        after = self.store.quote_snapshot(num)
        self.store.log_snapshot_changes("Cotización", num, before, after, "EDITAR" if before else "CREAR")
        head, det = self.store.get_quote(num)
        q = head.iloc[0]
        def qtext(field):
            value = q.get(field, "")
            return "" if pd.isna(value) else str(value).strip()
        self.clear_sales_form(); self.show_page("ventas"); self.update_idletasks()
        transfer = {
            "venta_cliente": qtext("cliente"), "venta_asesor": qtext("asesor"), "venta_direccion": qtext("direccion"),
            "venta_ciudad": qtext("ciudad"), "venta_telefono": qtext("telefono"), "venta_barrio": qtext("barrio"),
            "venta_local_edificio": qtext("local_edificio"), "venta_datos_entrega": qtext("datos_entrega"),
            "venta_obs": qtext("observaciones"), "venta_cotizacion_origen": num,
            "venta_domicilio_empresa": str(float(q.get("domicilio_empresa",0) or 0)),
            "venta_domicilio_cliente": str(float(q.get("domicilio_cliente",q.get("domicilio",0)) or 0)),
        }
        for key, value in transfer.items():
            if key in self.vars: self.vars[key].set(value)
        self.product_lines=[]
        for _, r in det.iterrows():
            prod_match = self.store.table("SELECT codigo, costo, comision_unitaria_sugerida FROM productos WHERE nombre=? LIMIT 1", (r["producto"],))
            code = str(prod_match.iloc[0]["codigo"] or "") if not prod_match.empty else ""
            cost = float(r.get("costo_unitario", 0) or 0)
            if cost <= 0 and not prod_match.empty: cost = float(prod_match.iloc[0].get("costo",0) or 0)
            commission_unit = float(r.get("comision_unitaria",0) or 0)
            if commission_unit <= 0 and not prod_match.empty: commission_unit = float(prod_match.iloc[0].get("comision_unitaria_sugerida",0) or 0)
            qty=float(r["cantidad"]); sale_price=float(r.get("precio_venta",0) or r.get("precio_unitario",0) or 0)
            subtotal=float(r["subtotal"]); iva=float(r["iva"])
            self.product_lines.append({
                "codigo":code, "producto":r["producto"], "cantidad_kls":qty,
                "valor_x_kl":sale_price, "valor_total":subtotal, "costo_unitario":cost,
                "comision_unitaria":commission_unit, "comision":qty*commission_unit,
                "iva_19":iva, "retenciones":0, "chile_fresco":0, "domicilio":0,
                "total_linea":subtotal+iva,
            })
        self.refresh_product_lines()
        self.set_sales_status(f"Cotización {num} cargada. Precio de venta, costo y comisión fueron transferidos sin duplicar valores.", "documento")
        messagebox.showinfo("Cotización convertida", f"Cotización {num} cargada en Ventas. Complete la cuenta de cobro y el pago.", parent=self)
    except Exception as exc:
        messagebox.showerror("Convertir cotización", str(exc), parent=self)
SalesFormApp.convert_quote_to_sale = _v98_convert_quote_to_sale


# Al cargar una venta existente, incorporar el costo guardado.
_v98_original_load_sale_for_edit = SalesFormApp.load_sale_for_edit
def _v98_load_sale_for_edit(self, factura: str):
    _v98_original_load_sale_for_edit(self, factura)
    try:
        details = self.store.table("SELECT * FROM ventas_detalle WHERE cuenta_cobro=? ORDER BY item", (factura,))
        if len(details) == len(self.product_lines):
            for i, (_, r) in enumerate(details.iterrows()):
                self.product_lines[i]["costo_unitario"] = float(r.get("costo_unitario",0) or 0)
                self.product_lines[i]["total_linea"] = self.product_lines[i]["valor_total"] + self.product_lines[i]["iva_19"] + self.product_lines[i]["retenciones"] + self.product_lines[i].get("chile_fresco",0)
            self.refresh_product_lines()
    except Exception:
        pass
SalesFormApp.load_sale_for_edit = _v98_load_sale_for_edit


# Excel diario: reforzar campos de costo/precio en VENTAS y detalle después de la exportación base.
_v98_previous_export_daily_snapshot = SalesStore.export_daily_snapshot
def _v98_export_daily_snapshot(self, output_path: Path | None = None) -> Path:
    saved = Path(_v98_previous_export_daily_snapshot(self, output_path or _daily_snapshot_target()))
    # Asegurar que el archivo guardado tenga las columnas explícitas en la hoja VENTAS.
    try:
        ventas = self.table("SELECT * FROM ventas ORDER BY fecha, cuenta_cobro")
        det = self.table("SELECT * FROM ventas_detalle ORDER BY cuenta_cobro, item")
        if not det.empty:
            # Ventas_detalle ya lleva costo_unitario por SELECT *; añadir alias claro de precio.
            det_export = det.copy()
            det_export["precio_venta"] = det_export.get("valor_x_kl", 0)
            det_export["total_linea"] = det_export.get("valor_total",0) + det_export.get("iva_19",0) + det_export.get("retenciones",0) + det_export.get("chile_fresco",0)
            # No reemplazar las otras hojas: solo refrescar detalle con campos explícitos.
            with pd.ExcelWriter(saved, engine="openpyxl", mode="a", if_sheet_exists="replace") as writer:
                det_export.rename(columns=str.upper).to_excel(writer, sheet_name="Ventas_detalle", index=False)
    except Exception:
        pass
    return saved
SalesStore.export_daily_snapshot = _v98_export_daily_snapshot


# Evitar que un diálogo nativo deje la aplicación minimizada u oculta en Windows.
_v98_original_asksaveasfilename = filedialog.asksaveasfilename
def _v98_asksaveasfilename(*args, **kwargs):
    parent = kwargs.get("parent")
    result = _v98_original_asksaveasfilename(*args, **kwargs)
    try:
        w = parent
        visited=set()
        while w is not None and id(w) not in visited:
            visited.add(id(w))
            try:
                w.deiconify(); w.lift(); w.focus_force()
                w.attributes("-topmost", True); w.after(120, lambda ww=w: ww.attributes("-topmost", False))
            except Exception:
                pass
            w = getattr(w, "master", None)
    except Exception:
        pass
    return result
filedialog.asksaveasfilename = _v98_asksaveasfilename


# Crear/actualizar una copia diaria incluso al abrir la aplicación, para que la ruta
# quede visible desde el comienzo y no dependa de que el primer cambio dispare el backup.
_v98_original_app_init = SalesFormApp.__init__
def _v98_app_init(self, *args, **kwargs):
    _v98_original_app_init(self, *args, **kwargs)
    try:
        path = self.store.export_daily_snapshot()
        self.last_daily_snapshot_path = str(path)
    except Exception as exc:
        self.last_daily_snapshot_path = ""
        # La variable `exc` deja de existir al terminar el except.
        # Capturamos el texto antes de programar el callback de Tkinter.
        _daily_error_text = str(exc)
        _daily_expected_path = str(_daily_snapshot_target())
        try:
            self.after(
                300,
                lambda err=_daily_error_text, expected=_daily_expected_path: messagebox.showwarning(
                    "Copia diaria",
                    "La aplicación abrió, pero no fue posible crear la copia diaria inicial.\n\n"
                    f"Ruta esperada: {expected}\n\nDetalle: {err}",
                    parent=self,
                ),
            )
        except Exception:
            pass
SalesFormApp.__init__ = _v98_app_init

# ==================== FIN V9.8 ====================


# ==================== V10.1.8 PRODUCTO MAESTRO / UNIDAD / COSTO ====================
# Objetivos:
# - La unidad y el costo provienen del maestro de productos cuando existan.
# - Si un producto se crea/edita en la app, su unidad/costo quedan en SQLite y en el Excel diario.
# - Cotización y venta muestran la unidad y conservan costo/comisión internos.
# - Al seleccionar otro producto, SIEMPRE se refrescan precio, costo, comisión y unidad.
# - La unidad se guarda por línea para no depender de cambios futuros del maestro.

_v985_previous_load_master_records = load_master_records
def load_master_records(source_files: list[Path] | None = None) -> tuple[list[dict], list[dict]]:
    clientes, productos = _v985_previous_load_master_records(source_files)
    product_map = {str(p.get("nombre", "") or "").strip().upper(): p for p in productos if p.get("nombre")}
    files = source_files if source_files is not None else read_master_sources()

    for source in files or []:
        path = Path(source)
        if not path.exists():
            continue
        try:
            book = pd.ExcelFile(path)
            sheet = _v95_find_sheet(book, "Productos_Maestro", "MAESTRO_PRODUCTOS", "PRODUCTOS")
            if not sheet:
                book.close()
                continue
            df = pd.read_excel(book, sheet_name=sheet, nrows=20000)
            cmap = normalized_columns(df)
            def c(*opts): return first_column(cmap, *opts)
            name_col = c("PRODUCTO", "NOMBRE")
            unit_col = c("UNIDAD", "UNIDAD_MEDIDA", "UNIDAD MEDIDA", "UOM")
            cost_col = c(
                "COSTO_UNITARIO", "COSTO UNITARIO", "COSTO",
                "COSTO_COMPRA", "COSTO COMPRA", "ULTIMO_COSTO", "ÚLTIMO COSTO"
            )
            if name_col:
                for _, row in df.iterrows():
                    name = _v95_clean_cell(row.get(name_col))
                    if not name:
                        continue
                    p = product_map.get(name.strip().upper())
                    if p is None:
                        continue
                    unit = _v95_clean_cell(row.get(unit_col)) if unit_col else ""
                    if unit:
                        p["unidad"] = unit.upper()
                    elif not str(p.get("unidad", "") or "").strip():
                        p["unidad"] = "KLS"
                    if cost_col:
                        p["costo"] = money(row.get(cost_col, 0))
            book.close()
        except Exception:
            try:
                book.close()
            except Exception:
                pass

    for p in productos:
        if not str(p.get("unidad", "") or "").strip():
            p["unidad"] = "KLS"
        p["unidad"] = str(p["unidad"]).strip().upper()
        p["costo"] = float(p.get("costo", 0) or 0)
    return clientes, productos


# Esquema: conservar la unidad usada realmente en cada línea.
_v985_previous_init_schema = SalesStore.init_schema
def _v985_init_schema(self):
    _v985_previous_init_schema(self)
    self.ensure_column("ventas_detalle", "unidad", "TEXT NOT NULL DEFAULT 'KLS'")
    self.ensure_column("cotizaciones_detalle", "unidad", "TEXT NOT NULL DEFAULT 'KLS'")
    try:
        self.conn.execute("""
            UPDATE ventas_detalle
               SET unidad = COALESCE(
                   NULLIF((SELECT p.unidad FROM productos p WHERE p.nombre=ventas_detalle.producto LIMIT 1),''),
                   'KLS'
               )
             WHERE unidad IS NULL OR TRIM(unidad)=''
        """)
        self.conn.execute("""
            UPDATE cotizaciones_detalle
               SET unidad = COALESCE(
                   NULLIF((SELECT p.unidad FROM productos p WHERE p.nombre=cotizaciones_detalle.producto LIMIT 1),''),
                   'KLS'
               )
             WHERE unidad IS NULL OR TRIM(unidad)=''
        """)
        self.conn.commit()
    except Exception:
        pass
SalesStore.init_schema = _v985_init_schema


def _v985_add_detail(self, data: dict):
    current = self.conn.execute(
        "SELECT COALESCE(MAX(item), 0) + 1 FROM ventas_detalle WHERE cuenta_cobro = ?",
        (data["cuenta_cobro"],),
    ).fetchone()[0]
    self.conn.execute(
        """
        INSERT INTO ventas_detalle (
            cuenta_cobro, item, producto, unidad, cantidad_kls, valor_x_kl,
            valor_total, costo_unitario, comision_unitaria, comision, iva_19,
            retenciones, chile_fresco, domicilio
        ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        """,
        (
            data["cuenta_cobro"], current, data["producto"],
            str(data.get("unidad", "KLS") or "KLS").strip().upper(),
            data["cantidad_kls"], data["valor_x_kl"], data["valor_total"],
            data.get("costo_unitario", 0), data.get("comision_unitaria", 0),
            data.get("comision", 0), data.get("iva_19", 0),
            data.get("retenciones", 0), data.get("chile_fresco", 0),
            data.get("domicilio", 0),
        ),
    )
    self.conn.commit()
SalesStore.add_detail = _v985_add_detail


def _v985_save_quote(self, data: dict, details: list[dict]):
    self.ensure_cliente(data["cliente"])
    self.conn.execute(
        """
        INSERT INTO cotizaciones (
            numero_cotizacion, fecha, valida_hasta, cliente, asesor, direccion,
            ciudad, telefono, barrio, local_edificio, datos_entrega, estado,
            forma_pago, domicilio, domicilio_empresa, domicilio_cliente, observaciones,
            cuenta_cobro_convertida, fecha_conversion
        ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        ON CONFLICT(numero_cotizacion) DO UPDATE SET
            fecha=excluded.fecha, valida_hasta=excluded.valida_hasta,
            cliente=excluded.cliente, asesor=excluded.asesor,
            direccion=excluded.direccion, ciudad=excluded.ciudad,
            telefono=excluded.telefono, barrio=excluded.barrio,
            local_edificio=excluded.local_edificio, datos_entrega=excluded.datos_entrega,
            estado=excluded.estado, forma_pago=excluded.forma_pago,
            domicilio=excluded.domicilio, domicilio_empresa=excluded.domicilio_empresa,
            domicilio_cliente=excluded.domicilio_cliente, observaciones=excluded.observaciones
        """,
        (
            data["numero_cotizacion"], data["fecha"], data.get("valida_hasta", ""),
            data["cliente"], data.get("asesor", ""), data.get("direccion", ""),
            data.get("ciudad", ""), data.get("telefono", ""), data.get("barrio", ""),
            data.get("local_edificio", ""), data.get("datos_entrega", ""),
            data.get("estado", "BORRADOR"), data.get("forma_pago", ""),
            float(data.get("domicilio_cliente", data.get("domicilio", 0)) or 0),
            float(data.get("domicilio_empresa", 0) or 0),
            float(data.get("domicilio_cliente", data.get("domicilio", 0)) or 0),
            data.get("observaciones", ""), data.get("cuenta_cobro_convertida", ""),
            data.get("fecha_conversion", ""),
        ),
    )
    self.conn.execute("DELETE FROM cotizaciones_detalle WHERE numero_cotizacion=?", (data["numero_cotizacion"],))
    for idx, d in enumerate(details, 1):
        pv = float(d.get("precio_venta", d.get("precio_unitario", 0)) or 0)
        self.conn.execute(
            """
            INSERT INTO cotizaciones_detalle (
                numero_cotizacion, item, producto, unidad, cantidad, precio_unitario,
                costo_unitario, comision_unitaria, precio_venta,
                descuento, subtotal, iva, total
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                data["numero_cotizacion"], idx, d["producto"],
                str(d.get("unidad", "KLS") or "KLS").strip().upper(),
                float(d["cantidad"]), pv,
                float(d.get("costo_unitario", 0) or 0),
                float(d.get("comision_unitaria", 0) or 0), pv,
                float(d.get("descuento", 0) or 0), float(d["subtotal"]),
                float(d.get("iva", 0) or 0), float(d["total"]),
            ),
        )
    self.conn.commit()
SalesStore.save_quote = _v985_save_quote


