def _v985_load_quote_by_number(self, num: str):
    head, det = self.store.get_quote(num)
    if head.empty:
        return
    q = head.iloc[0]
    mapping={
        "cot_numero":"numero_cotizacion","cot_fecha":"fecha","cot_valida":"valida_hasta",
        "cot_cliente":"cliente","cot_asesor":"asesor","cot_estado":"estado","cot_direccion":"direccion",
        "cot_ciudad":"ciudad","cot_telefono":"telefono","cot_barrio":"barrio",
        "cot_local_edificio":"local_edificio","cot_datos_entrega":"datos_entrega",
        "cot_forma_pago":"forma_pago","cot_domicilio_empresa":"domicilio_empresa",
        "cot_domicilio_cliente":"domicilio_cliente","cot_obs":"observaciones"
    }
    for key,col in mapping.items():
        if key in self.vars:
            self.vars[key].set("" if col not in q.index or pd.isna(q.get(col,"")) else str(q.get(col,"")))
    self.quote_lines=[]
    for _, r in det.iterrows():
        pv=float(r.get("precio_venta",0) or r.get("precio_unitario",0) or 0)
        self.quote_lines.append({
            "producto":str(r["producto"]), "unidad":str(r.get("unidad","KLS") or "KLS"),
            "cantidad":float(r["cantidad"]), "precio_unitario":pv, "precio_venta":pv,
            "costo_unitario":float(r.get("costo_unitario",0) or 0),
            "comision_unitaria":float(r.get("comision_unitaria",0) or 0),
            "descuento":float(r["descuento"]), "subtotal":float(r["subtotal"]),
            "iva":float(r["iva"]), "total":float(r["total"]),
        })
    self.refresh_quote_lines()
