def _v985_add_product_line(self):
    try:
        product_row=self.find_product_row(self.require("det_producto","Producto"))
        if product_row.empty:
            raise ValueError("Seleccione un producto válido desde la búsqueda por código o nombre.")
        p=product_row.iloc[0]
        cantidad=money(self.vars["det_cantidad"].get())
        precio=money(self.vars["det_valor_kl"].get())
        if cantidad <= 0:
            raise ValueError("La cantidad debe ser mayor a cero.")
        if precio <= 0:
            raise ValueError("El precio de venta debe ser mayor a cero.")
        valor_total=cantidad*precio
        self.vars["det_valor_total"].set(f"{valor_total:.0f}")
        iva=valor_total*0.19 if self.vars["det_auto_iva"].get().strip().upper()=="SI" else money(self.vars["det_iva"].get())
        self.vars["det_iva"].set(f"{iva:.0f}")
        unidad=str(self.vars.get("det_unidad",tk.StringVar(value="")).get() or p.get("unidad","KLS") or "KLS").strip().upper()
        com_u=money(self.vars["det_comision_unitaria"].get())
        line={
            "codigo":str(p.get("codigo","") or ""),
            "producto":str(p["nombre"]),
            "unidad":unidad,
            "cantidad_kls":cantidad,
            "valor_x_kl":precio,
            "valor_total":valor_total,
            "costo_unitario":money(self.vars.get("det_costo_unitario",tk.StringVar(value="0")).get()),
            "comision_unitaria":com_u,
            "comision":cantidad*com_u,
            "iva_19":iva,
            "retenciones":money(self.vars["det_retenciones"].get()),
            "chile_fresco":0,
            "domicilio":0,
        }
        line["total_linea"]=line["valor_total"]+line["iva_19"]+line["retenciones"]
        self.product_lines.append(line)
        self.refresh_product_lines()
        self.set_sales_status(f"Producto agregado: {line['producto']} ({unidad}) por {line['total_linea']:,.0f}.","productos")
    except Exception as exc:
        messagebox.showerror("Error",str(exc),parent=self)
SalesFormApp.add_product_line = _v985_add_product_line


