# Exportación comercial limpia.
_v986_previous_export_excel = SalesStore.export_excel
def _v986_export_excel(self, output_path: Path, append_existing: bool = False):
    # Primero generar todas las hojas auxiliares existentes (abonos, clientes, productos, etc.).
    result = _v986_previous_export_excel(self, output_path, append_existing)

    ventas = self.table("SELECT * FROM ventas ORDER BY fecha, cuenta_cobro")
    det = self.table("SELECT * FROM ventas_detalle ORDER BY cuenta_cobro, item")
    productos = self.table("SELECT * FROM productos ORDER BY nombre")
    resumen = self.sales_summary()

    if det.empty:
        detalle_out = pd.DataFrame(columns=[
            "ID","CUENTA_COBRO","ITEM","CODIGO_PRODUCTO","PRODUCTO","UNIDAD",
            "Cantidad","Costo por unidad","Costo total","Precio_venta_unidad","Venta total",
            "COMISION_UNITARIA","COMISION","IVA_19","RETENCIONES","TOTAL_LINEA","TOTAL_FACTURA"
        ])
    else:
        d = det.copy()
        if "codigo_producto" not in d.columns:
            d["codigo_producto"] = ""
        if "unidad" not in d.columns:
            d["unidad"] = "KLS"
        if "costo_unitario" not in d.columns:
            d["costo_unitario"] = 0.0

        # Completar código/unidad/costo desde el maestro solo cuando el histórico esté vacío.
        if not productos.empty:
            pmap = productos[["codigo","nombre","unidad","costo"]].copy()
            pmap = pmap.rename(columns={
                "codigo":"_codigo_maestro","nombre":"producto","unidad":"_unidad_maestro","costo":"_costo_maestro"
            })
            d = d.merge(pmap, on="producto", how="left")
            d["codigo_producto"] = d["codigo_producto"].fillna("").astype(str)
            d.loc[d["codigo_producto"].str.strip()=="","codigo_producto"] = d["_codigo_maestro"].fillna("")
            d["unidad"] = d["unidad"].fillna("")
            d.loc[d["unidad"].astype(str).str.strip()=="","unidad"] = d["_unidad_maestro"].fillna("KLS")
            d["costo_unitario"] = pd.to_numeric(d["costo_unitario"], errors="coerce").fillna(0)
            d.loc[d["costo_unitario"]==0,"costo_unitario"] = pd.to_numeric(
                d["_costo_maestro"], errors="coerce"
            ).fillna(0)

        d["cantidad_export"] = pd.to_numeric(d["cantidad_kls"], errors="coerce").fillna(0)
        d["costo_unidad_export"] = pd.to_numeric(d["costo_unitario"], errors="coerce").fillna(0)
        d["costo_total_export"] = d["cantidad_export"] * d["costo_unidad_export"]
        d["precio_venta_unidad_export"] = pd.to_numeric(d["valor_x_kl"], errors="coerce").fillna(0)
        d["venta_total_export"] = d["cantidad_export"] * d["precio_venta_unidad_export"]
        d["total_linea_export"] = (
            d["venta_total_export"]
            + pd.to_numeric(d.get("iva_19",0), errors="coerce").fillna(0)
            + pd.to_numeric(d.get("retenciones",0), errors="coerce").fillna(0)
        )

        detalle_out = pd.DataFrame({
            "ID": d.get("id",""),
            "CUENTA_COBRO": d["cuenta_cobro"],
            "ITEM": d["item"],
            "CODIGO_PRODUCTO": d["codigo_producto"],
            "PRODUCTO": d["producto"],
            "UNIDAD": d["unidad"],
            "Cantidad": d["cantidad_export"],
            "Costo por unidad": d["costo_unidad_export"],
            "Costo total": d["costo_total_export"],
            "Precio_venta_unidad": d["precio_venta_unidad_export"],
            "Venta total": d["venta_total_export"],
            "COMISION_UNITARIA": d.get("comision_unitaria",0),
            "COMISION": d.get("comision",0),
            "IVA_19": d.get("iva_19",0),
            "RETENCIONES": d.get("retenciones",0),
            "TOTAL_LINEA": d["total_linea_export"],
            # Debe ser numérica desde el inicio. Usar NaN permite dejar vacías
            # las líneas 2..N de una misma factura sin forzar dtype string.
            "TOTAL_FACTURA": pd.Series(float("nan"), index=d.index, dtype="float64"),
        })

        # TOTAL_FACTURA aparece una sola vez por cuenta para poder sumar la
        # columna directamente sin duplicar facturas con varios productos.
        if not resumen.empty and "cuenta_cobro" in resumen.columns and "total_factura" in resumen.columns:
            total_map = {
                str(r["cuenta_cobro"]): float(r["total_factura"] or 0)
                for _, r in resumen.iterrows()
            }
            first_mask = ~detalle_out["CUENTA_COBRO"].astype(str).duplicated()
            detalle_out.loc[first_mask, "TOTAL_FACTURA"] = (
                detalle_out.loc[first_mask, "CUENTA_COBRO"]
                .astype(str)
                .map(total_map)
                .astype("float64")
            )

    # Cabecera: una fila por cuenta/factura y domicilios contiguos.
    if ventas.empty:
        cab_out = pd.DataFrame(columns=[
            "CUENTA_COBRO","FECHA","CLIENTE","ESTADO_VENTA","FECHA_VENCIMIENTO","ASESOR",
            "CTA_BANCARIA","DIRECCION","CIUDAD_ENTREGA","BARRIO_ENTREGA","LOCAL_EDIFICIO",
            "DATOS_ENTREGA","TELEFONO_CLIENTE","ESTADO_PAGO","FORMA_PAGO",
            "DOMICILIO_EMPRESA","DOMICILIO_CLIENTE","TOTAL_FACTURA","TOTAL_ABONOS",
            "SALDO_PENDIENTE","TOTAL_COMISION","RECIBIDO_POR","OBSERVACION_LOGISTICA",
            "FACTURA_ELECTRONICA","FECHA_FACTURA_ELECTRONICA","COTIZACION_ORIGEN",
            "FUENTE_ORIGEN","ULTIMA_MODIFICACION","MODIFICADO_MANUALMENTE"
        ])
    else:
        cab = ventas.copy()
        if not resumen.empty:
            merge_cols = [c for c in ["cuenta_cobro","total_factura","total_abonos"] if c in resumen.columns]
            if len(merge_cols) >= 2:
                cab = cab.merge(resumen[merge_cols], on="cuenta_cobro", how="left")
        if "total_factura" not in cab.columns: cab["total_factura"] = 0.0
        if "total_abonos" not in cab.columns: cab["total_abonos"] = 0.0
        cab["saldo_pendiente"] = pd.to_numeric(cab["total_factura"], errors="coerce").fillna(0) - pd.to_numeric(cab["total_abonos"], errors="coerce").fillna(0)

        if det.empty:
            com_by_inv = pd.DataFrame(columns=["cuenta_cobro","total_comision"])
        else:
            com_by_inv = det.groupby("cuenta_cobro", as_index=False)["comision"].sum().rename(columns={"comision":"total_comision"})
        cab = cab.merge(com_by_inv, on="cuenta_cobro", how="left")
        cab["total_comision"] = pd.to_numeric(cab.get("total_comision",0), errors="coerce").fillna(0)

        cab_cols = [
            "cuenta_cobro","fecha","cliente","estado_venta","fecha_vencimiento","asesor",
            "cta_bancaria","direccion","ciudad_entrega","barrio_entrega","local_edificio",
            "datos_entrega","telefono_cliente","estado_pago","forma_pago",
            "domicilio_empresa","domicilio_cliente",
            "total_factura","total_abonos","saldo_pendiente","total_comision",
            "recibido_por","observacion_logistica","factura_electronica",
            "fecha_factura_electronica","cotizacion_origen","fuente_origen",
            "ultima_modificacion","modificado_manualmente"
        ]
        cab_cols = [c for c in cab_cols if c in cab.columns]
        cab_out = cab[cab_cols].copy()
        cab_out.columns = [str(c).upper() for c in cab_out.columns]

    # Hoja VENTAS: una fila por producto con costo y venta separados.
    flat_rows = []
    if not detalle_out.empty:
        sales_index = {str(r["cuenta_cobro"]): r for _, r in ventas.iterrows()}
        seen_accounts_for_total = set()
        for i, row in detalle_out.iterrows():
            cuenta = str(row["CUENTA_COBRO"])
            sale = sales_index.get(cuenta)
            if sale is None:
                continue
            total_factura_once = row.get("TOTAL_FACTURA", None) if cuenta not in seen_accounts_for_total else None
            seen_accounts_for_total.add(cuenta)
            flat_rows.append({
                "FECHA": sale.get("fecha",""),
                "CLIENTE": sale.get("cliente",""),
                "CUENTA DE COBRO": cuenta,
                "CODIGO_PRODUCTO": row["CODIGO_PRODUCTO"],
                "PRODUCTO": row["PRODUCTO"],
                "UNIDAD": row["UNIDAD"],
                "Cantidad": row["Cantidad"],
                "Costo por unidad": row["Costo por unidad"],
                "Costo total": row["Costo total"],
                "Precio_venta_unidad": row["Precio_venta_unidad"],
                "Venta total": row["Venta total"],
                "COMISION UNITARIA": row["COMISION_UNITARIA"],
                "COMISION": row["COMISION"],
                "IVA 19%": row["IVA_19"],
                "RETENCIONES": row["RETENCIONES"],
                "DOMICILIO EMPRESA": _v986_num(sale.get("domicilio_empresa",0)),
                "DOMICILIO CLIENTE": _v986_num(sale.get("domicilio_cliente",0)),
                "DIRECCION": sale.get("direccion",""),
                "CIUDAD": sale.get("ciudad_entrega",""),
                "BARRIO": sale.get("barrio_entrega",""),
                "LOCAL/EDIFICIO": sale.get("local_edificio",""),
                "DATOS ENTREGA": sale.get("datos_entrega",""),
                "TELEFONO CLIENTE": sale.get("telefono_cliente",""),
                "ASESOR": sale.get("asesor",""),
                "CTA BANCARIA": sale.get("cta_bancaria",""),
                "FORMA DE PAGO": sale.get("forma_pago",""),
                "ESTADO PAGO": sale.get("estado_pago",""),
                "ESTADO": sale.get("estado_venta",""),
                "TOTAL LINEA": row["TOTAL_LINEA"],
                "TOTAL_FACTURA": total_factura_once,
            })
    ventas_columns = [
        "FECHA","CLIENTE","CUENTA DE COBRO","CODIGO_PRODUCTO","PRODUCTO","UNIDAD",
        "Cantidad","Costo por unidad","Costo total","Precio_venta_unidad","Venta total",
        "COMISION UNITARIA","COMISION","IVA 19%","RETENCIONES",
        "DOMICILIO EMPRESA","DOMICILIO CLIENTE","DIRECCION","CIUDAD","BARRIO",
        "LOCAL/EDIFICIO","DATOS ENTREGA","TELEFONO CLIENTE","ASESOR","CTA BANCARIA",
        "FORMA DE PAGO","ESTADO PAGO","ESTADO","TOTAL LINEA","TOTAL_FACTURA"
    ]
    ventas_out = pd.DataFrame(flat_rows, columns=ventas_columns)

    # Reemplazar solamente las tres hojas comerciales; las demás permanecen como las generó la exportación base.
    with pd.ExcelWriter(output_path, engine="openpyxl", mode="a", if_sheet_exists="replace") as writer:
        ventas_out.to_excel(writer, sheet_name="VENTAS", index=False)
        cab_out.to_excel(writer, sheet_name="Ventas_cabecera", index=False)
        detalle_out.to_excel(writer, sheet_name="Ventas_detalle", index=False)

    return result


SalesStore.export_excel = _v986_export_excel

# ==================== FIN V10.1.8 ====================



# ==================== V10.1.8 MIGRACIÓN HISTÓRICA + FORMATO EXCEL ====================
# Migra una sola vez las líneas registradas con la semántica anterior:
#   valor_x_kl = costo/base
#   comisión/u = margen interno
#   total cobrado = valor_total + comisión
# a la semántica actual:
#   costo_unitario = costo/base
#   valor_x_kl = precio de venta final
#   valor_total = cantidad * precio de venta
# Esto conserva el total histórico de cada factura.

_V987_MIGRATION_KEY = "V9_8_7_PRECIO_COSTO_HISTORICO_20261001"


def _v987_migrate_legacy_sales(self):
    self.conn.execute("""
        CREATE TABLE IF NOT EXISTS migraciones_app (
            clave TEXT PRIMARY KEY,
            fecha TEXT NOT NULL,
            detalle TEXT
        )
    """)
    done = self.conn.execute(
        "SELECT 1 FROM migraciones_app WHERE clave=?",
        (_V987_MIGRATION_KEY,),
    ).fetchone()
    if done:
        return

    # Solo migrar líneas que aún no tienen costo_unitario informado.
    # En la base de pruebas de hoy esas filas corresponden a la semántica anterior.
    rows = self.conn.execute("""
        SELECT id, cantidad_kls, valor_x_kl, valor_total,
               COALESCE(costo_unitario,0) AS costo_unitario,
               COALESCE(comision_unitaria,0) AS comision_unitaria,
               COALESCE(comision,0) AS comision
        FROM ventas_detalle
        ORDER BY id
    """).fetchall()

    migrated = 0
    for row in rows:
        qty = float(row["cantidad_kls"] or 0)
        old_base = float(row["valor_x_kl"] or 0)
        old_total = float(row["valor_total"] or 0)
        current_cost = float(row["costo_unitario"] or 0)
        commission_u = float(row["comision_unitaria"] or 0)
        commission_total = float(row["comision"] or 0)

        if current_cost != 0:
            continue
        if qty <= 0:
            continue

        # Evidencia de semántica antigua: comisión informada y base + comisión
        # coincide con el total comercial que venía manejando la aplicación.
        # También permite comisión cero, en cuyo caso precio y costo coinciden.
        new_cost = old_base
        new_sale_price = old_base + commission_u
        new_sale_total = old_total + commission_total

        self.conn.execute("""
            UPDATE ventas_detalle
               SET costo_unitario=?,
                   valor_x_kl=?,
                   valor_total=?
             WHERE id=?
        """, (new_cost, new_sale_price, new_sale_total, row["id"]))
        migrated += 1

    self.conn.execute(
        "INSERT INTO migraciones_app (clave, fecha, detalle) VALUES (?, ?, ?)",
        (
            _V987_MIGRATION_KEY,
            datetime.now().isoformat(timespec="seconds"),
            f"Se migraron {migrated} líneas históricas de costo+comisión a costo/precio_venta.",
        ),
    )
    self.conn.commit()


_v987_previous_init_schema = SalesStore.init_schema
def _v987_init_schema(self):
    _v987_previous_init_schema(self)
    _v987_migrate_legacy_sales(self)
SalesStore.init_schema = _v987_init_schema


def _v987_style_excel_file(path):
    """Aplica presentación profesional al Excel exportado/copia diaria."""
    from openpyxl import load_workbook
    from openpyxl.styles import PatternFill, Font, Alignment, Border, Side
    from openpyxl.utils import get_column_letter

    path = Path(path)
    if not path.exists() or path.suffix.lower() != ".xlsx":
        return path

    wb = load_workbook(path)

    dark_green = "155E42"
    light_green = "E8F3EE"
    border_color = "D1D5DB"
    thin = Side(style="thin", color=border_color)
    border = Border(left=thin, right=thin, top=thin, bottom=thin)

    currency_names = {
        "COSTO POR UNIDAD","COSTO TOTAL","PRECIO_VENTA_UNIDAD","PRECIO VENTA",
        "VENTA TOTAL","COMISION UNITARIA","COMISION_UNITARIA","COMISION",
        "IVA 19%","IVA_19","RETENCIONES","TOTAL LINEA","TOTAL_LINEA",
        "DOMICILIO EMPRESA","DOMICILIO_EMPRESA","DOMICILIO CLIENTE","DOMICILIO_CLIENTE",
        "TOTAL_FACTURA","TOTAL FACTURA","TOTAL_ABONOS","SALDO_PENDIENTE","TOTAL_COMISION",
        "VALOR_ULTIMO_ABONO","VALOR_ABONO","VALOR_APLICADO","PRECIO_VENTA",
        "COMISION_UNITARIA_SUGERIDA","COSTO","PRECIO_REFERENCIA","ULTIMO_PRECIO",
        "STOCK_ACTUAL","STOCK_MINIMO"
    }
    quantity_names = {"CANTIDAD","CANT."}
    date_names = {
        "FECHA","FECHA_VENCIMIENTO","FECHA_ULTIMO_ABONO","FECHA_FACTURA_ELECTRONICA",
        "FECHA_ABONO","FECHA_APLICACION"
    }

    specific_widths = {
        "FECHA": 13, "CLIENTE": 30, "CUENTA DE COBRO": 16, "CUENTA_COBRO": 16,
        "CODIGO_PRODUCTO": 16, "PRODUCTO": 28, "UNIDAD": 12, "CANTIDAD": 12,
        "COSTO POR UNIDAD": 18, "COSTO TOTAL": 16, "PRECIO_VENTA_UNIDAD": 20,
        "VENTA TOTAL": 16, "TOTAL_FACTURA": 18, "TOTAL FACTURA": 18,
        "COMISION UNITARIA": 18, "COMISION_UNITARIA": 18,
        "COMISION": 15, "DOMICILIO EMPRESA": 19, "DOMICILIO_EMPRESA": 19,
        "DOMICILIO CLIENTE": 19, "DOMICILIO_CLIENTE": 19,
        "DIRECCION": 28, "CIUDAD": 22, "CIUDAD_ENTREGA": 22,
        "BARRIO": 24, "BARRIO_ENTREGA": 24, "LOCAL/EDIFICIO": 20,
        "LOCAL_EDIFICIO": 20, "DATOS ENTREGA": 26, "DATOS_ENTREGA": 26,
        "TELEFONO CLIENTE": 20, "TELEFONO_CLIENTE": 20, "ASESOR": 18,
        "FORMA DE PAGO": 18, "FORMA_PAGO": 18, "ESTADO PAGO": 16,
        "ESTADO_PAGO": 16, "HISTORIAL ABONOS": 45, "HISTORIAL_ABONOS": 45,
        "FUENTE_ORIGEN": 35, "ULTIMA_MODIFICACION": 22, "OBSERVACIONES": 30,
        "OBSERVACION_LOGISTICA": 30, "NOMBRE": 30
    }

    for ws in wb.worksheets:
        if ws.max_row < 1 or ws.max_column < 1:
            continue

        # Header
        for cell in ws[1]:
            cell.fill = PatternFill("solid", fgColor=dark_green)
            cell.font = Font(color="FFFFFF", bold=True)
            cell.alignment = Alignment(horizontal="center", vertical="center", wrap_text=True)
            cell.border = border
        ws.row_dimensions[1].height = 28
        ws.freeze_panes = "A2"
        ws.auto_filter.ref = ws.dimensions

        # Data styling
        headers = {}
        for col_idx, cell in enumerate(ws[1], start=1):
            header = str(cell.value or "").strip()
            headers[col_idx] = header
            normalized = header.upper()

            if normalized in specific_widths:
                ws.column_dimensions[get_column_letter(col_idx)].width = specific_widths[normalized]
            else:
                # Ancho razonable sin exagerar por textos largos.
                max_len = len(header)
                for row_idx in range(2, min(ws.max_row, 60) + 1):
                    value = ws.cell(row_idx, col_idx).value
                    if value is not None:
                        max_len = max(max_len, min(len(str(value)), 35))
                ws.column_dimensions[get_column_letter(col_idx)].width = min(max(max_len + 2, 10), 35)

            for row_idx in range(2, ws.max_row + 1):
                c = ws.cell(row_idx, col_idx)
                c.border = border
                c.alignment = Alignment(vertical="center", wrap_text=normalized in {
                    "HISTORIAL ABONOS","HISTORIAL_ABONOS","FUENTE_ORIGEN",
                    "OBSERVACIONES","OBSERVACION_LOGISTICA","DATOS ENTREGA","DATOS_ENTREGA"
                })

                if normalized in currency_names:
                    c.number_format = '$ #,##0'
                elif normalized in quantity_names:
                    c.number_format = '0.00'
                elif normalized in date_names:
                    c.number_format = 'yyyy-mm-dd'

                # Suave alternancia visual.
                if row_idx % 2 == 0:
                    c.fill = PatternFill("solid", fgColor=light_green)

        # Mantener códigos y cuentas de cobro como texto, conservando ceros a la izquierda.
        for col_idx, header in headers.items():
            if str(header).upper() in {"CUENTA_COBRO","CUENTA DE COBRO","CODIGO_PRODUCTO","CODIGO"}:
                for row_idx in range(2, ws.max_row + 1):
                    ws.cell(row_idx, col_idx).number_format = "@"

    wb.save(path)
    return path


# Manual export.
_v987_previous_export_excel = SalesStore.export_excel
def _v987_export_excel(self, output_path: Path, append_existing: bool = False):
    result = _v987_previous_export_excel(self, output_path, append_existing)
    _v987_style_excel_file(output_path)
    return result
SalesStore.export_excel = _v987_export_excel


# Copia diaria: estilizar después de que todos los wrappers hayan terminado de escribir.
_v987_previous_daily_snapshot = SalesStore.export_daily_snapshot
def _v987_export_daily_snapshot(self, output_path: Path | None = None) -> Path:
    saved = Path(_v987_previous_daily_snapshot(self, output_path))
    _v987_style_excel_file(saved)
    return saved
SalesStore.export_daily_snapshot = _v987_export_daily_snapshot

