# ==================== V10.1.8 MIGRACIÓN DESDE FUENTE COMPLETA ====================
# Permite usar un único Excel con maestros + operación comercial para migración.


def _v988_read_sheet(source_path: Path, sheet_name: str) -> pd.DataFrame:
    try:
        return pd.read_excel(source_path, sheet_name=sheet_name)
    except Exception:
        return pd.DataFrame()


def _v988_text(value) -> str:
    if value is None:
        return ""
    try:
        if pd.isna(value):
            return ""
    except Exception:
        pass
    return str(value).strip()


def _v988_number(value) -> float:
    try:
        return money(value)
    except Exception:
        return 0.0


def _v988_operational_counts(source_path: Path) -> dict:
    try:
        book = pd.ExcelFile(source_path)
        names = {str(s).strip().upper(): s for s in book.sheet_names}
        book.close()
    except Exception:
        return {"cabeceras":0, "detalles":0, "abonos":0, "aplicaciones":0}

    result = {}
    for logical in ["Ventas_cabecera","Ventas_detalle","Registro_abonos","Aplicacion_abonos"]:
        actual = names.get(logical.upper())
        if not actual:
            result[logical] = 0
            continue
        try:
            df = pd.read_excel(source_path, sheet_name=actual)
            result[logical] = int(len(df.dropna(how="all")))
        except Exception:
            result[logical] = 0
    return {
        "cabeceras": result.get("Ventas_cabecera",0),
        "detalles": result.get("Ventas_detalle",0),
        "abonos": result.get("Registro_abonos",0),
        "aplicaciones": result.get("Aplicacion_abonos",0),
    }


def _v988_import_operational_history(self, source_path: Path) -> dict:
    cab = _v988_read_sheet(source_path, "Ventas_cabecera")
    det = _v988_read_sheet(source_path, "Ventas_detalle")
    abonos = _v988_read_sheet(source_path, "Registro_abonos")
    apps = _v988_read_sheet(source_path, "Aplicacion_abonos")

    if cab.empty or det.empty:
        return {"facturas":0, "detalles":0, "abonos":0, "aplicaciones":0}

    cab.columns = [str(c).strip().upper() for c in cab.columns]
    det.columns = [str(c).strip().upper() for c in det.columns]
    if not abonos.empty:
        abonos.columns = [str(c).strip().upper() for c in abonos.columns]
    if not apps.empty:
        apps.columns = [str(c).strip().upper() for c in apps.columns]

    imported_invoices = 0
    imported_details = 0

    for _, row in cab.dropna(how="all").iterrows():
        cuenta = _v988_text(row.get("CUENTA_COBRO"))
        cliente = _v988_text(row.get("CLIENTE"))
        if not cuenta or not cliente:
            continue

        sale = {
            "cuenta_cobro": cuenta,
            "fecha": _v988_text(row.get("FECHA"))[:10],
            "cliente": cliente,
            "estado_venta": _v988_text(row.get("ESTADO_VENTA")) or "EMITIDA",
            "fecha_vencimiento": _v988_text(row.get("FECHA_VENCIMIENTO"))[:10],
            "asesor": _v988_text(row.get("ASESOR")),
            "cta_bancaria": _v988_text(row.get("CTA_BANCARIA")),
            "direccion": _v988_text(row.get("DIRECCION")),
            "ciudad_entrega": _v988_text(row.get("CIUDAD_ENTREGA")),
            "barrio_entrega": _v988_text(row.get("BARRIO_ENTREGA")),
            "local_edificio": _v988_text(row.get("LOCAL_EDIFICIO")),
            "datos_entrega": _v988_text(row.get("DATOS_ENTREGA")),
            "telefono_cliente": _v988_text(row.get("TELEFONO_CLIENTE")),
            "estado_pago": _v988_text(row.get("ESTADO_PAGO")) or "Pendiente",
            "domicilio_empresa": _v988_number(row.get("DOMICILIO_EMPRESA")),
            "domicilio_cliente": _v988_number(row.get("DOMICILIO_CLIENTE")),
            "forma_pago": _v988_text(row.get("FORMA_PAGO")),
            "recibido_por": _v988_text(row.get("RECIBIDO_POR")),
            "observacion_logistica": _v988_text(row.get("OBSERVACION_LOGISTICA")),
            "factura_electronica": _v988_text(row.get("FACTURA_ELECTRONICA")),
            "fecha_factura_electronica": _v988_text(row.get("FECHA_FACTURA_ELECTRONICA"))[:10],
            "cotizacion_origen": _v988_text(row.get("COTIZACION_ORIGEN")),
            "fuente_origen": f"Migrado desde {source_path.name}",
            "modificado_manualmente": 1,
        }

        self.store.ensure_cliente(cliente)
        self.store.upsert_sale(sale)

        rows_det = det[
            det["CUENTA_COBRO"].astype(str).str.strip() == cuenta
        ].copy() if "CUENTA_COBRO" in det.columns else pd.DataFrame()

        self.store.conn.execute("DELETE FROM ventas_detalle WHERE cuenta_cobro=?", (cuenta,))
        self.store.conn.commit()

        for _, d in rows_det.iterrows():
            producto = _v988_text(d.get("PRODUCTO"))
            if not producto:
                continue

            cantidad = _v988_number(d.get("CANTIDAD"))
            precio_venta = _v988_number(d.get("PRECIO_VENTA_UNIDAD"))
            venta_total = _v988_number(d.get("VENTA TOTAL"))
            costo_u = _v988_number(d.get("COSTO POR UNIDAD"))

            if venta_total == 0 and cantidad > 0 and precio_venta > 0:
                venta_total = cantidad * precio_venta

            self.store.add_detail({
                "cuenta_cobro": cuenta,
                "codigo": _v988_text(d.get("CODIGO_PRODUCTO")),
                "codigo_producto": _v988_text(d.get("CODIGO_PRODUCTO")),
                "producto": producto,
                "unidad": _v988_text(d.get("UNIDAD")) or "KLS",
                "cantidad_kls": cantidad,
                "valor_x_kl": precio_venta,
                "valor_total": venta_total,
                "costo_unitario": costo_u,
                "comision_unitaria": _v988_number(d.get("COMISION_UNITARIA")),
                "comision": _v988_number(d.get("COMISION")),
                "iva_19": _v988_number(d.get("IVA_19")),
                "retenciones": _v988_number(d.get("RETENCIONES")),
                "chile_fresco": 0,
                "domicilio": 0,
            })
            imported_details += 1

        imported_invoices += 1

    imported_payments = 0
    if not abonos.empty and "ID_ABONO" in abonos.columns:
        for _, r in abonos.dropna(how="all").iterrows():
            id_abono = _v988_text(r.get("ID_ABONO"))
            if not id_abono:
                continue
            self.store.upsert_abono({
                "id_abono": id_abono,
                "fecha_abono": _v988_text(r.get("FECHA_ABONO"))[:10],
                "cliente": _v988_text(r.get("CLIENTE")),
                "medio_pago": _v988_text(r.get("MEDIO_PAGO")) or "Transferencia",
                "cta_bancaria_destino": _v988_text(r.get("CTA_BANCARIA_DESTINO")),
                "referencia_pago": _v988_text(r.get("REFERENCIA_PAGO")),
                "valor_abono": _v988_number(r.get("VALOR_ABONO")),
                "soporte": _v988_text(r.get("SOPORTE")),
                "observacion_control": _v988_text(r.get("OBSERVACION_CONTROL")),
            })
            imported_payments += 1

    imported_apps = 0
    if not apps.empty and "CUENTA_COBRO" in apps.columns:
        target_accounts = {
            _v988_text(x) for x in apps["CUENTA_COBRO"].tolist() if _v988_text(x)
        }
        for cuenta in target_accounts:
            self.store.conn.execute("DELETE FROM aplicacion_abonos WHERE cuenta_cobro=?", (cuenta,))
        self.store.conn.commit()

        for _, r in apps.dropna(how="all").iterrows():
            id_abono = _v988_text(r.get("ID_ABONO"))
            cuenta = _v988_text(r.get("CUENTA_COBRO"))
            if not id_abono or not cuenta:
                continue
            self.store.conn.execute(
                """
                INSERT INTO aplicacion_abonos (
                    id_abono, cuenta_cobro, fecha_aplicacion,
                    orden_aplicacion, valor_aplicado, observacion_aplicacion
                ) VALUES (?, ?, ?, ?, ?, ?)
                """,
                (
                    id_abono,
                    cuenta,
                    _v988_text(r.get("FECHA_APLICACION"))[:10],
                    int(_v988_number(r.get("ORDEN_APLICACION")) or 1),
                    _v988_number(r.get("VALOR_APLICADO")),
                    _v988_text(r.get("OBSERVACION_APLICACION")),
                ),
            )
            imported_apps += 1
        self.store.conn.commit()

    return {
        "facturas": imported_invoices,
        "detalles": imported_details,
        "abonos": imported_payments,
        "aplicaciones": imported_apps,
    }


def _v988_import_master_source(self, source_path: Path):
    _v96_validate_master_workbook(source_path)

    clientes, productos = load_master_records([source_path])
    asesores = load_master_advisors([source_path])

    if not clientes or not productos or not asesores:
        raise ValueError(
            "La fuente debe contener registros en Clientes_Maestro, "
            "Productos_Maestro y Asesores_Maestro."
        )

    counts = _v988_operational_counts(source_path)
    has_operation = counts["cabeceras"] > 0 and counts["detalles"] > 0

    if has_operation:
        answer = messagebox.askyesno(
            "Importar fuente completa",
            "El archivo contiene maestros y operación comercial.\n\n"
            f"Clientes maestro: {len(clientes)}\n"
            f"Productos maestro: {len(productos)}\n"
            f"Asesores maestro: {len(asesores)}\n"
            f"Ventas/cabeceras: {counts['cabeceras']}\n"
            f"Líneas de detalle: {counts['detalles']}\n"
            f"Abonos: {counts['abonos']}\n\n"
            "¿Desea sincronizar también estas ventas y abonos con la base SQLite?\n\n"
            "Las cuentas existentes se actualizarán por número de cuenta; no se duplicarán.",
            parent=self,
        )
        if not answer:
            has_operation = False

    save_master_sources([source_path])
    self.store.import_master_records(clientes, productos, str(source_path))
    self.store.import_master_advisors(asesores, str(source_path))

    summary = {"facturas":0,"detalles":0,"abonos":0,"aplicaciones":0}
    if has_operation:
        summary = _v988_import_operational_history(self, source_path)

    self.store.register_source_import(
        source_path,
        len(clientes),
        len(productos),
        summary["facturas"],
        (
            f"Fuente completa V10.1.8. Asesores: {len(asesores)}. "
            f"Ventas: {summary['facturas']}; detalles: {summary['detalles']}; "
            f"abonos: {summary['abonos']}; aplicaciones: {summary['aplicaciones']}."
        ),
    )

    self.catalogs = load_catalogs()
    self.reload_master_catalogs()
    self.refresh_all()
    self.refresh_source_panel()

    snapshot_msg = ""
    try:
        snap = self.store.export_daily_snapshot()
        snapshot_msg = f"\n\nCopia diaria actualizada:\n{snap}"
    except Exception as exc:
        snapshot_msg = f"\n\nLa base SQLite quedó actualizada, pero falló la copia diaria:\n{exc}"

    messagebox.showinfo(
        "Fuente sincronizada",
        f"Fuente activa:\n{source_path}\n\n"
        f"Clientes: {len(clientes)}\n"
        f"Productos: {len(productos)}\n"
        f"Asesores: {len(asesores)}\n"
        f"Ventas importadas/actualizadas: {summary['facturas']}\n"
        f"Líneas de detalle: {summary['detalles']}\n"
        f"Abonos: {summary['abonos']}\n"
        f"Aplicaciones de abono: {summary['aplicaciones']}"
        + snapshot_msg,
        parent=self,
    )


SalesFormApp.import_master_source = _v988_import_master_source

