# ==================== V10.1.8 GUÍA DE ENVÍO ====================
# La guía NO describe el contenido del paquete.
# ID interno = número de pedido + fecha + hora de generación.
# Ejemplo cuenta 0007: 7-0210261134


def _v992_safe_text(value) -> str:
    if value is None:
        return ""
    try:
        if pd.isna(value):
            return ""
    except Exception:
        pass
    return str(value).strip()


def _v992_client_shipping_data(self, sale) -> dict:
    client_name = _v992_safe_text(sale.get("cliente", ""))
    client = self.table(
        "SELECT * FROM clientes WHERE TRIM(nombre)=TRIM(?) COLLATE NOCASE LIMIT 1",
        (client_name,),
    )
    master = client.iloc[0] if not client.empty else {}

    def choose(sale_key: str, master_key: str = ""):
        value = _v992_safe_text(sale.get(sale_key, ""))
        if value:
            return value
        if master_key:
            try:
                return _v992_safe_text(master.get(master_key, ""))
            except Exception:
                return ""
        return ""

    return {
        "nombre": client_name,
        "telefono": choose("telefono_cliente", "telefono"),
        "direccion": choose("direccion", "direccion"),
        "ciudad": choose("ciudad_entrega", "ciudad"),
        "barrio": choose("barrio_entrega", "barrio"),
        "local_edificio": choose("local_edificio", "local_edificio"),
        "datos_entrega": choose("datos_entrega", "datos_entrega"),
    }


def _v992_export_shipping_guide(self, cuenta_cobro: str, output_path: Path | None = None) -> Path:
    sale_df = self.table(
        "SELECT * FROM ventas WHERE cuenta_cobro=?",
        (cuenta_cobro,),
    )
    if sale_df.empty:
        raise ValueError(f"No existe la cuenta de cobro {cuenta_cobro}.")

    sale = sale_df.iloc[0]
    recipient = _v992_client_shipping_data(self, sale)

    order_num = _v992_safe_text(cuenta_cobro).lstrip("0") or "0"
    now_guide = datetime.now()
    shipping_id = f"{order_num}-{now_guide.strftime('%d%m%y%H%M')}"

    if output_path is None:
        PRINT_DIR.mkdir(parents=True, exist_ok=True)
        output_path = PRINT_DIR / f"Guia_envio_{make_code(cuenta_cobro, 'ENVIO')}.xlsx"
    else:
        output_path = Path(output_path)
        output_path.parent.mkdir(parents=True, exist_ok=True)

    with pd.ExcelWriter(output_path, engine="xlsxwriter") as writer:
        wb = writer.book
        ws = wb.add_worksheet("Guía de envío")
        writer.sheets["Guía de envío"] = ws

        green = "#155A3A"
        cream = "#F8F2E5"
        light_green = "#E7F1EC"
        white = "#FFFFFF"
        border_color = "#4B4B4B"
        border = {"border": 1, "border_color": border_color}

        fmt_title = wb.add_format({
            **border, "bold": True, "font_size": 20,
            "font_color": white, "bg_color": green,
            "align": "center", "valign": "vcenter"
        })
        fmt_ref = wb.add_format({
            **border, "bold": True, "font_size": 11,
            "bg_color": cream, "align": "center",
            "valign": "vcenter"
        })
        fmt_section = wb.add_format({
            **border, "bold": True, "font_size": 12,
            "font_color": white, "bg_color": green,
            "align": "center", "valign": "vcenter"
        })
        fmt_label = wb.add_format({
            **border, "bold": True, "font_size": 10,
            "bg_color": light_green, "valign": "vcenter"
        })
        fmt_value = wb.add_format({
            **border, "font_size": 10,
            "text_wrap": True, "valign": "vcenter"
        })
        fmt_value_bold = wb.add_format({
            **border, "bold": True, "font_size": 11,
            "text_wrap": True, "valign": "vcenter"
        })
        fmt_note = wb.add_format({
            "font_size": 8, "italic": True,
            "font_color": "#555555", "text_wrap": True,
            "align": "center"
        })

        ws.set_column("A:A", 18)
        ws.set_column("B:B", 24)
        ws.set_column("C:C", 18)
        ws.set_column("D:D", 18)
        ws.set_column("E:E", 24)
        ws.set_column("F:F", 18)

        ws.set_row(0, 34)
        ws.merge_range("A1:F1", "GUÍA DE ENVÍO", fmt_title)
        ws.merge_range("A2:C2", f"ID: {shipping_id}", fmt_ref)
        ws.merge_range("D2:F2", f"FECHA: {now_guide.strftime('%Y-%m-%d %H:%M')}", fmt_ref)

        # Remitente solicitado.
        ws.merge_range("A4:F4", "REMITENTE", fmt_section)
        sender = [
            ("Remitente", "Heidy Galeano"),
            ("C.C", "901,399,198"),
            ("Dirección", "CRA 21 # 16-20 LOCAL 1"),
            ("Ciudad", "Bogotá"),
            ("Teléfono", "3123138543"),
        ]
        row = 4
        for label, value in sender:
            ws.merge_range(row, 0, row, 1, label, fmt_label)
            ws.merge_range(
                row, 2, row, 5, value,
                fmt_value_bold if label == "Remitente" else fmt_value
            )
            ws.set_row(row, 22)
            row += 1

        # Destinatario.
        row += 1
        ws.merge_range(row, 0, row, 5, "DESTINATARIO", fmt_section)
        row += 1

        recipient_rows = [
            ("ID", shipping_id),
            ("Nombre", recipient["nombre"]),
            ("Teléfono", recipient["telefono"] or "NO SUMINISTRADO"),
            ("Dirección", recipient["direccion"] or "NO SUMINISTRADA"),
            ("Barrio", recipient["barrio"] or ""),
            ("Local / Edificio", recipient["local_edificio"] or ""),
            ("Ciudad", recipient["ciudad"] or "NO SUMINISTRADA"),
            ("Indicaciones de entrega", recipient["datos_entrega"] or ""),
        ]

        for label, value in recipient_rows:
            ws.merge_range(row, 0, row, 1, label, fmt_label)
            ws.merge_range(
                row, 2, row, 5, value,
                fmt_value_bold if label in {"ID", "Nombre"} else fmt_value
            )
            ws.set_row(row, 24 if label != "Indicaciones de entrega" else 38)
            row += 1

        row += 1
        ws.merge_range(
            row, 0, row, 5,
            "ID interno generado automáticamente con número de pedido, fecha y hora. "
            "No corresponde a un documento de identidad.",
            fmt_note
        )

        ws.hide_gridlines(2)
        ws.set_portrait()
        ws.set_paper(9)  # A4
        ws.fit_to_pages(1, 1)
        ws.set_margins(0.25, 0.25, 0.3, 0.3)
        ws.center_horizontally()
        ws.set_print_area(0, 0, row + 1, 5)

    return Path(output_path)


SalesStore.export_shipping_guide = _v992_export_shipping_guide


# Reemplaza el diálogo post-venta para ofrecer cuenta de cobro + guía.
_v992_previous_show_invoice_generation_dialog = SalesFormApp.show_invoice_generation_dialog

def _v992_show_invoice_generation_dialog(self, cuenta_cobro: str, total_factura: float, total_pagos: float):
    win = tk.Toplevel(self)
    win.title(f"Venta guardada - Cuenta {cuenta_cobro}")
    win.transient(self)
    win.grab_set()
    win.resizable(False, False)

    body = ttk.Frame(win, padding=18)
    body.pack(fill="both", expand=True)

    ttk.Label(
        body, text="Venta guardada correctamente",
        style="Title.TLabel"
    ).pack(anchor="w")
    ttk.Label(
        body, text=f"Cuenta de cobro: {cuenta_cobro}"
    ).pack(anchor="w", pady=(10, 0))
    ttk.Label(
        body, text=f"Total: ${total_factura:,.0f}"
    ).pack(anchor="w")
    ttk.Label(
        body, text=f"Pagado: ${total_pagos:,.0f}"
    ).pack(anchor="w")

    status = tk.StringVar(
        value="Puede generar la cuenta de cobro y la guía de envío."
    )
    ttk.Label(
        body, textvariable=status, wraplength=560
    ).pack(anchor="w", pady=(10, 10))

    buttons = ttk.Frame(body)
    buttons.pack(fill="x")

    def restore():
        try:
            win.deiconify()
            win.lift()
            win.focus_force()
        except Exception:
            pass

    def generate_invoice():
        try:
            safe_invoice = make_code(cuenta_cobro, "FACTURA")
            cfg = read_config()
            initial_dir = cfg.get("invoice_output_dir", "") or str(PRINT_DIR)
            try:
                Path(initial_dir).mkdir(parents=True, exist_ok=True)
            except Exception:
                initial_dir = str(APP_DIR)

            selected = filedialog.asksaveasfilename(
                parent=win,
                title="Guardar cuenta de cobro",
                initialdir=initial_dir,
                initialfile=f"Cuenta_cobro_{safe_invoice}.xlsx",
                defaultextension=".xlsx",
                filetypes=[("Excel", "*.xlsx")],
            )
            restore()
            if not selected:
                return

            path = self.store.export_invoice_print(
                cuenta_cobro, Path(selected)
            )
            cfg["invoice_output_dir"] = str(Path(path).parent)
            write_config(cfg)
            status.set(f"Cuenta de cobro generada: {path}")
            messagebox.showinfo(
                "Cuenta de cobro",
                f"Documento generado correctamente:\n{path}",
                parent=win,
            )
            win.after(100, restore)
        except Exception as exc:
            messagebox.showerror(
                "Cuenta de cobro", str(exc), parent=win
            )
            win.after(100, restore)

    def generate_shipping():
        try:
            safe_invoice = make_code(cuenta_cobro, "ENVIO")
            cfg = read_config()
            initial_dir = (
                cfg.get("shipping_guide_output_dir", "")
                or cfg.get("invoice_output_dir", "")
                or str(PRINT_DIR)
            )
            try:
                Path(initial_dir).mkdir(parents=True, exist_ok=True)
            except Exception:
                initial_dir = str(APP_DIR)

            selected = filedialog.asksaveasfilename(
                parent=win,
                title="Guardar guía de envío",
                initialdir=initial_dir,
                initialfile=f"Guia_envio_{safe_invoice}.xlsx",
                defaultextension=".xlsx",
                filetypes=[("Excel", "*.xlsx")],
            )
            restore()
            if not selected:
                return

            path = self.store.export_shipping_guide(
                cuenta_cobro, Path(selected)
            )
            cfg["shipping_guide_output_dir"] = str(Path(path).parent)
            write_config(cfg)
            status.set(f"Guía de envío generada: {path}")
            messagebox.showinfo(
                "Guía de envío",
                f"Guía generada correctamente:\n{path}",
                parent=win,
            )
            win.after(100, restore)
        except Exception as exc:
            messagebox.showerror(
                "Guía de envío", str(exc), parent=win
            )
            win.after(100, restore)

    ttk.Button(
        buttons,
        text="Generar cuenta de cobro",
        style="Primary.TButton",
        command=generate_invoice
    ).pack(side="left", padx=(0, 6))

    ttk.Button(
        buttons,
        text="Generar guía de envío",
        command=generate_shipping
    ).pack(side="left", padx=(0, 6))

    ttk.Button(
        buttons, text="Cerrar", command=win.destroy
    ).pack(side="right")

    win.update_idletasks()
    x = self.winfo_rootx() + max(
        0, (self.winfo_width() - win.winfo_width()) // 2
    )
    y = self.winfo_rooty() + max(
        0, (self.winfo_height() - win.winfo_height()) // 2
    )
    win.geometry(f"+{x}+{y}")
    self.wait_window(win)


