# ==================== V10.1.8 PORTABLE: FUENTE AUTOMÁTICA + BACKUP DB ====================

V995_REQUIRED_MASTER_SHEETS = {
    "CLIENTES_MAESTRO",
    "PRODUCTOS_MAESTRO",
    "ASESORES_MAESTRO",
}


def _v995_is_valid_master_excel(path: Path) -> bool:
    """Comprueba que un Excel pueda funcionar como fuente maestra MXPC."""
    try:
        path = Path(path)
        if not path.is_file() or path.suffix.lower() not in {".xlsx", ".xlsm", ".xlsb", ".xls"}:
            return False
        if path.name.startswith("~$"):
            return False

        book = pd.ExcelFile(path)
        sheets = {str(s).strip().upper() for s in book.sheet_names}
        book.close()
        return V995_REQUIRED_MASTER_SHEETS.issubset(sheets)
    except Exception:
        return False


def _v995_source_priority(path: Path):
    """Ordena fuentes candidatas: consolidada/completa primero y luego más reciente."""
    name = path.name.upper()
    if "FUENTE_COMPLETA" in name or "CONSOLIDADO" in name:
        rank = 3
    elif "BASE_MAESTRA" in name:
        rank = 2
    else:
        rank = 1

    try:
        modified = path.stat().st_mtime
    except Exception:
        modified = 0
    return (rank, modified)


def _v995_discover_master_source() -> Path | None:
    """Busca automáticamente la mejor fuente en la carpeta datos del portable."""
    PORTABLE_DATA_DIR.mkdir(parents=True, exist_ok=True)

    candidates = []
    for pattern in ("*.xlsx", "*.xlsm", "*.xlsb", "*.xls"):
        try:
            candidates.extend(PORTABLE_DATA_DIR.glob(pattern))
        except Exception:
            pass

    valid = [p for p in candidates if _v995_is_valid_master_excel(p)]
    if not valid:
        return None

    return max(valid, key=_v995_source_priority)


def _v995_persist_discovered_source(path: Path) -> None:
    """Guarda la nueva ruta sin borrar otras preferencias del usuario."""
    try:
        cfg = read_config()
        cfg["master_sources"] = [str(Path(path).resolve())]
        cfg["source_watch_folder"] = str(PORTABLE_DATA_DIR.resolve())
        cfg["master_source_updated_at"] = datetime.now().isoformat(timespec="seconds")
        cfg["master_source_discovery"] = "automatico_datos"
        write_config(cfg)
    except Exception:
        pass


# Guardar referencia a la implementación previa para mantener fallback compatible.
_v995_previous_read_master_sources = read_master_sources

def read_master_sources() -> list[Path]:
    """Obtiene la fuente activa y se autorrepara si el portable cambió de ubicación."""
    cfg = read_config()

    # 1) Respetar la fuente configurada si sigue existiendo y tiene el formato maestro.
    configured = []
    for raw in cfg.get("master_sources", []) or []:
        try:
            p = Path(raw)
            if p.exists() and _v995_is_valid_master_excel(p):
                configured.append(p)
        except Exception:
            pass
    if configured:
        return configured

    # 2) La ruta vieja ya no sirve: buscar dentro de .\datos automáticamente.
    discovered = _v995_discover_master_source()
    if discovered is not None:
        _v995_persist_discovered_source(discovered)
        return [discovered]

    # 3) Mantener compatibilidad con la fuente portable inicial si es válida.
    try:
        if PORTABLE_MASTER_PATH.exists() and _v995_is_valid_master_excel(PORTABLE_MASTER_PATH):
            _v995_persist_discovered_source(PORTABLE_MASTER_PATH)
            return [PORTABLE_MASTER_PATH]
    except Exception:
        pass

    # 4) Último fallback a la lógica histórica.
    try:
        return _v995_previous_read_master_sources()
    except Exception:
        return []


# Extender el arranque portable: resolver fuente automáticamente antes de construir la UI.
_v995_previous_initialize_portable_installation = initialize_portable_installation

def initialize_portable_installation():
    _v995_previous_initialize_portable_installation()

    # Asegurar toda la estructura portable.
    for folder in (
        PORTABLE_DATA_DIR,
        APP_DIR / "copias_diarias",
        APP_DIR / "respaldos_db",
        APP_DIR / "cuentas_cobro",
        APP_DIR / "cotizaciones_generadas",
    ):
        folder.mkdir(parents=True, exist_ok=True)

    # Si la ruta configurada quedó inválida tras mover/copiar la carpeta,
    # read_master_sources() la descubre en datos\ y reescribe el JSON.
    sources = read_master_sources()

    cfg = read_config()
    cfg["workspace_dir"] = str(APP_DIR)
    cfg["daily_output_dir"] = str(APP_DIR / "copias_diarias")
    cfg["invoice_output_dir"] = cfg.get("invoice_output_dir") or str(APP_DIR / "cuentas_cobro")
    cfg["quote_output_dir"] = cfg.get("quote_output_dir") or str(APP_DIR / "cotizaciones_generadas")
    cfg["source_watch_folder"] = str(PORTABLE_DATA_DIR)
    if sources:
        cfg["master_sources"] = [str(Path(s).resolve()) for s in sources]
    write_config(cfg)


