# ==================== V10.1.8 CARTERA + ETIQUETA DOMICILIO/ENVÍO ====================

REPORTS_DIR = APP_DIR / "reportes_cartera"


def _v1000_norm_city(value) -> str:
    import unicodedata
    text = str(value or "").strip().upper()
    text = "".join(
        ch for ch in unicodedata.normalize("NFD", text)
        if unicodedata.category(ch) != "Mn"
    )
    text = re.sub(r"[^A-Z0-9]+", " ", text)
    return re.sub(r"\s+", " ", text).strip()


def _v1000_shipping_label(city) -> str:
    """Bogotá -> DOMICILIO; cualquier otra ciudad -> ENVÍO."""
    city_norm = _v1000_norm_city(city)
    return "DOMICILIO" if "BOGOTA" in city_norm else "ENVÍO"


def _v1000_cartera_dataframe(self) -> pd.DataFrame:
    """Cartera gerencial vigente: una fila por cuenta con saldo real > 0."""
    summary = self.sales_summary().copy()
    if summary.empty:
        return pd.DataFrame(columns=[
            "fecha_venta","dias_cartera","cliente","cuenta_cobro","ciudad","asesor",
            "total_factura","total_abonos","saldo_pendiente","estado_cartera",
            "fecha_ultimo_abono","valor_ultimo_abono","telefono_cliente"
        ])

    sales = self.table("""
        SELECT cuenta_cobro, fecha, cliente, ciudad_entrega, asesor,
               telefono_cliente, estado_venta
          FROM ventas
    """)
    df = summary.merge(
        sales[[
            "cuenta_cobro","ciudad_entrega","asesor",
            "telefono_cliente"
        ]],
        on="cuenta_cobro",
        how="left",
    )

    df["total_factura"] = pd.to_numeric(df["total_factura"], errors="coerce").fillna(0)
    df["total_abonos"] = pd.to_numeric(df["total_abonos"], errors="coerce").fillna(0)
    df["saldo_pendiente"] = (df["total_factura"] - df["total_abonos"]).clip(lower=0)

    # Último abono real aplicado a cada cuenta.
    apps = self.table("""
        SELECT id_aplicacion, cuenta_cobro, fecha_aplicacion,
               valor_aplicado, id_abono, orden_aplicacion
          FROM aplicacion_abonos
         ORDER BY cuenta_cobro, fecha_aplicacion,
                  orden_aplicacion, id_aplicacion
    """)
    if not apps.empty:
        apps = apps.copy()
        apps["_fecha"] = pd.to_datetime(apps["fecha_aplicacion"], errors="coerce")
        apps = apps.sort_values(
            ["cuenta_cobro","_fecha","orden_aplicacion","id_aplicacion","id_abono"]
        )
        last = (
            apps.groupby("cuenta_cobro", as_index=False)
            .tail(1)[["cuenta_cobro","fecha_aplicacion","valor_aplicado"]]
            .rename(columns={
                "fecha_aplicacion":"fecha_ultimo_abono",
                "valor_aplicado":"valor_ultimo_abono",
            })
        )
        df = df.merge(last, on="cuenta_cobro", how="left")
    else:
        df["fecha_ultimo_abono"] = ""
        df["valor_ultimo_abono"] = 0.0

    df["fecha_ultimo_abono"] = df["fecha_ultimo_abono"].fillna("")
    df["valor_ultimo_abono"] = pd.to_numeric(
        df["valor_ultimo_abono"], errors="coerce"
    ).fillna(0)

    # Solo deudores reales y nunca ventas anuladas.
    df = df[
        (df["saldo_pendiente"] > 1)
        & (~df["estado_venta"].astype(str).str.upper().eq("ANULADA"))
    ].copy()

    today = pd.Timestamp(datetime.now().date())
    sale_dates = pd.to_datetime(df["fecha"], errors="coerce")
    df["dias_cartera"] = (today - sale_dates.dt.normalize()).dt.days.fillna(0).clip(lower=0).astype(int)
    df["estado_cartera"] = df.apply(
        lambda r: "PARCIAL" if float(r.get("total_abonos",0) or 0) > 0 else "PENDIENTE",
        axis=1,
    )

    df = df.rename(columns={
        "fecha":"fecha_venta",
        "ciudad_entrega":"ciudad",
    })
    # Referencia gerencial explícita: cuenta + fecha de la deuda.
    def _v1013_account_date(row):
        fecha = pd.to_datetime(row.get("fecha_venta"), errors="coerce")
        fecha_txt = fecha.strftime("%d/%m/%Y") if pd.notna(fecha) else str(row.get("fecha_venta",""))[:10]
        return f"{row.get('cuenta_cobro','')} ({fecha_txt})"

    df["cuenta_fecha"] = df.apply(_v1013_account_date, axis=1)

    cols = [
        "fecha_venta","dias_cartera","cliente","cuenta_cobro","cuenta_fecha",
        "ciudad","asesor","total_factura","total_abonos","saldo_pendiente",
        "estado_cartera","fecha_ultimo_abono","valor_ultimo_abono","telefono_cliente",
    ]
    for col in cols:
        if col not in df.columns:
            df[col] = ""
    return df[cols].sort_values(
        ["fecha_venta","saldo_pendiente"],
        ascending=[True,False],
    ).reset_index(drop=True)


SalesStore.cartera_management = _v1000_cartera_dataframe


# Añadir/actualizar una pestaña CARTERA en cada exportación y copia diaria.
_v1000_previous_export_excel = SalesStore.export_excel
def _v1000_export_excel(self, output_path: Path, append_existing: bool = False):
    result = _v1000_previous_export_excel(self, output_path, append_existing)
    cartera = self.cartera_management()
    with pd.ExcelWriter(
        output_path,
        engine="openpyxl",
        mode="a",
        if_sheet_exists="replace",
    ) as writer:
        cartera.rename(columns=str.upper).to_excel(
            writer,
            sheet_name="Cartera",
            index=False,
        )
    try:
        _v987_style_excel_file(output_path)
    except Exception:
        pass
    return result


SalesStore.export_excel = _v1000_export_excel


def _v1000_export_cartera_pdf(self, cutoff_date=None, output_path: Path | None = None) -> Path:
    """Reporte gerencial semanal de cartera en PDF."""
    from reportlab.lib import colors
    from reportlab.lib.pagesizes import A4, landscape
    from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
    from reportlab.lib.enums import TA_CENTER, TA_RIGHT
    from reportlab.lib.units import cm
    from reportlab.platypus import (
        SimpleDocTemplate, Paragraph, Spacer, Table, TableStyle, PageBreak
    )

    cartera = self.cartera_management()
    cutoff = cutoff_date or datetime.now().date()

    REPORTS_DIR.mkdir(parents=True, exist_ok=True)
    if output_path is None:
        output_path = REPORTS_DIR / f"Cartera_semanal_{cutoff.strftime('%Y-%m-%d')}.pdf"
    else:
        output_path = Path(output_path)
        output_path.parent.mkdir(parents=True, exist_ok=True)

    styles = getSampleStyleSheet()
    styles.add(ParagraphStyle(
        name="MXPCTitle",
        parent=styles["Title"],
        fontSize=18,
        leading=21,
        textColor=colors.HexColor("#155E42"),
        alignment=TA_CENTER,
        spaceAfter=8,
    ))
    styles.add(ParagraphStyle(
        name="MXPCMoney",
        parent=styles["BodyText"],
        alignment=TA_RIGHT,
        fontSize=9,
    ))
    styles.add(ParagraphStyle(
        name="MXPCSmall",
        parent=styles["BodyText"],
        fontSize=8,
        leading=10,
    ))

    doc = SimpleDocTemplate(
        str(output_path),
        pagesize=landscape(A4),
        leftMargin=1.0*cm,
        rightMargin=1.0*cm,
        topMargin=0.8*cm,
        bottomMargin=0.8*cm,
        title=f"Cartera semanal MXPC {cutoff}",
        author="MXPC Comercial",
    )

    story = [
        Paragraph("MXPC - REPORTE SEMANAL DE CARTERA", styles["MXPCTitle"]),
        Paragraph(
            f"Corte: {cutoff.strftime('%d/%m/%Y')} | "
            "Incluye únicamente cuentas con saldo pendiente. "
            "Las ventas anuladas están excluidas.",
            styles["BodyText"],
        ),
        Spacer(1, 10),
    ]

    total_cartera = float(cartera["saldo_pendiente"].sum()) if not cartera.empty else 0
    facturas = int(len(cartera))
    clientes = int(cartera["cliente"].nunique()) if not cartera.empty else 0
    parciales = int((cartera["estado_cartera"]=="PARCIAL").sum()) if not cartera.empty else 0

    kpis = [
        ["Cartera total", "Cuentas pendientes", "Clientes deudores", "Cuentas parciales"],
        [f"${total_cartera:,.0f}", f"{facturas}", f"{clientes}", f"{parciales}"],
    ]
    kt = Table(kpis, colWidths=[6.2*cm]*4)
    kt.setStyle(TableStyle([
        ("BACKGROUND",(0,0),(-1,0),colors.HexColor("#155E42")),
        ("TEXTCOLOR",(0,0),(-1,0),colors.white),
        ("FONTNAME",(0,0),(-1,0),"Helvetica-Bold"),
        ("FONTNAME",(0,1),(-1,1),"Helvetica-Bold"),
        ("FONTSIZE",(0,0),(-1,-1),11),
        ("ALIGN",(0,0),(-1,-1),"CENTER"),
        ("BACKGROUND",(0,1),(-1,1),colors.HexColor("#E7F1EC")),
        ("BOX",(0,0),(-1,-1),0.5,colors.HexColor("#155E42")),
        ("INNERGRID",(0,0),(-1,-1),0.25,colors.HexColor("#AAB8B0")),
        ("TOPPADDING",(0,0),(-1,-1),7),
        ("BOTTOMPADDING",(0,0),(-1,-1),7),
    ]))
    story += [kt, Spacer(1,12)]

    if cartera.empty:
        story.append(Paragraph("No hay cartera pendiente al corte.", styles["Heading2"]))
    else:
        # Resumen por cliente.
        # Resumen por cliente incluyendo exactamente qué cuentas conforman la deuda.
        def _v1013_pending_accounts(group):
            ordered = group.sort_values(["fecha_venta","cuenta_cobro"])
            refs = []
            for _, row in ordered.iterrows():
                fecha = pd.to_datetime(row.get("fecha_venta"), errors="coerce")
                fecha_txt = fecha.strftime("%d/%m/%Y") if pd.notna(fecha) else str(row.get("fecha_venta",""))[:10]
                refs.append(
                    f"{row.get('cuenta_cobro','')} ({fecha_txt}) - "
                    f"${float(row.get('saldo_pendiente',0) or 0):,.0f}"
                )
            return " | ".join(refs)

        by_client = (
            cartera.groupby("cliente", as_index=False)
            .agg(
                cuentas=("cuenta_cobro","count"),
                total_facturado=("total_factura","sum"),
                total_abonado=("total_abonos","sum"),
                saldo=("saldo_pendiente","sum"),
            )
            .sort_values("saldo", ascending=False)
        )
        account_refs = {
            client: _v1013_pending_accounts(group)
            for client, group in cartera.groupby("cliente")
        }

        story.append(Paragraph("Resumen por cliente", styles["Heading2"]))
        story.append(Paragraph(
            "La columna “Cuentas pendientes” identifica el número de cuenta, "
            "la fecha de la cuenta y el saldo individual que compone la deuda del cliente.",
            styles["MXPCSmall"],
        ))
        data = [["Cliente","Cuentas pendientes (fecha y saldo)","Facturado","Abonado","Saldo"]]
        for _, r in by_client.iterrows():
            client = str(r["cliente"])
            data.append([
                Paragraph(client, styles["MXPCSmall"]),
                Paragraph(account_refs.get(client,""), styles["MXPCSmall"]),
                f"${float(r['total_facturado']):,.0f}",
                f"${float(r['total_abonado']):,.0f}",
                f"${float(r['saldo']):,.0f}",
            ])
        t = Table(
            data,
            colWidths=[6.2*cm,10.0*cm,3.7*cm,3.7*cm,3.7*cm],
            repeatRows=1
        )
        t.setStyle(TableStyle([
            ("BACKGROUND",(0,0),(-1,0),colors.HexColor("#155E42")),
            ("TEXTCOLOR",(0,0),(-1,0),colors.white),
            ("FONTNAME",(0,0),(-1,0),"Helvetica-Bold"),
            ("ALIGN",(1,1),(-1,-1),"RIGHT"),
            ("GRID",(0,0),(-1,-1),0.25,colors.HexColor("#C7D2CC")),
            ("FONTSIZE",(0,0),(-1,-1),8),
            ("VALIGN",(0,0),(-1,-1),"MIDDLE"),
            ("ROWBACKGROUNDS",(0,1),(-1,-1),[colors.white,colors.HexColor("#F5F8F6")]),
        ]))
        story += [t, PageBreak()]

        story.append(Paragraph("Detalle de cuentas pendientes", styles["Heading2"]))
        detail = [["Fecha cuenta","Días","Cliente","Cuenta de cobro","Ciudad","Facturado","Abonado","Saldo","Estado"]]
        for _, r in cartera.iterrows():
            detail.append([
                str(r.get("fecha_venta",""))[:10],
                int(r.get("dias_cartera",0) or 0),
                Paragraph(str(r.get("cliente","")), styles["MXPCSmall"]),
                str(r.get("cuenta_cobro","")),
                Paragraph(str(r.get("ciudad","")), styles["MXPCSmall"]),
                f"${float(r.get('total_factura',0) or 0):,.0f}",
                f"${float(r.get('total_abonos',0) or 0):,.0f}",
                f"${float(r.get('saldo_pendiente',0) or 0):,.0f}",
                str(r.get("estado_cartera","")),
            ])
        td = Table(
            detail,
            colWidths=[2.1*cm,1.2*cm,6.0*cm,2.2*cm,3.4*cm,3.2*cm,3.2*cm,3.2*cm,2.3*cm],
            repeatRows=1,
        )
        td.setStyle(TableStyle([
            ("BACKGROUND",(0,0),(-1,0),colors.HexColor("#155E42")),
            ("TEXTCOLOR",(0,0),(-1,0),colors.white),
            ("FONTNAME",(0,0),(-1,0),"Helvetica-Bold"),
            ("ALIGN",(1,1),(1,-1),"CENTER"),
            ("ALIGN",(5,1),(7,-1),"RIGHT"),
            ("GRID",(0,0),(-1,-1),0.25,colors.HexColor("#C7D2CC")),
            ("FONTSIZE",(0,0),(-1,-1),7.5),
            ("VALIGN",(0,0),(-1,-1),"MIDDLE"),
            ("ROWBACKGROUNDS",(0,1),(-1,-1),[colors.white,colors.HexColor("#F5F8F6")]),
        ]))
        story.append(td)

    doc.build(story)
    return Path(output_path)


SalesStore.export_cartera_pdf = _v1000_export_cartera_pdf


def _v1000_latest_friday(now: datetime) -> date:
    """Último viernes cuyo cierre debería estar disponible."""
    today = now.date()
    days_since_friday = (today.weekday() - 4) % 7
    friday = today - timedelta(days=days_since_friday)
    # El viernes antes de 17:00 todavía no se considera cierre.
    if today.weekday() == 4 and now.hour < 17:
        friday -= timedelta(days=7)
    return friday


def _v1000_maybe_generate_weekly_cartera(self):
    """Genera una vez el PDF del último cierre de viernes, sin intervención."""
    try:
        now = datetime.now()
        cutoff = _v1000_latest_friday(now)

        # No generar un reporte retroactivo antes de que exista operación.
        if not self.store.table("SELECT 1 FROM ventas LIMIT 1").shape[0]:
            return

        REPORTS_DIR.mkdir(parents=True, exist_ok=True)
        target = REPORTS_DIR / f"Cartera_semanal_{cutoff.strftime('%Y-%m-%d')}.pdf"
        if target.exists():
            return

        # Si hoy es viernes, solo después de las 17:00.
        if now.weekday() == 4 and now.hour < 17:
            return

        self.store.export_cartera_pdf(cutoff, target)
    except Exception:
        # Un reporte gerencial nunca debe impedir abrir o guardar una venta.
        pass


# Crear la carpeta y revisar reporte semanal al abrir la aplicación.
_v1000_previous_app_init = SalesFormApp.__init__
def _v1000_app_init(self, *args, **kwargs):
    _v1000_previous_app_init(self, *args, **kwargs)
    try:
        REPORTS_DIR.mkdir(parents=True, exist_ok=True)
        self.after(1600, lambda: _v1000_maybe_generate_weekly_cartera(self))
    except Exception:
        pass


SalesFormApp.__init__ = _v1000_app_init


# También revisar el cierre semanal después de cambios de ventas/abonos.
for _v1000_method_name in ("save_sale","save_payment","apply_payment"):
    _v1000_original = getattr(SalesFormApp, _v1000_method_name, None)
    if _v1000_original is None:
        continue
    def _v1000_make_wrapper(original):
        def wrapped(self, *args, **kwargs):
            result = original(self, *args, **kwargs)
            try:
                _v1000_maybe_generate_weekly_cartera(self)
            except Exception:
                pass
            return result
        return wrapped
    setattr(
        SalesFormApp,
        _v1000_method_name,
        _v1000_make_wrapper(_v1000_original),
    )


