def _v1010_clean(value) -> str:
    if value is None:
        return ""
    try:
        if pd.isna(value):
            return ""
    except Exception:
        pass
    return str(value).strip()


def _v1010_load_transporters(source_files=None) -> list[dict]:
    files = source_files if source_files is not None else read_master_sources()
    rows = {}
    for source in files or []:
        path = Path(source)
        if not path.exists():
            continue
        try:
            book = pd.ExcelFile(path)
            lookup = {str(s).strip().upper(): s for s in book.sheet_names}
            sheet = lookup.get("TRANSPORTADORAS_MAESTRO")
            if not sheet:
                book.close()
                continue
            df = pd.read_excel(book, sheet_name=sheet, nrows=1000)
            cmap = normalized_columns(df)
            def c(*opts): return first_column(cmap, *opts)
            id_col = c("TRANSPORTADORA_ID","ID_TRANSPORTADORA","ID")
            name_col = c("NOMBRE","TRANSPORTADORA","PROVEEDOR")
            type_col = c("TIPO","TIPO_DESPACHO")
            coverage_col = c("COBERTURA")
            active_col = c("ACTIVO")
            source_col = c("FUENTE_DATOS","FUENTE")
            obs_col = c("OBSERVACIONES","NOTAS")
            if name_col:
                for _, r in df.iterrows():
                    name = _v1010_clean(r.get(name_col))
                    if not name:
                        continue
                    rows[name.upper()] = {
                        "transportadora_id": _v1010_clean(r.get(id_col)) if id_col else "",
                        "nombre": name,
                        "tipo": (_v1010_clean(r.get(type_col)) if type_col else "TRANSPORTADORA").upper(),
                        "cobertura": _v1010_clean(r.get(coverage_col)) if coverage_col else "",
                        "activo": (_v1010_clean(r.get(active_col)) if active_col else "SI") or "SI",
                        "fuente_datos": _v1010_clean(r.get(source_col)) if source_col else str(path),
                        "observaciones": _v1010_clean(r.get(obs_col)) if obs_col else "",
                    }
            book.close()
        except Exception:
            try:
                book.close()
            except Exception:
                pass

    if not rows:
        for item in V1010_DEFAULT_TRANSPORTERS:
            tid,name,tipo,cobertura,activo,fuente,obs = item
            rows[name.upper()] = {
                "transportadora_id":tid,
                "nombre":name,
                "tipo":tipo,
                "cobertura":cobertura,
                "activo":activo,
                "fuente_datos":fuente,
                "observaciones":obs,
            }
    return list(rows.values())


# Enriquecer clientes provenientes de Clientes_Maestro con asesor asignado.
_v1010_previous_load_master_records = load_master_records
def _v1010_load_master_records(source_files=None):
    clientes, productos = _v1010_previous_load_master_records(source_files)
    files = source_files if source_files is not None else read_master_sources()
    assignment = {}
    for source in files or []:
        path = Path(source)
        if not path.exists():
            continue
        try:
            book = pd.ExcelFile(path)
            lookup = {str(s).strip().upper(): s for s in book.sheet_names}
            sheet = lookup.get("CLIENTES_MAESTRO")
            if not sheet:
                book.close()
                continue
            df = pd.read_excel(book, sheet_name=sheet, nrows=20000)
            cmap = normalized_columns(df)
            def c(*opts): return first_column(cmap, *opts)
            name_col = c("NOMBRE","CLIENTE")
            advisor_id_col = c("ASESOR_ID","ID_ASESOR")
            advisor_col = c("ASESOR_ASIGNADO","ASESOR")
            if name_col:
                for _, r in df.iterrows():
                    name = _v1010_clean(r.get(name_col))
                    if name:
                        assignment[name.upper()] = (
                            _v1010_clean(r.get(advisor_id_col)) if advisor_id_col else "",
                            _v1010_clean(r.get(advisor_col)) if advisor_col else "",
                        )
            book.close()
        except Exception:
            try:
                book.close()
            except Exception:
                pass

    for client in clientes:
        aid, advisor = assignment.get(
            _v1010_clean(client.get("nombre")).upper(), ("","")
        )
        client["asesor_id"] = aid
        client["asesor_asignado"] = advisor
    return clientes, productos

load_master_records = _v1010_load_master_records


def _v1010_import_transporters(self, rows: list[dict]):
    stamp = datetime.now().isoformat(timespec="seconds")
    for r in rows:
        name = _v1010_clean(r.get("nombre"))
        if not name:
            continue
        tid = _v1010_clean(r.get("transportadora_id"))
        if not tid:
            current = self.conn.execute(
                "SELECT COALESCE(MAX(CAST(transportadora_id AS INTEGER)),3000)+1 "
                "FROM transportadoras WHERE transportadora_id GLOB '[0-9]*'"
            ).fetchone()[0]
            tid = str(current or 3001)
        self.conn.execute(
            """
            INSERT INTO transportadoras (
                transportadora_id,nombre,tipo,cobertura,activo,fuente_datos,
                observaciones,ultima_modificacion,modificado_manualmente
            ) VALUES (?,?,?,?,?,?,?,?,0)
            ON CONFLICT(transportadora_id) DO UPDATE SET
                nombre=excluded.nombre,tipo=excluded.tipo,cobertura=excluded.cobertura,
                activo=excluded.activo,fuente_datos=excluded.fuente_datos,
                observaciones=excluded.observaciones,
                ultima_modificacion=excluded.ultima_modificacion
            """,
            (
                tid,name,
                (_v1010_clean(r.get("tipo")) or "TRANSPORTADORA").upper(),
                _v1010_clean(r.get("cobertura")),
                (_v1010_clean(r.get("activo")) or "SI").upper(),
                _v1010_clean(r.get("fuente_datos")),
                _v1010_clean(r.get("observaciones")),
                stamp,
            ),
        )
    self.conn.commit()

SalesStore.import_transporters = _v1010_import_transporters


def _v1010_assign_advisors_from_history(self):
    """Completa solo clientes sin asesor, usando frecuencia histórica; empate = venta más reciente."""
    clients = self.table(
        "SELECT nombre,asesor_id,asesor_asignado FROM clientes"
    )
    if clients.empty:
        return
    sales = self.table(
        """
        SELECT cliente,asesor,fecha,COALESCE(ultima_modificacion,'') ultima_modificacion
          FROM ventas
         WHERE UPPER(COALESCE(estado_venta,'')) <> 'ANULADA'
           AND TRIM(COALESCE(asesor,'')) <> ''
        """
    )
    advisors = self.table(
        "SELECT asesor_id,nombre FROM asesores WHERE COALESCE(activo,'SI') <> 'NO'"
    )
    aid_map = {
        _v1010_clean(r.get("nombre")).upper(): _v1010_clean(r.get("asesor_id"))
        for _,r in advisors.iterrows()
    } if not advisors.empty else {}

    if sales.empty:
        return
    for _, client in clients.iterrows():
        if _v1010_clean(client.get("asesor_asignado")):
            continue
        name = _v1010_clean(client.get("nombre"))
        group = sales[sales["cliente"].astype(str).str.strip().str.upper()==name.upper()]
        if group.empty:
            continue
        counts = group["asesor"].astype(str).str.strip().str.upper().value_counts()
        if counts.empty:
            continue
        max_count = int(counts.max())
        candidates = set(counts[counts==max_count].index.tolist())
        g = group[group["asesor"].astype(str).str.strip().str.upper().isin(candidates)].copy()
        g["_sort"] = g["fecha"].astype(str) + "|" + g["ultima_modificacion"].astype(str)
        chosen = _v1010_clean(g.sort_values("_sort",ascending=False).iloc[0]["asesor"]).upper()
        self.conn.execute(
            """
            UPDATE clientes
               SET asesor_id=?, asesor_asignado=?
             WHERE nombre=? AND TRIM(COALESCE(asesor_asignado,''))=''
            """,
            (aid_map.get(chosen,""),chosen,name),
        )
    self.conn.commit()


# El esquema debe existir antes de que init_schema invoque seed_master_data().
_v1010_previous_seed_master_data = SalesStore.seed_master_data
def _v1010_seed_master_data(self):
    self.ensure_column("clientes","asesor_id","TEXT")
    self.ensure_column("clientes","asesor_asignado","TEXT")
    self.ensure_column("ventas","transportadora_id","TEXT")
    self.ensure_column("ventas","transportadora","TEXT")
    self.ensure_column("ventas","tipo_despacho","TEXT")
    self.conn.execute(
        """
        CREATE TABLE IF NOT EXISTS transportadoras (
            transportadora_id TEXT PRIMARY KEY,
            nombre TEXT NOT NULL UNIQUE,
            tipo TEXT NOT NULL DEFAULT 'TRANSPORTADORA',
            cobertura TEXT,
            activo TEXT NOT NULL DEFAULT 'SI',
            fuente_datos TEXT,
            observaciones TEXT,
            ultima_modificacion TEXT,
            modificado_manualmente INTEGER NOT NULL DEFAULT 0
        )
        """
    )
    self.conn.commit()

    _v1010_previous_seed_master_data(self)
    self.import_transporters(_v1010_load_transporters())
    _v1010_assign_advisors_from_history(self)

SalesStore.seed_master_data = _v1010_seed_master_data


# Importar asesor_id / asesor_asignado luego del importador histórico de clientes.
