def _v1010_import_master_records(self, clientes, productos, source_path=""):
    result = _v1010_previous_import_master_records(
        self,clientes,productos,source_path
    )
    for c in clientes:
        name = _v1010_clean(c.get("nombre"))
        if not name:
            continue
        aid = _v1010_clean(c.get("asesor_id"))
        advisor = _v1010_clean(c.get("asesor_asignado")).upper()
        if aid or advisor:
            self.conn.execute(
                """
                UPDATE clientes SET asesor_id=?, asesor_asignado=?
                 WHERE nombre=?
                """,
                (aid,advisor,name),
            )
    self.conn.commit()
    _v1010_assign_advisors_from_history(self)
    return result

