# Pasar campos logísticos al store sin reescribir la lógica validada de save_sale.
_v1010_previous_save_sale = SalesFormApp.save_sale
def _v1010_save_sale(self):
    _v1010_resolve_transporter(self)
    self.store._v1010_transportadora = self.vars.get(
        "venta_transportadora",tk.StringVar(value="")
    ).get().strip()
    self.store._v1010_transportadora_id = self.vars.get(
        "venta_transportadora_id",tk.StringVar(value="")
    ).get().strip()
    self.store._v1010_tipo_despacho = self.vars.get(
        "venta_tipo_despacho",tk.StringVar(value="")
    ).get().strip()
    try:
        return _v1010_previous_save_sale(self)
    finally:
        for attr in (
            "_v1010_transportadora","_v1010_transportadora_id",
            "_v1010_tipo_despacho"
        ):
            try:
                delattr(self.store,attr)
            except Exception:
                pass

SalesFormApp.save_sale = _v1010_save_sale


