# Guardar cliente con asesor asociado.
def _v1010_save_client(self):
    try:
        new_name=self.require("cli_nombre","Nombre del cliente")
        old_name=getattr(self,"editing_client_name",None)
        if old_name and old_name!=new_name:
            self.store.rename_client(old_name,new_name)

        advisor = self.vars.get(
            "cli_asesor",tk.StringVar(value="")
        ).get().strip().upper()
        aid=""
        if advisor:
            row=self.store.table(
                "SELECT asesor_id FROM asesores WHERE UPPER(TRIM(nombre))=? LIMIT 1",
                (advisor,),
            )
            if not row.empty:
                aid=_v1010_clean(row.iloc[0].get("asesor_id"))

        self.store.upsert_cliente({
            "nombre":new_name,
            "ciudad":self.vars["cli_ciudad"].get().strip(),
            "direccion":self.vars["cli_direccion"].get().strip(),
            "telefono":self.vars["cli_telefono"].get().strip(),
            "email":self.vars["cli_email"].get().strip(),
            "notas":self.vars["cli_notas"].get().strip(),
            "asesor_id":aid,
            "asesor_asignado":advisor,
            "fuente_origen":"Creado/actualizado en la app",
        })
        self.editing_client_name=new_name
        self.reload_master_catalogs()
        self.refresh_all()
        try:
            self.store.export_daily_snapshot()
        except Exception:
            pass
        messagebox.showinfo(
            "Cliente guardado",
            "El cliente quedó actualizado, incluido su asesor asignado."
        )
    except Exception as exc:
        messagebox.showerror("Error",str(exc))

SalesFormApp.save_client = _v1010_save_client


