def _v1010_on_transporter_select(self,_event=None):
    if not hasattr(self,"transporters_tree"):
        return
    selected=self.transporters_tree.selection()
    if not selected:
        return
    values=self.transporters_tree.item(selected[0],"values")
    if not values:
        return
    tid=str(values[0] or "").strip()
    row=self.store.table(
        "SELECT * FROM transportadoras WHERE transportadora_id=? LIMIT 1",
        (tid,),
    )
    if row.empty:
        return
    r=row.iloc[0]
    mapping={
        "trans_id":"transportadora_id",
        "trans_nombre":"nombre",
        "trans_tipo":"tipo",
        "trans_cobertura":"cobertura",
        "trans_activo":"activo",
        "trans_obs":"observaciones",
    }
    for key,col in mapping.items():
        if key in self.vars:
            self.vars[key].set(_v1010_clean(r.get(col)))

