def _v1014_refresh_payment_plan(self):
    rows=[]; total_saldo=0; total_apply=0
    for x in self.payment_plan:
        saldo=float(x.get("saldo",0) or 0)
        apply=float(x.get("valor_aplicado",0) or 0)
        rows.append((
            x["cuenta_cobro"],x.get("fecha_cuenta",""),x["cliente"],
            f"{saldo:,.0f}",f"{apply:,.0f}",f"{max(saldo-apply,0):,.0f}"
        ))
        total_saldo+=saldo; total_apply+=apply
    self.fill_tree(self.payment_plan_tree,rows)
    recibido=money(self.vars.get("abono_valor",tk.StringVar(value="0")).get())
    diferencia=recibido-total_apply
    self.vars["abono_balance_info"].set(
        f"Saldo seleccionado: ${total_saldo:,.0f} | "
        f"Recibido: ${recibido:,.0f} | Aplicado: ${total_apply:,.0f} | "
        f"Sin aplicar: ${max(diferencia,0):,.0f}"
    )

