# ==================== V10.1.8 CONTROL / ANULACIÓN DE ABONOS ====================

# Política de auditoría:
# - Un abono ya registrado no se edita en sitio.
# - Si fue aplicado y está errado, se ANULA con motivo obligatorio.
# - La anulación conserva el abono original y una copia íntegra de sus aplicaciones
#   en una tabla de auditoría, pero retira las aplicaciones activas para restituir cartera.
# - El ID de un abono anulado nunca se reutiliza.

_v1015_previous_seed_master_data = SalesStore.seed_master_data
def _v1015_seed_master_data(self):
    self.ensure_column("abonos", "estado_registro", "TEXT NOT NULL DEFAULT 'ACTIVO'")
    self.ensure_column("abonos", "fecha_anulacion", "TEXT")
    self.ensure_column("abonos", "motivo_anulacion", "TEXT")
    self.ensure_column("abonos", "anulado_por", "TEXT")
    self.conn.execute(
        """
        CREATE TABLE IF NOT EXISTS anulaciones_abonos (
            id_anulacion INTEGER PRIMARY KEY AUTOINCREMENT,
            id_abono TEXT NOT NULL,
            fecha_anulacion TEXT NOT NULL,
            motivo_anulacion TEXT NOT NULL,
            datos_abono_json TEXT NOT NULL,
            aplicaciones_json TEXT NOT NULL,
            cuentas_afectadas TEXT,
            valor_abono REAL NOT NULL DEFAULT 0
        )
        """
    )
    self.conn.commit()
    _v1015_previous_seed_master_data(self)

SalesStore.seed_master_data = _v1015_seed_master_data


def _v1015_payment_status(self, payment_id: str) -> dict:
    pid = str(payment_id or "").strip()
    if not pid:
        return {}
    ab = self.table(
        """
        SELECT *, COALESCE(estado_registro,'ACTIVO') AS estado_registro_calc
          FROM abonos
         WHERE id_abono=?
         LIMIT 1
        """,
        (pid,),
    )
    if ab.empty:
        return {}
    apps = self.table(
        """
        SELECT * FROM aplicacion_abonos
         WHERE id_abono=?
         ORDER BY orden_aplicacion,id_aplicacion
        """,
        (pid,),
    )
    r = ab.iloc[0].to_dict()
    r["num_aplicaciones"] = int(len(apps))
    r["total_aplicado_actual"] = float(
        pd.to_numeric(apps["valor_aplicado"], errors="coerce").fillna(0).sum()
    ) if not apps.empty else 0.0
    r["cuentas_actuales"] = (
        " | ".join(
            f"{x.get('cuenta_cobro','')} (${float(x.get('valor_aplicado',0) or 0):,.0f})"
            for _, x in apps.iterrows()
        )
        if not apps.empty else ""
    )
    return r

SalesStore.payment_status = _v1015_payment_status


def _v1015_possible_duplicate_payment(self, payment: dict) -> dict:
    """Busca duplicados probables sin asumir que todo pago del mismo valor es duplicado."""
    pid = str(payment.get("id_abono","") or "").strip()
    client = str(payment.get("cliente","") or "").strip()
    fecha = str(payment.get("fecha_abono","") or "").strip()
    referencia = str(payment.get("referencia_pago","") or "").strip()
    amount = float(payment.get("valor_abono",0) or 0)

    if pid:
        current = self.table(
            """
            SELECT id_abono,fecha_abono,cliente,valor_abono,
                   COALESCE(estado_registro,'ACTIVO') estado_registro
              FROM abonos
             WHERE id_abono=?
             LIMIT 1
            """,
            (pid,),
        )
        if not current.empty:
            r = current.iloc[0]
            return {
                "tipo":"ID_EXISTENTE",
                "bloquear":True,
                "id_abono":str(r["id_abono"]),
                "detalle":(
                    f"El ID {r['id_abono']} ya está registrado "
                    f"({r['fecha_abono']} / {r['cliente']} / ${float(r['valor_abono'] or 0):,.0f})."
                ),
            }

    if referencia:
        ref = self.table(
            """
            SELECT id_abono,fecha_abono,cliente,referencia_pago,valor_abono
              FROM abonos
             WHERE UPPER(TRIM(COALESCE(referencia_pago,'')))=UPPER(TRIM(?))
               AND COALESCE(estado_registro,'ACTIVO')='ACTIVO'
             ORDER BY fecha_abono DESC,id_abono DESC
             LIMIT 1
            """,
            (referencia,),
        )
        if not ref.empty:
            r = ref.iloc[0]
            return {
                "tipo":"REFERENCIA_DUPLICADA",
                "bloquear":True,
                "id_abono":str(r["id_abono"]),
                "detalle":(
                    f"La referencia {referencia} ya fue usada en el abono {r['id_abono']} "
                    f"del {r['fecha_abono']} por ${float(r['valor_abono'] or 0):,.0f}."
                ),
            }

    # Sin referencia única, misma fecha + cliente + valor es solo una ALERTA,
    # porque pueden existir pagos reales idénticos.
    if client and fecha and amount > 0:
        same = self.table(
            """
            SELECT id_abono,fecha_abono,cliente,valor_abono,referencia_pago
              FROM abonos
             WHERE UPPER(TRIM(cliente))=UPPER(TRIM(?))
               AND fecha_abono=?
               AND ABS(COALESCE(valor_abono,0)-?)<=1
               AND COALESCE(estado_registro,'ACTIVO')='ACTIVO'
             ORDER BY id_abono DESC
             LIMIT 1
            """,
            (client,fecha,amount),
        )
        if not same.empty:
            r = same.iloc[0]
            return {
                "tipo":"POSIBLE_DUPLICADO",
                "bloquear":False,
                "id_abono":str(r["id_abono"]),
                "detalle":(
                    f"Ya existe el abono {r['id_abono']} del {r['fecha_abono']} "
                    f"para {r['cliente']} por ${float(r['valor_abono'] or 0):,.0f}."
                ),
            }
    return {}

SalesStore.possible_duplicate_payment = _v1015_possible_duplicate_payment


# Mejorar el mensaje de la protección que ya existía por ID.
_v1015_previous_register_payment_batch = SalesStore.register_payment_batch
def _v1015_register_payment_batch(self, payment:dict, allocations:list[dict]) -> dict:
    pid = str(payment.get("id_abono","") or "").strip()
    existing = self.payment_status(pid) if pid else {}
    if existing:
        if str(existing.get("estado_registro_calc","ACTIVO")).upper() == "ANULADO":
            raise ValueError(
                f"El abono {pid} ya existe y fue ANULADO. Por auditoría su ID no puede reutilizarse. "
                "Registre el pago correcto con un nuevo ID."
            )
        if int(existing.get("num_aplicaciones",0) or 0) > 0:
            raise ValueError(
                f"El abono {pid} ya fue registrado y aplicado a "
                f"{existing.get('num_aplicaciones',0)} cuenta(s). No se puede modificar ni sobrescribir. "
                "Si está errado, seleccione el abono y use 'Anular abono'."
            )
        raise ValueError(
            f"El abono {pid} ya está registrado. No se sobrescribe un abono existente; "
            "utilice un nuevo ID o anule el registro si corresponde."
        )
    return _v1015_previous_register_payment_batch(self,payment,allocations)

SalesStore.register_payment_batch = _v1015_register_payment_batch


def _v1015_cancel_payment(self, payment_id:str, reason:str, cancelled_by:str="USUARIO") -> dict:
    pid = str(payment_id or "").strip()
    reason = str(reason or "").strip()
    if not pid:
        raise ValueError("Seleccione un abono para anular.")
    if not reason:
        raise ValueError("El motivo de anulación es obligatorio para auditoría.")

    ab = self.table(
        """
        SELECT * FROM abonos
         WHERE id_abono=?
         LIMIT 1
        """,
        (pid,),
    )
    if ab.empty:
        raise ValueError(f"No existe el abono {pid}.")
    ab_row = ab.iloc[0].to_dict()
    if str(ab_row.get("estado_registro","ACTIVO") or "ACTIVO").upper() == "ANULADO":
        raise ValueError(
            f"El abono {pid} ya fue anulado el {ab_row.get('fecha_anulacion','')}."
        )

    apps = self.table(
        """
        SELECT * FROM aplicacion_abonos
         WHERE id_abono=?
         ORDER BY orden_aplicacion,id_aplicacion
        """,
        (pid,),
    )
    accounts = list(dict.fromkeys(
        str(x).strip() for x in apps.get("cuenta_cobro",pd.Series(dtype=str)).tolist()
        if str(x).strip()
    ))

    before = {}
    for account in accounts:
        try:
            before[account] = self.sale_snapshot(account)
        except Exception:
            before[account] = {}

    now = datetime.now().isoformat(timespec="seconds")
    ab_json = json.dumps(ab_row, ensure_ascii=False, default=str)
    apps_json = json.dumps(
        apps.to_dict(orient="records") if not apps.empty else [],
        ensure_ascii=False, default=str
    )

    cur = self.conn.cursor()
    try:
        cur.execute("BEGIN IMMEDIATE")
        cur.execute(
            """
            INSERT INTO anulaciones_abonos (
                id_abono,fecha_anulacion,motivo_anulacion,datos_abono_json,
                aplicaciones_json,cuentas_afectadas,valor_abono
            ) VALUES (?,?,?,?,?,?,?)
            """,
            (
                pid,now,reason,ab_json,apps_json," | ".join(accounts),
                float(ab_row.get("valor_abono",0) or 0)
            ),
        )
        # Las aplicaciones salen del saldo activo, pero quedan preservadas en
        # anulaciones_abonos como evidencia íntegra de lo que se revirtió.
        cur.execute("DELETE FROM aplicacion_abonos WHERE id_abono=?", (pid,))
        cur.execute(
            """
            UPDATE abonos
               SET estado_registro='ANULADO',
                   fecha_anulacion=?,
                   motivo_anulacion=?,
                   anulado_por=?
             WHERE id_abono=?
            """,
            (now,reason,cancelled_by,pid),
        )
        self.conn.commit()
    except Exception:
        self.conn.rollback()
        raise

    # Recalcular cada cuenta cuya aplicación fue revertida.
    summary = self.sales_summary()
    changed = []
    for account in accounts:
        row = summary[summary["cuenta_cobro"].astype(str)==account]
        if row.empty:
            continue
        r = row.iloc[0]
        total = float(r.get("total_factura",0) or 0)
        paid = float(r.get("total_abonos",0) or 0)
        balance = max(total-paid,0)
        state = (
            "Pagado" if total > 0 and balance <= 1
            else "Parcial" if paid > 1
            else "Pendiente"
        )
        self.conn.execute(
            """
            UPDATE ventas
               SET estado_pago=?,ultima_modificacion=?
             WHERE cuenta_cobro=?
            """,
            (state,now,account),
        )
        changed.append((account,state,balance))
    self.conn.commit()

    # Historial de cambios sobre las cuentas afectadas.
    for account,_state,_balance in changed:
        try:
            after = self.sale_snapshot(account)
            self.log_snapshot_changes(
                "Venta",account,before.get(account,{}),after,
                f"ANULACION_ABONO {pid}: {reason}"
            )
        except Exception:
            pass

    return {
        "id_abono":pid,
        "valor":float(ab_row.get("valor_abono",0) or 0),
        "cuentas":accounts,
        "motivo":reason,
        "fecha_anulacion":now,
        "cuentas_actualizadas":changed,
    }

SalesStore.cancel_payment = _v1015_cancel_payment


