def _v1016_export_payment_control(self,output_path=None):
    target=Path(_v1016_previous_export_payment_control(self,output_path))
    _v1016_apply_payment_trace_to_export(self,target)
    return target

SalesStore.export_payment_control = _v1016_export_payment_control

