V1017_COLOMBIA_TZ = ZoneInfo("America/Bogota")
V1017_CARTEra_HOUR = 15


def _v1017_norm_sale_status(value: str) -> str:
    s = str(value or "").strip().upper()
    aliases = {
        "EMITIDO":"EMITIDA",
        "EMITIDA":"EMITIDA",
        "PARCIAL":"PARCIAL",
        "PAGADO":"PAGADA",
        "PAGADA":"PAGADA",
        "ANULADO":"ANULADA",
        "ANULADA":"ANULADA",
    }
    return aliases.get(s, s or "EMITIDA")


def _v1017_norm_payment_status(value: str) -> str:
    s = str(value or "").strip().upper()
    aliases = {
        "PENDIENTE":"Pendiente",
        "PARCIAL":"Parcial",
        "PAGADO":"Pagado",
        "PAGADA":"Pagado",
        "MIXTO":"Mixto",
        "ANULADO":"Anulada",
        "ANULADA":"Anulada",
    }
    return aliases.get(s, str(value or "").strip() or "Pendiente")


def _v1017_expected_sale_status(payment_status: str) -> str:
    """
    Relación oficial:
      Pendiente -> EMITIDA
      Parcial   -> PARCIAL
      Pagado    -> PAGADA
      Mixto     -> PAGADA   (varios medios, factura totalmente pagada)
    """
    p = _v1017_norm_payment_status(payment_status)
    if p == "Pendiente":
        return "EMITIDA"
    if p == "Parcial":
        return "PARCIAL"
    if p in {"Pagado","Mixto"}:
        return "PAGADA"
    if p == "Anulada":
        return "ANULADA"
    return "EMITIDA"


def _v1017_payment_status_from_amounts(total_factura: float, total_abonos: float, num_payments: int = 0) -> str:
    total = float(total_factura or 0)
    paid = float(total_abonos or 0)
    balance = max(total - paid, 0)
    if total <= 0:
        return "Pendiente"
    if balance <= 1 and paid > 0:
        return "Mixto" if int(num_payments or 0) > 1 else "Pagado"
    if paid > 1:
        return "Parcial"
    return "Pendiente"


def _v1017_sync_status_values(sale_status: str, payment_status: str) -> tuple[str,str,bool,str]:
    """
    Devuelve (estado_venta, estado_pago, changed, mensaje).
    ANULADA es terminal y no se transforma automáticamente a otro estado.
    """
    s = _v1017_norm_sale_status(sale_status)
    p = _v1017_norm_payment_status(payment_status)

    if s == "ANULADA":
        changed = p != "Anulada"
        msg = (
            "La venta está ANULADA. Por coherencia, su estado de pago también "
            "se registrará como Anulada."
        ) if changed else ""
        return "ANULADA","Anulada",changed,msg

    expected = _v1017_expected_sale_status(p)
    if s != expected:
        msg = (
            f"Los estados no son coherentes:\n\n"
            f"Estado de la factura: {s}\n"
            f"Estado de pago: {p}\n\n"
            f"Se ajustará automáticamente el estado de la factura a {expected}."
        )
        return expected,p,True,msg
    return s,p,False,""


def _v1017_apply_status_to_account(self, cuenta_cobro: str) -> dict:
    """Recalcula ambos estados usando pagos activos y mantiene ANULADA como terminal."""
    account = str(cuenta_cobro or "").strip()
    if not account:
        return {}
    sale = self.table(
        """
        SELECT cuenta_cobro,estado_venta,estado_pago
          FROM ventas WHERE cuenta_cobro=? LIMIT 1
        """,
        (account,),
    )
    if sale.empty:
        return {}
    current_sale = _v1017_norm_sale_status(sale.iloc[0].get("estado_venta"))
    if current_sale == "ANULADA":
        self.conn.execute(
            "UPDATE ventas SET estado_pago='Anulada', ultima_modificacion=? WHERE cuenta_cobro=?",
            (datetime.now().isoformat(timespec="seconds"), account),
        )
        self.conn.commit()
        return {"estado_venta":"ANULADA","estado_pago":"Anulada"}

    summary = self.sales_summary()
    row = summary[summary["cuenta_cobro"].astype(str) == account]
    if row.empty:
        return {}
    total = float(row.iloc[0].get("total_factura",0) or 0)
    paid = float(row.iloc[0].get("total_abonos",0) or 0)
    apps = self.table(
        """
        SELECT COUNT(DISTINCT a.id_abono) cantidad
          FROM aplicacion_abonos a
          JOIN abonos b ON b.id_abono=a.id_abono
         WHERE a.cuenta_cobro=?
           AND COALESCE(b.estado_registro,'ACTIVO') <> 'ANULADO'
        """,
        (account,),
    )
    n = int(apps.iloc[0]["cantidad"] or 0) if not apps.empty else 0
    payment_status = _v1017_payment_status_from_amounts(total,paid,n)
    sale_status = _v1017_expected_sale_status(payment_status)
    now = datetime.now().isoformat(timespec="seconds")
    self.conn.execute(
        """
        UPDATE ventas
           SET estado_venta=?, estado_pago=?, ultima_modificacion=?
         WHERE cuenta_cobro=?
        """,
        (sale_status,payment_status,now,account),
    )
    self.conn.commit()
    return {
        "estado_venta":sale_status,
        "estado_pago":payment_status,
        "total_factura":total,
        "total_abonos":paid,
        "saldo":max(total-paid,0),
    }

SalesStore.sync_account_status = _v1017_apply_status_to_account


# Al guardar venta, corregir combinaciones antes de persistir.
_v1017_previous_save_sale = SalesFormApp.save_sale
def _v1017_save_sale(self):
    sale_status = self.vars.get("venta_estado",tk.StringVar(value="EMITIDA")).get()
    pay_status = self.vars.get("venta_estado_pago",tk.StringVar(value="Pendiente")).get()

    new_sale,new_pay,changed,msg = _v1017_sync_status_values(sale_status,pay_status)

    # ANULADA no puede conservar pagos activos cargados en el formulario.
    if new_sale == "ANULADA" and getattr(self,"payment_lines",[]):
        if not messagebox.askyesno(
            "Venta anulada con pagos",
            "La venta está marcada como ANULADA, pero el formulario contiene pagos.\n\n"
            "Una venta anulada no puede registrar pagos activos. "
            "Si continúa, debe quitar primero los pagos del formulario.\n\n"
            "¿Desea volver al formulario para corregirlo?"
        ):
            return
        return

    if changed:
        messagebox.showwarning("Estados ajustados",msg)
        self.vars["venta_estado"].set(new_sale)
        self.vars["venta_estado_pago"].set(new_pay)

    result = _v1017_previous_save_sale(self)

    # Después del guardado, recalcular desde las aplicaciones reales.
    try:
        account = self.vars.get("venta_factura",tk.StringVar()).get().strip()
        if account:
            self.store.sync_account_status(account)
            self.refresh_all()
    except Exception:
        pass
    return result

SalesFormApp.save_sale = _v1017_save_sale


# Avisar inmediatamente cuando el usuario cambia manualmente alguno de los dos estados.
def _v1017_preview_state_consistency(self,_event=None):
    sale_status = self.vars.get("venta_estado",tk.StringVar(value="EMITIDA")).get()
    pay_status = self.vars.get("venta_estado_pago",tk.StringVar(value="Pendiente")).get()
    ns,np,changed,_msg = _v1017_sync_status_values(sale_status,pay_status)
    if changed and ns != "ANULADA":
        try:
            self.vars["venta_observacion_estado"].set(
                f"Estados por ajustar: {sale_status}/{pay_status} → {ns}/{np}. "
                "Al guardar se corregirán automáticamente."
            )
        except Exception:
            pass


