# Migración correctiva al abrir: sincroniza combinaciones incoherentes existentes,
# sin tocar ventas ANULADAS.
def _v1017_repair_existing_statuses(self):
    sales = self.table(
        """
        SELECT cuenta_cobro,estado_venta,estado_pago
          FROM ventas
        """
    )
    repaired = []
    for _,r in sales.iterrows():
        account = str(r.get("cuenta_cobro","") or "").strip()
        if not account:
            continue
        old_sale = _v1017_norm_sale_status(r.get("estado_venta"))
        old_pay = _v1017_norm_payment_status(r.get("estado_pago"))
        try:
            new = self.sync_account_status(account)
        except Exception:
            continue
        ns = new.get("estado_venta",old_sale)
        np = new.get("estado_pago",old_pay)
        if ns != old_sale or np != old_pay:
            repaired.append((account,old_sale,old_pay,ns,np))
    return repaired

SalesStore.repair_existing_statuses = _v1017_repair_existing_statuses


