# ---------- Reglas de producto ----------
def _v1020_product_change_preview(self, row:dict) -> tuple[dict,list[str]]:
    code=_v1020_text(row.get("CODIGO_PRODUCTO"))
    if not code:
        return {},[]
    current=self.table("SELECT * FROM productos WHERE codigo=? LIMIT 1",(code,))
    if current.empty:
        return {},[]
    cur=current.iloc[0]
    proposed={}
    warnings=[]

    requested_name=_v1020_text(row.get("NUEVO_NOMBRE"))
    requested_unit=_v1020_text(row.get("NUEVA_UNIDAD")).upper()
    requested_cost=row.get("NUEVO_COSTO_MAESTRO")
    requested_price=row.get("NUEVO_PRECIO_VENTA")
    requested_comm=row.get("NUEVA_COMISION")
    requested_fresh=_v1020_text(row.get("NUEVO_PRODUCTO_FRESCO")).upper()
    requested_iva=_v1020_text(row.get("NUEVO_IVA_APLICA")).upper()

    if requested_name and requested_name != _v1020_text(cur.get("nombre")):
        proposed["nombre"]=requested_name
        warnings.append(f"NOMBRE: {_v1020_text(cur.get('nombre'))} → {requested_name}")
    if requested_unit and requested_unit != _v1020_text(cur.get("unidad")).upper():
        proposed["unidad"]=requested_unit
        warnings.append(
            f"UNIDAD (CAMBIO SENSIBLE): {_v1020_text(cur.get('unidad'))} → {requested_unit}. "
            "No se convierten ventas históricas; el stock queda definido por el conteo físico."
        )
    if _v1020_text(requested_cost) != "":
        val=_v1020_num(requested_cost)
        if abs(val-_v1020_num(cur.get("costo")))>0.0001:
            proposed["costo"]=val
            warnings.append(f"COSTO MAESTRO: ${_v1020_num(cur.get('costo')):,.0f} → ${val:,.0f}")
    if _v1020_text(requested_price) != "":
        val=_v1020_num(requested_price)
        if abs(val-_v1020_num(cur.get("precio_venta")))>0.0001:
            proposed["precio_venta"]=val
            warnings.append(f"PRECIO VENTA: ${_v1020_num(cur.get('precio_venta')):,.0f} → ${val:,.0f}")
    if _v1020_text(requested_comm) != "":
        val=_v1020_num(requested_comm)
        if abs(val-_v1020_num(cur.get("comision_unitaria_sugerida")))>0.0001:
            proposed["comision_unitaria_sugerida"]=val
            warnings.append(
                f"COMISIÓN: ${_v1020_num(cur.get('comision_unitaria_sugerida')):,.0f} → ${val:,.0f}"
            )
    if requested_fresh in {"SI","NO"} and requested_fresh != _v1020_text(cur.get("producto_fresco")).upper():
        proposed["producto_fresco"]=requested_fresh
        warnings.append(f"PRODUCTO FRESCO: {_v1020_text(cur.get('producto_fresco'))} → {requested_fresh}")
    if requested_iva in {"SI","NO"} and requested_iva != _v1020_text(cur.get("iva_aplica")).upper():
        proposed["iva_aplica"]=requested_iva
        warnings.append(f"IVA APLICA: {_v1020_text(cur.get('iva_aplica'))} → {requested_iva}")

    if proposed.get("producto_fresco")=="SI":
        proposed["iva_aplica"]="NO"
        if "IVA APLICA" not in " ".join(warnings):
            warnings.append("IVA APLICA se forzará a NO porque PRODUCTO_FRESCO=SI.")

    return proposed,warnings

SalesStore.product_change_preview = _v1020_product_change_preview


def _v1020_apply_product_changes(self, code:str, changes:dict, responsable:str="", observacion:str=""):
    if not changes:
        return
    current=self.table("SELECT * FROM productos WHERE codigo=? LIMIT 1",(code,))
    if current.empty:
        raise ValueError(f"No existe el producto {code}.")
    cur=current.iloc[0].to_dict()
    allowed={
        "nombre","unidad","costo","precio_venta","comision_unitaria_sugerida",
        "producto_fresco","iva_aplica"
    }
    fields=[k for k in changes if k in allowed]
    if not fields:
        return
    sets=", ".join(f"{f}=?" for f in fields)
    vals=[changes[f] for f in fields]
    vals.append(code)
    self.conn.execute(f"UPDATE productos SET {sets} WHERE codigo=?",vals)
    now=datetime.now().isoformat(timespec="seconds")
    for f in fields:
        self.conn.execute(
            """
            INSERT INTO inventario_cambios_producto
            (fecha_hora,codigo_producto,campo,valor_anterior,valor_nuevo,origen,responsable,observacion)
            VALUES (?,?,?,?,?,'INVENTARIO',?,?)
            """,
            (now,code,f,_v1020_text(cur.get(f)),_v1020_text(changes[f]),responsable,observacion),
        )
    self.conn.commit()

SalesStore.apply_product_changes = _v1020_apply_product_changes


# ---------- Movimientos ----------
def _v1020_register_inventory_movement(self, data:dict) -> dict:
    movement_type=_v1020_text(data.get("tipo_movimiento")).upper()
    if movement_type not in V1020_INVENTORY_MOVEMENT_TYPES:
        raise ValueError(f"Tipo de movimiento inválido: {movement_type}")

    code=_v1020_text(data.get("codigo_producto"))
    if not code:
        raise ValueError("El código de producto es obligatorio.")
    product=self.table("SELECT * FROM productos WHERE codigo=? LIMIT 1",(code,))
    if product.empty:
        raise ValueError(f"No existe el producto {code}.")
    p=product.iloc[0]
    old=_v1020_num(p.get("stock_actual"))
    qty=abs(_v1020_num(data.get("cantidad_movimiento")))
    if qty <= 0 and movement_type!="AJUSTE_CONTEO":
        raise ValueError("La cantidad del movimiento debe ser mayor que cero.")

    if movement_type=="AJUSTE_CONTEO":
        new=max(_v1020_num(data.get("cantidad_movimiento")),0)
        delta=new-old
    elif movement_type in {"ENTRADA","AJUSTE_POSITIVO","DEVOLUCION_CLIENTE","OBSEQUIO"}:
        delta=qty
        new=old+qty
    elif movement_type in {"SALIDA","AJUSTE_NEGATIVO","MERMA","DEVOLUCION_PROVEEDOR","VENTA"}:
        delta=-qty
        new=old-qty
        if new < -0.0001:
            raise ValueError(
                f"Stock insuficiente para {p['nombre']}. Disponible: {old:,.2f} {p['unidad']}; "
                f"movimiento solicitado: {qty:,.2f}."
            )
        new=max(new,0)
    else:
        raise ValueError("Movimiento no soportado.")

    mid=_v1020_text(data.get("id_movimiento"))
    if not mid:
        mid=f"INV-{datetime.now().strftime('%Y%m%d%H%M%S%f')}"
    exists=self.table("SELECT 1 FROM inventario_movimientos WHERE id_movimiento=?",(mid,))
    if not exists.empty:
        raise ValueError(f"El movimiento {mid} ya fue registrado. No se duplica.")

    unit=_v1020_text(data.get("unidad")) or _v1020_text(p.get("unidad"))
    cost=_v1020_num(data.get("costo_unitario_entrada"))
    now=datetime.now().isoformat(timespec="seconds")
    fecha=_v1020_text(data.get("fecha_hora")) or now

    cur=self.conn.cursor()
    try:
        cur.execute("BEGIN IMMEDIATE")
        cur.execute(
            """
            INSERT INTO inventario_movimientos (
                id_movimiento,fecha_hora,tipo_movimiento,documento_referencia,
                codigo_producto,producto,unidad,lote,fecha_vencimiento,ubicacion,
                saldo_antes,cantidad_movimiento,saldo_despues,costo_unitario_entrada,
                costo_total_movimiento,responsable,soporte,observacion,origen,estado,fecha_cargue
            ) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)
            """,
            (
                mid,fecha,movement_type,_v1020_text(data.get("documento_referencia")),
                code,_v1020_text(p.get("nombre")),unit,_v1020_text(data.get("lote")),
                _v1020_text(data.get("fecha_vencimiento")),_v1020_text(data.get("ubicacion")),
                old,delta,new,cost,abs(delta)*cost,_v1020_text(data.get("responsable")),
                _v1020_text(data.get("soporte")),_v1020_text(data.get("observacion")),
                _v1020_text(data.get("origen")) or "MANUAL","APLICADO",now
            ),
        )
        cur.execute(
            """
            UPDATE productos
               SET stock_actual=?, ultima_modificacion=?, modificado_manualmente=1
             WHERE codigo=?
            """,
            (new,now,code),
        )
        self.conn.commit()
    except Exception:
        self.conn.rollback()
        raise

    return {"id_movimiento":mid,"codigo":code,"saldo_antes":old,"delta":delta,"saldo_despues":new}

SalesStore.register_inventory_movement = _v1020_register_inventory_movement


def _v1020_inventory_movements(self, limit:int=1000):
    return self.table(
        """
        SELECT * FROM inventario_movimientos
        ORDER BY fecha_hora DESC, fecha_cargue DESC
        LIMIT ?
        """,(limit,)
    )

SalesStore.inventory_movements = _v1020_inventory_movements


# ---------- Importar Excel ----------
def _v1020_import_inventory_excel(self, path:Path, confirm_changes_callback=None) -> dict:
    df=pd.read_excel(path,sheet_name="Carga_App")
    df.columns=[str(c).strip().upper() for c in df.columns]
    required={"TIPO_MOVIMIENTO","PRODUCTO","UNIDAD","CANTIDAD_MOVIMIENTO","ESTADO_REVISION"}
    missing=required-set(df.columns)
    if missing:
        raise ValueError("Faltan columnas en Carga_App: "+", ".join(sorted(missing)))

    df=df[df["PRODUCTO"].notna()].copy()
    if df.empty:
        raise ValueError("La hoja Carga_App no contiene movimientos.")

    valid=[]; skipped=[]; change_requests=[]
    next_code_cache=None
    for i,row in df.iterrows():
        r={k:row.get(k) for k in df.columns}
        status=_v1020_text(r.get("ESTADO_REVISION")).upper()
        if status!="OK":
            skipped.append(f"Fila {i+2}: estado {status or 'vacío'}")
            continue

        code=_v1020_text(r.get("CODIGO_PRODUCTO"))
        create=_v1020_yes(r.get("CREAR_PRODUCTO"))
        product_name=_v1020_text(r.get("PRODUCTO"))
        unit=_v1020_text(r.get("UNIDAD")).upper()
        existing=self.table("SELECT * FROM productos WHERE codigo=? LIMIT 1",(code,)) if code else pd.DataFrame()

        if existing.empty:
            if not create:
                skipped.append(f"Fila {i+2}: producto nuevo sin CREAR_PRODUCTO=SI ({product_name}).")
                continue
            if not code:
                if next_code_cache is None:
                    next_code_cache=int(self.next_product_code())
                code=str(next_code_cache); next_code_cache+=1
            duplicate_name=self.table("SELECT codigo FROM productos WHERE UPPER(TRIM(nombre))=UPPER(TRIM(?)) LIMIT 1",(product_name,))
            if not duplicate_name.empty:
                skipped.append(
                    f"Fila {i+2}: {product_name} ya existe con código {duplicate_name.iloc[0]['codigo']}; revisar."
                )
                continue
            self.upsert_producto({
                "codigo":code,"nombre":product_name,"unidad":unit or "KLS",
                "precio_venta":0,"comision_unitaria_sugerida":0,"costo":0,
                "stock_actual":0,"stock_minimo":0,"activo":"SI",
                "producto_fresco":"SI" if _v1020_yes(r.get("NUEVO_PRODUCTO_FRESCO")) else "NO",
                "iva_aplica":"NO" if _v1020_yes(r.get("NUEVO_PRODUCTO_FRESCO")) else (
                    _v1020_text(r.get("NUEVO_IVA_APLICA")).upper() or "SI"
                ),
                "fuente_origen":"Creado desde módulo Inventarios",
            })
        else:
            master_name=_v1020_text(existing.iloc[0].get("nombre"))
            if product_name and product_name.upper()!=master_name.upper() and not _v1020_yes(r.get("ACTUALIZAR_PRODUCTO")):
                skipped.append(
                    f"Fila {i+2}: código {code} corresponde a {master_name}, no a {product_name}; "
                    "marque ACTUALIZAR_PRODUCTO=SI solo si es una corrección real."
                )
                continue
            if _v1020_yes(r.get("ACTUALIZAR_PRODUCTO")):
                proposed,warnings=self.product_change_preview(r)
                if proposed:
                    change_requests.append((i+2,code,product_name,proposed,warnings,_v1020_text(r.get("RESPONSABLE"))))

        r["CODIGO_PRODUCTO"]=code
        valid.append((i+2,r))

    if change_requests and confirm_changes_callback:
        lines=[]
        for line,code,name,_changes,warns,_resp in change_requests:
            lines.append(f"Fila {line} - {code} {name}:\n  - "+"\n  - ".join(warns))
        if not confirm_changes_callback("\n\n".join(lines)):
            raise ValueError("Carga cancelada: no se aprobaron los cambios sensibles del maestro.")

    # Aplicar cambios aprobados.
    for line,code,name,changes,warns,resp in change_requests:
        self.apply_product_changes(
            code,changes,resp,
            f"Cambio aprobado durante carga de inventario. Fila {line}. " + " | ".join(warns)
        )

    loaded=[]
    errors=[]
    for line,r in valid:
        try:
            result=self.register_inventory_movement({
                "id_movimiento":_v1020_text(r.get("ID_MOVIMIENTO")),
                "fecha_hora":_v1020_text(r.get("FECHA")),
                "tipo_movimiento":_v1020_text(r.get("TIPO_MOVIMIENTO")),
                "documento_referencia":_v1020_text(r.get("DOCUMENTO_REFERENCIA")),
                "codigo_producto":_v1020_text(r.get("CODIGO_PRODUCTO")),
                "unidad":_v1020_text(r.get("UNIDAD")),
                "lote":_v1020_text(r.get("LOTE")),
                "fecha_vencimiento":_v1020_text(r.get("FECHA_VENCIMIENTO")),
                "ubicacion":_v1020_text(r.get("UBICACION")),
                "cantidad_movimiento":_v1020_num(r.get("CANTIDAD_MOVIMIENTO")),
                "costo_unitario_entrada":_v1020_num(r.get("COSTO_UNITARIO_ENTRADA")),
                "responsable":_v1020_text(r.get("RESPONSABLE")),
                "soporte":_v1020_text(r.get("SOPORTE")),
                "observacion":_v1020_text(r.get("OBSERVACION")),
                "origen":"EXCEL",
            })
            loaded.append(result)
        except Exception as exc:
            errors.append(f"Fila {line}: {exc}")

    return {
        "cargados":len(loaded),"omitidos":len(skipped),"errores":len(errors),
        "detalle_omitidos":skipped,"detalle_errores":errors
    }

SalesStore.import_inventory_excel = _v1020_import_inventory_excel


# ---------- Sincronizar ventas nuevas con inventario ----------
def _v1020_sync_sale_inventory(self, cuenta_cobro:str):
    account=_v1020_text(cuenta_cobro)
    if not account:
        return
    sale=self.table("SELECT estado_venta FROM ventas WHERE cuenta_cobro=? LIMIT 1",(account,))
    if sale.empty:
        return
    anulada=_v1017_norm_sale_status(sale.iloc[0].get("estado_venta"))=="ANULADA"
    details=self.table(
        """
        SELECT item,codigo_producto,producto,unidad,cantidad_kls
        FROM ventas_detalle WHERE cuenta_cobro=? ORDER BY item
        """,(account,)
    )
    desired={}
    if not anulada and not details.empty:
        for _,r in details.iterrows():
            code=_v1020_text(r.get("codigo_producto"))
            if not code:
                continue
            desired[f"VENTA-{account}-{int(r.get('item') or 0)}"]={
                "code":code,"qty":abs(_v1020_num(r.get("cantidad_kls"))),
                "producto":_v1020_text(r.get("producto")),"unidad":_v1020_text(r.get("unidad"))
            }

    existing=self.table(
        "SELECT * FROM inventario_movimientos WHERE origen='VENTA' AND documento_referencia=?",
        (account,)
    )
    existing_map={_v1020_text(r["id_movimiento"]):r for _,r in existing.iterrows()} if not existing.empty else {}

    # Revertir movimientos que ya no deberían existir o cambiaron.
    for mid,r in existing_map.items():
        wanted=desired.get(mid)
        old_qty=abs(_v1020_num(r.get("cantidad_movimiento")))
        if wanted and abs(old_qty-wanted["qty"])<=0.0001 and _v1020_text(r.get("codigo_producto"))==wanted["code"]:
            desired.pop(mid,None)
            continue
        code=_v1020_text(r.get("codigo_producto"))
        prod=self.table("SELECT stock_actual FROM productos WHERE codigo=?",(code,))
        if not prod.empty:
            current=_v1020_num(prod.iloc[0].get("stock_actual"))
            restored=current+old_qty
            self.conn.execute("UPDATE productos SET stock_actual=? WHERE codigo=?",(restored,code))
        self.conn.execute("DELETE FROM inventario_movimientos WHERE id_movimiento=?",(mid,))
    self.conn.commit()

    # Aplicar movimientos nuevos o modificados.
    for mid,w in desired.items():
        try:
            self.register_inventory_movement({
                "id_movimiento":mid,"fecha_hora":datetime.now().isoformat(timespec="seconds"),
                "tipo_movimiento":"VENTA","documento_referencia":account,
                "codigo_producto":w["code"],"unidad":w["unidad"],
                "cantidad_movimiento":w["qty"],"responsable":"SISTEMA",
                "observacion":f"Descuento automático por venta {account}",
                "origen":"VENTA",
            })
        except ValueError as exc:
            # La venta no se revierte por falta de stock; queda una observación visible.
            # Auditoría puede ajustar mediante conteo físico.
            self.conn.execute(
                """
                INSERT OR REPLACE INTO inventario_movimientos (
                    id_movimiento,fecha_hora,tipo_movimiento,documento_referencia,
                    codigo_producto,producto,unidad,saldo_antes,cantidad_movimiento,
                    saldo_despues,responsable,observacion,origen,estado,fecha_cargue
                )
                SELECT ?,?,'VENTA',?,codigo,nombre,unidad,stock_actual,0,stock_actual,
                       'SISTEMA',?,'VENTA','REVISAR',?
                  FROM productos WHERE codigo=?
                """,
                (
                    mid,datetime.now().isoformat(timespec="seconds"),account,
                    f"No se pudo descontar automáticamente {w['qty']:,.2f}: {exc}",
                    datetime.now().isoformat(timespec="seconds"),w["code"]
                )
            )
            self.conn.commit()

SalesStore.sync_sale_inventory = _v1020_sync_sale_inventory


_v1020_previous_save_sale = SalesFormApp.save_sale
def _v1020_save_sale(self):
    result=_v1020_previous_save_sale(self)
    try:
        account=self.vars.get("venta_factura",tk.StringVar()).get().strip()
        if account:
            self.store.sync_sale_inventory(account)
            if hasattr(self,"refresh_inventory"):
                self.refresh_inventory()
    except Exception:
        pass
    return result

SalesFormApp.save_sale = _v1020_save_sale


# ---------- Exportar inventario dentro de copias Excel ----------
_v1020_previous_export_excel = SalesStore.export_excel
def _v1020_export_excel(self,output_path:Path,append_existing:bool=False):
    result=_v1020_previous_export_excel(self,output_path,append_existing)
    movements=self.inventory_movements(100000)
    changes=self.table(
        "SELECT * FROM inventario_cambios_producto ORDER BY fecha_hora DESC,id_cambio DESC"
    )
    with pd.ExcelWriter(output_path,engine="openpyxl",mode="a",if_sheet_exists="replace") as writer:
        movements.rename(columns=str.upper).to_excel(writer,sheet_name="Inventario_movimientos",index=False)
        changes.rename(columns=str.upper).to_excel(writer,sheet_name="Inventario_cambios",index=False)
    try:
        _v987_style_excel_file(output_path)
    except Exception:
        pass
    return result

SalesStore.export_excel = _v1020_export_excel


# ---------- UI ----------
def _v1020_build_inventory_tab(self):
    page=self.inventory_tab
    top=ttk.Frame(page)
    top.pack(fill="x",pady=(0,8))
    ttk.Label(top,text="Inventarios",style="Title.TLabel").pack(side="left")
    ttk.Label(
        top,text="Movimientos auditables, conteos físicos y cargue desde Excel.",
        style="Hint.TLabel"
    ).pack(side="left",padx=12)

    actions=ttk.Frame(page)
    actions.pack(fill="x",pady=(0,8))
    ttk.Button(actions,text="Cargar Excel de inventario",style="Primary.TButton",
               command=self.import_inventory_file).pack(side="left",padx=3)
    ttk.Button(actions,text="Actualizar vista",style="Soft.TButton",
               command=self.refresh_inventory).pack(side="left",padx=3)

    form=ttk.LabelFrame(page,text="Registrar movimiento manual",padding=8)
    form.pack(fill="x",pady=(0,8))
    for c in (1,3,5):
        form.columnconfigure(c,weight=1)

    self.entry(form,"inv_fecha","Fecha",0,0).insert(0,today_text())
    self.entry(form,"inv_tipo","Tipo movimiento",0,2,values=list(V1020_INVENTORY_MOVEMENT_TYPES))
    self.vars["inv_tipo"].set("AJUSTE_CONTEO")
    self.entry(form,"inv_codigo","Código producto",0,4)
    self.entry(form,"inv_producto","Producto",1,0)
    self.entry(form,"inv_unidad","Unidad",1,2,values=["KLS","KG","GR","UNIDAD","CAJA","PAQUETE","BOLSA","LITRO","ML"])
    self.entry(form,"inv_cantidad","Cantidad / conteo",1,4)
    self.entry(form,"inv_documento","Documento referencia",2,0)
    self.entry(form,"inv_lote","Lote",2,2)
    self.entry(form,"inv_vencimiento","Vencimiento",2,4)
    self.entry(form,"inv_ubicacion","Ubicación",3,0)
    self.entry(form,"inv_costo","Costo unitario entrada",3,2)
    self.entry(form,"inv_responsable","Responsable",3,4)
    self.entry(form,"inv_soporte","Soporte / archivo",4,0)
    self.entry(form,"inv_observacion","Observación",4,2)
    ttk.Button(form,text="Registrar movimiento",style="Accent.TButton",
               command=self.register_inventory_manual).grid(row=4,column=4,columnspan=2,sticky="ew",padx=4,pady=4)

    stat=ttk.Frame(page)
    stat.pack(fill="x",pady=(0,8))
    self.vars["inventory_status"]=tk.StringVar(value="")
    ttk.Label(stat,textvariable=self.vars["inventory_status"],style="Section.TLabel").pack(anchor="w")

    table_frame=ttk.Frame(page)
    table_frame.pack(fill="both",expand=True)
    cols=("fecha","tipo","codigo","producto","unidad","antes","movimiento","despues","documento","estado")
    self.inventory_tree=ttk.Treeview(table_frame,columns=cols,show="headings")
    labels={
        "fecha":"Fecha","tipo":"Movimiento","codigo":"Código","producto":"Producto","unidad":"Unidad",
        "antes":"Saldo antes","movimiento":"Movimiento","despues":"Saldo después",
        "documento":"Documento","estado":"Estado"
    }
    widths={"fecha":145,"tipo":145,"codigo":90,"producto":220,"unidad":75,"antes":100,"movimiento":100,"despues":105,"documento":130,"estado":90}
    for c in cols:
        self.inventory_tree.heading(c,text=labels[c])
        self.inventory_tree.column(c,width=widths[c],anchor="w")
    self.add_tree_scrollbars(table_frame,self.inventory_tree)

SalesFormApp.build_inventory_tab = _v1020_build_inventory_tab


def _v1020_refresh_inventory(self):
    if not hasattr(self,"inventory_tree"):
        return
    for x in self.inventory_tree.get_children():
        self.inventory_tree.delete(x)
    df=self.store.inventory_movements(1500)
    if not df.empty:
        for _,r in df.iterrows():
            self.inventory_tree.insert("", "end", values=(
                r.get("fecha_hora",""),r.get("tipo_movimiento",""),r.get("codigo_producto",""),
                r.get("producto",""),r.get("unidad",""),
                f"{_v1020_num(r.get('saldo_antes')):,.2f}",
                f"{_v1020_num(r.get('cantidad_movimiento')):,.2f}",
                f"{_v1020_num(r.get('saldo_despues')):,.2f}",
                r.get("documento_referencia",""),r.get("estado",""),
            ))
    stock=self.store.table(
        "SELECT COUNT(*) productos, SUM(CASE WHEN stock_actual>0 THEN 1 ELSE 0 END) con_stock, "
        "SUM(CASE WHEN stock_actual<=stock_minimo THEN 1 ELSE 0 END) bajo_minimo FROM productos WHERE activo='SI'"
    )
    if not stock.empty:
        r=stock.iloc[0]
        self.vars["inventory_status"].set(
            f"Productos activos: {int(r.get('productos') or 0)} | "
            f"Con stock: {int(r.get('con_stock') or 0)} | "
            f"En/bajo mínimo: {int(r.get('bajo_minimo') or 0)} | "
            f"Movimientos mostrados: {len(df)}"
        )

SalesFormApp.refresh_inventory = _v1020_refresh_inventory


def _v1020_register_inventory_manual(self):
    try:
        code=self.vars["inv_codigo"].get().strip()
        if not code:
            raise ValueError("Ingrese el código del producto.")
        p=self.store.table("SELECT * FROM productos WHERE codigo=? LIMIT 1",(code,))
        if p.empty:
            raise ValueError("El código no existe. Para crear productos nuevos use el formato Excel y marque CREAR_PRODUCTO=SI.")
        row=p.iloc[0]
        typed_name=self.vars["inv_producto"].get().strip()
        if typed_name and typed_name.upper()!=str(row["nombre"]).strip().upper():
            if not messagebox.askyesno(
                "Producto diferente",
                f"El código {code} corresponde a '{row['nombre']}', no a '{typed_name}'.\n\n"
                "¿Desea registrar el movimiento usando el producto del maestro?"
            ):
                return
        self.store.register_inventory_movement({
            "fecha_hora":self.vars["inv_fecha"].get().strip(),
            "tipo_movimiento":self.vars["inv_tipo"].get().strip(),
            "codigo_producto":code,
            "unidad":self.vars["inv_unidad"].get().strip() or row["unidad"],
            "cantidad_movimiento":money(self.vars["inv_cantidad"].get()),
            "documento_referencia":self.vars["inv_documento"].get().strip(),
            "lote":self.vars["inv_lote"].get().strip(),
            "fecha_vencimiento":self.vars["inv_vencimiento"].get().strip(),
            "ubicacion":self.vars["inv_ubicacion"].get().strip(),
            "costo_unitario_entrada":money(self.vars["inv_costo"].get()),
            "responsable":self.vars["inv_responsable"].get().strip(),
            "soporte":self.vars["inv_soporte"].get().strip(),
            "observacion":self.vars["inv_observacion"].get().strip(),
            "origen":"MANUAL",
        })
        self.reload_master_catalogs()
        self.refresh_all()
        self.refresh_inventory()
        messagebox.showinfo("Inventario","Movimiento registrado correctamente.")
    except Exception as exc:
        messagebox.showerror("Inventario",str(exc))

SalesFormApp.register_inventory_manual = _v1020_register_inventory_manual


def _v1020_import_inventory_file(self):
    path=filedialog.askopenfilename(
        title="Seleccionar formato de inventario",
        filetypes=[("Excel","*.xlsx *.xls")]
    )
    if not path:
        return
    def confirm_changes(text):
        return messagebox.askyesno(
            "Cambios sensibles del maestro",
            "El archivo solicita modificar datos maestros de productos.\n\n"
            + text[:8000] +
            "\n\nEstos cambios NO son automáticos. ¿Autoriza aplicarlos?"
        )
    try:
        result=self.store.import_inventory_excel(Path(path),confirm_changes)
        self.reload_master_catalogs()
        self.refresh_all()
        self.refresh_inventory()
        msg=(
            f"Movimientos cargados: {result['cargados']}\n"
            f"Filas omitidas: {result['omitidos']}\n"
            f"Errores: {result['errores']}"
        )
        details=(result["detalle_omitidos"]+result["detalle_errores"])[:20]
        if details:
            msg += "\n\nRevisión:\n- " + "\n- ".join(details)
        messagebox.showinfo("Carga de inventario",msg)
    except Exception as exc:
        messagebox.showerror("Carga de inventario",str(exc))

SalesFormApp.import_inventory_file = _v1020_import_inventory_file


# Insertar nueva página y botón de navegación después de construir la UI existente.
_v1020_previous_create_widgets = SalesFormApp.create_widgets
def _v1020_create_widgets(self):
    _v1020_previous_create_widgets(self)
    body=self.dashboard_tab.master
    self.inventory_tab=ttk.Frame(body)
    self.inventory_tab.place(relx=0,rely=0,relwidth=1,relheight=1)
    self.pages["inventarios"]=self.inventory_tab
    self.build_inventory_tab()
    self.refresh_inventory()

SalesFormApp.create_widgets = _v1020_create_widgets

