# ==================== V10.2.1 CARGA SIMPLE DE INVENTARIO ====================

def _v1021_simple_movement_type(value:str) -> str:
    s=str(value or "").strip().upper()
    mapping={
        "CONTEO FÍSICO":"AJUSTE_CONTEO",
        "CONTEO FISICO":"AJUSTE_CONTEO",
        "ENTRADA":"ENTRADA",
        "SALIDA":"SALIDA",
        "MERMA":"MERMA",
        "OBSEQUIO":"OBSEQUIO",
        "DEVOLUCIÓN CLIENTE":"DEVOLUCION_CLIENTE",
        "DEVOLUCION CLIENTE":"DEVOLUCION_CLIENTE",
        "DEVOLUCIÓN PROVEEDOR":"DEVOLUCION_PROVEEDOR",
        "DEVOLUCION PROVEEDOR":"DEVOLUCION_PROVEEDOR",
    }
    return mapping.get(s,s)

def _v1021_import_inventory_excel(self,path:Path,confirm_changes_callback=None) -> dict:
    """
    Formato simplificado:
    Hoja: Inventario
    Columnas:
      Fecha, Tipo de movimiento, Código, Producto, Unidad,
      Cantidad / Conteo, Peso bruto (kg), Número de cajas,
      Tara por caja (kg), Cantidad final, Costo de entrada,
      Lote, Vencimiento, Ubicación, Responsable, Observación
    """
    try:
        df=pd.read_excel(path,sheet_name="Inventario")
    except Exception:
        # Compatibilidad hacia atrás con el formato V10.2.0.
        return _v1020_import_inventory_excel(self,path,confirm_changes_callback)

    df.columns=[str(c).strip() for c in df.columns]
    required={"Tipo de movimiento","Producto","Unidad"}
    missing=required-set(df.columns)
    if missing:
        raise ValueError(
            "El archivo no corresponde al formato simple de inventario. "
            "Faltan columnas: "+", ".join(sorted(missing))
        )

    df=df[df["Producto"].notna()].copy()
    if df.empty:
        raise ValueError("No hay productos para cargar en la hoja Inventario.")

    loaded=[]
    skipped=[]
    errors=[]
    next_code=None

    for i,row in df.iterrows():
        excel_row=i+2
        product_name=_v1020_text(row.get("Producto"))
        code=_v1020_text(row.get("Código"))
        unit=_v1020_text(row.get("Unidad")).upper()
        movement_type=_v1021_simple_movement_type(row.get("Tipo de movimiento"))

        # Cantidad: primero Cantidad final, luego Cantidad / Conteo, luego cálculo de peso.
        qty=_v1020_num(row.get("Cantidad final"),0)
        if qty <= 0:
            qty=_v1020_num(row.get("Cantidad / Conteo"),0)
        if qty <= 0:
            gross=_v1020_num(row.get("Peso bruto (kg)"),0)
            boxes=_v1020_num(row.get("Número de cajas"),0)
            tare=_v1020_num(row.get("Tara por caja (kg)"),0)
            if gross > 0:
                qty=max(gross-(boxes*tare),0)

        if qty <= 0:
            skipped.append(f"Fila {excel_row}: {product_name} sin cantidad válida.")
            continue

        # Resolver producto.
        existing=pd.DataFrame()
        if code:
            existing=self.table("SELECT * FROM productos WHERE codigo=? LIMIT 1",(code,))

        if existing.empty and not code:
            # Buscar por nombre exacto antes de crear.
            by_name=self.table(
                "SELECT * FROM productos WHERE UPPER(TRIM(nombre))=UPPER(TRIM(?)) LIMIT 1",
                (product_name,)
            )
            if not by_name.empty:
                existing=by_name
                code=_v1020_text(existing.iloc[0].get("codigo"))

        if existing.empty:
            # Producto nuevo: crear con datos mínimos, sin inventar precio/costo/comisión.
            if next_code is None:
                next_code=int(self.next_product_code())
            code=str(next_code)
            next_code += 1
            self.upsert_producto({
                "codigo":code,
                "nombre":product_name,
                "unidad":unit or "KLS",
                "precio_venta":0,
                "comision_unitaria_sugerida":0,
                "costo":0,
                "stock_actual":0,
                "stock_minimo":0,
                "activo":"SI",
                "producto_fresco":"NO",
                "iva_aplica":"SI",
                "fuente_origen":"Creado desde inventario simple",
            })
        else:
            master=existing.iloc[0]
            master_name=_v1020_text(master.get("nombre"))
            master_unit=_v1020_text(master.get("unidad")).upper()

            # El código manda. Si hay diferencia de nombre/unidad, no cambiar maestro automáticamente.
            if product_name and product_name.upper()!=master_name.upper():
                skipped.append(
                    f"Fila {excel_row}: código {code} corresponde a '{master_name}', "
                    f"pero el archivo dice '{product_name}'. Revisar manualmente."
                )
                continue
            if unit and master_unit and unit!=master_unit:
                skipped.append(
                    f"Fila {excel_row}: {master_name} está en {master_unit}, "
                    f"pero el archivo trae {unit}. Revisar cambio de unidad antes de cargar."
                )
                continue

        try:
            result=self.register_inventory_movement({
                "fecha_hora":_v1020_text(row.get("Fecha")) or datetime.now().isoformat(timespec="seconds"),
                "tipo_movimiento":movement_type,
                "documento_referencia":"",
                "codigo_producto":code,
                "unidad":unit,
                "lote":_v1020_text(row.get("Lote")),
                "fecha_vencimiento":_v1020_text(row.get("Vencimiento")),
                "ubicacion":_v1020_text(row.get("Ubicación")),
                "cantidad_movimiento":qty,
                "costo_unitario_entrada":_v1020_num(row.get("Costo de entrada"),0),
                "responsable":_v1020_text(row.get("Responsable")),
                "soporte":"",
                "observacion":_v1020_text(row.get("Observación")),
                "origen":"EXCEL_SIMPLE",
            })
            loaded.append(result)
        except Exception as exc:
            errors.append(f"Fila {excel_row}: {exc}")

    return {
        "cargados":len(loaded),
        "omitidos":len(skipped),
        "errores":len(errors),
        "detalle_omitidos":skipped,
        "detalle_errores":errors,
    }

SalesStore.import_inventory_excel = _v1021_import_inventory_excel

# ==================== FIN V10.2.1 ====================



# ==================== V10.2.2 REPORTE GERENCIAL DE INVENTARIOS ====================

INVENTORY_REPORTS_DIR = APP_DIR / "reportes_inventario"


def _v1022_inventory_period_bounds(start_date: date, end_date: date):
    """Rango completo para consultas SQL: inicio 00:00:00 / fin 23:59:59."""
    start_dt = datetime.combine(start_date, datetime.min.time())
    end_dt = datetime.combine(end_date, datetime.max.time())
    return start_dt.isoformat(timespec="seconds"), end_dt.isoformat(timespec="seconds")


def _v1022_inventory_report_data(self, start_date: date, end_date: date) -> dict:
    """
    Arma el dataset gerencial de movimientos.
    IMPORTANTE: no suma KLS con UNIDAD; todos los indicadores se presentan por unidad.
    """
    start_iso, end_iso = _v1022_inventory_period_bounds(start_date, end_date)

    movements = self.table(
        """
        SELECT
            id_movimiento, fecha_hora, tipo_movimiento, documento_referencia,
            codigo_producto, producto, unidad, lote, ubicacion,
            saldo_antes, cantidad_movimiento, saldo_despues,
            costo_unitario_entrada, costo_total_movimiento,
            responsable, observacion, origen, estado
        FROM inventario_movimientos
        WHERE fecha_hora >= ? AND fecha_hora <= ?
        ORDER BY fecha_hora, id_movimiento
        """,
        (start_iso, end_iso),
    )

    if movements.empty:
        movements = pd.DataFrame(columns=[
            "id_movimiento","fecha_hora","tipo_movimiento","documento_referencia",
            "codigo_producto","producto","unidad","lote","ubicacion",
            "saldo_antes","cantidad_movimiento","saldo_despues",
            "costo_unitario_entrada","costo_total_movimiento",
            "responsable","observacion","origen","estado"
        ])

    # Normalización para análisis
    if not movements.empty:
        movements["tipo_movimiento"] = movements["tipo_movimiento"].astype(str).str.upper()
        movements["unidad"] = movements["unidad"].astype(str).str.upper().replace({"KG":"KLS"})
        movements["cantidad_movimiento"] = pd.to_numeric(
            movements["cantidad_movimiento"], errors="coerce"
        ).fillna(0.0)
        movements["costo_total_movimiento"] = pd.to_numeric(
            movements["costo_total_movimiento"], errors="coerce"
        ).fillna(0.0)

    # Resumen por unidad para no mezclar magnitudes incompatibles.
    unit_summary = []
    if not movements.empty:
        for unit, g in movements.groupby("unidad", dropna=False):
            unit = str(unit or "SIN UNIDAD")
            entries = g[g["cantidad_movimiento"] > 0]["cantidad_movimiento"].sum()
            exits = abs(g[g["cantidad_movimiento"] < 0]["cantidad_movimiento"].sum())
            sales = abs(
                g[g["tipo_movimiento"] == "VENTA"]["cantidad_movimiento"].sum()
            )
            shrink = abs(
                g[g["tipo_movimiento"].isin(["MERMA","AJUSTE_NEGATIVO"])]["cantidad_movimiento"].sum()
            )
            adjustments = g[g["tipo_movimiento"].str.startswith("AJUSTE", na=False)]["cantidad_movimiento"].sum()

            unit_summary.append({
                "unidad": unit,
                "entradas": float(entries),
                "salidas": float(exits),
                "ventas": float(sales),
                "mermas_ajustes_negativos": float(shrink),
                "ajustes_netos": float(adjustments),
                "movimientos": int(len(g)),
            })

    unit_summary_df = pd.DataFrame(unit_summary)

    # Top productos por salida total y por ventas.
    product_summary = pd.DataFrame()
    if not movements.empty:
        tmp = movements.copy()
        tmp["salida_abs"] = tmp["cantidad_movimiento"].where(
            tmp["cantidad_movimiento"] < 0, 0
        ).abs()
        tmp["venta_abs"] = tmp["cantidad_movimiento"].where(
            tmp["tipo_movimiento"] == "VENTA", 0
        ).abs()
        product_summary = (
            tmp.groupby(["codigo_producto","producto","unidad"], dropna=False)
               .agg(
                   entradas=("cantidad_movimiento", lambda s: float(s[s > 0].sum())),
                   salidas=("salida_abs","sum"),
                   ventas=("venta_abs","sum"),
                   movimientos=("id_movimiento","count"),
               )
               .reset_index()
        )
        product_summary["movimiento_total"] = (
            product_summary["entradas"].abs() + product_summary["salidas"].abs()
        )
        product_summary = product_summary.sort_values(
            ["movimiento_total","ventas"], ascending=[False,False]
        )

    # Ventas, entradas, mermas y ajustes
    by_type = pd.DataFrame()
    if not movements.empty:
        by_type = (
            movements.groupby(["tipo_movimiento","unidad"], dropna=False)
                     .agg(
                         cantidad=("cantidad_movimiento","sum"),
                         movimientos=("id_movimiento","count"),
                     )
                     .reset_index()
        )

    # Registros marcados REVISAR
    review = movements[
        movements["estado"].astype(str).str.upper().eq("REVISAR")
    ].copy() if not movements.empty else movements.copy()

    return {
        "movements": movements,
        "unit_summary": unit_summary_df,
        "product_summary": product_summary,
        "by_type": by_type,
        "review": review,
        "start_date": start_date,
        "end_date": end_date,
    }


SalesStore.inventory_report_data = _v1022_inventory_report_data


def _v1022_export_inventory_pdf(
    self,
    start_date: date,
    end_date: date,
    output_path: Path,
    period_type: str = "SEMANAL",
) -> Path:
    from reportlab.lib import colors
    from reportlab.lib.pagesizes import A4, landscape
    from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
    from reportlab.lib.enums import TA_CENTER, TA_RIGHT
    from reportlab.lib.units import cm
    from reportlab.platypus import (
        SimpleDocTemplate, Table, TableStyle, Paragraph, Spacer, PageBreak, KeepTogether
    )

    data = self.inventory_report_data(start_date, end_date)
    mov = data["movements"]
    unit_summary = data["unit_summary"]
    products = data["product_summary"]
    review = data["review"]

    output_path = Path(output_path)
    output_path.parent.mkdir(parents=True, exist_ok=True)

    doc = SimpleDocTemplate(
        str(output_path),
        pagesize=landscape(A4),
        leftMargin=1.0*cm,
        rightMargin=1.0*cm,
        topMargin=1.0*cm,
        bottomMargin=1.0*cm,
        title=f"Reporte gerencial de inventarios {period_type}",
        author="MXPC",
    )

    styles = getSampleStyleSheet()
    styles.add(ParagraphStyle(
        name="MXPCTitle", parent=styles["Title"], fontName="Helvetica-Bold",
        fontSize=18, leading=22, textColor=colors.HexColor("#173D31"),
        spaceAfter=5
    ))
    styles.add(ParagraphStyle(
        name="MXPCSub", parent=styles["Normal"], fontSize=9, leading=12,
        textColor=colors.HexColor("#53635E"), spaceAfter=8
    ))
    styles.add(ParagraphStyle(
        name="MXPCSection", parent=styles["Heading2"], fontName="Helvetica-Bold",
        fontSize=12, leading=14, textColor=colors.HexColor("#173D31"),
        spaceBefore=6, spaceAfter=5
    ))
    styles.add(ParagraphStyle(
        name="MXPCCell", parent=styles["Normal"], fontSize=7, leading=8.5
    ))
    styles.add(ParagraphStyle(
        name="MXPCCellRight", parent=styles["Normal"], fontSize=7, leading=8.5,
        alignment=TA_RIGHT
    ))
    styles.add(ParagraphStyle(
        name="MXPCCenter", parent=styles["Normal"], fontSize=8, leading=10,
        alignment=TA_CENTER
    ))

    story = []
    period_label = "Semanal" if period_type.upper() == "SEMANAL" else "Mensual"
    story.append(Paragraph(
        f"Reporte gerencial de movimientos de inventario - {period_label}",
        styles["MXPCTitle"]
    ))
    story.append(Paragraph(
        f"Periodo: {start_date.strftime('%d/%m/%Y')} al {end_date.strftime('%d/%m/%Y')} | "
        f"Generado: {_v1017_colombia_now().strftime('%d/%m/%Y %H:%M')} hora Colombia",
        styles["MXPCSub"]
    ))

    # Resumen ejecutivo
    story.append(Paragraph("Resumen ejecutivo", styles["MXPCSection"]))

    total_mov = len(mov)
    sales_mov = int((mov["tipo_movimiento"] == "VENTA").sum()) if not mov.empty else 0
    review_count = len(review)

    kpi_data = [
        [
            Paragraph("<b>Movimientos</b>", styles["MXPCCenter"]),
            Paragraph("<b>Movimientos por venta</b>", styles["MXPCCenter"]),
            Paragraph("<b>Registros a revisar</b>", styles["MXPCCenter"]),
            Paragraph("<b>Productos con movimiento</b>", styles["MXPCCenter"]),
        ],
        [
            str(total_mov),
            str(sales_mov),
            str(review_count),
            str(mov["codigo_producto"].nunique() if not mov.empty else 0),
        ]
    ]
    kpi_table = Table(kpi_data, colWidths=[6.2*cm]*4)
    kpi_table.setStyle(TableStyle([
        ("BACKGROUND",(0,0),(-1,0),colors.HexColor("#155E42")),
        ("TEXTCOLOR",(0,0),(-1,0),colors.white),
        ("FONTNAME",(0,0),(-1,0),"Helvetica-Bold"),
        ("FONTSIZE",(0,0),(-1,-1),9),
        ("ALIGN",(0,0),(-1,-1),"CENTER"),
        ("VALIGN",(0,0),(-1,-1),"MIDDLE"),
        ("GRID",(0,0),(-1,-1),0.4,colors.HexColor("#B7C7C1")),
        ("BACKGROUND",(0,1),(-1,1),colors.HexColor("#F4F8F6")),
        ("TOPPADDING",(0,0),(-1,-1),6),
        ("BOTTOMPADDING",(0,0),(-1,-1),6),
    ]))
    story.append(kpi_table)
    story.append(Spacer(1, 0.25*cm))

    # Resumen por unidad
    story.append(Paragraph(
        "Movimientos por unidad (no se mezclan KLS con UNIDADES)",
        styles["MXPCSection"]
    ))
    if unit_summary.empty:
        story.append(Paragraph("No se registraron movimientos en el periodo.", styles["Normal"]))
    else:
        rows = [[
            "Unidad","Entradas","Salidas","Ventas","Mermas/Ajustes -","Ajuste neto","Mov."
        ]]
        for _, r in unit_summary.iterrows():
            rows.append([
                str(r["unidad"]),
                f"{r['entradas']:,.2f}",
                f"{r['salidas']:,.2f}",
                f"{r['ventas']:,.2f}",
                f"{r['mermas_ajustes_negativos']:,.2f}",
                f"{r['ajustes_netos']:,.2f}",
                str(int(r["movimientos"])),
            ])
        t = Table(rows, colWidths=[4.0*cm,3.1*cm,3.1*cm,3.1*cm,3.8*cm,3.3*cm,2.1*cm], repeatRows=1)
        t.setStyle(TableStyle([
            ("BACKGROUND",(0,0),(-1,0),colors.HexColor("#155E42")),
            ("TEXTCOLOR",(0,0),(-1,0),colors.white),
            ("FONTNAME",(0,0),(-1,0),"Helvetica-Bold"),
            ("GRID",(0,0),(-1,-1),0.35,colors.HexColor("#C6D2CE")),
            ("ALIGN",(1,1),(-1,-1),"RIGHT"),
            ("VALIGN",(0,0),(-1,-1),"MIDDLE"),
            ("FONTSIZE",(0,0),(-1,-1),8),
            ("ROWBACKGROUNDS",(0,1),(-1,-1),[colors.white,colors.HexColor("#F7F9F8")]),
            ("TOPPADDING",(0,0),(-1,-1),4),
            ("BOTTOMPADDING",(0,0),(-1,-1),4),
        ]))
        story.append(t)

    # Top productos
    story.append(Paragraph("Productos con mayor movimiento", styles["MXPCSection"]))
    if products.empty:
        story.append(Paragraph("Sin movimientos de productos.", styles["Normal"]))
    else:
        top = products.head(15)
        rows = [["Código","Producto","Unidad","Entradas","Salidas","Ventas","Mov."]]
        for _, r in top.iterrows():
            rows.append([
                str(r["codigo_producto"]),
                Paragraph(str(r["producto"]), styles["MXPCCell"]),
                str(r["unidad"]),
                f"{r['entradas']:,.2f}",
                f"{r['salidas']:,.2f}",
                f"{r['ventas']:,.2f}",
                str(int(r["movimientos"])),
            ])
        t = Table(rows, colWidths=[2.4*cm,8.8*cm,2.4*cm,3.0*cm,3.0*cm,3.0*cm,2.0*cm], repeatRows=1)
        t.setStyle(TableStyle([
            ("BACKGROUND",(0,0),(-1,0),colors.HexColor("#244F41")),
            ("TEXTCOLOR",(0,0),(-1,0),colors.white),
            ("FONTNAME",(0,0),(-1,0),"Helvetica-Bold"),
            ("GRID",(0,0),(-1,-1),0.3,colors.HexColor("#CDD7D3")),
            ("ALIGN",(3,1),(-1,-1),"RIGHT"),
            ("VALIGN",(0,0),(-1,-1),"MIDDLE"),
            ("FONTSIZE",(0,0),(-1,-1),7.5),
            ("ROWBACKGROUNDS",(0,1),(-1,-1),[colors.white,colors.HexColor("#F7F9F8")]),
        ]))
        story.append(t)

    # Alertas
    if review_count:
        story.append(Paragraph("Alertas / movimientos por revisar", styles["MXPCSection"]))
        rows = [["Fecha","Código","Producto","Movimiento","Documento","Observación"]]
        for _, r in review.head(20).iterrows():
            rows.append([
                str(r.get("fecha_hora",""))[:16],
                str(r.get("codigo_producto","")),
                Paragraph(str(r.get("producto","")), styles["MXPCCell"]),
                str(r.get("tipo_movimiento","")),
                str(r.get("documento_referencia","") or ""),
                Paragraph(str(r.get("observacion","") or ""), styles["MXPCCell"]),
            ])
        t = Table(rows, colWidths=[3.4*cm,2.0*cm,6.0*cm,3.3*cm,3.6*cm,8.0*cm], repeatRows=1)
        t.setStyle(TableStyle([
            ("BACKGROUND",(0,0),(-1,0),colors.HexColor("#A6632B")),
            ("TEXTCOLOR",(0,0),(-1,0),colors.white),
            ("FONTNAME",(0,0),(-1,0),"Helvetica-Bold"),
            ("GRID",(0,0),(-1,-1),0.3,colors.HexColor("#D5C9BF")),
            ("FONTSIZE",(0,0),(-1,-1),7),
            ("VALIGN",(0,0),(-1,-1),"TOP"),
            ("ROWBACKGROUNDS",(0,1),(-1,-1),[colors.white,colors.HexColor("#FFF8F0")]),
        ]))
        story.append(t)

    # Detalle completo
    story.append(PageBreak())
    story.append(Paragraph("Detalle de movimientos", styles["MXPCSection"]))
    rows = [["Fecha","Tipo","Código","Producto","Unidad","Antes","Movimiento","Después","Documento","Origen"]]
    if mov.empty:
        rows.append(["-","-","-","Sin movimientos","-","-","-","-","-","-"])
    else:
        for _, r in mov.iterrows():
            rows.append([
                str(r.get("fecha_hora",""))[:16],
                str(r.get("tipo_movimiento","")),
                str(r.get("codigo_producto","")),
                Paragraph(str(r.get("producto","")), styles["MXPCCell"]),
                str(r.get("unidad","")),
                f"{_v1020_num(r.get('saldo_antes')):,.2f}",
                f"{_v1020_num(r.get('cantidad_movimiento')):,.2f}",
                f"{_v1020_num(r.get('saldo_despues')):,.2f}",
                Paragraph(str(r.get("documento_referencia","") or ""), styles["MXPCCell"]),
                str(r.get("origen","")),
            ])
    t = Table(
        rows,
        colWidths=[2.8*cm,3.2*cm,2.0*cm,6.3*cm,1.8*cm,2.3*cm,2.5*cm,2.3*cm,3.2*cm,2.2*cm],
        repeatRows=1
    )
    t.setStyle(TableStyle([
        ("BACKGROUND",(0,0),(-1,0),colors.HexColor("#173D31")),
        ("TEXTCOLOR",(0,0),(-1,0),colors.white),
        ("FONTNAME",(0,0),(-1,0),"Helvetica-Bold"),
        ("GRID",(0,0),(-1,-1),0.25,colors.HexColor("#D3DAD7")),
        ("FONTSIZE",(0,0),(-1,-1),6.6),
        ("VALIGN",(0,0),(-1,-1),"TOP"),
        ("ALIGN",(5,1),(7,-1),"RIGHT"),
        ("ROWBACKGROUNDS",(0,1),(-1,-1),[colors.white,colors.HexColor("#F8FAF9")]),
        ("TOPPADDING",(0,0),(-1,-1),3),
        ("BOTTOMPADDING",(0,0),(-1,-1),3),
    ]))
    story.append(t)

    doc.build(story)
    return output_path


SalesStore.export_inventory_report_pdf = _v1022_export_inventory_pdf


def _v1022_export_inventory_excel(
    self,
    start_date: date,
    end_date: date,
    output_path: Path,
    period_type: str = "SEMANAL",
) -> Path:
    """Detalle de soporte del reporte gerencial."""
    data = self.inventory_report_data(start_date, end_date)
    output_path = Path(output_path)
    output_path.parent.mkdir(parents=True, exist_ok=True)

    with pd.ExcelWriter(output_path, engine="openpyxl") as writer:
        data["unit_summary"].rename(columns=str.upper).to_excel(
            writer, sheet_name="Resumen_unidades", index=False
        )
        data["product_summary"].rename(columns=str.upper).to_excel(
            writer, sheet_name="Resumen_productos", index=False
        )
        data["by_type"].rename(columns=str.upper).to_excel(
            writer, sheet_name="Resumen_movimientos", index=False
        )
        data["movements"].rename(columns=str.upper).to_excel(
            writer, sheet_name="Detalle_movimientos", index=False
        )
        data["review"].rename(columns=str.upper).to_excel(
            writer, sheet_name="Revisar", index=False
        )

    try:
        from openpyxl import load_workbook
        from openpyxl.styles import PatternFill, Font, Alignment, Border, Side
        book = load_workbook(output_path)
        green = "155E42"
        white = "FFFFFF"
        border = Border(
            left=Side(style="thin", color="D7DFDC"),
            right=Side(style="thin", color="D7DFDC"),
            top=Side(style="thin", color="D7DFDC"),
            bottom=Side(style="thin", color="D7DFDC"),
        )
        for ws in book.worksheets:
            ws.freeze_panes = "A2"
            ws.auto_filter.ref = ws.dimensions
            for cell in ws[1]:
                cell.fill = PatternFill("solid", fgColor=green)
                cell.font = Font(bold=True, color=white)
                cell.alignment = Alignment(horizontal="center", vertical="center", wrap_text=True)
            for row in ws.iter_rows():
                for cell in row:
                    cell.border = border
                    cell.alignment = Alignment(vertical="top", wrap_text=True)
            for col in ws.columns:
                letter = col[0].column_letter
                max_len = min(max((len(str(c.value or "")) for c in col), default=10) + 2, 45)
                ws.column_dimensions[letter].width = max(11, max_len)
        book.save(output_path)
    except Exception:
        pass

    return output_path


SalesStore.export_inventory_report_excel = _v1022_export_inventory_excel


def _v1022_week_period(now: datetime | None = None):
    now = now or _v1017_colombia_now()
    cutoff = _v1017_latest_friday_3pm(now)
    start = cutoff - timedelta(days=cutoff.weekday())  # lunes
    return start, cutoff


def _v1022_previous_month_period(reference: date | None = None):
    reference = reference or _v1017_colombia_now().date()
    first = reference.replace(day=1)
    end = first - timedelta(days=1)
    start = end.replace(day=1)
    return start, end


def _v1022_generate_inventory_weekly(self, now: datetime | None = None):
    now = now or _v1017_colombia_now()

    # El reporte de la semana corriente se habilita el viernes a las 15:00 Colombia.
    if now.weekday() == 4 and now.hour < 15:
        return []

    start_date, end_date = _v1022_week_period(now)
    INVENTORY_REPORTS_DIR.mkdir(parents=True, exist_ok=True)

    label = f"{start_date:%Y-%m-%d}_a_{end_date:%Y-%m-%d}"
    pdf = INVENTORY_REPORTS_DIR / f"Inventario_semanal_{label}.pdf"
    xlsx = INVENTORY_REPORTS_DIR / f"Inventario_semanal_{label}.xlsx"

    generated = []
    if not pdf.exists():
        self.store.export_inventory_report_pdf(start_date, end_date, pdf, "SEMANAL")
        generated.append(pdf)
    if not xlsx.exists():
        self.store.export_inventory_report_excel(start_date, end_date, xlsx, "SEMANAL")
        generated.append(xlsx)
    return generated


def _v1022_generate_inventory_monthly(self, now: datetime | None = None):
    now = now or _v1017_colombia_now()
    start_date, end_date = _v1022_previous_month_period(now.date())
    INVENTORY_REPORTS_DIR.mkdir(parents=True, exist_ok=True)

    label = f"{start_date:%Y-%m-%d}_a_{end_date:%Y-%m-%d}"
    pdf = INVENTORY_REPORTS_DIR / f"Inventario_mensual_{label}.pdf"
    xlsx = INVENTORY_REPORTS_DIR / f"Inventario_mensual_{label}.xlsx"

    generated = []
    if not pdf.exists():
        self.store.export_inventory_report_pdf(start_date, end_date, pdf, "MENSUAL")
        generated.append(pdf)
    if not xlsx.exists():
        self.store.export_inventory_report_excel(start_date, end_date, xlsx, "MENSUAL")
        generated.append(xlsx)
    return generated


def _v1022_generate_due_inventory_reports(self):
    """
    Semanal:
      viernes 15:00 hora Colombia, lunes-viernes.
    Mensual:
      primera ejecución disponible luego del cambio de mes, mes calendario anterior.
    """
    now = _v1017_colombia_now()
    generated = []

    try:
        generated.extend(_v1022_generate_inventory_weekly(self, now))
    except Exception:
        pass

    try:
        generated.extend(_v1022_generate_inventory_monthly(self, now))
    except Exception:
        pass

    return generated


def _v1022_schedule_inventory_reports(self):
    """
    Comprueba cada hora.
    Esto también permite recuperación si el equipo estaba apagado el viernes a las 15:00.
    """
    def run():
        try:
            _v1022_generate_due_inventory_reports(self)
        finally:
            try:
                self.after(3_600_000, run)
            except Exception:
                pass

    try:
        self.after(3500, run)
    except Exception:
        pass


