V1024_NAV_ITEMS = [
    ("dashboard", "Inicio"),
    ("cotizaciones", "Cotizaciones"),
    ("ventas", "Ventas"),
    ("abonos", "Pagos / Abonos"),
    ("inventarios", "Inventarios"),
    ("maestros", "Clientes / Productos"),
    ("resumen", "Cartera / Resumen"),
]

def _v1024_build_top_navigation(self):
    """
    Barra superior compacta y siempre visible.
    Complementa el menú lateral y muestra claramente la sección activa.
    """
    if hasattr(self, "_top_nav_frame") and self._top_nav_frame.winfo_exists():
        return

    # Main content frame is the parent of the page container.
    try:
        content_parent = self.dashboard_tab.master.master
    except Exception:
        try:
            content_parent = self.dashboard_tab.master
        except Exception:
            return

    nav = tk.Frame(content_parent, bg="#E9F1EE", height=48)
    nav.pack(fill="x", side="top", before=self.dashboard_tab.master, padx=0, pady=(0,6))
    nav.pack_propagate(False)
    self._top_nav_frame = nav
    self._top_nav_buttons = {}

    # Horizontal scroll container for small screens.
    canvas = tk.Canvas(
        nav, bg="#E9F1EE", height=46,
        highlightthickness=0, bd=0
    )
    canvas.pack(side="left", fill="both", expand=True)

    inner = tk.Frame(canvas, bg="#E9F1EE")
    window_id = canvas.create_window((0,0), window=inner, anchor="nw")

    def sync_scroll(_event=None):
        try:
            canvas.configure(scrollregion=canvas.bbox("all"))
            # Keep inner at least as wide as canvas when possible.
            canvas.itemconfigure(window_id, height=44)
        except Exception:
            pass

    def fit_inner(event):
        try:
            req = inner.winfo_reqwidth()
            canvas.itemconfigure(window_id, width=max(req, event.width))
        except Exception:
            pass

    inner.bind("<Configure>", sync_scroll)
    canvas.bind("<Configure>", fit_inner)

    # Mouse wheel / Shift+wheel horizontal navigation.
    def wheel(event):
        try:
            delta = -1 if event.delta > 0 else 1
            canvas.xview_scroll(delta * 3, "units")
        except Exception:
            pass

    canvas.bind("<Shift-MouseWheel>", wheel)

    for key, label in V1024_NAV_ITEMS:
        btn = tk.Button(
            inner,
            text=label,
            command=lambda k=key: self.show_page(k),
            bg="#DDEAE5",
            fg="#163D31",
            activebackground="#C6DDD4",
            activeforeground="#163D31",
            relief="flat",
            bd=0,
            padx=14,
            pady=7,
            font=("Segoe UI", 9, "bold"),
            cursor="hand2",
        )
        btn.pack(side="left", padx=(0,4), pady=5)
        self._top_nav_buttons[key] = btn

    # Indicador compacto de sección actual a la derecha.
    self._current_section_var = tk.StringVar(value="Inicio")
    indicator = tk.Label(
        nav,
        textvariable=self._current_section_var,
        bg="#173D31",
        fg="#FFFFFF",
        padx=12,
        pady=8,
        font=("Segoe UI", 9, "bold"),
    )
    indicator.pack(side="right", padx=(6,8), pady=5)
    self._current_section_label = indicator

def _v1024_update_nav_state(self, page_key):
    label_map = dict(V1024_NAV_ITEMS)
    label = label_map.get(page_key, page_key)
    try:
        self._current_section_var.set(label)
    except Exception:
        pass

    # Highlight top navigation.
    try:
        for key, btn in self._top_nav_buttons.items():
            active = key == page_key
            btn.configure(
                bg="#B45A37" if active else "#DDEAE5",
                fg="#FFFFFF" if active else "#163D31",
                activebackground="#9E4C2F" if active else "#C6DDD4",
                activeforeground="#FFFFFF" if active else "#163D31",
                relief="sunken" if active else "flat",
            )
    except Exception:
        pass

    # Highlight sidebar navigation too.
    try:
        for key, btn in getattr(self, "_sidebar_nav_buttons", {}).items():
            active = key == page_key
            btn.configure(
                bg="#B45A37" if active else "#245744",
                fg="#FFFFFF",
                activebackground="#9E4C2F" if active else "#2E6A55",
                relief="sunken" if active else "flat",
            )
    except Exception:
        pass


# Capture sidebar buttons in the existing navigation without rebuilding the whole layout.
_v1024_previous_create_widgets = SalesFormApp.create_widgets
def _v1024_create_widgets(self):
    _v1024_previous_create_widgets(self)

    # Identify sidebar navigation buttons by visible text.
    self._sidebar_nav_buttons = {}
    label_to_key = {label:key for key,label in V1024_NAV_ITEMS}
    try:
        for child in self.sidebar.winfo_children():
            if isinstance(child, tk.Button):
                txt = str(child.cget("text")).strip()
                if txt in label_to_key:
                    self._sidebar_nav_buttons[label_to_key[txt]] = child
    except Exception:
        pass

    self._v1024_build_top_navigation()
    self._v1024_update_nav_state("dashboard")

