# ==================== V10.2.5 INICIALIZACIÓN DE STOCK DESDE MAESTRO ====================

def _v1025_master_stock_rows(source_files=None):
    """
    Lee el stock inicial directamente desde Productos_Maestro / Productos.
    Se usa SOLO para inicializar inventario cuando la base aún no tiene
    movimientos ni stock positivo, evitando reiniciar stock en cada arranque.
    """
    files = source_files if source_files is not None else read_master_sources()
    result = []

    for source in files or []:
        path = Path(source)
        if not path.exists():
            continue
        try:
            book = pd.ExcelFile(path)
            sheet = _v95_find_sheet(
                book, "Productos_Maestro", "MAESTRO_PRODUCTOS", "PRODUCTOS"
            )
            if not sheet:
                book.close()
                continue

            df = pd.read_excel(book, sheet_name=sheet, nrows=20000)
            cmap = normalized_columns(df)

            def c(*opts):
                return first_column(cmap, *opts)

            code_col = c(
                "CODIGO_PRODUCTO", "CODIGO PRODUCTO", "CODIGO", "CÓDIGO", "SKU"
            )
            name_col = c("PRODUCTO", "NOMBRE")
            unit_col = c("UNIDAD", "UNIDAD_MEDIDA", "UNIDAD MEDIDA", "UOM")
            stock_col = c("STOCK_ACTUAL", "STOCK ACTUAL", "INVENTARIO")
            active_col = c("ACTIVO")

            if not name_col or not stock_col:
                book.close()
                continue

            for _, row in df.iterrows():
                name = _v95_clean_cell(row.get(name_col))
                if not name:
                    continue

                stock = money(row.get(stock_col, 0))
                if stock <= 0:
                    continue

                code = _v95_clean_cell(row.get(code_col)) if code_col else ""
                unit = (
                    _v95_clean_cell(row.get(unit_col)).upper()
                    if unit_col else ""
                )
                active = (
                    _v95_clean_cell(row.get(active_col)).upper()
                    if active_col else "SI"
                ) or "SI"

                result.append({
                    "codigo": code,
                    "nombre": name,
                    "unidad": unit,
                    "stock": float(stock),
                    "activo": active,
                    "source": str(path),
                })

            book.close()
        except Exception:
            try:
                book.close()
            except Exception:
                pass

    return result


def _v1025_initialize_inventory_stock_from_master(self):
    """
    Inicialización única y segura.

    Condiciones:
    1. No debe existir ningún movimiento de inventario.
    2. No debe existir stock positivo en la base SQLite.
    3. La fuente maestra debe contener STOCK_ACTUAL > 0.

    Una vez inicializado, se crean movimientos SALDO_INICIAL para dejar auditoría.
    En futuros arranques NO se vuelve a leer el stock del Excel, de modo que las
    ventas/entradas/salidas posteriores no se pierdan.
    """
    try:
        self.conn.execute(
            """
            CREATE TABLE IF NOT EXISTS inventario_config (
                clave TEXT PRIMARY KEY,
                valor TEXT,
                fecha_actualizacion TEXT
            )
            """
        )
        self.conn.commit()

        marker = self.conn.execute(
            "SELECT valor FROM inventario_config WHERE clave='stock_inicializado'"
        ).fetchone()

        # Si ya fue inicializado explícitamente, no tocar inventario.
        if marker and str(marker[0] or "").strip().upper() == "SI":
            return {"inicializado": False, "motivo": "YA_INICIALIZADO", "productos": 0}

        movement_count = self.conn.execute(
            "SELECT COUNT(*) FROM inventario_movimientos"
        ).fetchone()[0]

        positive_stock = self.conn.execute(
            "SELECT COUNT(*) FROM productos WHERE COALESCE(stock_actual,0) > 0"
        ).fetchone()[0]

        # Si ya existe operación de inventario, registrar marcador y respetarla.
        if movement_count > 0 or positive_stock > 0:
            self.conn.execute(
                """
                INSERT INTO inventario_config(clave,valor,fecha_actualizacion)
                VALUES('stock_inicializado','SI',?)
                ON CONFLICT(clave) DO UPDATE SET
                    valor='SI', fecha_actualizacion=excluded.fecha_actualizacion
                """,
                (datetime.now().isoformat(timespec="seconds"),)
            )
            self.conn.commit()
            return {
                "inicializado": False,
                "motivo": "DB_YA_TIENE_OPERACION",
                "productos": int(positive_stock),
            }

        rows = _v1025_master_stock_rows()
        if not rows:
            return {"inicializado": False, "motivo": "MAESTRO_SIN_STOCK", "productos": 0}

        now = datetime.now().isoformat(timespec="seconds")
        applied = 0
        not_found = []

        cur = self.conn.cursor()
        cur.execute("BEGIN IMMEDIATE")
        try:
            for item in rows:
                code = str(item.get("codigo", "") or "").strip()
                name = str(item.get("nombre", "") or "").strip()

                product = None
                if code:
                    product = cur.execute(
                        """
                        SELECT codigo,nombre,unidad,stock_actual
                        FROM productos
                        WHERE codigo=?
                        LIMIT 1
                        """,
                        (code,)
                    ).fetchone()

                if product is None and name:
                    product = cur.execute(
                        """
                        SELECT codigo,nombre,unidad,stock_actual
                        FROM productos
                        WHERE TRIM(nombre)=TRIM(?) COLLATE NOCASE
                        LIMIT 1
                        """,
                        (name,)
                    ).fetchone()

                if product is None:
                    not_found.append(f"{code} {name}".strip())
                    continue

                db_code = str(product["codigo"])
                db_name = str(product["nombre"])
                db_unit = str(product["unidad"] or item.get("unidad") or "KLS").upper()
                stock = float(item["stock"])

                cur.execute(
                    """
                    UPDATE productos
                       SET stock_actual=?,
                           ultima_modificacion=?,
                           fuente_origen=CASE
                               WHEN TRIM(COALESCE(fuente_origen,''))=''
                               THEN ?
                               ELSE fuente_origen
                           END
                     WHERE codigo=?
                    """,
                    (stock, now, item.get("source",""), db_code)
                )

                movement_id = f"INICIAL-{db_code}-20261013"
                cur.execute(
                    """
                    INSERT OR IGNORE INTO inventario_movimientos (
                        id_movimiento,fecha_hora,tipo_movimiento,
                        documento_referencia,codigo_producto,producto,unidad,
                        saldo_antes,cantidad_movimiento,saldo_despues,
                        costo_unitario_entrada,costo_total_movimiento,
                        responsable,soporte,observacion,origen,estado,fecha_cargue
                    ) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)
                    """,
                    (
                        movement_id,
                        now,
                        "SALDO_INICIAL",
                        "BASE_MAESTRA_INVENTARIO_2026-10-13",
                        db_code,
                        db_name,
                        db_unit,
                        0.0,
                        stock,
                        stock,
                        0.0,
                        0.0,
                        "SISTEMA",
                        "",
                        "Stock inicial cargado desde la base maestra de inventario revisada.",
                        "FUENTE_MAESTRA",
                        "APLICADO",
                        now,
                    )
                )
                applied += 1

            cur.execute(
                """
                INSERT INTO inventario_config(clave,valor,fecha_actualizacion)
                VALUES('stock_inicializado','SI',?)
                ON CONFLICT(clave) DO UPDATE SET
                    valor='SI', fecha_actualizacion=excluded.fecha_actualizacion
                """,
                (now,)
            )
            self.conn.commit()
        except Exception:
            self.conn.rollback()
            raise

        return {
            "inicializado": True,
            "motivo": "OK",
            "productos": applied,
            "no_encontrados": not_found,
        }

    except Exception as exc:
        return {
            "inicializado": False,
            "motivo": f"ERROR: {exc}",
            "productos": 0,
        }


SalesStore.initialize_inventory_stock_from_master = _v1025_initialize_inventory_stock_from_master


