# Registrar corte después de un AJUSTE_CONTEO.
_v1026_previous_register_inventory_movement = SalesStore.register_inventory_movement
def _v1026_register_inventory_movement(self,data:dict) -> dict:
    data = dict(data or {})
    movement_type = _v1020_text(data.get("tipo_movimiento")).upper()

    if movement_type == "AJUSTE_CONTEO":
        data["fecha_hora"] = _v1026_normalize_count_datetime(data.get("fecha_hora"))

    result = _v1026_previous_register_inventory_movement(self,data)

    if movement_type == "AJUSTE_CONTEO":
        code = _v1020_text(data.get("codigo_producto"))
        cutoff = _v1026_normalize_count_datetime(data.get("fecha_hora"))
        now = datetime.now().isoformat(timespec="seconds")

        cur = self.conn.cursor()
        cur.execute(
            """
            INSERT INTO inventario_cortes
            (codigo_producto,fecha_hora_corte,cantidad_contada,id_movimiento,
             responsable,observacion,fecha_registro)
            VALUES (?,?,?,?,?,?,?)
            """,
            (
                code,
                cutoff,
                float(result.get("saldo_despues",0) or 0),
                result.get("id_movimiento",""),
                _v1020_text(data.get("responsable")),
                _v1020_text(data.get("observacion")),
                now,
            )
        )
        id_corte = cur.lastrowid
        self.conn.commit()
        self.snapshot_sales_at_cut(id_corte,code)

        result["id_corte"] = id_corte
        result["fecha_hora_corte"] = cutoff

    return result

SalesStore.register_inventory_movement = _v1026_register_inventory_movement


def _v1026_sale_effect_for_latest_cut(
    self,
    codigo_producto:str,
    cuenta_cobro:str,
    item:int,
    cantidad_actual:float,
):
    """
    Calcula solo el efecto de la venta posterior al último conteo físico.

    Ejemplos:
      - Venta ya existía en el corte con 5 unidades y sigue en 5 => efecto 0.
      - Venta existía con 5 y luego se corrige a 6 => efecto -1.
      - Venta existía con 5 y se corrige a 4 => efecto +1.
      - Venta nueva después del corte => efecto -cantidad completa.
    """
    cut = self.latest_inventory_cut(codigo_producto)
    if not cut:
        return {
            "id_corte": None,
            "baseline": 0.0,
            "delta_venta": abs(float(cantidad_actual or 0)),
        }

    baseline = self.cut_baseline_qty(
        int(cut["id_corte"]),
        cuenta_cobro,
        int(item),
    )
    current = abs(float(cantidad_actual or 0))
    return {
        "id_corte": int(cut["id_corte"]),
        "baseline": baseline,
        "delta_venta": current - baseline,
        "fecha_hora_corte": cut.get("fecha_hora_corte"),
    }

SalesStore.sale_effect_for_latest_cut = _v1026_sale_effect_for_latest_cut


def _v1026_apply_sale_effect(
    self,
    *,
    cuenta_cobro:str,
    item:int,
    codigo_producto:str,
    producto:str,
    unidad:str,
    cantidad_actual:float,
):
    """
    Sincroniza el efecto neto de una línea de venta respecto al último conteo.
    Mantiene un movimiento independiente por corte para conservar auditoría.
    """
    info = self.sale_effect_for_latest_cut(
        codigo_producto,cuenta_cobro,item,cantidad_actual
    )
    cut_tag = str(info["id_corte"]) if info["id_corte"] is not None else "BASE"
    movement_id = f"VENTACORTE-{cuenta_cobro}-{int(item)}-{cut_tag}"
    desired_sale_delta = float(info["delta_venta"])

    # Efecto deseado sobre stock:
    # +delta venta => salida (-stock)
    # -delta venta => devolución/corrección (+stock)
    desired_stock_effect = -desired_sale_delta

    existing = self.table(
        """
        SELECT *
        FROM inventario_movimientos
        WHERE id_movimiento=?
        LIMIT 1
        """,
        (movement_id,),
    )
    old_effect = 0.0 if existing.empty else _v1020_num(
        existing.iloc[0].get("cantidad_movimiento"),0
    )

    diff = desired_stock_effect - old_effect

    product_row = self.table(
        "SELECT stock_actual,nombre,unidad FROM productos WHERE codigo=? LIMIT 1",
        (codigo_producto,),
    )
    if product_row.empty:
        return {"estado":"REVISAR","motivo":"PRODUCTO_NO_EXISTE"}

    current_stock = _v1020_num(product_row.iloc[0].get("stock_actual"),0)
    proposed_stock = current_stock + diff

    if proposed_stock < -0.0001:
        # No alterar el saldo; dejar auditoría pendiente.
        now = datetime.now().isoformat(timespec="seconds")
        self.conn.execute(
            """
            INSERT OR REPLACE INTO inventario_movimientos (
                id_movimiento,fecha_hora,tipo_movimiento,documento_referencia,
                codigo_producto,producto,unidad,saldo_antes,cantidad_movimiento,
                saldo_despues,responsable,observacion,origen,estado,fecha_cargue
            ) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)
            """,
            (
                movement_id,now,"VENTA",cuenta_cobro,codigo_producto,producto,unidad,
                current_stock,old_effect,current_stock,"SISTEMA",
                f"REVISAR: la venta requiere efecto {desired_stock_effect:,.2f}; "
                f"stock disponible {current_stock:,.2f}. "
                f"Baseline del último conteo: {info['baseline']:,.2f}.",
                "VENTA","REVISAR",now
            )
        )
        self.conn.commit()
        return {"estado":"REVISAR","saldo":current_stock}

    proposed_stock = max(proposed_stock,0)
    now = datetime.now().isoformat(timespec="seconds")

    # Si el efecto neto queda en cero, eliminar solo el movimiento técnico del corte.
    if abs(desired_stock_effect) < 0.0001:
        if not existing.empty:
            self.conn.execute(
                "UPDATE productos SET stock_actual=? WHERE codigo=?",
                (proposed_stock,codigo_producto),
            )
            self.conn.execute(
                "DELETE FROM inventario_movimientos WHERE id_movimiento=?",
                (movement_id,),
            )
            self.conn.commit()
        return {
            "estado":"SIN_EFECTO",
            "saldo":proposed_stock,
            "baseline":info["baseline"],
        }

    move_type = "VENTA" if desired_stock_effect < 0 else "AJUSTE_VENTA"
    observation = (
        f"Efecto neto posterior al corte físico. "
        f"Cantidad actual venta: {abs(float(cantidad_actual or 0)):,.2f}; "
        f"incluida en último conteo: {info['baseline']:,.2f}; "
        f"efecto inventario: {desired_stock_effect:,.2f}."
    )

    if existing.empty:
        self.conn.execute(
            """
            INSERT INTO inventario_movimientos (
                id_movimiento,fecha_hora,tipo_movimiento,documento_referencia,
                codigo_producto,producto,unidad,saldo_antes,cantidad_movimiento,
                saldo_despues,costo_unitario_entrada,costo_total_movimiento,
                responsable,soporte,observacion,origen,estado,fecha_cargue
            ) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)
            """,
            (
                movement_id,now,move_type,cuenta_cobro,codigo_producto,producto,unidad,
                current_stock,desired_stock_effect,proposed_stock,0,0,
                "SISTEMA","",observation,"VENTA","APLICADO",now
            )
        )
    else:
        self.conn.execute(
            """
            UPDATE inventario_movimientos
               SET fecha_hora=?,
                   tipo_movimiento=?,
                   producto=?,
                   unidad=?,
                   saldo_antes=?,
                   cantidad_movimiento=?,
                   saldo_despues=?,
                   observacion=?,
                   estado='APLICADO',
                   fecha_cargue=?
             WHERE id_movimiento=?
            """,
            (
                now,move_type,producto,unidad,current_stock,
                desired_stock_effect,proposed_stock,observation,now,movement_id
            )
        )

    self.conn.execute(
        """
        UPDATE productos
           SET stock_actual=?, ultima_modificacion=?, modificado_manualmente=1
         WHERE codigo=?
        """,
        (proposed_stock,now,codigo_producto),
    )
    self.conn.commit()

    return {
        "estado":"APLICADO",
        "saldo":proposed_stock,
        "efecto":desired_stock_effect,
        "baseline":info["baseline"],
    }

SalesStore.apply_sale_effect = _v1026_apply_sale_effect


# Reemplazar la sincronización de ventas del V10.2.0 por la lógica basada en cortes.
def _v1026_sync_sale_inventory(self,cuenta_cobro:str):
    account = _v1020_text(cuenta_cobro)
    if not account:
        return []

    sale = self.table(
        "SELECT estado_venta FROM ventas WHERE cuenta_cobro=? LIMIT 1",
        (account,),
    )
    if sale.empty:
        return []

    anulada = _v1017_norm_sale_status(
        sale.iloc[0].get("estado_venta")
    ) == "ANULADA"

    details = self.table(
        """
        SELECT item,codigo_producto,producto,unidad,cantidad_kls
        FROM ventas_detalle
        WHERE cuenta_cobro=?
        ORDER BY item
        """,
        (account,),
    )

    results = []
    if details.empty:
        return results

    for _, r in details.iterrows():
        code = _v1020_text(r.get("codigo_producto"))
        if not code:
            continue
        qty = 0.0 if anulada else abs(_v1020_num(r.get("cantidad_kls"),0))
        try:
            results.append(
                self.apply_sale_effect(
                    cuenta_cobro=account,
                    item=int(_v1020_num(r.get("item"),0)),
                    codigo_producto=code,
                    producto=_v1020_text(r.get("producto")),
                    unidad=_v1020_text(r.get("unidad")),
                    cantidad_actual=qty,
                )
            )
        except Exception as exc:
            results.append({"estado":"ERROR","error":str(exc),"codigo":code})

    return results

SalesStore.sync_sale_inventory = _v1026_sync_sale_inventory


# Mostrar fecha y hora de corte en el formulario de inventario.
