def _v1026_build_inventory_tab(self):
    _v1026_previous_build_inventory_tab(self)
    try:
        self.vars["inv_fecha"].set(
            _v1017_colombia_now().strftime("%Y-%m-%d %H:%M:%S")
        )
        # Agregar una nota visible y simple.
        form = None
        for child in self.inventory_tab.winfo_children():
            try:
                if isinstance(child, ttk.LabelFrame) and "movimiento manual" in str(child.cget("text")).lower():
                    form = child
                    break
            except Exception:
                pass
        if form is not None:
            ttk.Label(
                form,
                text="Para Conteo físico use fecha y hora: el conteo se convierte en el nuevo punto de corte del producto.",
                style="Hint.TLabel"
            ).grid(row=5,column=0,columnspan=6,sticky="w",padx=4,pady=(4,0))
    except Exception:
        pass

SalesFormApp.build_inventory_tab = _v1026_build_inventory_tab


