# ==================== V10.2.7 SINCRONIZACIÓN SEGURA DE STOCK MAESTRO ====================

def _v1027_master_stock_map(source_files=None):
    """
    Lee STOCK_ACTUAL del maestro sin modificar aún SQLite.
    Devuelve mapa por código y, como respaldo, por nombre.
    """
    rows = _v1025_master_stock_rows(source_files)
    by_code, by_name = {}, {}
    for r in rows:
        code = _v1020_text(r.get("codigo"))
        name = _v1020_text(r.get("nombre")).upper()
        if code:
            by_code[code] = r
        if name:
            by_name[name] = r
    return by_code, by_name


def _v1027_inventory_has_real_operation(self):
    """
    Distingue movimientos operativos reales de residuos técnicos.
    SALDO_INICIAL no bloquea una resincronización manual.
    """
    try:
        row = self.conn.execute(
            """
            SELECT COUNT(*)
            FROM inventario_movimientos
            WHERE UPPER(COALESCE(tipo_movimiento,'')) NOT IN ('SALDO_INICIAL')
              AND UPPER(COALESCE(estado,'APLICADO')) <> 'REVISAR'
            """
        ).fetchone()
        return int(row[0] or 0) > 0
    except Exception:
        return False


def _v1027_sync_stock_from_master(self, force=False):
    """
    Sincroniza el stock del maestro de forma controlada.

    - Si ya hay operación real de inventario, no sobrescribe automáticamente.
    - Si no hay operación real, permite recuperar un maestro previamente cargado
      con STOCK_ACTUAL que versiones anteriores dejaron en cero.
    - Registra / actualiza SALDO_INICIAL para trazabilidad.
    """
    self.conn.execute(
        """
        CREATE TABLE IF NOT EXISTS inventario_config (
            clave TEXT PRIMARY KEY,
            valor TEXT,
            fecha_actualizacion TEXT
        )
        """
    )
    self.conn.commit()

    if self.inventory_has_real_operation() and not force:
        return {
            "aplicado": False,
            "motivo": "HAY_OPERACION_REAL",
            "productos": 0,
        }

    by_code, by_name = _v1027_master_stock_map()
    if not by_code and not by_name:
        return {
            "aplicado": False,
            "motivo": "MAESTRO_SIN_STOCK",
            "productos": 0,
        }

    products = self.table(
        "SELECT codigo,nombre,unidad,COALESCE(stock_actual,0) stock_actual FROM productos"
    )
    if products.empty:
        return {
            "aplicado": False,
            "motivo": "SIN_PRODUCTOS_SQLITE",
            "productos": 0,
        }

    now = _v1017_colombia_now().replace(tzinfo=None).isoformat(timespec="seconds")
    applied = 0
    missing = []

    cur = self.conn.cursor()
    cur.execute("BEGIN IMMEDIATE")
    try:
        for _, p in products.iterrows():
            code = _v1020_text(p.get("codigo"))
            name = _v1020_text(p.get("nombre"))
            item = by_code.get(code) or by_name.get(name.upper())
            if not item:
                continue

            stock = float(item.get("stock", 0) or 0)
            if stock <= 0:
                continue

            cur.execute(
                """
                UPDATE productos
                   SET stock_actual=?,
                       ultima_modificacion=?
                 WHERE codigo=?
                """,
                (stock, now, code)
            )

            movement_id = f"INICIAL-{code}-20261013"
            existing = cur.execute(
                "SELECT id_movimiento FROM inventario_movimientos WHERE id_movimiento=?",
                (movement_id,)
            ).fetchone()

            if existing:
                cur.execute(
                    """
                    UPDATE inventario_movimientos
                       SET fecha_hora=?,
                           documento_referencia='BASE_MAESTRA_INVENTARIO_2026-10-13',
                           producto=?,
                           unidad=?,
                           saldo_antes=0,
                           cantidad_movimiento=?,
                           saldo_despues=?,
                           observacion='Stock inicial sincronizado desde maestro revisado.',
                           origen='FUENTE_MAESTRA',
                           estado='APLICADO',
                           fecha_cargue=?
                     WHERE id_movimiento=?
                    """,
                    (
                        now, name, _v1020_text(p.get("unidad")) or item.get("unidad","KLS"),
                        stock, stock, now, movement_id
                    )
                )
            else:
                cur.execute(
                    """
                    INSERT INTO inventario_movimientos (
                        id_movimiento,fecha_hora,tipo_movimiento,documento_referencia,
                        codigo_producto,producto,unidad,saldo_antes,cantidad_movimiento,
                        saldo_despues,costo_unitario_entrada,costo_total_movimiento,
                        responsable,soporte,observacion,origen,estado,fecha_cargue
                    ) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)
                    """,
                    (
                        movement_id, now, "SALDO_INICIAL",
                        "BASE_MAESTRA_INVENTARIO_2026-10-13",
                        code, name,
                        _v1020_text(p.get("unidad")) or item.get("unidad","KLS"),
                        0.0, stock, stock, 0.0, 0.0,
                        "SISTEMA", "",
                        "Stock inicial sincronizado desde maestro revisado.",
                        "FUENTE_MAESTRA", "APLICADO", now
                    )
                )
            applied += 1

        cur.execute(
            """
            INSERT INTO inventario_config(clave,valor,fecha_actualizacion)
            VALUES('stock_inicializado','SI',?)
            ON CONFLICT(clave) DO UPDATE SET
                valor='SI',
                fecha_actualizacion=excluded.fecha_actualizacion
            """,
            (now,)
        )
        self.conn.commit()
    except Exception:
        self.conn.rollback()
        raise

    return {
        "aplicado": True,
        "motivo": "OK",
        "productos": applied,
        "faltantes": missing,
    }


SalesStore.inventory_has_real_operation = _v1027_inventory_has_real_operation
SalesStore.sync_stock_from_master = _v1027_sync_stock_from_master


def _v1027_recover_zero_stock_on_start(self):
    """
    Recuperación automática SOLO cuando:
    - todos los productos tienen stock 0,
    - el maestro sí tiene stock,
    - y todavía no existe operación real de inventario.
    """
    try:
        positive = self.conn.execute(
            "SELECT COUNT(*) FROM productos WHERE COALESCE(stock_actual,0)>0"
        ).fetchone()[0]
        if int(positive or 0) > 0:
            return {"aplicado": False, "motivo": "YA_HAY_STOCK"}

        if self.inventory_has_real_operation():
            return {"aplicado": False, "motivo": "HAY_OPERACION_REAL"}

        by_code, by_name = _v1027_master_stock_map()
        if not by_code and not by_name:
            return {"aplicado": False, "motivo": "MAESTRO_SIN_STOCK"}

        return self.sync_stock_from_master(force=False)
    except Exception as exc:
        return {"aplicado": False, "motivo": f"ERROR: {exc}"}


SalesStore.recover_zero_stock_on_start = _v1027_recover_zero_stock_on_start


# Ejecutar recuperación después de todas las inicializaciones previas.
_v1027_previous_store_init = SalesStore.__init__
def _v1027_store_init(self,*args,**kwargs):
    _v1027_previous_store_init(self,*args,**kwargs)
    try:
        self._stock_recovery_result = self.recover_zero_stock_on_start()
    except Exception:
        self._stock_recovery_result = {"aplicado": False, "motivo": "ERROR"}

SalesStore.__init__ = _v1027_store_init


# Botón manual visible dentro de Inventarios.
_v1027_previous_build_inventory_tab = SalesFormApp.build_inventory_tab
def _v1027_build_inventory_tab(self):
    _v1027_previous_build_inventory_tab(self)
    try:
        children = self.inventory_tab.winfo_children()
        actions = children[1] if len(children) > 1 else self.inventory_tab
        ttk.Button(
            actions,
            text="Sincronizar stock maestro",
            style="Soft.TButton",
            command=self.sync_inventory_stock_from_master_ui,
        ).pack(side="left", padx=3)
    except Exception:
        pass

SalesFormApp.build_inventory_tab = _v1027_build_inventory_tab


def _v1027_sync_inventory_stock_from_master_ui(self):
    try:
        has_ops = self.store.inventory_has_real_operation()
        if has_ops:
            ok = messagebox.askyesno(
                "Inventario con movimientos",
                "Ya existen movimientos reales de inventario.\n\n"
                "Sincronizar nuevamente el STOCK_ACTUAL del maestro puede reemplazar "
                "el saldo operativo actual.\n\n"
                "¿Deseas continuar de todas formas?",
                parent=self,
            )
            if not ok:
                return
            result = self.store.sync_stock_from_master(force=True)
        else:
            result = self.store.sync_stock_from_master(force=False)

        if result.get("aplicado"):
            self.refresh_inventory()
            try:
                self.reload_master_catalogs()
            except Exception:
                pass
            try:
                self.refresh_all()
            except Exception:
                pass
            messagebox.showinfo(
                "Stock sincronizado",
                f"Se cargó el stock del maestro para {result.get('productos',0)} productos.",
                parent=self,
            )
        else:
            messagebox.showwarning(
                "Stock no sincronizado",
                f"No se realizaron cambios.\nMotivo: {result.get('motivo','SIN DETALLE')}",
                parent=self,
            )
    except Exception as exc:
        messagebox.showerror("Stock maestro", str(exc), parent=self)

SalesFormApp.sync_inventory_stock_from_master_ui = _v1027_sync_inventory_stock_from_master_ui


# Mostrar recuperación automática en estado del módulo.
_v1027_previous_refresh_inventory = SalesFormApp.refresh_inventory
def _v1027_refresh_inventory(self):
    _v1027_previous_refresh_inventory(self)
    try:
        result = getattr(self.store, "_stock_recovery_result", {})
        if result.get("aplicado"):
            current = self.vars["inventory_status"].get()
            self.vars["inventory_status"].set(
                current + f" | Recuperados desde maestro: {result.get('productos',0)}"
            )
    except Exception:
        pass

SalesFormApp.refresh_inventory = _v1027_refresh_inventory

# ==================== FIN V10.2.7 ====================



# ==================== V10.2.8 CARGA FINAL INVENTARIO + VENTAS POST-CORTE ====================

def _v1028_yes(v) -> bool:
    return str(v or "").strip().upper() in {"SI","SÍ","YES","TRUE","1","X"}

def _v1028_date_text(v) -> str:
    s = _v1020_text(v)
    if not s:
        return ""
    try:
        d = pd.to_datetime(s, errors="raise")
        return d.strftime("%Y-%m-%d")
    except Exception:
        return s[:10]

def _v1028_update_product_master(self, code, *, new_name=None, new_unit=None, active=None, reason="Inventario Excel"):
    df = self.table("SELECT * FROM productos WHERE codigo=? LIMIT 1",(code,))
    if df.empty:
        raise ValueError(f"No existe el producto {code}.")
    p = df.iloc[0]
    now = datetime.now().isoformat(timespec="seconds")

    changes = {}
    if new_name and _v1020_text(new_name) != _v1020_text(p.get("nombre")):
        changes["nombre"] = _v1020_text(new_name)
    if new_unit and _v1020_text(new_unit).upper() != _v1020_text(p.get("unidad")).upper():
        changes["unidad"] = _v1020_text(new_unit).upper()
    if active:
        av = "SI" if _v1028_yes(active) else "NO"
        if av != _v1020_text(p.get("activo")).upper():
            changes["activo"] = av

    if not changes:
        return []

    # Evitar nombres duplicados.
    if "nombre" in changes:
        dup = self.table(
            "SELECT codigo FROM productos WHERE UPPER(TRIM(nombre))=UPPER(TRIM(?)) AND codigo<>? LIMIT 1",
            (changes["nombre"], code)
        )
        if not dup.empty:
            raise ValueError(
                f"No se puede renombrar {code} a '{changes['nombre']}': "
                f"ya existe en el código {dup.iloc[0].get('codigo')}."
            )

    for field, new_value in changes.items():
        old_value = _v1020_text(p.get(field))
        self.conn.execute(
            """
            INSERT INTO inventario_cambios_producto
            (fecha_hora,codigo_producto,campo,valor_anterior,valor_nuevo,origen,responsable,observacion)
            VALUES (?,?,?,?,?,'INVENTARIO_EXCEL','SISTEMA',?)
            """,
            (now,code,field,old_value,_v1020_text(new_value),reason)
        )

    sets = []
    params = []
    for field,new_value in changes.items():
        sets.append(f"{field}=?")
        params.append(new_value)
    sets.extend(["ultima_modificacion=?","modificado_manualmente=1"])
    params.extend([now,code])
    self.conn.execute(
        f"UPDATE productos SET {', '.join(sets)} WHERE codigo=?",
        tuple(params)
    )
    self.conn.commit()
    return list(changes.keys())

SalesStore.update_product_master_from_inventory = _v1028_update_product_master


def _v1028_snapshot_sales_at_cut(self, id_corte:int, codigo_producto:str):
    """
    V10.2.8:
    - Corte a 00:00:00: las ventas de ese mismo día NO se consideran incluidas
      en el conteo y se descontarán posteriormente.
    - Corte con hora distinta de 00:00:00: como ventas.fecha solo tiene precisión
      de día, las ventas del mismo día se consideran incluidas en el conteo.
    """
    cut_df = self.table(
        "SELECT fecha_hora_corte FROM inventario_cortes WHERE id_corte=? LIMIT 1",
        (int(id_corte),)
    )
    if cut_df.empty:
        return

    cut_raw = _v1020_text(cut_df.iloc[0].get("fecha_hora_corte"))
    try:
        cut_dt = pd.to_datetime(cut_raw).to_pydatetime()
    except Exception:
        cut_dt = datetime.now()

    cut_date = cut_dt.strftime("%Y-%m-%d")
    start_of_day = (cut_dt.hour, cut_dt.minute, cut_dt.second) == (0,0,0)

    op = "<" if start_of_day else "<="
    sales = self.table(
        f"""
        SELECT
            d.cuenta_cobro,
            d.item,
            d.codigo_producto,
            COALESCE(d.cantidad_kls,0) cantidad,
            COALESCE(v.estado_venta,'') estado_venta,
            v.fecha
        FROM ventas_detalle d
        JOIN ventas v ON v.cuenta_cobro=d.cuenta_cobro
        WHERE d.codigo_producto=?
          AND date(v.fecha) {op} date(?)
        """,
        (codigo_producto, cut_date),
    )

    cur = self.conn.cursor()
    for _, r in sales.iterrows():
        if _v1017_norm_sale_status(r.get("estado_venta")) == "ANULADA":
            continue
        account = _v1020_text(r.get("cuenta_cobro"))
        item = int(_v1020_num(r.get("item"),0))
        key = f"{account}|{item}"
        qty = abs(_v1020_num(r.get("cantidad"),0))
        cur.execute(
            """
            INSERT OR REPLACE INTO inventario_corte_ventas
            (id_corte,venta_item_key,cuenta_cobro,item,cantidad_en_corte)
            VALUES (?,?,?,?,?)
            """,
            (id_corte,key,account,item,qty),
        )
    self.conn.commit()

SalesStore.snapshot_sales_at_cut = _v1028_snapshot_sales_at_cut


def _v1028_reconcile_sales_since_date(self, product_codes, from_date):
    """
    Descuenta ventas registradas en la DB desde la fecha del corte (inclusive)
    únicamente para los productos cargados en este inventario.
    """
    codes = sorted({_v1020_text(c) for c in product_codes if _v1020_text(c)})
    if not codes:
        return {"lineas":0,"aplicadas":0,"revisar":0,"errores":[]}

    placeholders = ",".join(["?"]*len(codes))
    params = [*codes, _v1028_date_text(from_date)]
    df = self.table(
        f"""
        SELECT
            v.cuenta_cobro,
            v.fecha,
            v.estado_venta,
            d.item,
            d.codigo_producto,
            d.producto,
            d.unidad,
            COALESCE(d.cantidad_kls,0) cantidad
        FROM ventas v
        JOIN ventas_detalle d ON d.cuenta_cobro=v.cuenta_cobro
        WHERE d.codigo_producto IN ({placeholders})
          AND date(v.fecha) >= date(?)
        ORDER BY v.fecha, v.cuenta_cobro, d.item
        """,
        tuple(params)
    )

    applied = 0
    review = 0
    errors = []

    for _, r in df.iterrows():
        qty = 0.0 if _v1017_norm_sale_status(r.get("estado_venta")) == "ANULADA" else abs(_v1020_num(r.get("cantidad"),0))
        try:
            result = self.apply_sale_effect(
                cuenta_cobro=_v1020_text(r.get("cuenta_cobro")),
                item=int(_v1020_num(r.get("item"),0)),
                codigo_producto=_v1020_text(r.get("codigo_producto")),
                producto=_v1020_text(r.get("producto")),
                unidad=_v1020_text(r.get("unidad")),
                cantidad_actual=qty,
            )
            if result.get("estado") == "APLICADO":
                applied += 1
            elif result.get("estado") == "REVISAR":
                review += 1
        except Exception as exc:
            errors.append(
                f"{_v1020_text(r.get('cuenta_cobro'))} / "
                f"{_v1020_text(r.get('codigo_producto'))}: {exc}"
            )

    return {
        "lineas":len(df),
        "aplicadas":applied,
        "revisar":review,
        "errores":errors,
    }

SalesStore.reconcile_sales_since_inventory_date = _v1028_reconcile_sales_since_date


def _v1028_apply_master_change_sheet(self, path:Path, confirm_changes_callback=None):
    try:
        df = pd.read_excel(path, sheet_name="Cambios_maestro")
    except Exception:
        return {"actualizados":0,"errores":[]}

    df.columns=[str(c).strip() for c in df.columns]
    df=df[df.get("Código",pd.Series(dtype=object)).notna()].copy()
    if df.empty:
        return {"actualizados":0,"errores":[]}

    summary=[]
    for _,r in df.iterrows():
        summary.append(
            f"{_v1020_text(r.get('Código'))}: "
            f"{_v1020_text(r.get('Nombre actual'))} -> {_v1020_text(r.get('Nombre nuevo'))}; "
            f"unidad {_v1020_text(r.get('Unidad nueva'))}"
        )

    if confirm_changes_callback and summary:
        if not confirm_changes_callback("\n".join(summary)):
            return {"actualizados":0,"errores":["Cambios de maestro no autorizados por el usuario."]}

    updated=0
    errors=[]
    for i,r in df.iterrows():
        code=_v1020_text(r.get("Código"))
        try:
            fields=self.update_product_master_from_inventory(
                code,
                new_name=_v1020_text(r.get("Nombre nuevo")) or None,
                new_unit=_v1020_text(r.get("Unidad nueva")) or None,
                active=_v1020_text(r.get("Activo")) or None,
                reason=_v1020_text(r.get("Motivo")) or "Cambio aprobado desde Excel",
            )
            if fields:
                updated += 1
        except Exception as exc:
            errors.append(f"Cambios_maestro fila {i+2}: {exc}")
    return {"actualizados":updated,"errores":errors}


def _v1028_import_inventory_excel(self,path:Path,confirm_changes_callback=None) -> dict:
    # Preferir hoja final preparada para carga; mantener compatibilidad con formato simple anterior.
    sheet_name = None
    try:
        book = pd.ExcelFile(path)
        if "Inventario_Carga_App" in book.sheet_names:
            sheet_name = "Inventario_Carga_App"
        elif "Inventario" in book.sheet_names:
            sheet_name = "Inventario"
        book.close()
    except Exception:
        pass

    if not sheet_name:
        return _v1021_import_inventory_excel(self,path,confirm_changes_callback)

    df = pd.read_excel(path,sheet_name=sheet_name)
    df.columns=[str(c).strip() for c in df.columns]

    required={"Tipo de movimiento","Producto","Unidad"}
    missing=required-set(df.columns)
    if missing:
        raise ValueError("Faltan columnas: "+", ".join(sorted(missing)))

    # Cambios de maestro sin movimiento de inventario (ej. CHAMOY 500 -> 450).
    master_result = self._v1028_apply_master_change_sheet(path,confirm_changes_callback)

    if "Estado de carga" in df.columns:
        df=df[
            df["Estado de carga"].fillna("CARGAR").astype(str).str.strip().str.upper().eq("CARGAR")
        ].copy()

    df=df[df["Producto"].notna()].copy()
    if df.empty:
        raise ValueError("No hay productos para cargar.")

    loaded=[]
    skipped=[]
    errors=list(master_result.get("errores",[]))
    created=[]
    updated=[]
    cut_groups={}  # fecha -> set(códigos)

    for i,row in df.iterrows():
        excel_row=i+2
        product_name=_v1020_text(row.get("Producto"))
        requested_code=_v1020_text(row.get("Código"))
        code=requested_code
        unit=_v1020_text(row.get("Unidad")).upper()
        movement_type=_v1021_simple_movement_type(row.get("Tipo de movimiento"))
        update_master=_v1028_yes(row.get("Actualizar maestro"))
        active=_v1020_text(row.get("Activo")) or "SI"
        discount_same_day=_v1028_yes(row.get("Descontar ventas del día"))

        qty=_v1020_num(row.get("Cantidad final"),0)
        if qty <= 0:
            qty=_v1020_num(row.get("Cantidad / Conteo"),0)
        if qty <= 0:
            gross=_v1020_num(row.get("Peso bruto (kg)"),0)
            boxes=_v1020_num(row.get("Número de cajas"),0)
            tare=_v1020_num(row.get("Tara por caja (kg)"),0)
            if gross > 0:
                qty=max(gross-(boxes*tare),0)
        if qty <= 0:
            skipped.append(f"Fila {excel_row}: {product_name} sin cantidad válida.")
            continue

        existing=pd.DataFrame()
        if code:
            existing=self.table("SELECT * FROM productos WHERE codigo=? LIMIT 1",(code,))

        if existing.empty and not code:
            existing=self.table(
                "SELECT * FROM productos WHERE UPPER(TRIM(nombre))=UPPER(TRIM(?)) LIMIT 1",
                (product_name,)
            )
            if not existing.empty:
                code=_v1020_text(existing.iloc[0].get("codigo"))

        if existing.empty:
            # Evitar duplicar por nombre con otro código.
            by_name=self.table(
                "SELECT * FROM productos WHERE UPPER(TRIM(nombre))=UPPER(TRIM(?)) LIMIT 1",
                (product_name,)
            )
            if not by_name.empty:
                code=_v1020_text(by_name.iloc[0].get("codigo"))
                existing=by_name
            else:
                # Respetar código explícito del archivo. Si está vacío, generar siguiente.
                if not code:
                    code=self.next_product_code()
                # Validar que el código siga libre.
                conflict=self.table("SELECT nombre FROM productos WHERE codigo=? LIMIT 1",(code,))
                if not conflict.empty:
                    skipped.append(
                        f"Fila {excel_row}: código {code} ya pertenece a "
                        f"{_v1020_text(conflict.iloc[0].get('nombre'))}."
                    )
                    continue
                self.upsert_producto({
                    "codigo":code,
                    "nombre":product_name,
                    "unidad":unit or "KLS",
                    "precio_venta":0,
                    "comision_unitaria_sugerida":0,
                    "costo":0,
                    "stock_actual":0,
                    "stock_minimo":0,
                    "activo":"SI" if _v1028_yes(active) else "NO",
                    "fuente_origen":"Creado desde inventario aprobado",
                })
                created.append(f"{code} - {product_name}")
                existing=self.table("SELECT * FROM productos WHERE codigo=? LIMIT 1",(code,))

        if existing.empty:
            errors.append(f"Fila {excel_row}: no fue posible resolver {product_name}.")
            continue

        master=existing.iloc[0]
        master_name=_v1020_text(master.get("nombre"))
        master_unit=_v1020_text(master.get("unidad")).upper()
        master_active=_v1020_text(master.get("activo")).upper()

        name_diff=product_name and product_name.upper()!=master_name.upper()
        unit_diff=unit and master_unit and unit!=master_unit
        active_target="SI" if _v1028_yes(active) else "NO"
        active_diff=active_target!=master_active

        if (name_diff or unit_diff or active_diff):
            if update_master:
                try:
                    fields=self.update_product_master_from_inventory(
                        code,
                        new_name=product_name if name_diff else None,
                        new_unit=unit if unit_diff else None,
                        active=active_target if active_diff else None,
                        reason=f"Carga inventario fila {excel_row}",
                    )
                    if fields:
                        updated.append(f"{code} - {product_name}: {', '.join(fields)}")
                except Exception as exc:
                    errors.append(f"Fila {excel_row}: {exc}")
                    continue
            else:
                diffs=[]
                if name_diff: diffs.append(f"nombre maestro '{master_name}'")
                if unit_diff: diffs.append(f"unidad maestro {master_unit}")
                if active_diff: diffs.append(f"activo maestro {master_active}")
                skipped.append(
                    f"Fila {excel_row}: {code} {product_name} difiere del maestro "
                    f"({'; '.join(diffs)}). Marque 'Actualizar maestro' = SI."
                )
                continue

        raw_date=_v1020_text(row.get("Fecha")) or datetime.now().isoformat(timespec="seconds")
        date_only=_v1028_date_text(raw_date)

        # Para este inventario, si se pide descontar ventas del día, el corte es 00:00.
        if movement_type=="AJUSTE_CONTEO" and discount_same_day and date_only:
            movement_datetime=f"{date_only} 00:00:00"
            cut_groups.setdefault(date_only,set()).add(code)
        else:
            movement_datetime=raw_date

        try:
            result=self.register_inventory_movement({
                "fecha_hora":movement_datetime,
                "tipo_movimiento":movement_type,
                "documento_referencia":"INVENTARIO_FISICO_EXCEL",
                "codigo_producto":code,
                "unidad":unit,
                "lote":_v1020_text(row.get("Lote")),
                "fecha_vencimiento":_v1020_text(row.get("Vencimiento")),
                "ubicacion":_v1020_text(row.get("Ubicación")),
                "cantidad_movimiento":qty,
                "costo_unitario_entrada":_v1020_num(row.get("Costo de entrada"),0),
                "responsable":_v1020_text(row.get("Responsable")) or "CARGA EXCEL",
                "soporte":str(path),
                "observacion":_v1020_text(row.get("Observación")),
                "origen":"EXCEL_SIMPLE",
            })
            loaded.append(result)
        except Exception as exc:
            errors.append(f"Fila {excel_row}: {exc}")

    # Reconciliar ventas del mismo día y posteriores, solamente para los códigos cargados.
    reconciled_lines=0
    reconciled_applied=0
    reconciled_review=0
    for cut_date,codes in sorted(cut_groups.items()):
        try:
            rr=self.reconcile_sales_since_inventory_date(codes,cut_date)
            reconciled_lines += rr.get("lineas",0)
            reconciled_applied += rr.get("aplicadas",0)
            reconciled_review += rr.get("revisar",0)
            errors.extend(rr.get("errores",[]))
        except Exception as exc:
            errors.append(f"Reconciliación ventas {cut_date}: {exc}")

    return {
        "cargados":len(loaded),
        "omitidos":len(skipped),
        "errores":len(errors),
        "detalle_omitidos":skipped,
        "detalle_errores":errors,
        "productos_creados":created,
        "productos_actualizados":updated,
        "cambios_maestro":master_result.get("actualizados",0),
        "ventas_lineas_detectadas":reconciled_lines,
        "ventas_lineas_descontadas":reconciled_applied,
        "ventas_lineas_revisar":reconciled_review,
    }

