# Mensaje de carga más completo.
def _v1028_import_inventory_file(self):
    path=filedialog.askopenfilename(
        title="Seleccionar formato de inventario",
        filetypes=[("Excel","*.xlsx *.xls")]
    )
    if not path:
        return

    def confirm_changes(text):
        return messagebox.askyesno(
            "Cambios aprobados del maestro",
            "El archivo contiene cambios en nombres/unidades/estado del maestro.\n\n"
            + text[:8000] +
            "\n\n¿Autoriza aplicar estos cambios?"
        )

    try:
        result=self.store.import_inventory_excel(Path(path),confirm_changes)
        self.reload_master_catalogs()
        self.refresh_all()
        self.refresh_inventory()

        created=result.get("productos_creados",[])
        updated=result.get("productos_actualizados",[])
        msg=(
            f"Movimientos cargados: {result.get('cargados',0)}\n"
            f"Productos nuevos creados: {len(created)}\n"
            f"Productos existentes actualizados: {len(updated)}\n"
            f"Cambios de maestro adicionales: {result.get('cambios_maestro',0)}\n"
            f"Ventas detectadas desde el corte: {result.get('ventas_lineas_detectadas',0)}\n"
            f"Descuentos de venta aplicados: {result.get('ventas_lineas_descontadas',0)}\n"
            f"Ventas para revisar: {result.get('ventas_lineas_revisar',0)}\n"
            f"Filas omitidas: {result.get('omitidos',0)}\n"
            f"Errores: {result.get('errores',0)}"
        )

        if created:
            msg += "\n\nNuevos productos (precio/costo/comisión quedan en 0 hasta completarlos):\n- " + "\n- ".join(created[:12])
        details=(result.get("detalle_omitidos",[])+result.get("detalle_errores",[]))[:20]
        if details:
            msg += "\n\nRevisión:\n- " + "\n- ".join(details)

        messagebox.showinfo("Carga de inventario",msg)
    except Exception as exc:
        messagebox.showerror("Carga de inventario",str(exc))

