def _v1032_sales_summary(self) -> pd.DataFrame:
    """
    TOTAL_FACTURA: productos + IVA + domicilio cliente.
    TOTAL_ABONOS: pagos realmente aplicados + retención reconocida.
    La retención NO aumenta la factura; reduce el saldo a pagar en efectivo.
    """
    return self.table(
        """
        SELECT
            v.cuenta_cobro,
            v.fecha,
            v.cliente,
            v.estado_venta,
            v.fuente_origen,
            COALESCE(SUM(
                d.valor_total
                + d.iva_19
                + d.chile_fresco
            ), 0)
            + COALESCE(v.domicilio_cliente, 0) AS total_factura,
            COALESCE((
                SELECT SUM(a.valor_aplicado)
                FROM aplicacion_abonos a
                JOIN abonos b ON b.id_abono=a.id_abono
                WHERE a.cuenta_cobro = v.cuenta_cobro
                  AND COALESCE(b.estado_registro,'ACTIVO') <> 'ANULADO'
            ), 0)
            + COALESCE(v.retencion_venta,0) AS total_abonos,
            COALESCE(v.retencion_venta,0) AS retencion_venta
        FROM ventas v
        LEFT JOIN ventas_detalle d ON d.cuenta_cobro = v.cuenta_cobro
        GROUP BY
            v.cuenta_cobro, v.fecha, v.cliente, v.estado_venta,
            v.fuente_origen, v.domicilio_empresa, v.domicilio_cliente,
            v.retencion_venta
        ORDER BY v.fecha DESC, v.cuenta_cobro DESC
        """
    )

SalesStore.sales_summary = _v1032_sales_summary


# Añadir la retención en "Pago y domicilio" y quitarla del producto.
_v1032_previous_build_sales_tab = SalesFormApp.build_sales_tab
def _v1032_build_sales_tab(self):
    _v1032_previous_build_sales_tab(self)

    # Campo viejo de retención por producto: ocultar y dejar siempre en cero.
    try:
        if "det_retenciones" in self.widgets:
            self.vars["det_retenciones"].set("0")
            self.widgets["det_retenciones"].grid_remove()
            # Ocultar también la etiqueta asociada si está inmediatamente antes en el grid.
            parent = self.widgets["det_retenciones"].master
            info = self.widgets["det_retenciones"].grid_info()
            r, c = int(info.get("row",4)), int(info.get("column",3))
            for w in parent.grid_slaves(row=r):
                gi=w.grid_info()
                if int(gi.get("column",0)) == max(c-1,0) and isinstance(w,ttk.Label):
                    w.grid_remove()
    except Exception:
        pass

    # Encontrar "3. Pago y domicilio".
    pay = None
    try:
        for child in self.sales_capture.winfo_children():
            if isinstance(child, ttk.LabelFrame):
                if "pago y domicilio" in str(child.cget("text")).lower():
                    pay = child
                    break
    except Exception:
        pay = None

    if pay is not None and "venta_retencion" not in self.vars:
        self.entry(
            pay, "venta_retencion", "Retención", 1, 2
        ).insert(0, "0")
        self.widgets["venta_retencion"].bind(
            "<FocusOut>", self.refresh_invoice_totals, add="+"
        )
        self.widgets["venta_retencion"].bind(
            "<KeyRelease>", self.refresh_invoice_totals, add="+"
        )

