# Exportar la retención explícitamente.
_v1032_previous_export_excel = SalesStore.export_excel
def _v1032_export_excel(self, output_path:Path, append_existing:bool=False):
    result = _v1032_previous_export_excel(self,output_path,append_existing)
    try:
        from openpyxl import load_workbook
        book=load_workbook(output_path)
        retention_map={
            str(r["cuenta_cobro"]):float(r["retencion_venta"] or 0)
            for _,r in self.table(
                "SELECT cuenta_cobro,COALESCE(retencion_venta,0) retencion_venta FROM ventas"
            ).iterrows()
        }
        for sheet_name,account_headers in [
            ("Ventas_cabecera",["CUENTA_COBRO","CUENTA DE COBRO"]),
            ("VENTAS",["CUENTA_COBRO","CUENTA DE COBRO"]),
        ]:
            if sheet_name not in book.sheetnames:
                continue
            ws=book[sheet_name]
            header={str(c.value or "").strip().upper():c.column for c in ws[1]}
            account_col=None
            for h in account_headers:
                if h in header:
                    account_col=header[h]
                    break
            if not account_col:
                continue
            ret_col=header.get("RETENCION_VENTA")
            if not ret_col:
                ret_col=ws.max_column+1
                ws.cell(1,ret_col,"RETENCION_VENTA")
            for row in range(2,ws.max_row+1):
                account=str(ws.cell(row,account_col).value or "").strip()
                ws.cell(row,ret_col,retention_map.get(account,0))
        book.save(output_path)
        book.close()
    except Exception:
        pass
    return result

SalesStore.export_excel = _v1032_export_excel


