if "REPOSICION" not in V1020_INVENTORY_MOVEMENT_TYPES:
    V1020_INVENTORY_MOVEMENT_TYPES = (
        "ENTRADA","REPOSICION","SALIDA","AJUSTE_CONTEO","AJUSTE_POSITIVO",
        "AJUSTE_NEGATIVO","MERMA","DEVOLUCION_CLIENTE",
        "DEVOLUCION_PROVEEDOR","OBSEQUIO","VENTA"
    )

_v1032_previous_simple_movement_type = _v1021_simple_movement_type
def _v1032_simple_movement_type(value):
    s=str(value or "").strip().upper()
    if s in {"REPOSICIÓN","REPOSICION"}:
        return "REPOSICION"
    return _v1032_previous_simple_movement_type(value)

_v1021_simple_movement_type = _v1032_simple_movement_type


_v1032_previous_register_inventory_movement = SalesStore.register_inventory_movement
def _v1032_register_inventory_movement(self,data:dict):
    data=dict(data or {})
    move=_v1020_text(data.get("tipo_movimiento")).upper()
    code=_v1020_text(data.get("codigo_producto"))

    if move=="OBSEQUIO":
        # Un obsequio entra a costo cero.
        data["costo_unitario_entrada"]=0.0
    elif move=="REPOSICION":
        # Reposición conserva costo: si no se informa, usar el costo maestro.
        entered=_v1020_num(data.get("costo_unitario_entrada"))
        if entered <= 0 and code:
            p=self.table("SELECT costo FROM productos WHERE codigo=? LIMIT 1",(code,))
            if not p.empty:
                data["costo_unitario_entrada"]=_v1020_num(p.iloc[0].get("costo"))

    # La implementación anterior no conoce REPOSICION; procesarla como ENTRADA
    # pero conservar el tipo real en el movimiento.
    if move=="REPOSICION":
        data_base=dict(data)
        data_base["tipo_movimiento"]="ENTRADA"
        result=_v1032_previous_register_inventory_movement(self,data_base)
        self.conn.execute(
            "UPDATE inventario_movimientos SET tipo_movimiento='REPOSICION' WHERE id_movimiento=?",
            (result["id_movimiento"],)
        )
        self.conn.commit()
        return result

    return _v1032_previous_register_inventory_movement(self,data)

SalesStore.register_inventory_movement = _v1032_register_inventory_movement


def _v1032_latest_special_inbound(self,code:str):
    """
    Devuelve el último ingreso relevante. Solo pregunta precio cero si el
    ingreso más reciente entre entradas/conteos especiales fue REPOSICION u OBSEQUIO.
    """
    df=self.table(
        """
        SELECT tipo_movimiento,costo_unitario_entrada,fecha_hora,id_movimiento
        FROM inventario_movimientos
        WHERE codigo_producto=?
          AND tipo_movimiento IN ('ENTRADA','REPOSICION','OBSEQUIO','AJUSTE_CONTEO')
          AND COALESCE(estado,'APLICADO')='APLICADO'
        ORDER BY datetime(fecha_hora) DESC, fecha_cargue DESC
        LIMIT 1
        """,
        (code,)
    )
    if df.empty:
        return None
    r=df.iloc[0].to_dict()
    if _v1020_text(r.get("tipo_movimiento")).upper() not in {"REPOSICION","OBSEQUIO"}:
        return None
    return r

SalesStore.latest_special_inbound = _v1032_latest_special_inbound


# Al seleccionar producto, preguntar por precio $0 si el último ingreso es especial.
_v1032_previous_on_detail_product_select = SalesFormApp.on_detail_product_select
def _v1032_on_detail_product_select(self,_event=None):
    result=_v1032_previous_on_detail_product_select(self,_event)
    try:
        row=self.find_product_row(self.vars["det_producto"].get().strip())
        if row.empty:
            return result
        code=str(row.iloc[0].get("codigo","")).strip()
        special=self.store.latest_special_inbound(code)
        if special:
            move=str(special.get("tipo_movimiento","")).upper()
            label="reposición" if move=="REPOSICION" else "obsequio"
            use_zero=messagebox.askyesno(
                "Producto con ingreso especial",
                f"El último ingreso de este producto fue por {label}.\n\n"
                "¿Desea registrar esta venta con precio de venta $0?\n\n"
                + (
                    "En reposición se conserva el costo del producto."
                    if move=="REPOSICION"
                    else "En obsequio el costo de esta salida será $0."
                )
            )
            if not hasattr(self,"_v1032_zero_price"):
                self._v1032_zero_price={}
            self._v1032_zero_price[code]={
                "authorized":bool(use_zero),
                "type":move,
            }
            if use_zero:
                self.vars["det_valor_kl"].set("0")
                self.vars["det_valor_total"].set("0")
                self.vars["det_iva"].set("0")
                self.vars["det_auto_iva"].set("NO")
                self.vars["det_total_linea"].set("0")
    except Exception:
        pass
    return result

SalesFormApp.on_detail_product_select = _v1032_on_detail_product_select


# Permitir agregar la línea gratuita sin romper las validaciones antiguas.
_v1032_previous_add_product_line = SalesFormApp.add_product_line
def _v1032_add_product_line(self):
    row=self.find_product_row(
        self.vars.get("det_producto",tk.StringVar()).get().strip()
    )
    code="" if row.empty else str(row.iloc[0].get("codigo","")).strip()
    special_info=getattr(self,"_v1032_zero_price",{}).get(code,{})
    zero_ok=bool(special_info.get("authorized"))

    if zero_ok:
        qty=money(self.vars["det_cantidad"].get())
        if qty <= 0:
            messagebox.showerror("Error","La cantidad debe ser mayor a cero.")
            return
        # La lógica histórica exige precio > 0; usamos un valor técnico temporal
        # y reemplazamos inmediatamente la línea por $0.
        old_price=self.vars["det_valor_kl"].get()
        old_subtotal=self.vars["det_valor_total"].get()
        old_iva=self.vars["det_iva"].get()
        try:
            self.vars["det_valor_kl"].set("0.01")
            self.vars["det_valor_total"].set(str(qty*0.01))
            self.vars["det_iva"].set("0")
            before=len(self.product_lines)
            result=_v1032_previous_add_product_line(self)
            if len(self.product_lines)>before:
                line=self.product_lines[-1]
                line["valor_x_kl"]=0.0
                line["valor_total"]=0.0
                line["iva_19"]=0.0
                line["retenciones"]=0.0
                line["total_linea"]=0.0
                line["precio_cero_autorizado"]=True
                line["tipo_ingreso_especial"]=special_info.get("type","")
                if special_info.get("type")=="OBSEQUIO":
                    line["costo_unitario"]=0.0
                # REPOSICION mantiene el costo que ya tomó del maestro.
                self.refresh_product_lines()
            return result
        finally:
            self.vars["det_valor_kl"].set("0")
            self.vars["det_valor_total"].set("0")
            self.vars["det_iva"].set("0")
            self.vars["det_total_linea"].set("0")
    else:
        before=len(self.product_lines)
        result=_v1032_previous_add_product_line(self)
        if len(self.product_lines)>before and special_info.get("type")=="OBSEQUIO":
            self.product_lines[-1]["costo_unitario"]=0.0
            self.product_lines[-1]["tipo_ingreso_especial"]="OBSEQUIO"
            self.refresh_product_lines()
        elif len(self.product_lines)>before and special_info.get("type")=="REPOSICION":
            self.product_lines[-1]["tipo_ingreso_especial"]="REPOSICION"
        return result

SalesFormApp.add_product_line = _v1032_add_product_line


