# ==================== V10.3.3 UNIDAD EDITABLE EN COTIZACIÓN Y VENTA ====================

V1033_UNITS = [
    "KLS","KG","GR","UNIDAD","CAJA","PAQUETE","BOLSA","LATA",
    "BOTELLA","FRASCO","GALON","DISPLAY","DOCENA"
]

def _v1033_normalize_unit(value) -> str:
    unit = str(value or "").strip().upper()
    aliases = {
        "KILO":"KLS","KILOS":"KLS","KILOGRAMO":"KLS","KILOGRAMOS":"KLS",
        "UND":"UNIDAD","UNIDADES":"UNIDAD","U":"UNIDAD",
        "PAQ":"PAQUETE","PAQ.":"PAQUETE",
    }
    return aliases.get(unit, unit)


def _v1033_confirm_unit_change(self, product_row, selected_unit, source_label):
    """
    Permite usar una unidad distinta solo para la transacción o,
    si el usuario lo autoriza, actualizar también el maestro de productos.
    """
    code = str(product_row.get("codigo","") or "").strip()
    name = str(product_row.get("nombre","") or "").strip()
    master_unit = _v1033_normalize_unit(product_row.get("unidad","KLS"))
    selected_unit = _v1033_normalize_unit(selected_unit)

    if not selected_unit:
        selected_unit = master_unit

    if selected_unit == master_unit:
        return selected_unit

    update_master = messagebox.askyesno(
        "Unidad diferente al maestro",
        f"El producto:\n\n{code} - {name}\n\n"
        f"está registrado en el maestro como: {master_unit}\n"
        f"y en esta {source_label} seleccionó: {selected_unit}.\n\n"
        "¿Desea cambiar también la unidad en la base maestra de productos?\n\n"
        "Sí = cambia el maestro y futuras operaciones usarán la nueva unidad.\n"
        "No = usa la unidad solo en esta operación.",
        parent=self,
    )

    if update_master:
        try:
            fields = self.store.update_product_master_from_inventory(
                code,
                new_unit=selected_unit,
                reason=f"Cambio de unidad autorizado desde {source_label}",
            )
            # Recargar catálogos para que la nueva unidad quede disponible inmediatamente.
            try:
                self.reload_master_catalogs()
            except Exception:
                pass
            if fields:
                messagebox.showinfo(
                    "Unidad actualizada",
                    f"{code} - {name}\n\n"
                    f"Unidad del maestro actualizada:\n{master_unit} → {selected_unit}",
                    parent=self,
                )
        except Exception as exc:
            raise ValueError(
                f"No fue posible actualizar la unidad del maestro.\n\n{exc}"
            )

    return selected_unit


SalesFormApp._v1033_confirm_unit_change = _v1033_confirm_unit_change


