def _v1034_payment_integrity_for_account(self, account: str) -> dict:
    account = str(account or "").strip()
    sale = self.table(
        """
        SELECT
            cuenta_cobro, estado_venta, estado_pago,
            COALESCE(retencion_venta,0) retencion_venta
        FROM ventas
        WHERE cuenta_cobro=?
        LIMIT 1
        """,
        (account,),
    )
    if sale.empty:
        return {}

    current_sale = _v1017_norm_sale_status(sale.iloc[0].get("estado_venta"))
    current_payment = _v1017_norm_payment_status(sale.iloc[0].get("estado_pago"))
    retention = float(sale.iloc[0].get("retencion_venta",0) or 0)

    summary = self.sales_summary()
    sr = summary[summary["cuenta_cobro"].astype(str) == account]
    if sr.empty:
        total = 0.0
        recognized = retention
    else:
        total = float(sr.iloc[0].get("total_factura",0) or 0)
        recognized = float(sr.iloc[0].get("total_abonos",0) or 0)

    payment_count_df = self.table(
        """
        SELECT COUNT(DISTINCT a.id_abono) cantidad
        FROM aplicacion_abonos a
        JOIN abonos b ON b.id_abono=a.id_abono
        WHERE a.cuenta_cobro=?
          AND COALESCE(b.estado_registro,'ACTIVO') <> 'ANULADO'
        """,
        (account,),
    )
    payment_count = (
        int(payment_count_df.iloc[0].get("cantidad",0) or 0)
        if not payment_count_df.empty else 0
    )
    components = payment_count + (1 if retention > 0.0001 else 0)

    if current_sale == "ANULADA":
        expected_sale = "ANULADA"
        expected_payment = "Anulada"
    else:
        expected_payment = _v1017_payment_status_from_amounts(
            total, recognized, components
        )
        expected_sale = _v1017_expected_sale_status(expected_payment)

    coherent = (
        current_sale == expected_sale
        and _v1017_norm_payment_status(current_payment)
            == _v1017_norm_payment_status(expected_payment)
    )

    return {
        "cuenta_cobro": account,
        "total_factura": total,
        "total_reconocido": recognized,
        "estado_venta_actual": current_sale,
        "estado_pago_actual": current_payment,
        "estado_venta_esperado": expected_sale,
        "estado_pago_esperado": expected_payment,
        "componentes_pago": components,
        "coherente": coherent,
    }

SalesStore.payment_integrity_for_account = _v1034_payment_integrity_for_account


