PAYMENT_PROOFS_DIR = APP_DIR / "soportes_ventas"
CLIENT_PORTFOLIO_REPORTS_DIR = APP_DIR / "reportes_cartera_clientes"

BOLD_RETEFUENTE_RATE = 0.015
BOLD_RETEICA_RATE = 0.004
BOLD_COMMISSION_RATE = 0.0299
BOLD_FIXED_FEE = 900.0


def _v1040_parse_date(value, default=None):
    try:
        return pd.to_datetime(str(value).strip()).date()
    except Exception:
        return default


def _v1040_safe_filename(value):
    value = re.sub(r'[<>:"/\\|?*]+', "_", str(value or "").strip())
    value = re.sub(r"\s+", "_", value).strip("._")
    return value or "archivo"


def _v1040_sha256(path:Path):
    h=hashlib.sha256()
    with open(path,"rb") as f:
        for chunk in iter(lambda:f.read(1024*1024),b""):
            h.update(chunk)
    return h.hexdigest()


def _v1040_open_path(path):
    p=Path(path)
    if not p.exists():
        raise FileNotFoundError(f"No existe el archivo:\n{p}")
    if sys.platform.startswith("win"):
        os.startfile(str(p))
    else:
        import subprocess
        subprocess.Popen(["xdg-open",str(p)])


def _v1040_bold_metrics(base, invoice_total=0.0, advisor_commission=0.0):
    base=max(float(base or 0),0.0)
    retefuente=round(base*BOLD_RETEFUENTE_RATE,2)
    reteica=round(base*BOLD_RETEICA_RATE,2)
    pct=round(base*BOLD_COMMISSION_RATE,2)
    fixed=BOLD_FIXED_FEE if base>0 else 0.0
    bold_total=round(retefuente+reteica+pct+fixed,2)
    net_bold=round(max(base-bold_total,0),2)
    invoice_total=float(invoice_total or 0)
    advisor_commission=float(advisor_commission or 0)
    total_without_advisor=round(invoice_total-advisor_commission,2)
    net_company=round(invoice_total-advisor_commission-bold_total,2)
    return {
        "bold_base":base,
        "bold_retefuente":retefuente,
        "bold_reteica":reteica,
        "bold_comision_porcentual":pct,
        "bold_comision_fija":fixed,
        "bold_costos_total":bold_total,
        "bold_neto_recibido":net_bold,
        "total_comision_asesor":advisor_commission,
        "total_sin_comision_asesor":total_without_advisor,
        "neto_empresa_estimado":net_company,
    }


def _v1040_bold_base_from_lines(lines):
    total=0.0
    for line in lines or []:
        medium=str(line.get("medio_pago","") or "").upper()
        account=str(line.get("cta_bancaria_destino","") or "").upper()
        if "BOLD" in medium or "BOLD" in account:
            total += float(line.get("valor_abono",0) or 0)
    return total


