SalesStore.latest_sale_support = _v1040_latest_sale_support


def _v1040_save_sale_support(self,account,source_path,origin="VENTA"):
    source=Path(source_path)
    if not source.exists() or not source.is_file():
        raise FileNotFoundError("El comprobante de pago seleccionado ya no existe.")

    account=str(account or "").strip()
    folder=PAYMENT_PROOFS_DIR / _v1040_safe_filename(account)
    folder.mkdir(parents=True,exist_ok=True)

    stamp=datetime.now().strftime("%Y%m%d_%H%M%S")
    name=f"{stamp}_{_v1040_safe_filename(source.name)}"
    target=folder/name
    counter=1
    while target.exists():
        target=folder/f"{stamp}_{counter:02d}_{_v1040_safe_filename(source.name)}"
        counter += 1
    shutil.copy2(source,target)

    try:
        relative=str(target.relative_to(APP_DIR))
    except Exception:
        relative=str(target)

    previous=self.latest_sale_support(account)
    previous_name=""
    if not previous.empty:
        previous_name=str(previous.iloc[0].get("nombre_original","") or "")
        self.conn.execute(
            "UPDATE venta_soportes SET activo=0 WHERE cuenta_cobro=? AND activo=1",
            (account,)
        )

    self.conn.execute(
        """
        INSERT INTO venta_soportes(
            cuenta_cobro,fecha_hora,tipo_soporte,ruta_relativa,nombre_original,
            extension,tamanio_bytes,sha256,activo,origen
        ) VALUES (?,?,?,?,?,?,?,?,1,?)
        """,
        (
            account,datetime.now().isoformat(timespec="seconds"),"COMPROBANTE_PAGO",
            relative,source.name,source.suffix.lower(),int(source.stat().st_size),
            _v1040_sha256(source),origin
        )
    )
    self.conn.execute(
        "UPDATE ventas SET comprobante_pago=? WHERE cuenta_cobro=?",
        (relative,account)
    )
    self.conn.commit()

    try:
        self.invoice_history_insert(
            account,"ADJUNTAR_SOPORTE","PAGOS","comprobante_pago",
            previous_name,source.name,"APP","USUARIO"
        )
    except Exception:
        pass
    return target

SalesStore.save_sale_support = _v1040_save_sale_support


def _v1040_support_absolute_path(self,account):
    df=self.latest_sale_support(account)
    if df.empty:
        return None
    raw=str(df.iloc[0].get("ruta_relativa","") or "")
    if not raw:
        return None
    p=Path(raw)
    if not p.is_absolute():
        p=APP_DIR/p
    return p

SalesStore.support_absolute_path = _v1040_support_absolute_path


def _v1040_calculate_account_bold(self,account):
    account=str(account or "").strip()
    summary=self.sales_summary()
    sr=summary[summary["cuenta_cobro"].astype(str)==account] if not summary.empty else pd.DataFrame()
    invoice_total=float(sr.iloc[0].get("total_factura",0) or 0) if not sr.empty else 0.0

    detail=self.table(
        "SELECT COALESCE(SUM(comision),0) total FROM ventas_detalle WHERE cuenta_cobro=?",
        (account,)
    )
    advisor=float(detail.iloc[0].get("total",0) or 0) if not detail.empty else 0.0

    bold=self.table(
        """
        SELECT COALESCE(SUM(a.valor_aplicado),0) total
        FROM aplicacion_abonos a
        JOIN abonos b ON b.id_abono=a.id_abono
        WHERE a.cuenta_cobro=?
          AND COALESCE(b.estado_registro,'ACTIVO')<>'ANULADO'
          AND (
            UPPER(COALESCE(b.medio_pago,'')) LIKE '%BOLD%'
            OR UPPER(COALESCE(b.cta_bancaria_destino,'')) LIKE '%BOLD%'
          )
        """,
        (account,)
    )
    bold_base=float(bold.iloc[0].get("total",0) or 0) if not bold.empty else 0.0

    if bold_base<=0:
        sale=self.table(
            "SELECT forma_pago,cta_bancaria FROM ventas WHERE cuenta_cobro=? LIMIT 1",
            (account,)
        )
        if not sale.empty:
            descriptor=(
                str(sale.iloc[0].get("forma_pago","") or "")+" "+
                str(sale.iloc[0].get("cta_bancaria","") or "")
            ).upper()
            if "BOLD" in descriptor:
                bold_base=invoice_total

    return _v1040_bold_metrics(bold_base,invoice_total,advisor)

SalesStore.calculate_account_bold = _v1040_calculate_account_bold


def _v1040_update_bold_metrics(self,account,metrics=None):
    metrics=metrics or self.calculate_account_bold(account)
    self.conn.execute(
        """
        UPDATE ventas SET
            bold_base=?,bold_retefuente=?,bold_reteica=?,
            bold_comision_porcentual=?,bold_comision_fija=?,
            bold_costos_total=?,bold_neto_recibido=?,
            total_comision_asesor=?,total_sin_comision_asesor=?,
            neto_empresa_estimado=?
        WHERE cuenta_cobro=?
        """,
        (
            metrics["bold_base"],metrics["bold_retefuente"],metrics["bold_reteica"],
            metrics["bold_comision_porcentual"],metrics["bold_comision_fija"],
            metrics["bold_costos_total"],metrics["bold_neto_recibido"],
            metrics["total_comision_asesor"],metrics["total_sin_comision_asesor"],
            metrics["neto_empresa_estimado"],str(account or "").strip()
        )
    )
    self.conn.commit()
    return metrics

SalesStore.update_bold_metrics = _v1040_update_bold_metrics


def _v1040_backfill_bold_metrics(self):
    df=self.table("SELECT cuenta_cobro FROM ventas")
    for _,r in df.iterrows():
        account=str(r.get("cuenta_cobro","") or "").strip()
        if account:
            try:
                self.update_bold_metrics(account)
            except Exception:
                pass

SalesStore.backfill_bold_metrics = _v1040_backfill_bold_metrics


# Guardar métricas BOLD y soporte antes de abrir el diálogo de cuenta de cobro.
_v1040_previous_upsert_sale = SalesStore.upsert_sale
def _v1040_upsert_sale(self,data:dict):
    result=_v1040_previous_upsert_sale(self,data)
    account=str(data.get("cuenta_cobro","") or "").strip()

    metrics=getattr(self,"_v1040_pending_bold_metrics",None)
    if metrics and account:
        self.update_bold_metrics(account,metrics)

    support=getattr(self,"_v1040_pending_support_path","")
    if support and account:
        self.save_sale_support(account,support,"VENTA")

    return result

SalesStore.upsert_sale = _v1040_upsert_sale


