def _v1040_select_payment_proof(self):
    path=filedialog.askopenfilename(
        title="Seleccionar comprobante de pago",
        filetypes=[
            ("Soportes","*.pdf *.png *.jpg *.jpeg *.webp *.bmp *.tif *.tiff"),
            ("PDF","*.pdf"),
            ("Imágenes","*.png *.jpg *.jpeg *.webp *.bmp *.tif *.tiff"),
            ("Todos","*.*"),
        ]
    )
    if path:
        self.vars["venta_comprobante"].set(path)

SalesFormApp.select_payment_proof = _v1040_select_payment_proof


def _v1040_open_payment_proof(self):
    account=self.vars.get("venta_factura",tk.StringVar()).get().strip()
    typed=self.vars.get("venta_comprobante",tk.StringVar()).get().strip()
    try:
        if typed and Path(typed).exists():
            _v1040_open_path(typed)
            return
        p=self.store.support_absolute_path(account)
        if not p:
            raise FileNotFoundError("Esta cuenta todavía no tiene comprobante guardado.")
        _v1040_open_path(p)
    except Exception as exc:
        messagebox.showerror("Comprobante de pago",str(exc),parent=self)

SalesFormApp.open_payment_proof = _v1040_open_payment_proof


def _v1040_refresh_bold_info(self):
    if not hasattr(self,"bold_vars"):
        return
    invoice=float(self.invoice_total() or 0)
    base=_v1040_bold_base_from_lines(getattr(self,"payment_lines",[]))
    advisor=sum(float(x.get("comision",0) or 0) for x in getattr(self,"product_lines",[]))
    m=_v1040_bold_metrics(base,invoice,advisor)
    mapping={
        "base":m["bold_base"],
        "retefuente":m["bold_retefuente"],
        "reteica":m["bold_reteica"],
        "porcentual":m["bold_comision_porcentual"],
        "fija":m["bold_comision_fija"],
        "costos":m["bold_costos_total"],
        "neto_bold":m["bold_neto_recibido"],
        "sin_comision":m["total_sin_comision_asesor"],
        "neto_empresa":m["neto_empresa_estimado"],
    }
    for key,val in mapping.items():
        self.bold_vars[key].set(f"$ {val:,.0f}")

SalesFormApp.refresh_bold_info = _v1040_refresh_bold_info


