_v1040_previous_build_sales_tab = SalesFormApp.build_sales_tab
def _v1040_build_sales_tab(self):
    _v1040_previous_build_sales_tab(self)

    pay_widget=self.widgets.get("venta_domicilio_cliente")
    if pay_widget is None:
        return
    pay=pay_widget.master

    # Corrige el solapamiento visual: Retención y Transportadora eran creados en la misma celda.
    try:
        ret=self.widgets.get("venta_retencion")
        if ret is not None:
            ret.grid_configure(row=4,column=1,sticky="ew",padx=4,pady=3)
            for w in pay.grid_slaves():
                if isinstance(w,ttk.Label) and str(w.cget("text")).strip().startswith("Retención"):
                    w.configure(text="Retención")
                    w.grid_configure(row=4,column=0,sticky="w",padx=4,pady=3)
    except Exception:
        pass

    # Comprobante de pago.
    if "venta_comprobante" not in self.vars:
        comp=self.entry(
            pay,"venta_comprobante","Comprobante de pago",4,2,width=28
        )
        comp.configure(state="readonly")
        ttk.Button(
            pay,text="Seleccionar",command=self.select_payment_proof
        ).grid(row=4,column=4,sticky="ew",padx=3,pady=3)
        ttk.Button(
            pay,text="Abrir",command=self.open_payment_proof
        ).grid(row=4,column=5,sticky="ew",padx=3,pady=3)

    # Botón agregar pago pasa a la siguiente fila.
    for w in pay.winfo_children():
        try:
            if isinstance(w,ttk.Button) and str(w.cget("text"))=="Agregar pago":
                w.grid_configure(row=5,column=0,columnspan=6,sticky="ew",padx=4,pady=(6,0))
        except Exception:
            pass

    # Cálculo BOLD solo para operación interna.
    bold_box=ttk.LabelFrame(
        self.sales_capture,
        text="Cálculo interno BOLD — no aparece en la cuenta de cobro",
        padding=8
    )
    bold_box.pack(fill="x",pady=(8,0))
    self.bold_vars={k:tk.StringVar(value="$ 0") for k in [
        "base","retefuente","reteica","porcentual","fija","costos",
        "neto_bold","sin_comision","neto_empresa"
    ]}
    labels=[
        ("Base BOLD","base"),
        ("Retefuente 1,5%","retefuente"),
        ("ReteICA 0,4%","reteica"),
        ("Comisión BOLD 2,99%","porcentual"),
        ("Comisión BOLD fija","fija"),
        ("Total costos BOLD","costos"),
        ("Neto recibido BOLD","neto_bold"),
        ("Total sin comisión asesor","sin_comision"),
        ("Neto empresa estimado","neto_empresa"),
    ]
    for i,(label,key) in enumerate(labels):
        r=i//3
        c=(i%3)*2
        ttk.Label(bold_box,text=label,style="Muted.TLabel").grid(
            row=r,column=c,sticky="w",padx=(4,5),pady=2
        )
        ttk.Label(bold_box,textvariable=self.bold_vars[key]).grid(
            row=r,column=c+1,sticky="e",padx=(0,14),pady=2
        )
        bold_box.columnconfigure(c+1,weight=1)

    self.refresh_bold_info()

SalesFormApp.build_sales_tab = _v1040_build_sales_tab


