# Validación + datos pendientes antes de la cadena de guardado.
_v1040_previous_save_sale = SalesFormApp.save_sale
def _v1040_save_sale(self):
    account=self.vars.get("venta_factura",tk.StringVar()).get().strip()
    selected_support=self.vars.get("venta_comprobante",tk.StringVar()).get().strip()

    recognized=sum(
        float(x.get("valor_abono",0) or 0)
        for x in getattr(self,"payment_lines",[])
    ) + money(self.vars.get("venta_retencion",tk.StringVar(value="0")).get())

    existing_support=False
    if account:
        try:
            existing_support=not self.store.latest_sale_support(account).empty
        except Exception:
            existing_support=False

    # Una venta sin pago todavía puede ser Pendiente. El soporte se vuelve obligatorio
    # en cuanto existe pago o retención.
    if recognized>0.0001 and not selected_support and not existing_support:
        messagebox.showerror(
            "Comprobante obligatorio",
            "La venta tiene un pago o retención registrado.\n\n"
            "Debe adjuntar el comprobante de pago antes de guardar.\n\n"
            "Para una venta totalmente Pendiente (sin pago) el comprobante se exigirá "
            "cuando se registre el primer pago.",
            parent=self,
        )
        return

    invoice=float(self.invoice_total() or 0)
    advisor=sum(float(x.get("comision",0) or 0) for x in getattr(self,"product_lines",[]))
    bold_base=_v1040_bold_base_from_lines(getattr(self,"payment_lines",[]))
    metrics=_v1040_bold_metrics(bold_base,invoice,advisor)

    self.store._v1040_pending_bold_metrics=metrics
    if selected_support and Path(selected_support).exists():
        self.store._v1040_pending_support_path=selected_support
    else:
        self.store._v1040_pending_support_path=""

    try:
        return _v1040_previous_save_sale(self)
    finally:
        for attr in ["_v1040_pending_bold_metrics","_v1040_pending_support_path"]:
            try:
                delattr(self.store,attr)
            except Exception:
                pass

SalesFormApp.save_sale = _v1040_save_sale


