_v1040_previous_export_invoice_print = SalesStore.export_invoice_print
def _v1040_export_invoice_print(self,cuenta_cobro:str,output_path:Path|None=None):
    path=_v1040_previous_export_invoice_print(self,cuenta_cobro,output_path)
    try:
        support=self.latest_sale_support(cuenta_cobro)
        if not support.empty:
            from openpyxl import load_workbook
            from openpyxl.styles import Font, PatternFill, Alignment, Border, Side
            book=load_workbook(path)
            ws=book["Cuenta de cobro"]
            r=ws.max_row+2
            ws.merge_cells(start_row=r,start_column=1,end_row=r,end_column=6)
            cell=ws.cell(r,1)
            cell.value=f"COMPROBANTE DE PAGO REGISTRADO: {support.iloc[0].get('nombre_original','')}"
            cell.font=Font(bold=True,color="155A3A",size=9)
            cell.fill=PatternFill("solid",fgColor="E7F1EC")
            cell.alignment=Alignment(horizontal="left",vertical="center",wrap_text=True)
            thin=Side(style="thin",color="4B4B4B")
            for c in range(1,7):
                ws.cell(r,c).border=Border(left=thin,right=thin,top=thin,bottom=thin)
            ws.print_area=f"A1:F{r}"
            book.save(path)
            book.close()
    except Exception:
        pass
    return path

SalesStore.export_invoice_print = _v1040_export_invoice_print


# -----------------------------------------------------------------------
# Exportación: soportes y métricas BOLD.
# -----------------------------------------------------------------------
_v1040_previous_export_excel = SalesStore.export_excel
def _v1040_export_excel(self,output_path:Path,append_existing:bool=False):
    result=_v1040_previous_export_excel(self,output_path,append_existing)
    try:
        from openpyxl import load_workbook
        book=load_workbook(output_path)

        sale_metrics=self.table(
            """
            SELECT cuenta_cobro,comprobante_pago,
                   bold_base,bold_retefuente,bold_reteica,bold_comision_porcentual,
                   bold_comision_fija,bold_costos_total,bold_neto_recibido,
                   total_comision_asesor,total_sin_comision_asesor,neto_empresa_estimado
            FROM ventas
            """
        )
        metrics={
            str(r["cuenta_cobro"]):r.to_dict()
            for _,r in sale_metrics.iterrows()
        }

        new_headers=[
            "BOLD_BASE","BOLD_RETEFUENTE_1_5","BOLD_RETEICA_0_4",
            "BOLD_COMISION_2_99","BOLD_COMISION_FIJA","BOLD_COSTOS_TOTAL",
            "BOLD_NETO_RECIBIDO","TOTAL_COMISION_ASESOR",
            "TOTAL_SIN_COMISION_ASESOR","NETO_EMPRESA_ESTIMADO",
            "COMPROBANTE_PAGO"
        ]

        for sheet_name,account_labels in [
            ("Ventas_cabecera",["CUENTA_COBRO"]),
            ("VENTAS",["CUENTA DE COBRO","CUENTA_COBRO"]),
        ]:
            if sheet_name not in book.sheetnames:
                continue
            ws=book[sheet_name]
            header={str(c.value or "").strip().upper():c.column for c in ws[1]}
            account_col=None
            for lab in account_labels:
                if lab in header:
                    account_col=header[lab]
                    break
            if not account_col:
                continue

            cols={}
            for h in new_headers:
                if h in header:
                    cols[h]=header[h]
                else:
                    cols[h]=ws.max_column+1
                    ws.cell(1,cols[h],h)
                    header[h]=cols[h]

            seen=set()
            for rr in range(2,ws.max_row+1):
                account=str(ws.cell(rr,account_col).value or "").strip()
                m=metrics.get(account)
                if not m:
                    continue
                # En VENTAS se escribe una sola vez por factura para evitar duplicar sumas.
                first = account not in seen
                seen.add(account)
                values=[
                    m.get("bold_base",0),m.get("bold_retefuente",0),m.get("bold_reteica",0),
                    m.get("bold_comision_porcentual",0),m.get("bold_comision_fija",0),
                    m.get("bold_costos_total",0),m.get("bold_neto_recibido",0),
                    m.get("total_comision_asesor",0),m.get("total_sin_comision_asesor",0),
                    m.get("neto_empresa_estimado",0),m.get("comprobante_pago","")
                ]
                for h,val in zip(new_headers,values):
                    ws.cell(rr,cols[h],val if sheet_name!="VENTAS" or first else None)

        # Soportes para auditoría.
        supports=self.table(
            "SELECT * FROM venta_soportes ORDER BY cuenta_cobro,fecha_hora"
        )
        if "Soportes_pago" in book.sheetnames:
            del book["Soportes_pago"]
        ws=book.create_sheet("Soportes_pago")
        headers=list(supports.columns)
        for c,h in enumerate(headers,1):
            ws.cell(1,c,h.upper())
        for ri,row in enumerate(supports.itertuples(index=False,name=None),2):
            for ci,val in enumerate(row,1):
                ws.cell(ri,ci,None if pd.isna(val) else val)

        book.save(output_path)
        book.close()
    except Exception:
        pass
    return result

SalesStore.export_excel = _v1040_export_excel


# -----------------------------------------------------------------------
# INFORME INTEGRAL DE INVENTARIOS: stock actual + movimientos.
# -----------------------------------------------------------------------
def _v1040_inventory_full_data(self,start_date:date,end_date:date):
    data=self.inventory_report_data(start_date,end_date)
    stock=self.table(
        """
        SELECT
            codigo AS codigo_producto,nombre AS producto,unidad,
            COALESCE(stock_actual,0) stock_actual,
            COALESCE(stock_minimo,0) stock_minimo,
            CASE
              WHEN COALESCE(stock_actual,0)<=0 THEN 'SIN STOCK'
              WHEN COALESCE(stock_actual,0)<=COALESCE(stock_minimo,0) THEN 'EN/BAJO MINIMO'
              ELSE 'OK'
            END estado_stock,
            activo,ultima_modificacion
        FROM productos
        ORDER BY nombre
        """
    )
    data["stock_actual"]=stock
    return data

SalesStore.inventory_full_report_data = _v1040_inventory_full_data


def _v1040_export_inventory_full_excel(self,start_date,end_date,output_path):
    data=self.inventory_full_report_data(start_date,end_date)
    output_path=Path(output_path)
    output_path.parent.mkdir(parents=True,exist_ok=True)

    with pd.ExcelWriter(output_path,engine="openpyxl") as writer:
        data["stock_actual"].rename(columns=str.upper).to_excel(
            writer,sheet_name="Stock_actual",index=False
        )
        data["unit_summary"].rename(columns=str.upper).to_excel(
            writer,sheet_name="Resumen_unidades",index=False
        )
        data["by_type"].rename(columns=str.upper).to_excel(
            writer,sheet_name="Resumen_movimientos",index=False
        )
        data["product_summary"].rename(columns=str.upper).to_excel(
            writer,sheet_name="Resumen_productos",index=False
        )
        data["movements"].rename(columns=str.upper).to_excel(
            writer,sheet_name="Registro_movimientos",index=False
        )
        data["review"].rename(columns=str.upper).to_excel(
            writer,sheet_name="Revisar",index=False
        )

    try:
        _v987_style_excel_file(output_path)
    except Exception:
        pass
    return output_path

SalesStore.export_inventory_full_excel = _v1040_export_inventory_full_excel


def _v1040_export_inventory_full_pdf(self,start_date,end_date,output_path):
    from reportlab.lib import colors
    from reportlab.lib.pagesizes import A4,landscape
    from reportlab.lib.styles import getSampleStyleSheet,ParagraphStyle
    from reportlab.lib.units import cm
    from reportlab.platypus import SimpleDocTemplate,Table,TableStyle,Paragraph,Spacer,PageBreak

    data=self.inventory_full_report_data(start_date,end_date)
    stock=data["stock_actual"]
    mov=data["movements"]
    summary=data["unit_summary"]

    output_path=Path(output_path)
    output_path.parent.mkdir(parents=True,exist_ok=True)
    doc=SimpleDocTemplate(
        str(output_path),pagesize=landscape(A4),
        leftMargin=.8*cm,rightMargin=.8*cm,topMargin=.8*cm,bottomMargin=.8*cm,
        title="Informe integral de inventarios MXPC"
    )
    styles=getSampleStyleSheet()
    styles.add(ParagraphStyle(
        name="MXTitle",parent=styles["Title"],fontSize=17,leading=20,
        textColor=colors.HexColor("#155E42")
    ))
    story=[
        Paragraph("Informe integral de inventarios",styles["MXTitle"]),
        Paragraph(
            f"Periodo de movimientos: {start_date:%d/%m/%Y} al {end_date:%d/%m/%Y} · "
            f"Generado {_v1017_colombia_now():%d/%m/%Y %H:%M}",
            styles["Normal"]
        ),
        Spacer(1,.3*cm),
    ]

    active=int((stock["activo"].astype(str).str.upper()=="SI").sum()) if not stock.empty else 0
    with_stock=int((pd.to_numeric(stock["stock_actual"],errors="coerce").fillna(0)>0).sum()) if not stock.empty else 0
    low=int(stock["estado_stock"].isin(["SIN STOCK","EN/BAJO MINIMO"]).sum()) if not stock.empty else 0
    kpi=Table([
        ["Productos activos","Con stock","Sin/baixo mínimo","Movimientos periodo"],
        [active,with_stock,low,len(mov)]
    ],colWidths=[6.2*cm]*4)
    kpi.setStyle(TableStyle([
        ("BACKGROUND",(0,0),(-1,0),colors.HexColor("#155E42")),
        ("TEXTCOLOR",(0,0),(-1,0),colors.white),
        ("FONTNAME",(0,0),(-1,0),"Helvetica-Bold"),
        ("GRID",(0,0),(-1,-1),.4,colors.grey),
        ("ALIGN",(0,0),(-1,-1),"CENTER"),
        ("BOTTOMPADDING",(0,0),(-1,-1),5),
        ("TOPPADDING",(0,0),(-1,-1),5),
    ]))
    story += [kpi,Spacer(1,.3*cm),Paragraph("Stock actual",styles["Heading2"])]

    rows=[["Código","Producto","Unidad","Stock","Mínimo","Estado"]]
    for _,r in stock.iterrows():
        rows.append([
            str(r.get("codigo_producto","")),
            Paragraph(str(r.get("producto","")),styles["BodyText"]),
            str(r.get("unidad","")),
            f"{float(r.get('stock_actual',0) or 0):,.2f}",
            f"{float(r.get('stock_minimo',0) or 0):,.2f}",
            str(r.get("estado_stock","")),
        ])
