def _v1040_client_portfolio_data(self,client,start_date,end_date):
    client=str(client or "").strip()
    start_date=_v1040_parse_date(start_date,start_date)
    end_date=_v1040_parse_date(end_date,end_date)

    sales=self.table(
        """
        SELECT cuenta_cobro,fecha,cliente,estado_venta,estado_pago,
               direccion,ciudad_entrega,telefono_cliente,
               factura_electronica,forma_pago
        FROM ventas
        WHERE cliente=?
        ORDER BY fecha,cuenta_cobro
        """,
        (client,)
    )
    summary=self.sales_summary()
    if sales.empty:
        merged=pd.DataFrame()
    else:
        merged=sales.merge(
            summary[["cuenta_cobro","total_factura","total_abonos"]],
            on="cuenta_cobro",how="left"
        )
        merged["total_factura"]=pd.to_numeric(merged["total_factura"],errors="coerce").fillna(0)
        merged["total_abonos"]=pd.to_numeric(merged["total_abonos"],errors="coerce").fillna(0)
        merged["saldo"]=(merged["total_factura"]-merged["total_abonos"]).clip(lower=0)
        merged=merged[merged["estado_venta"].astype(str).str.upper()!="ANULADA"].copy()

    global_debt=merged[merged["saldo"]>1].copy() if not merged.empty else pd.DataFrame()
    if not merged.empty:
        dates=pd.to_datetime(merged["fecha"],errors="coerce").dt.date
        period=merged[
            (dates>=start_date)&(dates<=end_date)&(merged["saldo"]>1)
        ].copy()
    else:
        period=pd.DataFrame()

    apps=self.table(
        """
        SELECT
            b.id_abono,b.fecha_abono,b.medio_pago,b.cta_bancaria_destino,
            b.referencia_pago,b.valor_abono,
            a.fecha_aplicacion,a.cuenta_cobro,a.valor_aplicado,
            v.fecha fecha_factura,v.estado_venta
        FROM aplicacion_abonos a
        JOIN abonos b ON b.id_abono=a.id_abono
        JOIN ventas v ON v.cuenta_cobro=a.cuenta_cobro
        WHERE v.cliente=?
          AND COALESCE(b.estado_registro,'ACTIVO')<>'ANULADO'
        ORDER BY b.fecha_abono,a.fecha_aplicacion,a.cuenta_cobro
        """,
        (client,)
    )
    if not apps.empty:
        appdates=pd.to_datetime(apps["fecha_aplicacion"],errors="coerce").dt.date
        apps["EN_PERIODO"]=(
            (appdates>=start_date)&(appdates<=end_date)
        ).map({True:"SI",False:"NO"})

    return {
        "client":client,
        "global":global_debt,
        "period":period,
        "applications":apps,
        "start_date":start_date,
        "end_date":end_date,
        "total_global":float(global_debt["saldo"].sum()) if not global_debt.empty else 0.0,
        "total_period":float(period["saldo"].sum()) if not period.empty else 0.0,
    }

SalesStore.client_portfolio_report_data = _v1040_client_portfolio_data


def _v1040_export_client_portfolio_excel(self,client,start_date,end_date,output_path):
    data=self.client_portfolio_report_data(client,start_date,end_date)
    output_path=Path(output_path)
    output_path.parent.mkdir(parents=True,exist_ok=True)

    resumen=pd.DataFrame([
        ["CLIENTE",data["client"]],
        ["PERIODO",f"{data['start_date']:%d/%m/%Y} - {data['end_date']:%d/%m/%Y}"],
        ["DEUDA GLOBAL",data["total_global"]],
        ["DEUDA DE FACTURAS DEL PERIODO",data["total_period"]],
        ["FACTURAS ADEUDADAS GLOBAL",len(data["global"])],
        ["FACTURAS ADEUDADAS PERIODO",len(data["period"])],
    ],columns=["CONCEPTO","VALOR"])

    with pd.ExcelWriter(output_path,engine="openpyxl") as writer:
        resumen.to_excel(writer,sheet_name="Resumen",index=False)
        data["global"].rename(columns=str.upper).to_excel(
            writer,sheet_name="Cartera_global",index=False
        )
        data["period"].rename(columns=str.upper).to_excel(
            writer,sheet_name="Facturas_periodo",index=False
        )
        data["applications"].rename(columns=str.upper).to_excel(
            writer,sheet_name="Abonos_aplicaciones",index=False
        )
    try:
        _v987_style_excel_file(output_path)
    except Exception:
        pass
    return output_path

SalesStore.export_client_portfolio_excel = _v1040_export_client_portfolio_excel


