# ==================== V10.4.1 ORDEN DE VENTAS + LINKS DE CARTERA ====================

def _v1041_parse_business_date(value):
    try:
        return pd.to_datetime(value, errors="raise").date()
    except Exception:
        return date.min


def _v1041_account_parts(account):
    raw=str(account or "").strip()
    upper=raw.upper()
    is_numeric=bool(re.fullmatch(r"\d+",raw))
    is_special=(upper.startswith("MCFE") or upper.endswith("G") or not is_numeric)
    nums=re.findall(r"\d+",upper)
    embedded=int(nums[-1]) if nums else 0
    numeric=int(raw) if is_numeric else None
    return raw,upper,is_numeric,is_special,embedded,numeric


def _v1041_invoice_order_map(cabecera_rows):
    """
    Orden comercial:
    - Cuentas puramente numéricas conservan orden numérico.
    - Cuentas especiales (MCFE..., ...G u otro alfanumérico) se anclan a su FECHA,
      justo después de las cuentas numéricas correspondientes a esa fecha.
      Así no se envían artificialmente al final del libro.
    """
    parsed=[]
    for row in cabecera_rows:
        account=str(row.get("account","") or "").strip()
        if not account:
            continue
        d=_v1041_parse_business_date(row.get("date"))
        raw,upper,is_numeric,is_special,embedded,numeric=_v1041_account_parts(account)
        parsed.append({
            "account":raw,"date":d,"is_numeric":is_numeric,
            "embedded":embedded,"numeric":numeric
        })

    numeric_by_date={}
    for x in parsed:
        if x["is_numeric"]:
            numeric_by_date[x["date"]]=max(
                numeric_by_date.get(x["date"],-1),
                int(x["numeric"])
            )

    # Máximo acumulado de cuenta numérica hasta cada fecha.
    dates=sorted({x["date"] for x in parsed})
    running=-1
    anchor_by_date={}
    for d in dates:
        running=max(running,numeric_by_date.get(d,-1))
        anchor_by_date[d]=running

    keys={}
    for x in parsed:
        if x["is_numeric"]:
            key=(float(x["numeric"]),x["date"].toordinal(),0,x["account"])
        else:
            anchor=anchor_by_date.get(x["date"],-1)
            # 0.5 coloca cuentas especiales después de las numéricas de ese día
            # y antes de la siguiente cuenta numérica cronológica.
            key=(float(anchor)+0.5,x["date"].toordinal(),x["embedded"],x["account"])
        keys[x["account"]]=key
    return keys


def _v1041_sort_excel_sales_sheets(path:Path):
    from openpyxl import load_workbook
    from copy import copy

    path=Path(path)
    book=load_workbook(path)

    # Construir mapa de cuenta -> fecha desde cabecera.
    cab_name="Ventas_cabecera"
    if cab_name not in book.sheetnames:
        book.close()
        return path

    cab=book[cab_name]
    header={str(c.value or "").strip().upper():c.column for c in cab[1]}
    acct_col=header.get("CUENTA_COBRO")
    date_col=header.get("FECHA")
    if not acct_col or not date_col:
        book.close()
        return path

    cab_rows=[]
    for r in range(2,cab.max_row+1):
        account=str(cab.cell(r,acct_col).value or "").strip()
        if not account:
            continue
        cab_rows.append({
            "account":account,
            "date":cab.cell(r,date_col).value
        })
    order_map=_v1041_invoice_order_map(cab_rows)
    date_map={x["account"]:_v1041_parse_business_date(x["date"]) for x in cab_rows}

    def row_snapshot(ws,row):
        cells=[]
        for c in range(1,ws.max_column+1):
            src=ws.cell(row,c)
            cells.append({
                "value":src.value,
                "style":copy(src._style),
                "number_format":src.number_format,
                "font":copy(src.font),
                "fill":copy(src.fill),
                "border":copy(src.border),
                "alignment":copy(src.alignment),
                "protection":copy(src.protection),
                "hyperlink":copy(src.hyperlink) if src.hyperlink else None,
                "comment":copy(src.comment) if src.comment else None,
            })
        return cells

    def apply_snapshot(ws,row,snap):
        for c,item in enumerate(snap,start=1):
            dstc=ws.cell(row,c)
            dstc.value=item["value"]
            dstc._style=copy(item["style"])
            dstc.number_format=item["number_format"]
            dstc.font=copy(item["font"])
            dstc.fill=copy(item["fill"])
            dstc.border=copy(item["border"])
            dstc.alignment=copy(item["alignment"])
            dstc.protection=copy(item["protection"])
            dstc._hyperlink=copy(item["hyperlink"]) if item["hyperlink"] else None
            dstc.comment=copy(item["comment"]) if item["comment"] else None

    specs=[
        ("Ventas_cabecera","CUENTA_COBRO","FECHA",None),
        ("VENTAS","CUENTA DE COBRO","FECHA",None),
        ("Ventas_detalle","CUENTA_COBRO",None,"ITEM"),
    ]

    for sheet_name,account_header,date_header,item_header in specs:
        if sheet_name not in book.sheetnames:
            continue
        ws=book[sheet_name]
        h={str(c.value or "").strip().upper():c.column for c in ws[1]}
        account_col=h.get(account_header.upper())
        if not account_col:
            continue
        row_date_col=h.get(date_header.upper()) if date_header else None
        item_col=h.get(item_header.upper()) if item_header else None

        snapshots=[]
        for r in range(2,ws.max_row+1):
            account=str(ws.cell(r,account_col).value or "").strip()
            if not account:
                continue
            d=(
                _v1041_parse_business_date(ws.cell(r,row_date_col).value)
                if row_date_col else date_map.get(account,date.min)
            )
            business_key=order_map.get(
                account,
                (10**12,d.toordinal(),0,account)
            )
            item=float(ws.cell(r,item_col).value or 0) if item_col else 0
            snapshots.append((
                business_key,
                d.toordinal(),
                item,
                r,
                row_snapshot(ws,r)
            ))

        snapshots.sort(key=lambda x:(x[0],x[1],x[2],x[3]))
        target_row=2
        for _,_,_,source_row,snap in snapshots:
            apply_snapshot(ws,target_row,snap)
            target_row += 1

        # Limpiar posibles filas sobrantes.
        for r in range(target_row,ws.max_row+1):
            for c in range(1,ws.max_column+1):
                ws.cell(r,c).value=None

        try:
            ws.auto_filter.ref=ws.dimensions
        except Exception:
            pass

    book.save(path)
    book.close()
    return path


# Aplicar el mismo orden a copia diaria y al export temporal que alimenta el maestro.
_v1041_previous_export_excel = SalesStore.export_excel
def _v1041_export_excel(self,output_path:Path,append_existing:bool=False):
    result=_v1041_previous_export_excel(self,output_path,append_existing)
    try:
        _v1041_sort_excel_sales_sheets(Path(output_path))
    except Exception:
        pass
    return result

SalesStore.export_excel = _v1041_export_excel


# -----------------------------------------------------------------------
# EXCEL DE CARTERA CON LINK INTERNO AL DETALLE DE LA CUENTA
# -----------------------------------------------------------------------
def _v1041_export_client_portfolio_excel(self,client,start_date,end_date,output_path):
    from openpyxl import load_workbook
    from openpyxl.styles import Font

    data=self.client_portfolio_report_data(client,start_date,end_date)
    output_path=Path(output_path)
    output_path.parent.mkdir(parents=True,exist_ok=True)

    resumen=pd.DataFrame([
        ["CLIENTE",data["client"]],
        ["PERIODO",f"{data['start_date']:%d/%m/%Y} - {data['end_date']:%d/%m/%Y}"],
        ["DEUDA GLOBAL",data["total_global"]],
        ["DEUDA DE FACTURAS DEL PERIODO",data["total_period"]],
        ["FACTURAS ADEUDADAS GLOBAL",len(data["global"])],
        ["FACTURAS ADEUDADAS PERIODO",len(data["period"])],
    ],columns=["CONCEPTO","VALOR"])

    # Solo detalle comercial visible para el cliente, sin costos ni comisiones internas.
    debt_accounts=sorted({
        str(x).strip()
        for x in data["global"].get("cuenta_cobro",pd.Series(dtype=object)).tolist()
        if str(x).strip()
    })

    if debt_accounts:
        placeholders=",".join(["?"]*len(debt_accounts))
        detail=self.table(
            f"""
            SELECT
                v.cuenta_cobro,
                v.fecha,
                v.cliente,
                d.item,
                d.codigo_producto,
                d.producto,
                d.unidad,
                d.cantidad_kls cantidad,
                d.valor_x_kl precio_unitario,
                d.valor_total venta_total,
                COALESCE(v.domicilio_cliente,0) domicilio_cliente,
                COALESCE(v.estado_pago,'') estado_pago,
                COALESCE(v.estado_venta,'') estado_venta
            FROM ventas v
            JOIN ventas_detalle d ON d.cuenta_cobro=v.cuenta_cobro
            WHERE v.cuenta_cobro IN ({placeholders})
            ORDER BY v.fecha,v.cuenta_cobro,d.item
            """,
            tuple(debt_accounts)
        )
        # Añadir total/saldo por factura.
        summary=self.sales_summary()
        detail=detail.merge(
            summary[["cuenta_cobro","total_factura","total_abonos"]],
            on="cuenta_cobro",how="left"
        )
        detail["saldo_pendiente"]=(
            pd.to_numeric(detail["total_factura"],errors="coerce").fillna(0)
            - pd.to_numeric(detail["total_abonos"],errors="coerce").fillna(0)
        ).clip(lower=0)
    else:
        detail=pd.DataFrame(columns=[
            "cuenta_cobro","fecha","cliente","item","codigo_producto","producto",
            "unidad","cantidad","precio_unitario","venta_total","domicilio_cliente",
            "estado_pago","estado_venta","total_factura","total_abonos","saldo_pendiente"
        ])

    with pd.ExcelWriter(output_path,engine="openpyxl") as writer:
        resumen.to_excel(writer,sheet_name="Resumen",index=False)

        global_out=data["global"].copy()
        if not global_out.empty:
            global_out["VER_DETALLE"]="Abrir cuenta"
        global_out.rename(columns=str.upper).to_excel(
            writer,sheet_name="Cartera_global",index=False
        )

        period_out=data["period"].copy()
        if not period_out.empty:
            period_out["VER_DETALLE"]="Abrir cuenta"
        period_out.rename(columns=str.upper).to_excel(
            writer,sheet_name="Facturas_periodo",index=False
        )

        data["applications"].rename(columns=str.upper).to_excel(
            writer,sheet_name="Abonos_aplicaciones",index=False
        )
        detail.rename(columns=str.upper).to_excel(
            writer,sheet_name="VENTAS",index=False
        )

    try:
        _v987_style_excel_file(output_path)
    except Exception:
        pass

    # Hipervínculos internos hacia la primera línea de cada cuenta en VENTAS.
    book=load_workbook(output_path)
    ws_detail=book["VENTAS"]

    detail_header={
        str(c.value or "").strip().upper():c.column
        for c in ws_detail[1]
    }
    detail_account_col=detail_header.get("CUENTA_COBRO")
    first_row_by_account={}
    if detail_account_col:
        for r in range(2,ws_detail.max_row+1):
            account=str(ws_detail.cell(r,detail_account_col).value or "").strip()
            if account and account not in first_row_by_account:
                first_row_by_account[account]=r
        ws_detail.auto_filter.ref=ws_detail.dimensions
        ws_detail.freeze_panes="A2"

    for sheet_name in ["Cartera_global","Facturas_periodo"]:
        ws=book[sheet_name]
        h={str(c.value or "").strip().upper():c.column for c in ws[1]}
        account_col=h.get("CUENTA_COBRO")
        link_col=h.get("VER_DETALLE")
        if not account_col:
            continue
        for r in range(2,ws.max_row+1):
            account=str(ws.cell(r,account_col).value or "").strip()
            target=first_row_by_account.get(account)
            if not target:
                continue
            link=f"#'VENTAS'!A{target}"
            ws.cell(r,account_col).hyperlink=link
            ws.cell(r,account_col).style="Hyperlink"
            if link_col:
                ws.cell(r,link_col).value="Abrir detalle"
                ws.cell(r,link_col).hyperlink=link
                ws.cell(r,link_col).style="Hyperlink"

    book.save(output_path)
    book.close()
    return output_path

SalesStore.export_client_portfolio_excel = _v1041_export_client_portfolio_excel


