# ==================== V10.4.2 AJUSTE DE ORDEN PARA CUENTAS ESPECIALES ====================

def _v1042_invoice_order_map(cabecera_rows):
    """
    Mantiene el orden numérico para cuentas normales y evita que series
    alfanuméricas/externas (MCFE..., ...G) terminen al final del libro.

    Para determinar la secuencia normal se identifica el bloque numérico denso
    (1,2,3,... con saltos pequeños). Los números históricos externos como 2541
    no se usan como ancla para MCFE/G.
    """
    parsed=[]
    numeric_values=[]
    for row in cabecera_rows:
        account=str(row.get("account","") or "").strip()
        if not account:
            continue
        d=_v1041_parse_business_date(row.get("date"))
        raw,upper,is_numeric,is_special,embedded,numeric=_v1041_account_parts(account)
        parsed.append({
            "account":raw,"date":d,"is_numeric":is_numeric,
            "embedded":embedded,"numeric":numeric
        })
        if is_numeric and numeric is not None:
            numeric_values.append(int(numeric))

    # Detectar la secuencia numérica operativa principal.
    uniq=sorted(set(numeric_values))
    regular_ceiling=-1
    if uniq:
        regular_ceiling=uniq[0]
        prev=uniq[0]
        for n in uniq[1:]:
            # Las cuentas operativas avanzan de forma densa. Un salto grande
            # indica otra serie histórica/externa.
            if n-prev>25:
                break
            regular_ceiling=n
            prev=n

    regular_by_date={}
    for x in parsed:
        if x["is_numeric"] and x["numeric"] is not None and x["numeric"]<=regular_ceiling:
            regular_by_date[x["date"]]=max(
                regular_by_date.get(x["date"],-1),
                int(x["numeric"])
            )

    dates=sorted({x["date"] for x in parsed})
    running=-1
    anchor_by_date={}
    for d in dates:
        running=max(running,regular_by_date.get(d,-1))
        anchor_by_date[d]=running

    keys={}
    for x in parsed:
        if x["is_numeric"]:
            # Todas las cuentas numéricas siguen orden numérico.
            key=(float(x["numeric"]),x["date"].toordinal(),0,x["account"])
        else:
            # MCFE/G se inserta cronológicamente después de la secuencia normal
            # correspondiente a su fecha, no después de las series 2000+.
            anchor=anchor_by_date.get(x["date"],-1)
            key=(float(anchor)+0.5,x["date"].toordinal(),x["embedded"],x["account"])
        keys[x["account"]]=key
    return keys


# La rutina de post-proceso usa esta versión corregida.
_v1041_invoice_order_map = _v1042_invoice_order_map

# ==================== FIN V10.4.2 ====================



# ==================== V10.4.3 LINKS DE CARTERA EN COPIA DIARIA Y MAESTRO ====================

def _v1043_add_portfolio_links_to_export(path:Path):
    from openpyxl import load_workbook
    from openpyxl.styles import Font

    path=Path(path)
    book=load_workbook(path)

    if "VENTAS" not in book.sheetnames:
        book.close()
        return path

    ws_sales=book["VENTAS"]
    sh={str(c.value or "").strip().upper():c.column for c in ws_sales[1]}
    acct_col=sh.get("CUENTA DE COBRO") or sh.get("CUENTA_COBRO")
    if not acct_col:
        book.close()
        return path

    first_row={}
    for r in range(2,ws_sales.max_row+1):
        account=str(ws_sales.cell(r,acct_col).value or "").strip()
        if account and account not in first_row:
            first_row[account]=r

    for sheet_name,possible_headers in [
        ("Cartera",["CUENTA_COBRO","CUENTA DE COBRO"]),
        ("Cartera_pendiente",["CUENTA_COBRO","CUENTA DE COBRO"]),
    ]:
        if sheet_name not in book.sheetnames:
            continue
        ws=book[sheet_name]
        h={str(c.value or "").strip().upper():c.column for c in ws[1]}

        source_col=None
        for candidate in possible_headers:
            if candidate in h:
                source_col=h[candidate]
                break
        if not source_col:
            continue

        link_col=h.get("VER_DETALLE")
        if not link_col:
            link_col=ws.max_column+1
            ws.cell(1,link_col,"VER_DETALLE")

        for r in range(2,ws.max_row+1):
            account=str(ws.cell(r,source_col).value or "").strip()
            target=first_row.get(account)
            if not target:
                continue
            link=f"#'VENTAS'!A{target}"
            ws.cell(r,link_col,"Ver detalle")
            ws.cell(r,link_col).hyperlink=link
            ws.cell(r,link_col).style="Hyperlink"

        try:
            ws.auto_filter.ref=ws.dimensions
        except Exception:
            pass

    book.save(path)
    book.close()
    return path


_v1043_previous_export_excel = SalesStore.export_excel
def _v1043_export_excel(self,output_path:Path,append_existing:bool=False):
    result=_v1043_previous_export_excel(self,output_path,append_existing)
    try:
        _v1043_add_portfolio_links_to_export(Path(output_path))
    except Exception:
        pass
    return result

SalesStore.export_excel = _v1043_export_excel

